		&& Enumerable.Range(24, 39).All(i => HoldOf(codFullMap, $"ACH_{i}", [.. mw2Trusted]) == NotOwned)
		&& Enumerable.Range(63, 94).All(i => HoldOf(codFullMap, $"ACH_{i}", [.. mw2Trusted]) == None)
		&& !mw2Trusted.Contains(2519060u),
