	Dictionary<uint, uint> statNow = new() { [256] = 12, [300] = (uint) BitConverter.SingleToInt32Bits(2.5f) };
	(double, double) ProgressRead(SteamKit2.KeyValue p) => ((double, double)) progressOf.Invoke(null, [p, statNames, statNow])!;
