		(hourA == null) && (dayStart == 21) && (hourB != null) && (hourC == null) && (hourCfg.FarmUntilHour == 24) && (hourD == null) && (hourCfg.SendAroundHour == -1),
		$"{hourA} {dayStart} {hourB} {hourC} {hourD}");
	string appJs = Src("wwwroot/app.js");
	Check("hour settings: the dashboard shows a list of hours - 12-hour labels when the browser's clock is, 09:00 otherwise; the server clamps them like numbers; the e2e test changes and puts them back",
		appJs.Contains("case 'Hour': {", StringComparison.Ordinal) && appJs.Contains("hourClock.twelve = cycle === 'h11' || cycle === 'h12';", StringComparison.Ordinal)
		&& appJs.Contains("if (!twelveHourClock()) return `${String(h).padStart(2, '0')}:00`;", StringComparison.Ordinal)
		&& Src("Web/WebHost.cs").Contains("SettingKind.Int or SettingKind.Hour or SettingKind.Float", StringComparison.Ordinal)
		&& File.ReadAllText(Path.Combine(repo, "tests", "e2e", "dashboard.mjs")).Contains("} else if (kind === 'Hour') {", StringComparison.Ordinal)
		&& File.ReadAllText(Path.Combine(repo, "tests", "e2e", "dashboard.mjs")).Contains("} else if (def.Kind === 'Hour') {", StringComparison.Ordinal));

	// ── How fast is an everyday setting, right under "Earn achievements over time" ──────────────────────────────────
	int earnAt = NocatFarm.Config.Settings.Bot.ToList().FindIndex(static d => d.Name == "UnlockAchievements");
	Check("how fast: shown without Show advanced, directly under 'Earn achievements over time'",
		NocatFarm.Config.Settings.Bot[earnAt + 1] is { Name: "AchievementPace", Advanced: false, Kind: NocatFarm.Config.SettingKind.Choice }
		&& File.ReadAllText(Path.Combine(repo, "docs", "settings.md")).Contains("| Achievements | *Earn achievements over time*, and while it's on *How fast* and *Achievement hunt* |", StringComparison.Ordinal));

	// ── How fast: careful doubles every wait, brisk halves it, normal is as it was ───────────────────────────────────
	MethodInfo paceMinutes = typeof(NocatFarm.Modules.AchievementPacer).GetMethod("PaceMinutes", SP)!;
	MethodInfo repace = typeof(NocatFarm.Modules.AchievementPacer).GetMethod("Repace", SP)!;
	int PaceM(int pace, int m) => (int) paceMinutes.Invoke(null, [pace, m])!;
	DateTime Re(DateTime from, DateTime next, int was, int now) => (DateTime) repace.Invoke(null, [from, next, was, now])!;
	int[] waits = [1, 4, 12, 20, 25, 60, 120, 150];
	Check("how fast: normal leaves every wait exactly; careful doubles, brisk halves (never under a minute) - gaps, play needed, bursts, grind gaps alike",
		waits.All(m => PaceM(1, m) == m) && waits.All(m => PaceM(0, m) == m * 2) && waits.All(m => PaceM(2, m) == Math.Max(1, m / 2))
		&& waits.All(m => PaceM(2, m) >= 1) && (PaceM(0, 20) == 40) && (PaceM(0, 120) == 240) && (PaceM(2, 60) == 30) && (PaceM(2, 150) == 75) && (PaceM(2, 25) == 12)
		&& (PaceM(7, 60) == 60) && (PaceM(-1, 60) == 60));
	DateTime paceT0 = new(2026, 10, 1, 12, 0, 0, DateTimeKind.Utc);
	Check("how fast: changed half way through a wait, the rest of it is re-spaced at once - normal 60 to careful 120, to brisk 30; careful 120 to brisk 30",
		(Re(paceT0, paceT0.AddMinutes(60), 1, 0) == paceT0.AddMinutes(120)) && (Re(paceT0, paceT0.AddMinutes(60), 1, 2) == paceT0.AddMinutes(30))
		&& (Re(paceT0, paceT0.AddMinutes(120), 0, 2) == paceT0.AddMinutes(30)) && (Re(paceT0, paceT0.AddMinutes(60), 1, 1) == paceT0.AddMinutes(60)));
	Check("how fast: applied to the clock gap and the play needed (Due and the status line), re-spaced on the next look - and nowhere near the rarity floor, order rules, counters, holds or the skip",
		pacerSrc.Contains("int playedGate = PlayedGate(prof, onboarding, pace);", StringComparison.Ordinal)
		&& pacerSrc.Contains("int playedGate = PlayedGate(prof, onboarding, Bot.Cfg.AchievementPace);", StringComparison.Ordinal)
		&& pacerSrc.Contains("g.NextAllow = Respaced(g.PacedFrom, g.NextAllow, g.PaceUsed, pace, g.Pulled);", StringComparison.Ordinal)
		&& pacerSrc.Contains("g.NextAllow = DateTime.UtcNow.AddMinutes(Paced(gap));", StringComparison.Ordinal)
		&& pacerSrc.Contains("RepaceIfChanged(each, Bot.Cfg.AchievementPace);", StringComparison.Ordinal) && pacerSrc.Contains("RepaceIfChanged(g, pace);", StringComparison.Ordinal)
		&& pacerSrc.Contains("g.NextAllow = g.PacedFrom.AddMinutes(Paced(FullGap(grind, onboarding, prof)));", StringComparison.Ordinal)
		&& (System.Text.RegularExpressions.Regex.Matches(pacerSrc, @"Cfg\.AchievementPace\b").Count == 6)
		&& (sortGame.GetParameters().All(static p => p.Name != "pace")) && (eligibleOf.GetParameters().All(static p => p.Name != "pace")));

	// 'dlc leave' is kept with the licences among the game's DLC ids - the same whether the map was built in a hurry (a
	// nameless DLC taken as one that may have achievements, so a group of its own) or in full (named a soundtrack, so
	// no group).
	NocatFarm.Core.DlcAchievements.Map hurried = new() {
		App = 50, Dlc = [51, 52, 53, 54], Hurried = true, Groups = [
			new() { App = 51, Ids = [51], Name = "Story", Unsure = NocatFarm.Core.DlcAchievements.Doubt.NoFigures },
			new() { App = 52, Ids = [52], Name = "", Unsure = NocatFarm.Core.DlcAchievements.Doubt.Delisted }]
	};
	NocatFarm.Core.DlcAchievements.Map full = new() {
		App = 50, Dlc = [51, 52, 53, 54], Groups = [new() { App = 51, Ids = [51], Name = "Story", Unsure = NocatFarm.Core.DlcAchievements.Doubt.NoFigures }]
	};
	HashSet<uint> ownsThese = [52, 54, 999];
	string hurriedKey = NocatFarm.Core.DlcAchievements.LicenceKey(hurried, ownsThese.Contains);
	string fullKey = NocatFarm.Core.DlcAchievements.LicenceKey(full, ownsThese.Contains);
	Check("dlc leave key: a map built again (hurried, then in full) keeps the same key",
		(hurriedKey == "52,54") && (fullKey == hurriedKey), $"{hurriedKey} / {fullKey}");
	Check("dlc leave key: a map saved before the DLC list was kept uses its groups' ids", NocatFarm.Core.DlcAchievements.LicenceKey(
		new NocatFarm.Core.DlcAchievements.Map { App = 60, Groups = [new() { App = 61, Ids = [61, 6100] }] }, static id => id == 6100) == "6100");
}

// ── earn anyway: games held whole are let go, 'dlc leave' / 'dlc undo', the old question gone ──────────────────────
{
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	NocatFarm.Config.GlobalConfig realGlobal = NocatFarm.Config.Live.Global;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-dlcleave-" + Guid.NewGuid().ToString("N"));
	Directory.CreateDirectory(Path.Combine(tmpRoot, "config", "state"));
	NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);
	string repoSrc = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm");
	string Src(string rel) => File.ReadAllText(Path.Combine(repoSrc, rel)).Replace("\r\n", "\n");
	List<(NocatFarm.Topic Topic, string Source, string Text)> published = [];
	void Heard(NocatFarm.Topic topic, string source, string text) {
		lock (published) {
			published.Add((topic, source, text));
		}
	}

	try {
		// What the pacer last concluded, as an older version saved it. 440 held whole (9 = DlcUnmapped) - let go now. 500
		// held whole but "carried on" back then - let go too, the old answer means nothing now. 730 held whole and left
		// paused - stays held. 22380 held for a DLC known exactly (7 = DlcOnly) - stays. 950 earning, with add-ons Steam
		// doesn't explain.
		File.WriteAllText(Path.Combine(tmpRoot, "config", "state", "cheevo-asker.json"), """
			[
			  { "App": 440, "Last": 9, "Total": 50, "Unlocked": 10, "Reachable": 12, "DlcHeld": 38, "Unmapped": true, "DlcOwned": [], "DlcKey": "", "DlcAsked": "" },
			  { "App": 500, "Last": 9, "Total": 50, "Unlocked": 10, "Unmapped": true, "DlcOwned": [], "DlcKey": "" },
			  { "App": 730, "Last": 9, "Total": 50, "Unlocked": 10, "Unmapped": true, "DlcOwned": [731], "DlcKey": "731" },
			  { "App": 22380, "Last": 7, "Total": 50, "Unlocked": 10, "DlcHeld": 5, "DlcOwned": [], "DlcKey": "" },
			  { "App": 950, "Last": 1, "Total": 50, "Unlocked": 10, "Unclear": true, "DlcOwned": [951], "DlcKey": "" }
			]
			""");

		var mgr = new NocatFarm.Core.BotManager(new NocatFarm.Config.GlobalConfig { WebEnabled = false });
		var bots = (System.Collections.Concurrent.ConcurrentDictionary<string, NocatFarm.Core.Bot>) typeof(NocatFarm.Core.BotManager)
			.GetField("_bots", BindingFlags.NonPublic | BindingFlags.Instance)!.GetValue(mgr)!;
		var asker = new NocatFarm.Core.Bot("asker", new NocatFarm.Config.BotConfig {
			UnlockAchievements = true, AchievementDlcLeft = new() { [730] = "731" }
		});
		var pacer = new NocatFarm.Modules.AchievementPacer(asker);
		asker.AddModule(pacer);
		bots["asker"] = asker;
		NocatFarm.Core.GameNames.Learn(950, "Quiet Fields");

		// Reading the state is what lets them go: on the first start, not after a week.
		NocatFarm.Log.Published += Heard;
		bool unclear440 = pacer.IsUnclear(440);
		NocatFarm.Log.Published -= Heard;
		string State(uint app) => pacer.Snapshot().Single(r => r.App == app).State;
		Check("dlc legacy: games held whole are let go on the first start",
			(State(440) == "Unknown") && (State(500) == "Unknown") && !pacer.NothingLeft(440) && !pacer.NothingLeft(500),
			$"{State(440)} {State(500)}");
		Check("dlc legacy: a game left paused stays held, and one held for a DLC known exactly stays as it was",
			(State(730) == "DlcUnmapped") && pacer.NothingLeft(730) && (State(22380) == "DlcOnly") && (State(950) == "Earning"),
			$"{State(730)} {State(22380)} {State(950)}");
		Check("dlc legacy: what a released game could reach is worked out again, and it's remembered as having unclear add-ons",
			unclear440 && pacer.IsUnclear(950) && !pacer.IsUnclear(22380)
			&& (pacer.Progress(440) == (10, 50)) && (pacer.Snapshot().Single(static r => r.App == 440).DlcHeld == 0),
			$"{pacer.Progress(440)}");
		Check("dlc legacy: nothing is said to Discord or Telegram about it", published.Count == 0, string.Join(" | ", published.Select(static p => p.Text)));

		// The question is gone: no asking, no log line, no dashboard card.
		Check("dlc no question: the asking and its log line are gone",
			(typeof(NocatFarm.Modules.AchievementPacer).GetMethod("AskAboutHeldGames", BindingFlags.NonPublic | BindingFlags.Instance) == null)
			&& (typeof(NocatFarm.Modules.AchievementPacer).GetMethod("HeldWholeGames") == null)
			&& (typeof(NocatFarm.Commands).Assembly.GetType("NocatFarm.Core.DlcQuestions") == null)
			&& !Src("Modules/AchievementPacer.cs").Contains("Answer on the dashboard", StringComparison.Ordinal)
			&& !Src("Modules/AchievementPacer.cs").Contains("is paused for achievements", StringComparison.Ordinal)
			&& !Src("Modules/AchievementPacer.cs").Contains("Log.Publish(", StringComparison.Ordinal)
			&& !Src("Modules/AchievementPacer.cs").Contains("DlcAsked", StringComparison.Ordinal)
			&& !Src("wwwroot/lang/de.json").Contains("is paused for achievements - it has add-ons", StringComparison.Ordinal));

		// Leave one alone, by part of the name, any case: kept with the licences read for it, saved.
		string left = await Commands.RunAsync(mgr, "dlc leave asker team fortress");
		string onDisk = File.ReadAllText(Path.Combine(tmpRoot, "config", "asker.json"));
		Check("dlc leave: by name - kept on the account's list, saved, says how to undo it",
			left.Contains("Team Fortress 2 is left alone for achievements now", StringComparison.Ordinal) && left.Contains("'dlc undo asker Team Fortress 2'", StringComparison.Ordinal)
			&& (asker.Cfg.AchievementDlcLeft.GetValueOrDefault(440u) == "") && onDisk.Contains("\"440\": \"\"", StringComparison.Ordinal), left);
		Check("dlc leave: a left game counts as left alone everywhere - the write's re-check and the list for the dashboard",
			NocatFarm.Core.DlcChoices.LeftPaused(asker).Select(static a => a.App).SequenceEqual([440u, 730u])
			&& !new NocatFarm.Core.DlcAchievements.View { Map = new() { App = 440, Groups = [new() { App = 441 }] }, Trusted = true }.StillSo(asker));
		string notUnclear = await Commands.RunAsync(mgr, "dlc leave asker 22380");
		Check("dlc leave: only a game with add-ons Steam doesn't explain - not one known exactly, not any number",
			notUnclear.Contains("nothing to leave alone", StringComparison.Ordinal) && !asker.Cfg.AchievementDlcLeft.ContainsKey(22380u)
			&& !NocatFarm.Core.DlcChoices.Answerable(asker, 22380) && NocatFarm.Core.DlcChoices.Answerable(asker, 950) && NocatFarm.Core.DlcChoices.Answerable(asker, 730), notUnclear);

		// Undo, by appID: earns again, let go at once.
		string undone = await Commands.RunAsync(mgr, "dlc undo asker 730");
		Check("dlc undo: the game earns again (base game first) and is let go at once",
			undone.Contains("Counter-Strike 2 earns achievements again - the base game's first", StringComparison.Ordinal)
			&& !asker.Cfg.AchievementDlcLeft.ContainsKey(730u) && (State(730) == "Unknown"), undone);
		string nothing = await Commands.RunAsync(mgr, "dlc undo asker 22380");
		Check("dlc undo: nothing to take back says so", nothing.Contains("isn't left alone, so there's nothing to take back", StringComparison.Ordinal), nothing);

		// The old 'carry on' is gone: not a choice any more, so it changes nothing - 'dlc undo' takes back a 'dlc leave'.
		string carried = await Commands.RunAsync(mgr, "dlc carryon asker 440");
		bool stillLeft = asker.Cfg.AchievementDlcLeft.ContainsKey(440u);
		string undoLeft = await Commands.RunAsync(mgr, "dlc undo asker 440");
		Check("dlc carryon: gone - taken as an account name that isn't there, the game stays left alone; undo takes it back",
			carried.Contains("There's no account called 'carryon'", StringComparison.Ordinal) && stillLeft
			&& undoLeft.Contains("Team Fortress 2 earns achievements again", StringComparison.Ordinal) && !asker.Cfg.AchievementDlcLeft.ContainsKey(440u),
			carried + " / " + undoLeft);
		string tooShort = await Commands.RunAsync(mgr, "dlc leave asker e");
		string zero = await Commands.RunAsync(mgr, "dlc leave asker 0");
		Check("dlc find: one letter or a bare 0 doesn't pick a game", tooShort.Contains("Type more of the game's name", StringComparison.Ordinal)
			&& zero.Contains("Type more of the game's name", StringComparison.Ordinal), tooShort + " / " + zero);

		// Steam chat: looking is fine, choosing is for the owner.
		Check("dlc: leave and undo are refused from Steam chat, looking isn't",
			NocatFarm.Commands.SteamChatRefusesAnswer(mgr, "dlc leave asker 440") && NocatFarm.Commands.SteamChatRefusesAnswer(mgr, "dlcach leave asker 440")
			&& NocatFarm.Commands.SteamChatRefusesAnswer(mgr, "dlc UNDO asker 440") && !NocatFarm.Commands.SteamChatRefusesAnswer(mgr, "dlc asker")
			&& !NocatFarm.Commands.SteamChatRefusesAnswer(mgr, "dlc asker Team Fortress 2"));
		NocatFarm.Core.BotManager? realHost = NocatFarm.Commands.Host;
		NocatFarm.Commands.Host = mgr;
		string fromChat = await NocatFarm.Commands.RunAsync("dlc leave asker 950", "asker");
		NocatFarm.Commands.Host = realHost;
		Check("dlc: a Steam chat 'leave' isn't taken", fromChat.Contains("has to be done at the PC", StringComparison.Ordinal)
			&& !asker.Cfg.AchievementDlcLeft.ContainsKey(950u), fromChat);

		// Finding the game, the old name of the command, and its help.
		string unsure = await Commands.RunAsync(mgr, "dlc leave asker te");
		string noGame = await Commands.RunAsync(mgr, "dlc leave asker Half-Life 3");
		Check("dlc find: a name that fits several asks which; one that fits none says so",
			unsure.Contains("More than one game matches \"te\"", StringComparison.Ordinal) && noGame.Contains("has no game called \"Half-Life 3\"", StringComparison.Ordinal),
			unsure + " / " + noGame);
		string old = await Commands.RunAsync(mgr, "dlcach asker");
		string usage = await Commands.RunAsync(mgr, "dlcach");
		Check("dlc: 'dlcach' still works, and the bare command shows leave and undo - not carryon",
			old.Contains("asker isn't logged in", StringComparison.Ordinal) && usage.Contains("dlc leave <account> <game>", StringComparison.Ordinal)
			&& usage.Contains("dlc undo <account> <game>", StringComparison.Ordinal) && !usage.Contains("carryon", StringComparison.Ordinal), old + " / " + usage);
		NocatFarm.CommandDef dlcDef = NocatFarm.Commands.All.Single(static c => c.Name == "dlc");
		Check("dlc help: earns anyway, base game first; leave and undo; no question, no carryon",
			dlcDef.Args.Contains("leave|undo", StringComparison.Ordinal) && !dlcDef.Args.Contains("carryon", StringComparison.Ordinal)
			&& dlcDef.Help.Contains("it earns anyway: the base game's first", StringComparison.Ordinal) && !dlcDef.Help.Contains("carryon", StringComparison.Ordinal)
			&& !dlcDef.Help.Contains("you're asked", StringComparison.Ordinal), dlcDef.Help);
		string noAccount = await Commands.RunAsync(mgr, "dlc leave nobody 440");
		Check("dlc: a choice for an account that isn't there is refused", !noAccount.Contains("left alone for achievements", StringComparison.Ordinal), noAccount);

		// Two games of the same name: the hint gives the appID, which finds just the one. A game called "140" is found by
		// its name before the number is taken as an appID.
		BindingFlags libFlags = BindingFlags.NonPublic | BindingFlags.Instance;
		List<NocatFarm.Core.Library.Entry> twins = [new(90001, "Doom", 600, DateTime.MinValue, 0), new(90002, "DOOM", 60, DateTime.MinValue, 0), new(90003, "140", 60, DateTime.MinValue, 0)];
		typeof(NocatFarm.Core.Library).GetField("_games", libFlags)!.SetValue(asker.Library, twins);
		typeof(NocatFarm.Core.Library).GetField("_byApp", libFlags)!.SetValue(asker.Library, twins.ToDictionary(static e => e.AppId));
		NocatFarm.Core.GameNames.Learn(90001, "Doom");
		NocatFarm.Core.GameNames.Learn(90002, "DOOM");
		Check("dlc: the name to type is the appID when another game has the same name, the name otherwise",
			(NocatFarm.Core.DlcChoices.Typed(asker, 90001) == "90001") && (NocatFarm.Core.DlcChoices.Typed(asker, 440) == "Team Fortress 2")
			&& (NocatFarm.Core.DlcChoices.Find(asker, "90001").App == 90001),
			NocatFarm.Core.DlcChoices.Typed(asker, 90001));
		Check("dlc find: a game called \"140\" by its name, not as appID 140", NocatFarm.Core.DlcChoices.Find(asker, "140").App == 90003);
		Check("dlc: the pacer's state is written in order - the copy and the write under one lock, the dashboard's save and the tick's can't swap",
			Src("Modules/AchievementPacer.cs").Contains("\tprivate void Save() {\n\t\tlock (_saveGate) {\n\t\t\tSaveInOrder();", StringComparison.Ordinal));

		// What 'dlc <account> <game>' says, by the sentences it is made of.
		string cmd = Src("Commands.cs");
		Check("dlc wording: a game that earns anyway says so, base game first, names the add-ons it won't touch, and how to leave it alone",
			cmd.Contains("It earns them anyway - the base game's first, and the {1} it can't place after those, in case some come with that DLC.", StringComparison.Ordinal)
			&& cmd.Contains("\"It never touches the achievements of {0}, which it doesn't own.\"", StringComparison.Ordinal)
			&& cmd.Contains("\"To have {1} left alone instead: 'dlc leave {0} {2}'.\"", StringComparison.Ordinal)
			&& cmd.Contains("earns them anyway, base game first; {0} from DLC it doesn't own left alone", StringComparison.Ordinal));
		Check("dlc wording: no 'add to list' or 'carry on' advice any more; a game left alone says how to undo it",
			!cmd.Contains("VouchHint", StringComparison.Ordinal) && !cmd.Contains("dlc carryon {0}", StringComparison.Ordinal)
			&& !cmd.Contains("Trusted: you said", StringComparison.Ordinal) && !cmd.Contains("you said carry on", StringComparison.Ordinal)
			&& cmd.Contains("lines.Add(\"  \" + LeftHint(bot, app));", StringComparison.Ordinal)
			&& cmd.Contains("(dlc.Trusted ? \"\" : \" \" + LeftHint(bot, appId))", StringComparison.Ordinal));
	} finally {
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);
		NocatFarm.Config.Live.Global = realGlobal;

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
			// temp - it goes when Windows tidies up
		}
	}

	// The dashboard: no question card any more - the games left alone, each with its undo, and one endpoint.
	string js = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "wwwroot", "app.js")).Replace("\r\n", "\n");
	string web = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Web", "WebHost.cs")).Replace("\r\n", "\n");
	string css = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "wwwroot", "style.css"));
	Check("dlc dashboard: the question card and its buttons are gone",
		!js.Contains("dlcAsks", StringComparison.Ordinal) && !js.Contains("dlccarryon", StringComparison.Ordinal) && !js.Contains("dlcleave", StringComparison.Ordinal)
		&& !js.Contains("I own what matters", StringComparison.Ordinal) && !js.Contains("pacerAsks", StringComparison.Ordinal) && !js.Contains("DlcQuestions", StringComparison.Ordinal)
		&& !css.Contains(".dlcask", StringComparison.Ordinal));
	Check("dlc dashboard: a game left alone is listed with its undo, escaped",
		js.Contains("case 'dlcundo': answerDlc(name, el.dataset.app, 'undo'); break;", StringComparison.Ordinal)
		&& js.Contains("${esc(t('Left alone for achievements:'))} ${pacerLeft.map(link).join(' · ')}", StringComparison.Ordinal)
		&& js.Contains("${pacerFor === settingsTarget ? dlcAnswered(settingsTarget) : ''}", StringComparison.Ordinal));
	Check("dlc dashboard: the endpoint checks the sign-in first; the status has no questions, the achievements the games left alone",
		web.Contains("app.MapPost(\"/api/bots/{name}/achievements/dlc\", async (HttpContext ctx, string name) => {\n\t\t\tif (!Authorised(ctx)) {", StringComparison.Ordinal)
		&& !web.Contains("DlcQuestions", StringComparison.Ordinal) && !web.Contains("DlcCarriedOn", StringComparison.Ordinal)
		&& web.Contains("DlcLeft = bot == null ? [] : DlcChoices.LeftPaused(bot),", StringComparison.Ordinal));
}

// ── a game held on a wrong DLC map comes back by itself: Portal, held whole for Portal with RTX ─────────────────
{
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-dlcfree-" + Guid.NewGuid().ToString("N"));
	Directory.CreateDirectory(Path.Combine(tmpRoot, "config", "state"));
	NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);
	var maps = (Dictionary<uint, NocatFarm.Core.DlcAchievements.Map>) typeof(NocatFarm.Core.DlcAchievements)
		.GetField("Maps", BindingFlags.NonPublic | BindingFlags.Static)!.GetValue(null)!;
	NocatFarm.Core.Bot? bot = null;

	try {
		// Portal as the old rules mapped it: all 15 "from" Portal with RTX, which the account doesn't own. 6 unlocked, the
		// other 9 held - the pacer called it done for DLC, and the hunt dropped it ("done with Portal's achievements").
		List<NocatFarm.Core.DlcAchievements.Entry> portal = [.. Enumerable.Range(0, 15).Select(static i => new NocatFarm.Core.DlcAchievements.Entry($"PORTAL_{i}", $"Achievement {i}", "Do a thing.", false))];
		List<string> keys = [.. portal.Select(static e => e.Name.ToLowerInvariant())];
		NocatFarm.Core.DlcAchievements.Map old = new() {
			App = 400, BuiltAt = DateTime.UtcNow.AddDays(-1), Rule = 6, DlcCount = 2, OnStore = 2, StoreSays = true, SchemaCount = 15, Names = keys, Dlc = [323170, 2012840],
			Groups = [new() { App = 2012840, Ids = [2012840], Name = "Portal with RTX", Total = 15, Located = 15, Exact = true }],
			Owners = keys.ToDictionary(static k => k, static _ => new List<uint> { 2012840 }), Sure = keys.ToDictionary(static k => k, static _ => new List<uint> { 2012840 })
		};
		long oldStamp = NocatFarm.Core.DlcAchievements.Stamp(old);
		long oldKey = NocatFarm.Core.DlcAchievements.HoldKey(old, new HashSet<uint>(), new HashSet<uint>());
		File.WriteAllText(Path.Combine(tmpRoot, "config", "state", "cheevo-freed.json"), $$"""
			[
			  { "App": 400, "Last": 7, "Total": 15, "Unlocked": 6, "Reachable": 6, "DlcHeld": 9, "DlcOwned": [], "DlcKey": "", "Licences": 77, "MapStamp": {{oldStamp}}, "HoldKey": {{oldKey}} },
			  { "App": 620, "Last": 1, "Total": 51, "Unlocked": 3 }
			]
			""");

		bot = new NocatFarm.Core.Bot("freed", new NocatFarm.Config.BotConfig {
			UnlockAchievements = true, AchievementBoost = 1, AchievementBoostGames = [400, 620], BoostSwitchFromPct = 100, BoostSwitchToPct = 100
		});
		var pacer = new NocatFarm.Modules.AchievementPacer(bot);
		var hunt = new NocatFarm.Modules.AchievementBoost(bot);
		bot.AddModule(pacer);
		bot.AddModule(hunt);
		NocatFarm.Core.DlcAchievements.Current(400);   // read the (empty) saved maps first, so they can't land on top
		maps[400] = old;
		_ = pacer.IsUnclear(400);                      // reads the saved state
		MethodInfo targets = typeof(NocatFarm.Modules.AchievementBoost).GetMethod("Targets", BindingFlags.NonPublic | BindingFlags.Instance)!;
		MethodInfo nextTarget = typeof(NocatFarm.Modules.AchievementBoost).GetMethod("NextTarget", BindingFlags.NonPublic | BindingFlags.Instance)!;
		List<uint> Targets() => (List<uint>) targets.Invoke(hunt, [])!;
		Check("dlc freed: held whole on the old map, Portal is 'nothing left' and out of the hunt",
			pacer.NothingLeft(400) && !Targets().Contains(400) && Targets().Contains(620), string.Join(",", Targets()));

		// The new rules build it again: Portal with RTX is a game, not a DLC - nothing in Portal is held.
		NocatFarm.Core.DlcAchievements.Map rebuilt = NocatFarm.Core.DlcAchievements.Assemble(400, "Portal", portal, NocatFarm.Core.DlcAchievements.Merge(400, [
			new(323170, 323170, "Portal Soundtrack", 0, [], Type: "music"),
			new(2012840, 2012840, "Portal with RTX", 15, [.. portal.Take(10).Select(static e => e.Display)], Type: "game")], "Portal"), 2, 2, DateTime.UtcNow);
		rebuilt.Dlc = [323170, 2012840];
		maps[400] = rebuilt;

		// The minute's look at held games - the account's licences read, unchanged.
		Type botType = typeof(NocatFarm.Core.Bot);
		botType.GetField("_licenseStamp", BindingFlags.NonPublic | BindingFlags.Instance)!.SetValue(bot, 77L);
		botType.GetField("_appOwnedSince", BindingFlags.NonPublic | BindingFlags.Instance)!.SetValue(bot,
			new Dictionary<uint, NocatFarm.Core.AppOwnership> { [400] = new(DateTime.UtcNow.AddYears(-5), true, true, Permanent: true) });
		await (Task) typeof(NocatFarm.Modules.AchievementPacer).GetMethod("RecheckLicencesAsync", BindingFlags.NonPublic | BindingFlags.Instance)!
			.Invoke(pacer, [CancellationToken.None])!;
		string state = pacer.Snapshot().Single(static r => r.App == 400).State;
		Check("dlc freed: once the map is built again, Portal is looked at again by itself - no longer 'nothing left', and not 6 of 6",
			(state == "Unknown") && !pacer.NothingLeft(400) && (pacer.Progress(400) == (6, 15)), $"{state} {pacer.Progress(400)}");
		List<uint> picks = [(uint) nextTarget.Invoke(hunt, [Targets()])!, (uint) nextTarget.Invoke(hunt, [Targets()])!];
		Check("dlc freed: and it's back in the hunt - in its turn with the other game again",
			Targets().Contains(400) && picks.Contains(400u) && picks.Contains(620u), string.Join(",", picks));
	} finally {
		maps.Remove(400);
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);

		if (bot != null) {
			await bot.DisposeAsync();
		}

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
			// temp - it goes when Windows tidies up
		}
	}
}

// ── achievement bursts: only common ones come a few minutes apart (AchievementBurstMinPct) ─────────────────────────
// reap saw three achievements that ~1% of players have pop within eight minutes. A burst now only starts, and only goes
// on, while the next pick is common enough; a rare one ends it and gets the full wait - in normal play and a grind.
{
	const BindingFlags SP = BindingFlags.Static | BindingFlags.NonPublic;
	string pacerSrc = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Modules", "AchievementPacer.cs")).Replace("\r\n", "\n");
	Type pacerType = typeof(NocatFarm.Modules.AchievementPacer);
	MethodInfo mayBurst = pacerType.GetMethod("MayBurst", SP)!;
	MethodInfo nextMayBurst = pacerType.GetMethod("NextMayBurst", SP)!;
	MethodInfo nextPick = pacerType.GetMethod("NextPick", SP)!;
	NocatFarm.Core.Achievement Ach(string name, double? percent) =>
		new() { Name = name, Display = name, StatId = 1, Bit = 0, Unlocked = false, Protected = false, GlobalPercent = percent };
	bool May(NocatFarm.Core.Achievement a, int atPct) => (bool) mayBurst.Invoke(null, [a, atPct])!;
	Func<NocatFarm.Core.Achievement, bool> noLater = static _ => false;
	bool NextMay(List<NocatFarm.Core.Achievement> eligible, NocatFarm.Core.Achievement pick, int atPct) => (bool) nextMayBurst.Invoke(null, [eligible, pick, noLater, atPct])!;
	NocatFarm.Core.Achievement Pick(List<NocatFarm.Core.Achievement> eligible, bool wobble) => (NocatFarm.Core.Achievement) nextPick.Invoke(null, [eligible, noLater, wobble, null])!;

	NocatFarm.Core.Achievement[] range = [Ach("R08", 0.8), Ach("R99", 9.9), Ach("C10", 10), Ach("C50", 50), Ach("C100", 100), Ach("NONE", null)];
	string Bursting(int atPct) => string.Join(",", range.Where(a => May(a, atPct)).Select(static a => a.Name));
	Check("bursts: default 10% - 10% and up may burst; 9.9%, 0.8% and one with no figure never do", Bursting(10) == "C10,C50,C100", Bursting(10));
	Check("bursts: 0 lets any achievement burst, one with no figure too", Bursting(0) == "R08,R99,C10,C50,C100,NONE", Bursting(0));
	Check("bursts: 50 - only half the players or more", Bursting(50) == "C50,C100", Bursting(50));
	Check("bursts: 100 - no bursts at all, not even an achievement everybody has", Bursting(100).Length == 0, Bursting(100));

	var first = Ach("FIRST", 70);
	Check("bursts: a rare next one (1.2%) never starts or carries on a burst at 10%; a common one (40%) may",
		!NextMay([first, Ach("RARE", 1.2)], first, 10) && NextMay([first, Ach("COMMON", 40)], first, 10)
		&& !NextMay([first, Ach("COMMON", 40), Ach("RARE", 1.2)], first, 50) && NextMay([first, Ach("COMMON", 40), Ach("RARE", 1.2)], first, 10));
	Check("bursts: the wobble counts too - 11% with 9.5% just behind (the next look might take either) doesn't burst at 10%",
		!NextMay([first, Ach("A11", 11), Ach("B95", 9.5)], first, 10) && NextMay([first, Ach("A40", 40), Ach("B38", 38)], first, 10));
	Check("bursts: at 100 nothing bursts; at 0 even a rare next one may; with nothing else open there's nothing to burst with",
		!NextMay([first, Ach("C90", 90)], first, 100) && NextMay([first, Ach("RARE", 0.5)], first, 0) && !NextMay([first], first, 0));

	// A whole game, unlocked in the pacer's order: whenever a quick one would be allowed after an unlock, it is common.
	List<NocatFarm.Core.Achievement> game = [Ach("G1", 81), Ach("G2", 64), Ach("G3", 52), Ach("G4", 33), Ach("G5", 21), Ach("G6", 12), Ach("G7", 10.5),
		Ach("G8", 9.7), Ach("G9", 4.1), Ach("G10", 1.3), Ach("G11", 1.1), Ach("G12", 0.9)];
	foreach (int atPct in new[] { 0, 10, 50, 100 }) {
		List<NocatFarm.Core.Achievement> stillOpen = [.. game];
		List<string> quickAfter = [];
		bool rareQuick = false;

		while (stillOpen.Count > 0) {
			var picked = Pick(stillOpen, false);
			bool burst = NextMay(stillOpen, picked, atPct);
			stillOpen.Remove(picked);

			if (burst) {
				// Either pick the next look could make comes quickly: both must be common enough.
				var next = Pick(stillOpen, false);
				var wobbled = Pick(stillOpen, true);
				quickAfter.Add(next.Name);
				rareQuick |= !May(next, atPct) || !May(wobbled, atPct) || ((atPct > 0) && ((next.GlobalPercent ?? 0) < atPct));
			}
		}

		string expect = atPct switch {
			0 => "G2,G3,G4,G5,G6,G7,G8,G9,G10,G11,G12",
			10 => "G2,G3,G4,G5,G6",
			50 => "G2,G3",
			_ => ""
		};
		Check($"bursts: a 12-achievement game at {atPct}% - a rare one never comes a few minutes after another; only these may", !rareQuick && (string.Join(",", quickAfter) == expect),
			string.Join(",", quickAfter));
	}

	// The pacer goes by it after every unlock - normal play and a grind alike - and stops a burst on a rare pick.
	int unlockAt = pacerSrc.IndexOf("int nowUnlocked = already + 1;", StringComparison.Ordinal);
	string gapSrc = unlockAt < 0 ? "" : pacerSrc[unlockAt..pacerSrc.IndexOf("g.NextAllow = DateTime.UtcNow.AddMinutes(Paced(gap));", unlockAt, StringComparison.Ordinal)];
	Check("bursts: after every unlock, normal or grind, a burst starts or carries on only when the next may burst; else the full wait",
		gapSrc.Contains("bool burstNext = NextMayBurst(eligible, pick, later, burstMin);", StringComparison.Ordinal)
		&& gapSrc.Contains("int burstChance = grind ? 25 : onboarding ? 45 : 12;", StringComparison.Ordinal)
		&& gapSrc.Contains("if (burstNext && (g.BurstLeft > 0)) {", StringComparison.Ordinal)
		&& gapSrc.Contains("} else if (burstNext && (_rng.Next(100) < burstChance)) {", StringComparison.Ordinal)
		&& gapSrc.Contains("gap = quick ? _rng.Next(1, 5) : FullGap(grind, onboarding, prof);", StringComparison.Ordinal)
		&& (System.Text.RegularExpressions.Regex.Matches(gapSrc, @"_rng\.Next\(1, 5\)").Count == 1) && !gapSrc.Contains("if (grind) {", StringComparison.Ordinal));
	Check("bursts: a rare pick in a burst (it changed since the last look, or a restart) isn't unlocked - the burst ends and it waits the full time",
		pacerSrc.Contains("if (((g.BurstLeft > 0) || g.Quick) && !MayBurst(pick, burstMin)) {", StringComparison.Ordinal)
		&& pacerSrc.Contains("g.NextAllow = g.PacedFrom.AddMinutes(Paced(FullGap(grind, onboarding, prof)));", StringComparison.Ordinal)
		&& pacerSrc.Contains("int burstMin = Bot.Cfg.AchievementBurstMinPct;", StringComparison.Ordinal)
		&& pacerSrc.Contains("Quick = s.Quick,", StringComparison.Ordinal) && pacerSrc.Contains("Quick = kv.Value.Quick,", StringComparison.Ordinal));
	Check("bursts: the metas keep their own rule - straight after the last one they wait on, no burst and no slot of their own",
		pacerSrc.Contains("List<Achievement> follow = ReadyMetas(sorted.Candidates, set.All, new HashSet<string>([pick.Name], StringComparer.Ordinal));", StringComparison.Ordinal)
		&& pacerSrc.Contains("if ((follow.Count > 0) && (nowUnlocked + follow.Count <= ceilingCount)) {", StringComparison.Ordinal)
		&& (pacerSrc[pacerSrc.IndexOf("private async Task<int> UnlockMetasAsync(", StringComparison.Ordinal)..].Split("\n\t}\n")[0] is string metaBody)
		&& !metaBody.Contains("MayBurst", StringComparison.Ordinal) && !metaBody.Contains("Quick", StringComparison.Ordinal) && !metaBody.Contains("BurstLeft", StringComparison.Ordinal));

	// The setting: per account, Achievements, behind Show advanced, 0-100, 10 by default.
	var burstDef = NocatFarm.Config.Settings.FindBot("AchievementBurstMinPct");
	var burstCfg = new NocatFarm.Config.BotConfig();
	Check("bursts: a per-account setting under Achievements, behind Show advanced, 0 to 100, 10 by default",
		burstDef is { Section: NocatFarm.Config.Settings.SecAchievements, Advanced: true, Kind: NocatFarm.Config.SettingKind.Int, Min: 0.0, Max: 100.0, Label: "Quick bursts only for achievements held by at least" }
		&& (NocatFarm.Config.Settings.UnitOf(burstDef) == "%")
		&& (burstCfg.AchievementBurstMinPct == 10) && (NocatFarm.Config.Settings.Apply(burstCfg, burstDef!, "0") == null) && (burstCfg.AchievementBurstMinPct == 0)
		&& (NocatFarm.Config.Settings.Apply(burstCfg, burstDef!, "100") == null) && (burstCfg.AchievementBurstMinPct == 100)
		&& (NocatFarm.Config.Settings.Apply(burstCfg, burstDef!, "101") != null) && (burstCfg.AchievementBurstMinPct == 100));
	Check("bursts: the docs say so", File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "docs", "settings.md"))
		.Contains("*Quick bursts only for achievements held by at least* (10%", StringComparison.Ordinal));
}

// ── old settings files: 1.6.4's and 1.6.5's, as they wrote them, load with every choice kept ─────────────────────────
// 1.6.4 had the old keys only (Update by itself, the three free-game switches, the booster text, the three refund settings,
// "carry on"); 1.6.5 to 1.6.9 wrote the new keys with a copy of the old ones beside them for the version before. Both load
// here into the same choices, and the next save writes only the new keys.
{
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-oldcfg-" + Guid.NewGuid().ToString("N"));
	Directory.CreateDirectory(Path.Combine(tmpRoot, "config"));
	NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);

	try {
		string cfgDir = NocatFarm.Config.ConfigStore.ConfigDir;
		string OnDisk(string name) => File.ReadAllText(Path.Combine(cfgDir, name + ".json"));
		string[] retired = ["\"AutoUpdate\"", "\"ClaimFreeGames\"", "\"ClaimFreeDlc\"", "\"ClaimFreeDlcBase\"", "\"BoosterGames\"",
			"\"ProtectGiftedGames\"", "\"RefundHoldDays\"", "\"HoldNewFamilyGames\"", "\"AchievementDlcTrusted\"", "\"DiscordShowNames\"",
			"\"FarmOnlyWhileAsleep\"", "\"MainGameSharePct\""];
		bool NoneRetired(string text) => !retired.Any(k => text.Contains(k, StringComparison.Ordinal));

		// ── 1.6.4 ──
		File.WriteAllText(Path.Combine(cfgDir, "old164.json"), """
			{
			  "Enabled": true,
			  "SteamLogin": "old164login",
			  "SkipRefundableGames": true,
			  "ProtectGiftedGames": false,
			  "RefundHoldDays": 30,
			  "HoldNewFamilyGames": false,
			  "FarmCardsWhen": 0,
			  "FarmOnlyWhileAsleep": true,
			  "AchievementNeverGames": [570],
			  "AchievementDlcTrusted": [500],
			  "ClaimFreeGames": true,
			  "ClaimFreeDlc": true,
			  "ClaimFreeDlcBase": false,
			  "CraftBadges": true,
			  "BoosterGames": "730, 440",
			  "BoosterGems": 1,
			  "LegitMode": true,
			  "GameWeights": "730, 440, 550",
			  "MainGameSharePct": 80,
			  "IdleGames": [730, 440, 550],
			  "OfflineIdleAtNight": true,
			  "OfflineIdleGames": [],
			  "AchievementPace": 2
			}
			""");
		File.WriteAllText(NocatFarm.Config.ConfigStore.GlobalPath, """
			{
			  "DiscordShowNames": false,
			  "DiscordSecondLine": 2,
			  "CheckForUpdates": true,
			  "AutoUpdate": 1,
			  "UpdateWhenAsked": 1,
			  "AutoUpdateFromHour": 4,
			  "AutoUpdateUntilHour": 7
			}
			""");
		var b164 = NocatFarm.Config.ConfigStore.LoadBot("old164")!;
		var b164Again = NocatFarm.Config.ConfigStore.LoadBot("old164")!;
		var g164 = NocatFarm.Config.ConfigStore.LoadGlobal();
		var g164Again = NocatFarm.Config.ConfigStore.LoadGlobal();
		bool Same164(NocatFarm.Config.BotConfig b) =>
			(b.ClaimFree == NocatFarm.Modules.FreeClaims.GamesAndDlc) && b.BoosterPackGames.SequenceEqual<uint>([730, 440]) && (b.BoosterGems == 1) && b.CraftBadges
			&& b.SkipRefundableGames && (b.FarmCardsWhen == NocatFarm.Modules.FarmWhen.Night) && !b.FarmOnlyWhileAsleep && b.AchievementNeverGames.SequenceEqual<uint>([570])
			&& (b.AchievementDlcLeft.Count == 0) && b.LegitMode && (b.GameWeights == "730:80, 440:10, 550:10") && b.IdleGames.SequenceEqual<uint>([730, 440, 550])
			&& !b.OfflineIdleAtNight && (b.AchievementPace == 2) && b.Enabled && (b.SteamLogin == "old164login");
		Check("old config 1.6.4: every choice kept - free games and DLC, booster list, refunds on, cards at night, human mode with its shares, pace",
			Same164(b164) && Same164(b164Again), $"ClaimFree {b164.ClaimFree}, boosters {string.Join(",", b164.BoosterPackGames)}, weights {b164.GameWeights}, cards {b164.FarmCardsWhen}");
		Check("old config 1.6.4: updates at night and a click still waits, the hours kept; the Discord line it had",
			(g164.UpdateMode == NocatFarm.Core.UpdateModes.AtNight) && g164.UpdateClickWaits && (g164.AutoUpdateFromHour == 4) && (g164.AutoUpdateUntilHour == 7)
			&& (g164.DiscordSecondLine == 2) && (g164Again.UpdateMode == g164.UpdateMode) && (g164Again.UpdateClickWaits == g164.UpdateClickWaits),
			$"{g164.UpdateMode} {g164.UpdateClickWaits} {g164.DiscordSecondLine}");
		Check("old config 1.6.4: saved back with only today's keys - none of the old ones written again",
			NoneRetired(OnDisk("old164")) && NoneRetired(File.ReadAllText(NocatFarm.Config.ConfigStore.GlobalPath)) && OnDisk("old164").Contains("\"ClaimFree\": 2", StringComparison.Ordinal)
			&& File.ReadAllText(NocatFarm.Config.ConfigStore.GlobalPath).Contains("\"UpdateMode\": 2", StringComparison.Ordinal),
			OnDisk("old164"));

		// ── 1.6.5 (and up to 1.6.9): the new keys, each with the copy for the version before beside it ──
		File.WriteAllText(Path.Combine(cfgDir, "old165.json"), """
			{
			  "Enabled": true,
			  "SteamLogin": "old165login",
			  "SkipRefundableGames": false,
			  "ProtectGiftedGames": false,
			  "RefundHoldDays": 21,
			  "FarmCardsWhen": 2,
			  "CardSittingsPct": 55,
			  "FarmOnlyWhileAsleep": false,
			  "AchievementDlcTrusted": [500, 440],
			  "AchievementDlcLeft": { "440": "441" },
			  "ClaimFree": 1,
			  "ClaimFreeGames": true,
			  "BoosterPackGames": [730, 440],
			  "BoosterGames": "730, 440",
			  "LegitMode": true,
			  "GameWeights": "730:70, 440:30",
			  "MainGameSharePct": 0,
			  "OfflineIdleAtNight": true,
			  "OfflineIdleTopGames": 2,
			  "OfflineIdleGames": []
			}
			""");
		File.WriteAllText(Path.Combine(cfgDir, "old165off.json"), """
			{ "SteamLogin": "old165off", "ClaimFree": 0, "ClaimFreeGames": false, "BoosterPackGames": [], "OfflineIdleAtNight": false, "OfflineIdleTopGames": 1 }
			""");
		File.WriteAllText(NocatFarm.Config.ConfigStore.GlobalPath, """
			{
			  "DiscordShowNames": true,
			  "DiscordSecondLine": 1,
			  "AutoUpdate": 0,
			  "UpdateWhenAsked": 1,
			  "UpdateMode": 0
			}
			""");
		var b165 = NocatFarm.Config.ConfigStore.LoadBot("old165")!;
		var b165Again = NocatFarm.Config.ConfigStore.LoadBot("old165")!;
		var b165Off = NocatFarm.Config.ConfigStore.LoadBot("old165off")!;
		var g165 = NocatFarm.Config.ConfigStore.LoadGlobal();
		bool Same165(NocatFarm.Config.BotConfig b) =>
			(b.ClaimFree == NocatFarm.Modules.FreeClaims.Games) && b.BoosterPackGames.SequenceEqual<uint>([730, 440]) && !b.SkipRefundableGames
			&& (b.FarmCardsWhen == 2) && (b.CardSittingsPct == 55) && (b.AchievementDlcLeft.GetValueOrDefault(440u) == "441") && (b.AchievementDlcLeft.Count == 1)
			&& b.LegitMode && (b.GameWeights == "730:70, 440:30") && b.OfflineIdleAtNight && (b.OfflineIdleTopGames == 2);
		Check("old config 1.6.5: every choice kept - the new keys win, the copies beside them read as nothing; overnight banking stays on",
			Same165(b165) && Same165(b165Again), $"ClaimFree {b165.ClaimFree}, boosters {string.Join(",", b165.BoosterPackGames)}, left {b165.AchievementDlcLeft.Count}, night {b165.OfflineIdleAtNight}");
		Check("old config 1.6.5: off stays off - no free games, no boosters, no overnight banking",
			(b165Off.ClaimFree == NocatFarm.Modules.FreeClaims.Off) && (b165Off.BoosterPackGames.Count == 0) && !b165Off.OfflineIdleAtNight);
		Check("old config 1.6.5: once everyone's asleep kept (a click waits), the old AutoUpdate copy ignored; the Discord line moved as before",
			(g165.UpdateMode == NocatFarm.Core.UpdateModes.JustTellMe) && g165.UpdateClickWaits && (g165.DiscordSecondLine == NocatFarm.Core.DiscordPresence.LineAccounts),
			$"{g165.UpdateMode} {g165.UpdateClickWaits} {g165.DiscordSecondLine}");
		NocatFarm.Config.ConfigStore.SaveBot("old165", b165);
		NocatFarm.Config.ConfigStore.SaveGlobal(g165);
		Check("old config 1.6.5: saved back with only today's keys",
			NoneRetired(OnDisk("old165")) && NoneRetired(File.ReadAllText(NocatFarm.Config.ConfigStore.GlobalPath))
			&& Same165(NocatFarm.Config.ConfigStore.LoadBot("old165")!) && (NocatFarm.Config.ConfigStore.LoadGlobal().UpdateMode == NocatFarm.Core.UpdateModes.JustTellMe),
			OnDisk("old165"));
	} finally {
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
			// temp - it goes when Windows tidies up
		}
	}
}

// ── simpler settings: one switch for refunds ──────────────────────────────────────────────────────────────
{
	var protect = NocatFarm.Config.Settings.FindBot("SkipRefundableGames");
	Check("refunds: one visible switch, \"Protect refunds\", under What it plays, on every kind of account",
		protect is { Label: "Protect refunds", Advanced: false, Mode: "any", Kind: NocatFarm.Config.SettingKind.Bool } && (protect.Section == NocatFarm.Config.Settings.SecPlaying));
	Check("refunds: gifted games, family games and the day count aren't settings any more",
		new[] { "ProtectGiftedGames", "RefundHoldDays", "HoldNewFamilyGames" }.All(static n => NocatFarm.Config.Settings.Find(n) == null));
	Check("refunds: Steam's own 14 days, and gifted games count", (NocatFarm.Core.RefundGuard.HoldDays == 14)
		&& new NocatFarm.Core.AppOwnership(DateTime.UtcNow, false, true, Gift: true).Refundable && !new NocatFarm.Core.AppOwnership(DateTime.UtcNow, false, true).Refundable);
	Check("refunds: on for a new account (1.8.2) - an account from before keeps what it had", new NocatFarm.Config.BotConfig().SkipRefundableGames);
	Check("refunds: the tooltips no longer say refundable games are skipped regardless",
		new[] { "IdleWholeLibrary", "NewGamesFirst", "JoinFriends" }.All(static n => NocatFarm.Config.Settings.FindBot(n)!.Tooltip.Contains("\"Protect refunds\"", StringComparison.Ordinal)));

	string realRoot = NocatFarm.Config.ConfigStore.Root;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-simple-" + Guid.NewGuid().ToString("N"));
	Directory.CreateDirectory(Path.Combine(tmpRoot, "config"));
	NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);

	try {
		string Write(string name, string json) { File.WriteAllText(Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, name + ".json"), json); return name; }
		string OnDisk(string name) => File.ReadAllText(Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, name + ".json"));

		// An account that had it all on, gifted games off and a 30-day hold: protection stays on (that's the choice that
		// matters), and the folded-in keys are gone from the file once it's saved.
		var on = NocatFarm.Config.ConfigStore.LoadBot(Write("refund-on", "{\"SkipRefundableGames\":true,\"ProtectGiftedGames\":false,\"RefundHoldDays\":30,\"HoldNewFamilyGames\":false}"))!;
		NocatFarm.Config.ConfigStore.SaveBot("refund-on", on);
		var off = NocatFarm.Config.ConfigStore.LoadBot(Write("refund-off", "{\"SkipRefundableGames\":false,\"ProtectGiftedGames\":true}"))!;
		Check("refunds migration: an old file keeps its switch as it was, on or off", on.SkipRefundableGames && !off.SkipRefundableGames);
		Check("refunds migration: the folded-in keys are read by nothing, and gone from the file at its next save",
			!OnDisk("refund-on").Contains("ProtectGiftedGames", StringComparison.Ordinal) && !OnDisk("refund-on").Contains("RefundHoldDays", StringComparison.Ordinal)
			&& !OnDisk("refund-on").Contains("HoldNewFamilyGames", StringComparison.Ordinal) && OnDisk("refund-on").Contains("\"SkipRefundableGames\": true", StringComparison.Ordinal)
			&& new[] { "ProtectGiftedGames", "RefundHoldDays", "HoldNewFamilyGames" }.All(static n => typeof(NocatFarm.Config.BotConfig).GetProperty(n) == null));
		NocatFarm.Config.ConfigStore.SaveBot("refund-new", new NocatFarm.Config.BotConfig { SkipRefundableGames = true });
		Check("refunds: a new account's file doesn't get them",
			!OnDisk("refund-new").Contains("ProtectGiftedGames", StringComparison.Ordinal) && !OnDisk("refund-new").Contains("RefundHoldDays", StringComparison.Ordinal)
			&& !OnDisk("refund-new").Contains("HoldNewFamilyGames", StringComparison.Ordinal));
		// Free games: three chained switches became one choice - off, games, games and DLC.
		var claim = NocatFarm.Config.Settings.FindBot("ClaimFree");
		Check("free games: one choice, off / games / games and DLC, off by default",
			claim is { Kind: NocatFarm.Config.SettingKind.Choice, Advanced: false } && (NocatFarm.Config.Settings.ParseChoices(claim).Count == 3)
			&& (new NocatFarm.Config.BotConfig().ClaimFree == NocatFarm.Modules.FreeClaims.Off)
			&& new[] { "ClaimFreeGames", "ClaimFreeDlc", "ClaimFreeDlcBase" }.All(static n => NocatFarm.Config.Settings.Find(n) == null));
		var typed = new NocatFarm.Config.BotConfig();
		Check("free games: typed by name at the console", (NocatFarm.Config.Settings.Apply(typed, claim!, "games and DLC") == null) && (typed.ClaimFree == 2)
			&& (NocatFarm.Config.Settings.Apply(typed, claim!, "games") == null) && (typed.ClaimFree == 1));
		int Claimed(string name, string json) => NocatFarm.Config.ConfigStore.LoadBot(Write(name, json))!.ClaimFree;
		Check("free games migration: games on -> games", Claimed("free-games", "{\"ClaimFreeGames\":true}") == NocatFarm.Modules.FreeClaims.Games);
		Check("free games migration: games and DLC on (its game switch off or on) -> games and DLC",
			(Claimed("free-dlc", "{\"ClaimFreeGames\":true,\"ClaimFreeDlc\":true,\"ClaimFreeDlcBase\":false}") == NocatFarm.Modules.FreeClaims.GamesAndDlc)
			&& (Claimed("free-dlc2", "{\"ClaimFreeGames\":true,\"ClaimFreeDlc\":true}") == NocatFarm.Modules.FreeClaims.GamesAndDlc));
		Check("free games migration: DLC on without games did nothing, so stays off; nothing set stays off",
			(Claimed("free-onlydlc", "{\"ClaimFreeDlc\":true}") == NocatFarm.Modules.FreeClaims.Off) && (Claimed("free-none", "{\"Enabled\":true}") == NocatFarm.Modules.FreeClaims.Off));
		Check("free games migration: written back as the one choice only - the old switches gone from the file",
			OnDisk("free-dlc").Contains("\"ClaimFree\": 2", StringComparison.Ordinal) && !OnDisk("free-dlc").Contains("\"ClaimFreeGames\"", StringComparison.Ordinal)
			&& !OnDisk("free-dlc").Contains("\"ClaimFreeDlc", StringComparison.Ordinal));
		Check("free games: games only is written as ClaimFree 1, off as 0, with none of the old switches",
			OnDisk("free-games").Contains("\"ClaimFree\": 1", StringComparison.Ordinal) && !OnDisk("free-games").Contains("\"ClaimFreeGames\"", StringComparison.Ordinal)
			&& !OnDisk("free-games").Contains("\"ClaimFreeDlc", StringComparison.Ordinal) && !OnDisk("free-onlydlc").Contains("\"ClaimFreeGames\"", StringComparison.Ordinal));
		Check("free games: the new choice wins over the copy beside it (read twice, and edited by hand to disagree)",
			(Claimed("free-dlc", OnDisk("free-dlc")) == NocatFarm.Modules.FreeClaims.GamesAndDlc)
			&& (Claimed("free-hand", "{\"ClaimFree\":1,\"ClaimFreeGames\":true,\"ClaimFreeDlc\":true}") == NocatFarm.Modules.FreeClaims.Games)
			&& (Claimed("free-off", "{\"ClaimFree\":0,\"ClaimFreeGames\":true}") == NocatFarm.Modules.FreeClaims.Off));
		List<string> freeSaid = [];
		void FreeHeard(NocatFarm.Log.Entry e) {
			if (e.Said.ToEnglish().Contains("Claim free games now also claims", StringComparison.Ordinal)) {
				lock (freeSaid) {
					freeSaid.Add(e.Source + "|" + e.Said.ToEnglish());
				}
			}
		}
		NocatFarm.Log.Written += FreeHeard;
		Claimed("free-base-off", "{\"ClaimFreeGames\":true,\"ClaimFreeDlc\":true,\"ClaimFreeDlcBase\":false}");
		Claimed("free-base-off", OnDisk("free-base-off"));
		Claimed("free-base-on", "{\"ClaimFreeGames\":true,\"ClaimFreeDlc\":true,\"ClaimFreeDlcBase\":true}");
		NocatFarm.Log.Written -= FreeHeard;
		Check("free games migration: games and DLC with its game's switch off says once that free DLC's games are claimed now",
			(freeSaid.Count == 1) && freeSaid[0].StartsWith("free-base-off|free-base-off: Claim free games now also claims a free DLC's game", StringComparison.Ordinal),
			string.Join(" / ", freeSaid));
		Check("free games migration: an already-moved file is left as it is", Claimed("free-new", "{\"ClaimFree\":2}") == NocatFarm.Modules.FreeClaims.GamesAndDlc);
		// Updates: "Update by itself" and "When I say update" became one choice - nobody's updates behave any differently.
		var mode = NocatFarm.Config.Settings.FindGlobal("UpdateMode");
		Check("updates: one visible choice - ask me (once asleep / right away) / install by itself at night / don't look",
			mode is { Kind: NocatFarm.Config.SettingKind.Choice, Advanced: false } && (NocatFarm.Config.Settings.ParseChoices(mode).Count == 4)
			&& (NocatFarm.Config.Settings.FindGlobal("AutoUpdate") == null) && (NocatFarm.Config.Settings.FindGlobal("UpdateWhenAsked") == null));
		var freshG = new NocatFarm.Config.GlobalConfig();
		Check("updates: a new install is \"install when I click\" - the same as before (tell me, right away)",
			(freshG.UpdateMode == NocatFarm.Core.UpdateModes.WhenIClick) && !freshG.UpdateClickWaits);
		(int Mode, bool Waits, string File) Global(string json) {
			File.WriteAllText(NocatFarm.Config.ConfigStore.GlobalPath, json);
			NocatFarm.Config.GlobalConfig g = NocatFarm.Config.ConfigStore.LoadGlobal();
			NocatFarm.Config.GlobalConfig again = NocatFarm.Config.ConfigStore.LoadGlobal();   // read twice: the move happens once

			return (again.UpdateMode == g.UpdateMode) && (again.UpdateClickWaits == g.UpdateClickWaits)
				? (g.UpdateMode, g.UpdateClickWaits, File.ReadAllText(NocatFarm.Config.ConfigStore.GlobalPath))
				: (-1, false, "changed on the second read");
		}
		var tellNow = Global("{\"AutoUpdate\":0,\"UpdateWhenAsked\":0}");
		var tellWait = Global("{\"AutoUpdate\":0,\"UpdateWhenAsked\":1}");
		var nightNow = Global("{\"AutoUpdate\":1,\"UpdateWhenAsked\":0}");
		var nightWait = Global("{\"AutoUpdate\":1,\"UpdateWhenAsked\":1}");
		Check("updates migration: tell me + right away -> install when I click (a click installs now)", (tellNow.Mode == 1) && !tellNow.Waits, tellNow.File);
		Check("updates migration: tell me + when asleep -> once everyone's asleep (a click waits)", (tellWait.Mode == 0) && tellWait.Waits, tellWait.File);
		Check("updates migration: install at night + right away -> at night, a click installs now", (nightNow.Mode == 2) && !nightNow.Waits, nightNow.File);
		Check("updates migration: install at night + when asleep -> at night, and a click still waits", (nightWait.Mode == 2) && nightWait.Waits, nightWait.File);
		Check("updates migration: written as the one choice - no AutoUpdate in the file; at night keeps what a click does beside it",
			!nightWait.File.Contains("\"AutoUpdate\"", StringComparison.Ordinal) && nightWait.File.Contains("\"UpdateWhenAsked\": 1", StringComparison.Ordinal)
			&& nightWait.File.Contains("\"UpdateMode\": 2", StringComparison.Ordinal)
			&& !nightNow.File.Contains("\"AutoUpdate\"", StringComparison.Ordinal) && nightNow.File.Contains("\"UpdateWhenAsked\": 0", StringComparison.Ordinal));
		Check("updates: once everyone's asleep needs nothing beside it - UpdateMode alone, no AutoUpdate, no click-waits",
			tellWait.File.Contains("\"UpdateMode\": 0", StringComparison.Ordinal) && tellWait.File.Contains("\"UpdateWhenAsked\": 0", StringComparison.Ordinal)
			&& !tellWait.File.Contains("\"AutoUpdate\"", StringComparison.Ordinal));
		NocatFarm.Config.GlobalConfig switched = NocatFarm.Config.ConfigStore.LoadGlobal();
		NocatFarm.Config.Settings.Apply(switched, mode!, "1");
		NocatFarm.Config.ConfigStore.SaveGlobal(switched);
		NocatFarm.Config.GlobalConfig rereadG = NocatFarm.Config.ConfigStore.LoadGlobal();
		string clickFile = File.ReadAllText(NocatFarm.Config.ConfigStore.GlobalPath);
		Check("updates: choosing another one later sticks (the old click-waits doesn't bring it back)", (rereadG.UpdateMode == 1) && !rereadG.UpdateClickWaits
			&& !clickFile.Contains("\"AutoUpdate\"", StringComparison.Ordinal) && clickFile.Contains("\"UpdateWhenAsked\": 0", StringComparison.Ordinal), clickFile);
		var handEdited = Global("{\"AutoUpdate\":1,\"UpdateWhenAsked\":1,\"UpdateMode\":1}");
		Check("updates: once the new key is in the file it wins over the copy beside it", (handEdited.Mode == 1) && !handEdited.Waits, handEdited.File);
		string tutJs = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "wwwroot", "app.js")).Replace("\r\n", "\n");
		Check("updates: the first-run setup switching \"Keep it up to date by itself\" off keeps what a click did - it waited, so once everyone's asleep; else install when I click",
			tutJs.Contains("const mode = d.autoUpdate ? 2 : (g.UpdateMode === 2 ? (g.UpdateWhenAsked === 1 ? 0 : 1) : g.UpdateMode);", StringComparison.Ordinal));
		// --setup takes UpdateMode; the old AutoUpdate= alias is gone (the installer never passed it) and is refused like any
		// other unknown choice, leaving the settings as they were.
		File.WriteAllText(NocatFarm.Config.ConfigStore.GlobalPath, "{\"UpdateMode\":1}");
		int oldAlias = NocatFarm.Config.SetupChoices.Run(["AutoUpdate=1"]);
		int afterAlias = NocatFarm.Config.ConfigStore.LoadGlobal().UpdateMode;
		int setup = NocatFarm.Config.SetupChoices.Run(["UpdateMode=2"]);
		Check("updates: a setup takes UpdateMode; the old AutoUpdate= alias is refused and changes nothing",
			(oldAlias == 2) && (afterAlias == 1) && (setup == 0) && (NocatFarm.Config.ConfigStore.LoadGlobal().UpdateMode == 2), $"{oldAlias} {afterAlias} {setup}");
		string installerCode = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "tools", "installer", "code.iss"));
		Check("updates: the installer never passes AutoUpdate to --setup", !installerCode.Contains("AutoUpdate", StringComparison.OrdinalIgnoreCase));
		// Booster games: a text box of numbers became a game list like the others.
		var boostDef = NocatFarm.Config.Settings.FindBot("BoosterPackGames");
		Check("boosters: a game list now, and the old name still finds it ('set new BoosterGames 730')",
			boostDef is { Kind: NocatFarm.Config.SettingKind.AppIds } && (NocatFarm.Config.Settings.FindBot("BoosterGames")?.Name == "BoosterPackGames"));
		var bcfg = NocatFarm.Config.ConfigStore.LoadBot(Write("boost-old", "{\"BoosterGames\":\"730, 440 ;x 0 440\"}"))!;
		Check("boosters migration: the typed list becomes the game list, junk and repeats dropped, and the text is gone from the file",
			bcfg.BoosterPackGames.SequenceEqual<uint>([730, 440]) && (bcfg.BoosterGames == null) && !OnDisk("boost-old").Contains("\"BoosterGames\"", StringComparison.Ordinal)
			&& System.Text.RegularExpressions.Regex.IsMatch(OnDisk("boost-old"), @"""BoosterPackGames"":\s*\[\s*730,\s*440\s*\]"),
			string.Join(",", bcfg.BoosterPackGames));
		var bhand = NocatFarm.Config.ConfigStore.LoadBot(Write("boost-hand", "{\"BoosterPackGames\":[730],\"BoosterGames\":\"730, 440\"}"))!;
		Check("boosters: once the list is in the file it wins - a game taken off it doesn't come back from the copy",
			bhand.BoosterPackGames.SequenceEqual<uint>([730]) && (bhand.BoosterGames == null), string.Join(",", bhand.BoosterPackGames));
		var bempty = NocatFarm.Config.ConfigStore.LoadBot(Write("boost-empty", "{\"BoosterGames\":\"\"}"))!;
		Check("boosters migration: an empty one is just empty", (bempty.BoosterPackGames.Count == 0) && !OnDisk("boost-empty").Contains("\"BoosterGames\"", StringComparison.Ordinal));
		Check("boosters: the module reads the list", NocatFarm.Modules.Boosters.Games(new NocatFarm.Core.Bot("harness-boost", bcfg)).SequenceEqual<uint>([730, 440]));
		// Wind-down: 5-12 was the old default once, and a one-time migration turned it into 15-20 on every load - so somebody
		// who picked 5-12 on purpose could never keep it. A load leaves it alone now, and again on the next load.
		var wind = NocatFarm.Config.ConfigStore.LoadBot(Write("wind-5-12", "{\"PostFarmWindDownMinMinutes\":5,\"PostFarmWindDownMaxMinutes\":12}"))!;
		var windAgain = NocatFarm.Config.ConfigStore.LoadBot("wind-5-12")!;
		Check("wind-down: 5-12 chosen on purpose survives a load, and the next one",
			(wind.PostFarmWindDownMinMinutes == 5) && (wind.PostFarmWindDownMaxMinutes == 12) && (windAgain.PostFarmWindDownMinMinutes == 5) && (windAgain.PostFarmWindDownMaxMinutes == 12),
			$"{wind.PostFarmWindDownMinMinutes}-{wind.PostFarmWindDownMaxMinutes}");
		// Overnight: a file from before the top-games number with the switch on and nothing listed banked nothing - it keeps
		// banking nothing. Said once.
		List<string> nightSaid = [];
		void NightHeard(NocatFarm.Log.Entry e) {
			if (e.Said.ToEnglish().Contains("Bank hours overnight was on with no games listed", StringComparison.Ordinal)) {
				lock (nightSaid) {
					nightSaid.Add(e.Said.ToEnglish());
				}
			}
		}
		NocatFarm.Log.Written += NightHeard;
		var nightOld = NocatFarm.Config.ConfigStore.LoadBot(Write("night-old", "{\"LegitMode\":true,\"OfflineIdleAtNight\":true,\"OfflineIdleGames\":[]}"))!;
		var nightAgain = NocatFarm.Config.ConfigStore.LoadBot("night-old")!;
		var nightListed = NocatFarm.Config.ConfigStore.LoadBot(Write("night-listed", "{\"OfflineIdleAtNight\":true,\"OfflineIdleGames\":[730]}"))!;
		var nightOff = NocatFarm.Config.ConfigStore.LoadBot(Write("night-off", "{\"OfflineIdleAtNight\":false}"))!;
		var nightBare = NocatFarm.Config.ConfigStore.LoadBot(Write("night-bare", "{\"LegitMode\":true}"))!;
		var nightNew = NocatFarm.Config.ConfigStore.LoadBot(Write("night-new", "{\"OfflineIdleAtNight\":true,\"OfflineIdleGames\":[],\"OfflineIdleTopGames\":2}"))!;
		NocatFarm.Config.ConfigStore.SaveBot("night-fresh", new NocatFarm.Config.BotConfig());
		var nightFresh = NocatFarm.Config.ConfigStore.LoadBot("night-fresh")!;
		NocatFarm.Log.Written -= NightHeard;
		Check("overnight migration: on with nothing listed, from before the top-games number - switched off, so nothing changes; said once",
			!nightOld.OfflineIdleAtNight && !nightAgain.OfflineIdleAtNight && OnDisk("night-old").Contains("\"OfflineIdleTopGames\": 1", StringComparison.Ordinal)
			&& (nightSaid.Count == 1) && (nightSaid[0] == "night-old: Bank hours overnight was on with no games listed, which banked nothing - switched off so nothing changes. Turn it on to idle its most-played games overnight."),
			string.Join(" / ", nightSaid));
		Check("overnight migration: a list with games, off already, a file without the switch, one written since, and a new account are left alone",
			nightListed.OfflineIdleAtNight && !nightOff.OfflineIdleAtNight && nightBare.OfflineIdleAtNight && nightNew.OfflineIdleAtNight && nightFresh.OfflineIdleAtNight);
		// Back to the version before by hand: it saves the file without the top-games number. The owner had turned the
		// switch on since; updating again must not switch it off a second time.
		var nightRolled = NocatFarm.Config.ConfigStore.LoadBot(Write("night-old", "{\"LegitMode\":true,\"OfflineIdleAtNight\":true,\"OfflineIdleGames\":[]}"))!;
		Check("overnight migration: once seen, a file the version before saved again is left as it is",
			nightRolled.OfflineIdleAtNight && File.Exists(Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", "overnight-night-old.seen"))
			&& !NocatFarm.Config.ConfigStore.MigrateOvernight(new NocatFarm.Config.BotConfig { OfflineIdleAtNight = true }, "x", seenBefore: true));
		// SIMPLE-MIGRATIONS
	} finally {
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);
		try { Directory.Delete(tmpRoot, true); } catch (IOException) { }
	}
}

// ── simpler settings: banking overnight with nothing on the list ─────────────────────────────────────────────────
{
	string Src(string rel) => File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", rel)).Replace("\r\n", "\n");
	List<NocatFarm.Config.SettingDef> bot = [.. NocatFarm.Config.Settings.Bot];
	int at = bot.FindIndex(static d => d.Name == "OfflineIdleAtNight");
	Check("overnight: the list and the top-games number sit right under the switch, shown while it's on, human mode only; the number behind Show advanced",
		(at >= 0) && (bot[at + 1].Name == "OfflineIdleGames") && (bot[at + 2].Name == "OfflineIdleTopGames")
		&& bot.Skip(at).Take(3).All(static d => d.Mode == "legit") && !bot[at].Advanced && !bot[at + 1].Advanced && bot[at + 2].Advanced
		&& bot.Skip(at + 1).Take(2).All(static d => d.ShowWhen == "OfflineIdleAtNight=true"));
	Check("overnight: the top-games number is 1 to 10, 1 by default", bot[at + 2] is { Kind: NocatFarm.Config.SettingKind.Int, Min: 1.0, Max: 10.0 }
		&& (new NocatFarm.Config.BotConfig().OfflineIdleTopGames == 1));

	List<NocatFarm.Core.Library.Entry> lib = [
		new(730, "CS2", 90000, DateTime.MinValue, 0), new(440, "TF2", 50000, DateTime.MinValue, 0), new(570, "Dota 2", 40000, DateTime.MinValue, 0),
		new(620, "Portal 2", 3000, DateTime.MinValue, 0), new(550, "L4D2", 2000, DateTime.MinValue, 0), new(4000, "GMod", 1000, DateTime.MinValue, 0),
		new(8001, "Borrowed", 99999, DateTime.MinValue, 76561198000000001), new(999, "Never played", 0, DateTime.MinValue, 0)
	];
	Check("overnight: the most-played first, only games actually played, as many as asked",
		NocatFarm.Modules.HumanMode.TopPlayed(lib, 3, static a => a != 8001).SequenceEqual<uint>([730, 440, 570])
		&& NocatFarm.Modules.HumanMode.TopPlayed(lib, 10, static a => a != 8001).Count == 6
		&& !NocatFarm.Modules.HumanMode.TopPlayed(lib, 10, static _ => true).Contains(999u));

	var cfg = new NocatFarm.Config.BotConfig { LegitMode = true, GameWeights = "730:70, 440:30", BlacklistedGames = [730], SkipRefundableGames = true };
	var nb = new NocatFarm.Core.Bot("harness-night-top", cfg);
	var hm = new NocatFarm.Modules.HumanMode(nb);
	nb.AddModule(hm);
	BindingFlags inst = BindingFlags.NonPublic | BindingFlags.Instance;
	typeof(NocatFarm.Core.Library).GetField("_games", inst)!.SetValue(nb.Library, lib);
	typeof(NocatFarm.Core.Library).GetField("_byApp", inst)!.SetValue(nb.Library, lib.ToDictionary(static e => e.AppId));
	typeof(NocatFarm.Core.Library).GetProperty("Ready")!.SetValue(nb.Library, true);
	typeof(NocatFarm.Core.RefundGuard).GetField("_held", inst)!.SetValue(nb.Refunds, new HashSet<uint> { 440 });
	Check("overnight: an empty list idles the top game it may play - not the blacklisted one, not one held for a refund, not a family game",
		hm.NightPicked.SequenceEqual<uint>([570]) && (hm.NightGameCount == 1) && (hm.NightPickedNames(hm.NightPicked) == "Dota 2"), string.Join(",", hm.NightPicked));
	cfg.IncludeFamilyLibrary = true;
	Check("overnight: a family game counts once shared games are allowed", hm.NightPicked.SequenceEqual<uint>([8001]));
	cfg.IncludeFamilyLibrary = false;
	var bw = new NocatFarm.Modules.BanWatch(nb);
	nb.AddModule(bw);
	Type savedT = typeof(NocatFarm.Modules.BanWatch).GetNestedType("Saved", BindingFlags.NonPublic)!;
	typeof(NocatFarm.Modules.BanWatch).GetField("_loaded", inst)!.SetValue(bw, true);
	typeof(NocatFarm.Modules.BanWatch).GetField("_seen", inst)!.SetValue(bw, Activator.CreateInstance(savedT, 0, 1, false, "none", 0, 0L, new List<uint> { 570 }));
	Check("overnight: not a game Steam has it banned in", hm.NightPicked.SequenceEqual<uint>([620]), string.Join(",", hm.NightPicked));
	typeof(NocatFarm.Modules.BanWatch).GetField("_seen", inst)!.SetValue(bw, Activator.CreateInstance(savedT, 0, 0, false, "none", 0, 0L, null));
	cfg.OfflineIdleTopGames = 3;
	Check("overnight: the number sets how many", hm.NightPicked.SequenceEqual<uint>([570, 620, 550]) && (hm.NightGameCount == 3));
	Check("overnight: selfcheck counts the games it really banks (the picked ones)", NocatFarm.Core.SelfCheck.NightGames(nb) == 3);
	cfg.OfflineIdleGames = [4000];
	Check("overnight: a list with games wins, and the number is ignored", (hm.NightPicked.Count == 0) && (hm.NightGameCount == 1) && (NocatFarm.Core.SelfCheck.NightGames(nb) == 1));
	cfg.OfflineIdleGames = [440, 730, 8001, 4000, 77777];
	Check("overnight: the list goes by the same rules as the games it picks - not held for a refund, blacklisted or a family game; one the library doesn't show still goes on",
		hm.NightGameCount == 2, $"{hm.NightGameCount}");
	cfg.IncludeFamilyLibrary = true;
	Check("overnight: a family game on the list goes on once shared games are allowed", hm.NightGameCount == 3, $"{hm.NightGameCount}");
	cfg.IncludeFamilyLibrary = false;

	// The self-check's advice goes by what the list puts on, not by the dated hour target that needs the night too: with a
	// list of one it doesn't say to cut the list down to one or two.
	cfg.OfflineIdleGames = [4000];
	cfg.HourTargets = $"620:1000@{DateTime.Now.AddDays(5):yyyy-MM-dd}";
	typeof(NocatFarm.Core.Library).GetField("_twoWeeks", inst)!.SetValue(nb.Library, new Dictionary<uint, int> { [4000] = 14 * 24 * 60 + 600 });
	MethodInfo score = typeof(NocatFarm.Core.SelfCheck).GetMethod("Score", BindingFlags.NonPublic | BindingFlags.Static)!;
	var report = (NocatFarm.Core.SelfCheck.Report) score.Invoke(null, [nb, null])!;
	string fixes = string.Join(" | ", report.Tells.Select(static t => t.Fix));
	Check("self-check: a list of one and an hour target - the advice is about the target, not \"cut it down to one or two\"",
		(hm.NightGameCount == 2) && fixes.Contains("dated hour targets", StringComparison.Ordinal) && !fixes.Contains("down to one or two", StringComparison.Ordinal), fixes);
	cfg.HourTargets = "";
	cfg.OfflineIdleGames = [4000, 620, 550];
	report = (NocatFarm.Core.SelfCheck.Report) score.Invoke(null, [nb, null])!;
	fixes = string.Join(" | ", report.Tells.Select(static t => t.Fix));
	Check("self-check: a list of three still says to cut it down", fixes.Contains("it banks 3 games at once every night - cut OfflineIdleGames down to one or two", StringComparison.Ordinal), fixes);
	typeof(NocatFarm.Core.Library).GetField("_twoWeeks", inst)!.SetValue(nb.Library, new Dictionary<uint, int>());
	cfg.OfflineIdleGames = [4000];

	// A drop run on an account that farms at night or any time: the hidden card-sittings share doesn't raise its share of
	// the day - only the main game's does. With "mixed" (where the share shows) the higher of the two, as before.
	var shareCfg = new NocatFarm.Config.BotConfig { CardSittingsPct = 90, FarmCardsWhen = NocatFarm.Modules.FarmWhen.Night };
	int nightShare = NocatFarm.Modules.HumanMode.CardShare(shareCfg, true, 60);
	shareCfg.FarmCardsWhen = NocatFarm.Modules.FarmWhen.Any;
	int anyShare = NocatFarm.Modules.HumanMode.CardShare(shareCfg, true, 60);
	shareCfg.FarmCardsWhen = NocatFarm.Modules.FarmWhen.Mixed;
	int mixedShare = NocatFarm.Modules.HumanMode.CardShare(shareCfg, true, 60);
	int mixedNoRun = NocatFarm.Modules.HumanMode.CardShare(shareCfg, false, 60);
	Check("drop run: farming at night or any time uses the main game's share, not the hidden card-sittings one; mixed keeps the higher",
		(nightShare == 60) && (anyShare == 60) && (mixedShare == 90) && (mixedNoRun == 90), $"{nightShare} {anyShare} {mixedShare} {mixedNoRun}");
	cfg.OfflineIdleGames = [];
	cfg.OfflineIdleAtNight = false;
	Check("overnight: nothing is picked with banking overnight off", hm.NightPicked.Count == 0);
	cfg.OfflineIdleAtNight = true;
	cfg.LegitMode = false;
	Check("overnight: nor on a robot account", hm.NightPicked.Count == 0);
	cfg.LegitMode = true;
	typeof(NocatFarm.Core.Library).GetField("_games", inst)!.SetValue(nb.Library, new List<NocatFarm.Core.Library.Entry>());
	typeof(NocatFarm.Core.Library).GetField("_byApp", inst)!.SetValue(nb.Library, new Dictionary<uint, NocatFarm.Core.Library.Entry>());
	Check("overnight: nothing it may play - nothing picked, and the status says to add games", (hm.NightPicked.Count == 0) && (hm.NightGameCount == 0)
		&& Src("Modules/HumanMode.cs").Contains("Phase.Asleep when NothingToBank => Loc.T(\"asleep · up {0} · nothing to bank overnight - add games to the overnight list\"", StringComparison.Ordinal));
	Check("overnight: the status names the games it picked itself",
		Src("Modules/HumanMode.cs").Contains("Phase.NightIdle when NightPicked is { Count: > 0 } picked => Loc.T(\"asleep, no games chosen - idling your {0} most-played game(s): {1} · up {2}\"", StringComparison.Ordinal));
	string js = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "wwwroot", "app.js")).Replace("\r\n", "\n");
	Check("overnight: the Human mode panel names the picked games, or says to add some", js.Contains("card.NightPicked", StringComparison.Ordinal)
		&& js.Contains("t('Nothing to bank overnight yet: add games to \"Games to idle overnight\".')", StringComparison.Ordinal));
}

// ── simpler settings: card farming's when, only where it means something ─────────────────────────────────────────
{
	var farmWhen = NocatFarm.Config.Settings.FindBot("FarmCardsWhen")!;
	var cardShare = NocatFarm.Config.Settings.FindBot("CardSittingsPct")!;
	Check("cards: \"When to farm cards\" is human mode only, and its tooltip has no console example",
		(farmWhen.Mode == "legit") && !farmWhen.Tooltip.Contains("drops ", StringComparison.Ordinal) && !farmWhen.Tooltip.Contains("<account>", StringComparison.Ordinal));
	Check("cards: the share of card sittings shows only with \"mixed\"", (cardShare.ShowWhen == $"FarmCardsWhen={NocatFarm.Modules.FarmWhen.Mixed}")
		&& (cardShare.Mode == "legit") && !cardShare.Label.Contains("mixed", StringComparison.Ordinal));
	Check("cards: the clock window is for robot accounts", new[] { "FarmFromHour", "FarmUntilHour" }.All(static n => NocatFarm.Config.Settings.FindBot(n) is { Mode: "rage" }));
	Check("settings: ShowWhen names a real setting, with a value it can have", NocatFarm.Config.Settings.Bot.Concat(NocatFarm.Config.Settings.Global)
		.Where(static d => d.ShowWhen != null).All(static d => d.ShowWhen!.Split('=') is [{ } k, { Length: > 0 }] && (NocatFarm.Config.Settings.Find(k.TrimEnd('!')) != null)));

	// The window, an hour or two from now, so now is outside it whatever the day's jitter: a robot waits, a human-mode
	// account doesn't (its own day and "When to farm cards" decide), and its numbers stay in the file.
	int h = DateTime.Now.Hour;
	var wcfg = new NocatFarm.Config.BotConfig { FarmFromHour = (h + 2) % 24, FarmUntilHour = (h + 3) % 24 };
	var wbot = new NocatFarm.Core.Bot("harness-farm-window", wcfg);
	var farmer = new NocatFarm.Modules.CardFarmer(wbot);
	MethodInfo inWindow = typeof(NocatFarm.Modules.CardFarmer).GetMethod("InFarmWindow", BindingFlags.NonPublic | BindingFlags.Instance)!;
	bool robotIn = (bool) inWindow.Invoke(farmer, [])!;
	wcfg.LegitMode = true;
	bool humanIn = (bool) inWindow.Invoke(farmer, [])!;
	Check("cards: outside the clock window a robot waits; a human-mode account isn't held by it, and keeps the numbers",
		!robotIn && humanIn && (wcfg.FarmFromHour == (h + 2) % 24));

	string js = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "wwwroot", "app.js")).Replace("\r\n", "\n");
	Check("settings page: a ShowWhen setting is drawn only under that answer, unsaved edits included",
		js.Contains("if (!shownWhen(d, values)) return false;", StringComparison.Ordinal)
		&& js.Contains("const value = String(liveValue(def.ShowWhen.slice(0, not ? at - 1 : at), values));", StringComparison.Ordinal));
}

// ── simpler commands: one listed name each, older names still work, the hand tools last ───────────────────────────
{
	string? Canon(string w) => NocatFarm.Commands.Resolve(w)?.Name;
	Check("commands: the old names still reach their command", (Canon("name") == "gamename") && (Canon("unlock") == "dashboard") && (Canon("weekly") == "report")
		&& (Canon("loot") == "send") && (Canon("bots") == "status") && (Canon("cheevo") == "achievements") && (Canon("ach") == "achievements"));
	Check("commands: listed as gamename, achievements and dashboard unlock - no 'name', 'cheevo' or 'unlock' command of their own",
		!NocatFarm.Commands.All.Any(static c => c.Name is "name" or "cheevo" or "unlock") && NocatFarm.Commands.All.Any(static c => (c.Name == "dashboard") && c.Args.Contains("unlock", StringComparison.Ordinal)));
	Check("commands: the hidden names aren't shown", NocatFarm.Commands.All.All(static c => !c.Display.Split('|').Any(a => a is "name" or "unlock" or "weekly" or "loot" or "bots")));
	List<string> order = [.. NocatFarm.Commands.All.Select(static c => c.Group).Distinct()];
	Check("commands: an Advanced group, last, with the hand tools in it", (order[^1] == NocatFarm.Commands.GroupAdvanced)
		&& new[] { "fairswap", "addlicense", "reload", "screen" }.All(static n => NocatFarm.Commands.All.Single(c => c.Name == n).Group == NocatFarm.Commands.GroupAdvanced));
	string Help(params string[] args) => (string) typeof(NocatFarm.Commands).GetMethod("Help", BindingFlags.NonPublic | BindingFlags.Static)!.Invoke(null, [args])!;
	string all = Help();
	Check("help: Advanced is the last group, and no hidden name is listed", all.IndexOf("ADVANCED", StringComparison.Ordinal) > all.IndexOf("THE APP", StringComparison.Ordinal)
		&& !all.Contains("|bots", StringComparison.Ordinal) && !all.Contains("|loot", StringComparison.Ordinal) && !all.Contains("|weekly", StringComparison.Ordinal)
		&& !all.Contains("\n  unlock ", StringComparison.Ordinal) && !all.Contains("\n  name ", StringComparison.Ordinal));
	Check("help: 'help unlock' and 'help name' explain the command they reach", Help("unlock").StartsWith("dashboard", StringComparison.Ordinal) && Help("name").StartsWith("gamename", StringComparison.Ordinal));
	Check("help: stats says it's everything and report the short one",
		NocatFarm.Commands.All.Single(static c => c.Name == "stats").Help.StartsWith("Everything", StringComparison.Ordinal)
		&& NocatFarm.Commands.All.Single(static c => c.Name == "report").Help.StartsWith("The short one", StringComparison.Ordinal));
	Check("steam chat: the old 'unlock' is still refused there (it reaches dashboard)", NocatFarm.Commands.SteamChatRefuses(Canon("unlock")!));
	string docs = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "docs", "COMMANDS.md"));
	Check("docs: COMMANDS.md is generated from this list (Advanced last, no hidden names)", docs.Contains("## Advanced", StringComparison.Ordinal)
		&& docs.Contains("`gamename <account> [text\\|off]`", StringComparison.Ordinal) && !docs.Contains("`loot`", StringComparison.Ordinal));
}

// ── reaction speed: one choice that scales human mode's waits as they're picked ───────────────────────────────────
{
	var rs = NocatFarm.Config.Settings.FindBot("ReactionSpeed");
	Check("reaction speed: a visible human-mode choice, normal by default, with the one-line tooltip",
		rs is { Kind: NocatFarm.Config.SettingKind.Choice, Advanced: false, Mode: "legit" } && (rs.Section == NocatFarm.Config.Settings.SecHuman)
		&& (NocatFarm.Config.Settings.ParseChoices(rs).Select(static c => c.Label).SequenceEqual(["normal", "quick", "relaxed"]))
		&& (new NocatFarm.Config.BotConfig().ReactionSpeed == NocatFarm.Modules.ReactionSpeed.Normal)
		&& (rs.Tooltip == "How quickly it reacts and how long its breaks last. Every wait is still random - Quick halves them, Relaxed doubles them."));

	int Raw(NocatFarm.Config.BotConfig c, string n) => Convert.ToInt32(NocatFarm.Config.Settings.Read(c, n));
	var scaled = NocatFarm.Modules.ReactionSpeed.Scaled;
	Check("reaction speed: every scaled setting is a real per-account setting", scaled.All(static p => (NocatFarm.Config.Settings.FindBot(p.Min) != null) && ((p.Max == null) || (NocatFarm.Config.Settings.FindBot(p.Max) != null))));

	// Normal - and any account not in human mode - is exactly what's configured, for any numbers at all: the same values
	// go to the same random calls as before.
	var rnd = new Random(7);
	bool normalSame = true;
	for (int i = 0; i < 500; i++) {
		var c = new NocatFarm.Config.BotConfig { LegitMode = i % 2 == 0, ReactionSpeed = i % 2 == 0 ? 0 : rnd.Next(0, 3) };
		foreach ((string sMin, string? sMax) in scaled) {
			NocatFarm.Config.Settings.Apply(c, NocatFarm.Config.Settings.FindBot(sMin)!, rnd.Next(0, 200).ToString(System.Globalization.CultureInfo.InvariantCulture));
			if (sMax != null) {
				NocatFarm.Config.Settings.Apply(c, NocatFarm.Config.Settings.FindBot(sMax)!, rnd.Next(0, 200).ToString(System.Globalization.CultureInfo.InvariantCulture));
			}
		}
		foreach ((string sMin, string? sMax) in scaled) {
			normalSame &= sMax == null
				? NocatFarm.Modules.ReactionSpeed.One(c, sMin) == Raw(c, sMin)
				: NocatFarm.Modules.ReactionSpeed.Range(c, sMin, sMax) == (Raw(c, sMin), Raw(c, sMax));
		}
		normalSame &= NocatFarm.Modules.ReactionSpeed.Fixed(c, 10, 60) == (10, 60);
	}
	Check("reaction speed: Normal, and every robot account, use the configured numbers untouched (inverted pairs too)", normalSame);

	var quick = new NocatFarm.Config.BotConfig { LegitMode = true, ReactionSpeed = NocatFarm.Modules.ReactionSpeed.Quick,
		GiftDelayMinMinutes = 2, GiftDelayMaxMinutes = 15, BreakMinMinutes = 1, BreakMaxMinutes = 30, WakeDelayMinMinutes = 0, WakeDelayMaxMinutes = 0, AutoReplyDelaySeconds = 3 };
	var relaxed = new NocatFarm.Config.BotConfig { LegitMode = true, ReactionSpeed = NocatFarm.Modules.ReactionSpeed.Relaxed,
		GiftDelayMinMinutes = 2, GiftDelayMaxMinutes = 1000, MealBreakMinutes = 35 };
	Check("reaction speed: Quick halves both ends, rounding to the nearest minute",
		NocatFarm.Modules.ReactionSpeed.Range(quick, "GiftDelayMinMinutes", "GiftDelayMaxMinutes") == (1, 8)
		&& NocatFarm.Modules.ReactionSpeed.Fixed(quick, 10, 60) == (5, 30) && NocatFarm.Modules.ReactionSpeed.One(quick, "AutoReplyDelaySeconds") == 2);
	Check("reaction speed: a wait above zero never becomes zero, and one switched off stays off",
		NocatFarm.Modules.ReactionSpeed.Range(quick, "BreakMinMinutes", "BreakMaxMinutes") == (1, 15)
		&& NocatFarm.Modules.ReactionSpeed.Range(quick, "WakeDelayMinMinutes", "WakeDelayMaxMinutes") == (0, 0));
	Check("reaction speed: Relaxed doubles both ends, never past what the setting allows",
		NocatFarm.Modules.ReactionSpeed.Range(relaxed, "GiftDelayMinMinutes", "GiftDelayMaxMinutes") == (4, (int) NocatFarm.Config.Settings.FindBot("GiftDelayMaxMinutes")!.Max)
		&& NocatFarm.Modules.ReactionSpeed.One(relaxed, "MealBreakMinutes") == 70);
	bool ordered = true;
	foreach (int speed in new[] { 1, 2 }) {
		for (int i = 0; i < 300; i++) {
			var c = new NocatFarm.Config.BotConfig { LegitMode = true, ReactionSpeed = speed, TradeDelayMinMinutes = rnd.Next(0, 721), TradeDelayMaxMinutes = rnd.Next(0, 1441) };
			(int lo, int hi) = NocatFarm.Modules.ReactionSpeed.Range(c, "TradeDelayMinMinutes", "TradeDelayMaxMinutes");
			ordered &= (lo <= hi) && ((c.TradeDelayMinMinutes == 0) == (lo == 0));
		}
	}
	Check("reaction speed: scaled, the shortest is never above the longest", ordered);

	// Still random: many trade waits on Quick land all over the halved range, not on one value.
	var tbot = new NocatFarm.Core.Bot("harness-reaction", new NocatFarm.Config.BotConfig { LegitMode = true, ReactionSpeed = 1, TradeDelayMinMinutes = 4, TradeDelayMaxMinutes = 40 });
	var trading = new NocatFarm.Modules.Trading(tbot);
	MethodInfo tradeWait = typeof(NocatFarm.Modules.Trading).GetMethod("TradeWait", BindingFlags.NonPublic | BindingFlags.Instance)!;
	List<double> waits = [.. Enumerable.Range(0, 400).Select(_ => ((TimeSpan) tradeWait.Invoke(trading, [])!).TotalMinutes)];
	Check("reaction speed: every wait is still drawn at random, inside the scaled range (2-20 on Quick for 4-40)",
		waits.All(static w => w is >= 2 and <= 20) && (waits.Distinct().Count() > 50) && (waits.Max() > 15), $"{waits.Min():0.0}-{waits.Max():0.0}, {waits.Distinct().Count()} different");

	// The owner's safety: three minutes and clear reads after signing in come before any game, whatever the speed.
	var safeCfg = new NocatFarm.Config.BotConfig { LegitMode = true, ReactionSpeed = NocatFarm.Modules.ReactionSpeed.Quick, WarmUpMinMinutes = 1, WarmUpMaxMinutes = 1, GameWeights = "730" };
	var sbot = new NocatFarm.Core.Bot("harness-reaction-safe", safeCfg);
	var shm = new NocatFarm.Modules.HumanMode(sbot);
	sbot.AddModule(shm);
	DateTime signedIn = DateTime.UtcNow;
	typeof(NocatFarm.Core.Bot).GetProperty("OnlineSince")!.SetValue(sbot, signedIn);
	typeof(NocatFarm.Modules.HumanMode).GetMethod("SettledIn", BindingFlags.NonPublic | BindingFlags.Instance)!.Invoke(shm, []);
	DateTime ready = (DateTime) typeof(NocatFarm.Modules.HumanMode).GetField("_readyAt", BindingFlags.NonPublic | BindingFlags.Instance)!.GetValue(shm)!;
	Check("reaction speed: Quick never starts a game inside the three minutes after signing in", ready >= signedIn.AddSeconds(180), $"{(ready - signedIn).TotalSeconds:0}s");
	string[] never = ["ResumeDelayMinutes", "Rep4RepGapMinMinutes", "Rep4RepGapMaxMinutes", "Rep4RepDailyCap", "SessionMinMinutes", "SessionMaxMinutes",
		"WeekdayHours", "WeekendHours", "HoursUntilCardDrops", "AchievementGrindGapMinMinutes", "BoostSessionHours", "PostFarmWindDownMinMinutes", "FarmingDelayMinutes"];
	Check("reaction speed: what protects the owner, Steam's limits and how much it plays are never scaled",
		never.All(n => !scaled.Any(p => (p.Min == n) || (p.Max == n))));
}

// ── game lists: picked from the library by name ──────────────────────────────────────────────────────────────────
{
	string[] lists = ["IdleGames", "OfflineIdleGames", "BlacklistedGames", "PriorityGames", "AchievementGames", "AchievementNeverGames",
		"AchievementBoostGames", "InventoryIgnoreGames", "BoosterPackGames"];
	Check("game lists: every one is a game list (and the global blacklist too)", lists.All(static n => NocatFarm.Config.Settings.FindBot(n)?.Kind == NocatFarm.Config.SettingKind.AppIds)
		&& (NocatFarm.Config.Settings.FindGlobal("GlobalBlacklistedGames")?.Kind == NocatFarm.Config.SettingKind.AppIds));
	var lcfg = new NocatFarm.Config.BotConfig();
	Check("game lists: a pasted store link still goes in", (NocatFarm.Config.Settings.Apply(lcfg, NocatFarm.Config.Settings.FindBot("BoosterPackGames")!, "https://store.steampowered.com/app/440/Team_Fortress_2/") == null)
		&& lcfg.BoosterPackGames.SequenceEqual<uint>([440]));
	string root = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm");
	string js = File.ReadAllText(Path.Combine(root, "wwwroot", "app.js")).Replace("\r\n", "\n");
	string web = File.ReadAllText(Path.Combine(root, "Web", "WebHost.cs")).Replace("\r\n", "\n");
	Check("game lists: the whole library comes once per account (every account's for a global list), behind the sign-in",
		web.Contains("app.MapGet(\"/api/bots/{name}/library\", (HttpContext ctx, string name, string? all) => Guard(ctx, () => {", StringComparison.Ordinal)
		&& web.Contains("app.MapGet(\"/api/library\", (HttpContext ctx) => Guard(ctx, () => {", StringComparison.Ordinal)
		&& js.Contains("const url = key === '*' ? '/api/library' : `/api/bots/${encodeURIComponent(key)}/library?all=1`;", StringComparison.Ordinal));
	Check("game lists: searched on the page as it's typed - ten at most, the box keeps its focus (no redraw while typing)",
		js.Contains("oninput=\"appSearch('${def.Name}',this)\"", StringComparison.Ordinal) && js.Contains("return [...starts, ...inside].slice(0, 10);", StringComparison.Ordinal)
		&& !System.Text.RegularExpressions.Regex.Match(js, @"async function appSearch[\s\S]*?\n}\n").Value.Contains("renderSettings", StringComparison.Ordinal));
	Check("game lists: chips show the game's name, the appID only in the tooltip",
		js.Contains("data-tip=\"${esc(tf('appID {0} - open its Steam store page', a))}\">${esc(gameLabel(a))}</a>", StringComparison.Ordinal) && !js.Contains("class=\"tagid\"", StringComparison.Ordinal));
	Check("game lists: a comma ends only an appID or a link - \"Papers, Please\" can be typed",
		js.Contains("} else if (e.key === 'Enter' || (e.key === ',' && parseAppId(input.value))) {", StringComparison.Ordinal));
	Check("game lists: Enter before the matches are in waits for the library and takes the top match, rather than \"no game matches\"",
		js.Contains("else appEnterLater(name, input);", StringComparison.Ordinal) && js.Contains("async function appEnterLater(name, input) {\n  const typed = input.value;\n  if (!typed.trim()) return;\n  await appSearch(name, input);", StringComparison.Ordinal));
	Check("game lists: an appID typed with Enter puts the focus back in the box (not when it went in on leaving the box)",
		js.Contains("if (parseAppId(input.value)) addApp(name, input, true);", StringComparison.Ordinal) && js.Contains("const again = refocus && document.querySelector(", StringComparison.Ordinal)
		&& js.Contains("  if (parseAppId(input.value)) addApp(name, input);\n}", StringComparison.Ordinal));
	Check("settings page: an edit to a setting that gets hidden (ShowWhen) is dropped, so Save never saves what can't be seen",
		js.Contains("pending = {}; }\n  dropHiddenEdits();\n", StringComparison.Ordinal)
		&& js.Contains("if (def.ShowWhen && pending[def.Name] !== undefined && !shownWhen(def, values)) delete pending[def.Name];", StringComparison.Ordinal));
	Check("overnight preview: with nothing listed and the pick not known yet (unsaved edits, library not read), it says it idles its N most-played - \"nothing\" only when that's known",
		js.Contains("const known = !!card && !!card.LibraryReady && !unsaved;", StringComparison.Ordinal)
		&& js.Contains("tf('Overnight it goes invisible and, with no games chosen, idles its {0} most-played game(s).'", StringComparison.Ordinal)
		&& js.Contains("const nightEmpty = val('OfflineIdleAtNight') && !listed && known && !picked;", StringComparison.Ordinal)
		&& web.Contains("LibraryReady = b.Library.Ready,", StringComparison.Ordinal));
	// The Linux/Mac swap script reaches the shell with \n alone. Built on Windows, the source can have \r\n, and 1.6.4's
	// script failed on its first command with every line ending in \r - the app closed for the update and never came back.
	{
		string shScript = (string) typeof(NocatFarm.Core.SelfUpdate).GetProperty("UnixScript", BindingFlags.Static | BindingFlags.NonPublic)!.GetValue(null)!;
		Check("update: the Linux/Mac swap script has no \\r in it, whatever the source's line endings",
			!shScript.Contains('\r') && shScript.StartsWith("#!/bin/sh\n", StringComparison.Ordinal)
			&& File.ReadAllText(Path.Combine(root, "Core", "SelfUpdate.cs")).Contains("WindowsScript(Environment.ProcessId) : UnixScript, ct)", StringComparison.Ordinal));
	}
	// The overnight note: looked for before the file is read, written only once the switch-off is on disk, and forgotten
	// for every account a restore puts back.
	string cfgSrc = File.ReadAllText(Path.Combine(root, "Config", "Configs.cs")).Replace("\r\n", "\n");
	string backupSrc = File.ReadAllText(Path.Combine(root, "Core", "Backup.cs")).Replace("\r\n", "\n");
	Check("overnight note: checked before reading, written after a good save, cleared by a restore",
		(cfgSrc.IndexOf("bool seenBefore = File.Exists(seen);", StringComparison.Ordinal) < cfgSrc.IndexOf("string text = ReadShared(file);", StringComparison.Ordinal))
		&& cfgSrc.Contains("if (!seenBefore && (!night || saved)) {", StringComparison.Ordinal)
		&& backupSrc.Contains("@\"|state/overnight-(?<name>", StringComparison.Ordinal)
		&& backupSrc.Contains("if (restored.Contains($\"state/overnight-{name}.seen\")) {", StringComparison.Ordinal)
		// ...together with the account's own file, in either zip order, case ignored; and names end at \z, not $.
		&& backupSrc.Contains("if (NoteOf(rel) is { } noted && restored.Contains($\"{noted}.json\")) {\n\t\t\t\tcontinue;", StringComparison.Ordinal)
		&& backupSrc.Contains("new(contents.Select(static c => c.Rel), StringComparer.OrdinalIgnoreCase);", StringComparison.Ordinal)
		&& backupSrc.Contains(".seen)\\z\", RegexOptions.CultureInvariant)]", StringComparison.Ordinal));
	// selfcheck counts the overnight games it may really bank; a DLC map from before the whole-DLC list is built again.
	Check("selfcheck: the overnight advice counts only games the night rules allow; maps from before rule 6 are rebuilt",
		File.ReadAllText(Path.Combine(root, "Core", "SelfCheck.cs")).Contains("(human?.ListedNightCount ?? bot.Cfg.OfflineIdleGames.Count)", StringComparison.Ordinal)
		&& File.ReadAllText(Path.Combine(root, "Modules", "HumanMode.cs")).Contains("Bot.Cfg.OfflineIdleGames.Count(a => MayBankAtNight(a, banned))", StringComparison.Ordinal)
		&& (NocatFarm.Core.DlcAchievements.RuleNow >= 6));
	Check("old names: the sign-in page says 'dashboard unlock', the achievements usage says 'achievements'",
		js.Contains("t('Or type dashboard unlock in the nocat.farm window.')", StringComparison.Ordinal) && !js.Contains("'Or type unlock in", StringComparison.Ordinal)
		&& !File.ReadAllText(Path.Combine(root, "Commands.cs")).Contains("\"cheevo <account>", StringComparison.Ordinal)
		&& !File.ReadAllText(Path.Combine(root, "Commands.cs")).Contains("'cheevo {bot.Name}", StringComparison.Ordinal)
		&& !File.ReadAllText(Path.Combine(root, "..", "..", "docs", "phone-and-notifications.md")).Contains("/dashboard anywhere", StringComparison.Ordinal));
}

// ── learning from you: recent days count more, weekdays and weekends learned apart ─────────────────────────────────
{
	const BindingFlags Inst = BindingFlags.NonPublic | BindingFlags.Instance;
	const BindingFlags Stat = BindingFlags.NonPublic | BindingFlags.Static;
	Type hh = typeof(NocatFarm.Modules.HumanMode).Assembly.GetType("NocatFarm.Modules.HumanHabits")!;
	object? HH(string m, params object?[] args) => hh.GetMethod(m, Stat)!.Invoke(null, args);
	int Needed(string name) => (int) typeof(NocatFarm.Modules.OwnerHabits).GetField(name, Stat)!.GetRawConstantValue()!;
	double HalfLife(int follow) => NocatFarm.Modules.OwnerHabits.HalfLife(follow);
	NocatFarm.Modules.OwnerHabits.Sitting Sit(DateTime start, int minutes, uint app) => new() { Start = start, Minutes = minutes, App = app };
	string Clock(int minutes) => (string) typeof(NocatFarm.Modules.OwnerHabits).GetMethod("Clock", Stat)!.Invoke(null, [minutes])!;
	string Seen(NocatFarm.Modules.LearnedHabits l) => ((NocatFarm.Core.Said) HH("Seen", l)!).ToEnglish();
	string Times(NocatFarm.Modules.LearnedHabits l) => string.Join(" · ", ((List<NocatFarm.Core.Said>) HH("Times", l)!).Select(static s => s.ToEnglish()));
	// A Thursday noon, fixed: which of the days are weekends must never depend on the day this runs.
	DateTime now = new(2026, 10, 1, 12, 0, 0);
	double W(double daysOld, int follow) => NocatFarm.Modules.OwnerHabits.Weight(now.AddDays(-daysOld), now, HalfLife(follow));

	// ── the fade ──
	Check("fade: at normal a sitting 14 days old counts half as much as today's, 28 days old a quarter",
		(W(0, 1) == 1) && (Math.Abs(W(14, 1) - 0.5) < 1e-9) && (Math.Abs(W(28, 1) - 0.25) < 1e-9));
	Check("fade: quickly halves every 7 days, slowly every 28, normal every 14",
		(HalfLife(2) == 7) && (HalfLife(0) == 28) && (HalfLife(1) == 14) && (Math.Abs(W(7, 2) - 0.5) < 1e-9) && (Math.Abs(W(28, 0) - 0.5) < 1e-9));
	Check("fade: a sitting dated after now (a clock put back) counts as today's, never more", W(-3, 1) == 1);
	var mixed = new NocatFarm.Modules.OwnerHabits();
	mixed.Add(Sit(now.AddDays(-14), 60, 730), now);
	mixed.Add(Sit(now.AddDays(-1).AddHours(2), 60, 440), now);
	var mixedGames = mixed.Picture(now, 14).Games;
	Check("fade: game shares count each sitting by its age (an hour 14 days ago is half of yesterday's hour)",
		Math.Abs((mixedGames[730] / mixedGames[440]) - (0.5 / Math.Pow(0.5, (now - now.AddDays(-1).AddHours(2)).TotalDays / 14))) < 1e-9,
		$"{mixedGames[730]:0.0} vs {mixedGames[440]:0.0}");

	// ── a change of routine: days of getting on at 15:00, then the most recent ones at 19:00 ──
	NocatFarm.Modules.OwnerHabits Routine(int newDays, int oldDays) {
		var h = new NocatFarm.Modules.OwnerHabits();

		for (int d = newDays + oldDays; d > newDays; d--) {
			h.Add(Sit(now.Date.AddDays(-d).AddHours(15), 180, 730), now);
		}

		for (int d = newDays; d >= 1; d--) {
			h.Add(Sit(now.Date.AddDays(-d).AddHours(19), 180, 730), now);
		}

		return h;
	}

	// The roll leans each day toward one of your days picked at random, recent ones likelier: the new routine's share of
	// that pull is how far toward it the get-on time moves on average.
	double NewShare(NocatFarm.Modules.OwnerHabits h, double halfLife) {
		var days = h.Picture(now, halfLife).Days;

		return days.Where(static d => d.Start == 19 * 60).Sum(static d => d.Weight) / days.Sum(static d => d.Weight);
	}

	int Usual(NocatFarm.Modules.OwnerHabits h, int follow) => h.Picture(now, HalfLife(follow)).UsualStart;
	var week = Routine(7, 20);   // 20 days of 15:00, then the last 7 at 19:00
	double flat = 7.0 / 27, slowShare = NewShare(week, 28), normalShare = NewShare(week, 14), quickShare = NewShare(week, 7);
	Check("routine change: after a week of 19:00, the new days carry more of the pull than equal days would - slowly < normal < quickly",
		(flat < slowShare) && (slowShare < normalShare) && (normalShare < quickShare) && (normalShare > 0.38) && (quickShare > 0.52),
		$"equal {flat:P0}, slowly {slowShare:P0}, normal {normalShare:P0}, quickly {quickShare:P0}");
	Check("routine change: the average day's get-on time moves further at quickly than at normal",
		(15 + (4 * quickShare)) > (15 + (4 * normalShare)) + 0.5, $"normal {Clock((int) ((15 + (4 * normalShare)) * 60))}, quickly {Clock((int) ((15 + (4 * quickShare)) * 60))}");
	Check("routine change: after one week quickly already says 'on around 19:00'; normal and slowly still 15:00",
		(Usual(week, 2) == 19 * 60) && (Usual(week, 1) == 15 * 60) && (Usual(week, 0) == 15 * 60));
	// The old routine as long as the memory goes (59 days back): the hardest case to move away from.
	var twoWeeks = Routine(14, 45);
	var month = Routine(30, 29);
	Check("routine change: after two weeks normal has followed even a routine as old as it remembers (slowly hasn't); after a month slowly has",
		(Usual(twoWeeks, 1) == 19 * 60) && (Usual(twoWeeks, 0) == 15 * 60) && (Usual(month, 0) == 19 * 60) && (NewShare(twoWeeks, 14) > 0.5),
		$"two weeks: normal {Clock(Usual(twoWeeks, 1))}, slowly {Clock(Usual(twoWeeks, 0))}; a month: slowly {Clock(Usual(month, 0))}");
	Check("routine change: with equal weights (no fade) a week of the new routine would hardly count", NewShare(week, 1e9) < 0.27);

	// ── the 7-day minimum is still 7 days, counted plainly ──
	Check("minimum: still 7 days before any of it is used; weekdays need 5 of their own, weekends 4",
		(Needed("DaysNeeded") == 7) && (Needed("WeekdaysNeeded") == 5) && (Needed("WeekendDaysNeeded") == 4));
	var oldWeek = new NocatFarm.Modules.OwnerHabits();

	for (int d = 50; d < 57; d++) {
		oldWeek.Add(Sit(now.Date.AddDays(-d).AddHours(20), 60, 730), now);
	}

	Check("minimum: seven days count as seven however faded - the fade changes what's learned, not whether enough was seen",
		oldWeek.Ready && (oldWeek.DaysSeen == 7) && oldWeek.Learn(now, 7, true).Ready);

	// ── weekdays and weekends: three weeks of weekdays 15:00-23:00 on CS2, weekends 11:00-03:00 on TF2 ──
	var split = new NocatFarm.Modules.OwnerHabits();

	for (int d = 1; d <= 21; d++) {
		DateTime day = now.Date.AddDays(-d);
		bool weekend = day.DayOfWeek is DayOfWeek.Saturday or DayOfWeek.Sunday;
		split.Add(weekend ? Sit(day.AddHours(11), 16 * 60, 440) : Sit(day.AddHours(15), 8 * 60, 730), now);
	}

	DateTime saturday = new(2026, 10, 3), sunday = new(2026, 10, 4), friday = new(2026, 10, 2), wednesday = new(2026, 9, 30);
	var apart = split.Learn(now, 14, true);
	var together = split.Learn(now, 14, false);
	Check("weekends apart: each half has its own days (15 weekdays, 6 weekend days) and enough of them",
		apart.Ready && apart.WeekdaysOwn && apart.WeekendsOwn && (apart.Weekdays!.DaysSeen == 15) && (apart.Weekends!.DaysSeen == 6));
	Check("weekends apart: a Saturday or Sunday goes by your weekends (on 11:00, off 03:00), a weekday - Friday too - by your weekdays (15:00-23:00)",
		(apart.For(saturday).UsualStart == 11 * 60) && (apart.For(sunday).UsualEnd == 27 * 60)
		&& (apart.For(wednesday).UsualStart == 15 * 60) && (apart.For(friday).UsualEnd == 23 * 60));
	Check("weekends apart: the weekend's games are the weekend's", apart.For(saturday).Games.Keys.SequenceEqual([440u]) && apart.For(wednesday).Games.Keys.SequenceEqual([730u]));
	Check("weekends apart: a game at 1am Saturday is still Friday night - a weekday",
		NocatFarm.Modules.OwnerHabits.IsWeekend(NocatFarm.Modules.OwnerHabits.DayOf(new DateTime(2026, 10, 3, 1, 0, 0))) == false);
	Check("weekends apart, switched off: one picture for every day, as before",
		!together.Apart && ReferenceEquals(together.For(saturday), together.All) && ReferenceEquals(together.For(wednesday), together.All) && (together.For(saturday).UsualStart == 15 * 60));

	// Only one weekend seen so far: the weekends go by the whole week until a second one comes, the weekdays by their own.
	var oneWeekend = new NocatFarm.Modules.OwnerHabits();

	foreach (var s in split.Sittings.Where(s => (now - s.Start).TotalDays < 7 || !NocatFarm.Modules.OwnerHabits.IsWeekend(NocatFarm.Modules.OwnerHabits.DayOf(s.Start)))) {
		oneWeekend.Add(s, now);
	}

	var partly = oneWeekend.Learn(now, 14, true);
	Check("weekends apart: too few weekend days (2 of 4) - weekends fall back to the whole week, weekdays keep their own",
		partly.Ready && partly.WeekdaysOwn && !partly.WeekendsOwn && (partly.Weekends!.DaysSeen == 2)
		&& ReferenceEquals(partly.For(saturday), partly.All) && ReferenceEquals(partly.For(wednesday), partly.Weekdays));
	var notYet = new NocatFarm.Modules.OwnerHabits();

	foreach (var s in split.Sittings.Where(static s => !NocatFarm.Modules.OwnerHabits.IsWeekend(NocatFarm.Modules.OwnerHabits.DayOf(s.Start))).Take(6)) {
		notYet.Add(s, now);
	}

	Check("weekends apart: 6 weekdays are enough for the weekdays' own picture, but nothing is used before 7 days in all",
		!notYet.Learn(now, 14, true).Ready && notYet.Learn(now, 14, true).WeekdaysOwn);

	// ── what it says ──
	Check("says: days seen, weekdays and weekends apart", Seen(apart) == "15 weekdays and 6 weekend days seen", Seen(apart));
	Check("says: days seen, all together", Seen(together) == "21 days seen", Seen(together));
	Check("says: before a week, how far off it is", Seen(notYet.Learn(now, 14, true)) == "6 of 7 days seen (6 weekdays, 0 weekend days), used once it has 7"
		&& (Seen(notYet.Learn(now, 14, false)) == "6 of 7 days seen, used once it has 7"), Seen(notYet.Learn(now, 14, true)));
	Check("says: when you're on, weekdays and weekends", Times(apart) == "weekdays: on around 15:00, off around 23:00 · weekends: on around 11:00, off around 03:00", Times(apart));
	Check("says: a half still going by the whole week says so", Times(partly).EndsWith("weekends: on around 15:00, off around 23:00 - the whole week's, until it has seen 4 weekend days", StringComparison.Ordinal), Times(partly));
	Check("says: all together, one usual time", Times(together) == "on around 15:00, off around 23:00", Times(together));
	Check("says: a game you play clearly more than the list gives it",
		((uint) HH("PlaysMore", apart.All, NocatFarm.Modules.HumanMode.ParseWeights("730:70, 440:30"))! == 440)
		&& ((uint) HH("PlaysMore", apart.All, NocatFarm.Modules.HumanMode.ParseWeights("730:55, 440:45"))! == 0)
		&& ((uint) HH("PlaysMore", apart.All, NocatFarm.Modules.HumanMode.ParseWeights("730:100"))! == 0));

	// ── in the account: the day's roll and the games go by the plan's own day ──
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-habits-" + Guid.NewGuid().ToString("N"));
	Directory.CreateDirectory(Path.Combine(tmpRoot, "config"));
	NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);

	try {
		var abot = new NocatFarm.Core.Bot("harness-habits-apart", new NocatFarm.Config.BotConfig { LegitMode = true, GameWeights = "730:50, 440:50", LearnFromOwner = 2 });
		var amode = new NocatFarm.Modules.HumanMode(abot);
		abot.AddModule(amode);
		typeof(NocatFarm.Modules.HumanMode).GetField("_habits", Inst)!.SetValue(amode, split);
		int StartFor(DateTime date) {
			object extras = typeof(NocatFarm.Modules.HumanMode).GetMethod("Extras", Inst)!.Invoke(amode, [date])!;

			return ((NocatFarm.Modules.HabitPicture) extras.GetType().GetProperty("Habits")!.GetValue(extras)!).UsualStart;
		}

		Check("account: a Saturday's roll leans toward your weekends, a Wednesday's toward your weekdays",
			(StartFor(saturday) == 11 * 60) && (StartFor(wednesday) == 15 * 60), $"{Clock(StartFor(saturday))}, {Clock(StartFor(wednesday))}");
		DateTime lastSaturday = DateTime.Now.Date.AddDays(-(((int) DateTime.Now.DayOfWeek + 1) % 7));
		DateTime lastWednesday = DateTime.Now.Date.AddDays(-(((int) DateTime.Now.DayOfWeek + 4) % 7));
		typeof(NocatFarm.Modules.HumanMode).GetField("_dayStamp", Inst)!.SetValue(amode, lastSaturday.DayOfYear);
		double weekendMain = NocatFarm.Modules.HumanMode.Shares(amode.Rotation)[0];
		typeof(NocatFarm.Modules.HumanMode).GetField("_dayStamp", Inst)!.SetValue(amode, lastWednesday.DayOfYear);
		double weekdayMain = NocatFarm.Modules.HumanMode.Shares(amode.Rotation)[0];
		Check("account: on a weekend plan the games lean to what you play at weekends (TF2), on a weekday to CS2",
			(weekendMain < 50) && (weekdayMain > 50), $"CS2 {weekendMain:0}% on Saturday, {weekdayMain:0}% on Wednesday");
		abot.Cfg.LearnWeekends = false;
		Check("account: with \"Weekends separately\" off, a Saturday goes by the whole week", StartFor(saturday) == 15 * 60, Clock(StartFor(saturday)));
		abot.Cfg.LearnWeekends = true;
		abot.Cfg.LearnFollow = 2;
		Check("account: changing \"Keeps up with changes\" is picked up at once (worked out again, not kept from before)",
			Math.Abs(((NocatFarm.Modules.LearnedHabits) typeof(NocatFarm.Modules.HumanMode).GetMethod("Learned", Inst)!.Invoke(amode, [])!).All.Days[^1].Weight
				- NocatFarm.Modules.OwnerHabits.Weight(split.Sittings[0].Start, DateTime.Now, 7)) < 1e-3);
		abot.Cfg.LearnFollow = 1;

		// 'habits' and 'human' say it plainly; the dashboard gets the same, translated.
		string report = string.Join("\n", amode.HabitsReport());
		abot.Cfg.GameWeights = "730:70, 440:30";
		string reportMore = string.Join("\n", amode.HabitsReport());
		Check("habits: in use, how it keeps up, days seen by weekdays and weekends, and when you're on in each",
			report.Contains("  in use (a lot) - its day leans toward yours, keeping up with changes normally (a day counts half as much after 14 days)", StringComparison.Ordinal)
			&& report.Contains("  so far        15 weekdays and 6 weekend days seen (the last 60 days are kept)", StringComparison.Ordinal)
			&& report.Contains("  usually       weekdays: on around 15:00, off around 23:00 · weekends: on around 11:00, off around 03:00", StringComparison.Ordinal), report);
		Check("habits: a game you play more than your list says is named", reportMore.Contains("  you play Team Fortress 2 more than your list says", StringComparison.Ordinal)
			&& !report.Contains("more than your list says", StringComparison.Ordinal), reportMore);
		string extrasLine = amode.ExtrasReport().Single(static l => l.StartsWith("learning from you", StringComparison.Ordinal));
		Check("human: one short line - days seen, weekdays and weekends, and the game",
			extrasLine == "learning from you   in use (a lot) - 15 weekdays and 6 weekend days seen · weekdays: on around 15:00, off around 23:00 · weekends: on around 11:00, off around 03:00 · you play Team Fortress 2 more than your list says",
			extrasLine);
		string panelOn = amode.LearnedLine();
		abot.Cfg.LearnFromOwner = 0;
		Check("dashboard: the Human mode panel gets the same line, and nothing while learning is off",
			panelOn.StartsWith("15 weekdays and 6 weekend days seen · weekdays: on around 15:00", StringComparison.Ordinal) && (amode.LearnedLine().Length == 0), panelOn);
		await abot.DisposeAsync();
	} finally {
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
		}
	}

	// ── the two settings ──
	List<NocatFarm.Config.SettingDef> human = [.. NocatFarm.Config.Settings.Bot.Where(static d => d.Section == NocatFarm.Config.Settings.SecHuman)];
	int learnAt = human.FindIndex(static d => d.Name == "LearnFromOwner");
	var follow = NocatFarm.Config.Settings.FindBot("LearnFollow")!;
	var weekends = NocatFarm.Config.Settings.FindBot("LearnWeekends")!;
	Check("settings: \"Keeps up with changes\" and \"Weekends separately\" sit right under \"Learn from how I play\", in that order",
		(learnAt >= 0) && (human[learnAt + 1] == follow) && (human[learnAt + 2] == weekends));
	Check("settings: both human mode only, behind Show advanced, and shown only while learning isn't off",
		new[] { follow, weekends }.All(static d => (d.Mode == "legit") && d.Advanced && (d.ShowWhen == "LearnFromOwner!=0")));
	Check("settings: the words", (follow.Label == "Keeps up with changes") && (follow.Choices == "0 slowly | 1 normal | 2 quickly")
		&& (follow.Tooltip == "How fast a change in when or what you play shows up. Older days count less and less - quickly follows a new routine in about a week, slowly takes about a month.")
		&& (weekends.Label == "Weekends separately")
		&& (weekends.Tooltip == "Learns your Saturdays and Sundays apart from the rest of the week, since most people play differently then."));
	var fc = new NocatFarm.Config.BotConfig();
	var oldCfg = System.Text.Json.JsonSerializer.Deserialize<NocatFarm.Config.BotConfig>("{\"LegitMode\":true,\"LearnFromOwner\":2}")!;
	Check("settings: normal and weekends apart by default - a config from before them too",
		(fc.LearnFollow == 1) && fc.LearnWeekends && (oldCfg.LearnFollow == 1) && oldCfg.LearnWeekends && (oldCfg.LearnFromOwner == 2));
	Check("settings: \"Keeps up with changes\" takes slowly / normal / quickly",
		(NocatFarm.Config.Settings.Apply(fc, follow, "quickly") == null) && (fc.LearnFollow == 2) && (NocatFarm.Config.Settings.Apply(fc, follow, "slowly") == null)
		&& (fc.LearnFollow == 0) && (NocatFarm.Config.Settings.Apply(fc, follow, "3") != null) && (NocatFarm.Config.Settings.Apply(fc, weekends, "off") == null) && !fc.LearnWeekends);
	string js = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "wwwroot", "app.js")).Replace("\r\n", "\n");
	Check("settings page: ShowWhen with != shows the setting for every answer but that one",
		js.Contains("const not = def.ShowWhen[at - 1] === '!';", StringComparison.Ordinal) && js.Contains("return not ? !same : same;", StringComparison.Ordinal));
	Check("settings page: the Human mode panel shows what it has learned, from the saved setting only",
		js.Contains("const learned = Number(val('LearnFromOwner') || 0) > 0 && learnedSaved && card ? card.Learned || '' : '';", StringComparison.Ordinal)
		&& js.Contains("const learnedSaved = ['LearnFromOwner', 'LearnFollow', 'LearnWeekends', 'GameWeights'].every((k) => pending[k] === undefined);", StringComparison.Ordinal)
		&& File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Web", "WebHost.cs"))
			.Contains("Learned = BotManager.ModuleOf<HumanMode>(b)?.LearnedLine() ?? \"\",", StringComparison.Ordinal));
}

// ── the pacer's refusals, stops, night minutes and saved rules; the summaries; hours ──────────────────────────
{
	const BindingFlags SP = BindingFlags.Static | BindingFlags.NonPublic;
	const BindingFlags IP = BindingFlags.Instance | BindingFlags.NonPublic;
	const BindingFlags F = BindingFlags.Instance | BindingFlags.Public;
	Type pacerType = typeof(NocatFarm.Modules.AchievementPacer);
	Type gs = pacerType.GetNestedType("GameState", BindingFlags.NonPublic)!;
	string root = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm");
	string Src(string rel) => File.ReadAllText(Path.Combine(root, rel)).Replace("\r\n", "\n");
	string pacerSrc = Src("Modules/AchievementPacer.cs");
	object NewState() => Activator.CreateInstance(gs, nonPublic: true)!;
	T StateOf<T>(object g, string field) => (T) gs.GetField(field, F)!.GetValue(g)!;
	void Set(object g, string field, object? value) => gs.GetField(field, F)!.SetValue(g, value);
	NocatFarm.Core.Achievement A(string name, string desc, double pct) =>
		new() { Name = name, Display = name, Description = desc, StatId = 1, Bit = 0, Unlocked = false, Protected = false, GlobalPercent = pct };

	// 1. A put-back is parked even in a family game; three refusals over two days park anything; the next look skips once.
	MethodInfo park = pacerType.GetMethod("ParkRefusal", SP)!;
	bool Park(NocatFarm.Core.Achievements.Refusal r, bool shared) => (bool) park.Invoke(null, [r, shared, DateTime.MinValue, DateTime.UtcNow])!;
	Check("refusals: Steam putting the stat back parks it, family game or not; AccessDenied in a family game still doesn't (the owner may be in it)",
		Park(NocatFarm.Core.Achievements.Refusal.PutBack, shared: true) && Park(NocatFarm.Core.Achievements.Refusal.PutBack, shared: false)
		&& !Park(NocatFarm.Core.Achievements.Refusal.NotSettable, shared: true) && Park(NocatFarm.Core.Achievements.Refusal.NotSettable, shared: false)
		&& !Park(NocatFarm.Core.Achievements.Refusal.Transient, shared: false));
	MethodInfo struck = pacerType.GetMethod("StruckOut", SP)!;
	DateTime s0 = new(2026, 10, 1, 12, 0, 0, DateTimeKind.Utc);
	bool Struck(params double[] hoursIn) => (bool) struck.Invoke(null, [hoursIn.Select(h => s0.AddHours(h)).ToList()])!;
	Check("refusals: three over at least two days park it whatever Steam said - not two, not three in a bad afternoon",
		Struck(0, 1, 48) && Struck(0, 30, 60) && !Struck(0, 1, 2) && !Struck(0, 100) && !Struck(0, 20, 47.5));
	MethodInfo pickOf = pacerType.GetMethod("NextPick", SP)!;
	string Pick(List<NocatFarm.Core.Achievement> eligible, HashSet<string> later, string? skip) =>
		((NocatFarm.Core.Achievement) pickOf.Invoke(null, [eligible, (Func<NocatFarm.Core.Achievement, bool>) (a => later.Contains(a.Name)), false, skip])!).Name;
	List<NocatFarm.Core.Achievement> two = [A("TOP", "Win", 80), A("NEXT", "Win twice", 70), A("ADDON", "Win in the expansion", 90)];
	Check("refusals: the next look steps past the one just turned down - only if there's another, and never onto an add-on-looking one ahead of the base game",
		(Pick(two, ["ADDON"], null) == "TOP") && (Pick(two, ["ADDON"], "TOP") == "NEXT") && (Pick([two[0], two[2]], ["ADDON"], "TOP") == "TOP")
		&& (Pick([two[0]], [], "TOP") == "TOP"));
	Check("refusals: every refusal is a strike; parked or skipped once; a strike gone on an unlock; strikes saved for 14 days",
		pacerSrc.Contains("strikes.RemoveAll(t => at - t > StrikesKept);", StringComparison.Ordinal) && pacerSrc.Contains("g.SkipOnce = name;", StringComparison.Ordinal)
		&& pacerSrc.Contains("g.Strikes.Remove(pick.Name);", StringComparison.Ordinal) && pacerSrc.Contains("Strikes = s.Strikes ?? []", StringComparison.Ordinal)
		&& Src("Core/Achievements.cs").Contains("public enum Refusal {", StringComparison.Ordinal));

	// 2. "online" anywhere means other players, bar what's to read or buy - and "or" with an alone side still isn't.
	MethodInfo isMp = pacerType.GetMethod("IsMultiplayer", SP)!;
	NocatFarm.Core.Achievement A2(string name, string desc) => A(name, desc, 10);
	bool MpA(NocatFarm.Core.Achievement a) => (bool) isMp.Invoke(null, [a, false])!;
	string[] online = ["Win 10 matches online", "Defeat 50 players online", "Complete 5 races online", "Reach level 20 online", "Win a round of deathmatch online",
		"Win an online match", "Red Dead Online: Reach Rank 10", "Get onto the online leaderboard"];
	string[] notOnline = ["The ignition of natural gas can cause not only a heated argument on some online forum but also a 20% increase in the flight speed.",
		"Visit the online store", "Read the online manual", "Open the online guide", "Alone in Single Player or together in Multiplayer.",
		"Finish a mission in single player or online", "Complete the level in single player or multiplayer"];
	Check("multiplayer words: every 'online' is other players - matches, players, races, levels, a deathmatch round online",
		online.All(d => MpA(A2("ONL_" + Array.IndexOf(online, d), d))), string.Join(" | ", online.Where(d => !MpA(A2("ONL_" + Array.IndexOf(online, d), d)))));
	Check("multiplayer words: but not an online forum, store, manual or guide - nor alone offered too",
		notOnline.All(d => !MpA(A2("OFF_" + Array.IndexOf(notOnline, d), d))), string.Join(" | ", notOnline.Where(d => MpA(A2("OFF_" + Array.IndexOf(notOnline, d), d)))));

	// 3 and 4 need an account: one in a scratch folder, never the real one.
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-pacer-" + Guid.NewGuid().ToString("N"));
	Directory.CreateDirectory(Path.Combine(tmpRoot, "config", "state"));
	NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);

	try {
		var cfg = new NocatFarm.Config.BotConfig { LegitMode = true, AchievementSkipMultiplayer = true };
		await using var bot = new NocatFarm.Core.Bot("harness-f66", cfg);
		var pacer = new NocatFarm.Modules.AchievementPacer(bot);
		DateTime now = DateTime.UtcNow;

		// 3. A stop that ended by itself is let go there and then - not left behind its 8-25 hour back-off.
		MethodInfo endIfOver = pacerType.GetMethod("EndStopIfOver", IP)!;
		object stopped = NewState();
		Set(stopped, "Last", NocatFarm.Modules.AchievementPacer.Outcome.CountersOnly);
		Set(stopped, "RecheckAt", now.AddMinutes(-1));
		Set(stopped, "StuckLibMins", 100L);
		Set(stopped, "NextAllow", now.AddHours(20));
		bool ended = (bool) endIfOver.Invoke(pacer, [stopped, now])!;
		object earning = NewState();
		Set(earning, "Last", NocatFarm.Modules.AchievementPacer.Outcome.Earning);
		Set(earning, "NextAllow", now.AddHours(1));
		object forGood = NewState();
		Set(forGood, "Last", NocatFarm.Modules.AchievementPacer.Outcome.Capped);
		Set(forGood, "NextAllow", now.AddHours(20));
		Check("pacer stops: one whose time is up is unknown and due now, its stop cleared; an earning one and a stop for good are left as they are",
			ended && (StateOf<NocatFarm.Modules.AchievementPacer.Outcome>(stopped, "Last") == NocatFarm.Modules.AchievementPacer.Outcome.Unknown)
			&& (StateOf<DateTime>(stopped, "NextAllow") == now) && (StateOf<DateTime>(stopped, "RecheckAt") == DateTime.MinValue) && (StateOf<long>(stopped, "StuckLibMins") == -1)
			&& !(bool) endIfOver.Invoke(pacer, [earning, now])! && (StateOf<DateTime>(earning, "NextAllow") == now.AddHours(1))
			&& !(bool) endIfOver.Invoke(pacer, [forGood, now])! && (StateOf<DateTime>(forGood, "NextAllow") == now.AddHours(20))
			&& pacerSrc.Contains("EndStopIfOver(g, now);", StringComparison.Ordinal));

		// 4. A night idle on a human account: Steam counts the minutes, achievements credit none - it isn't the owner playing.
		MethodInfo ownerPlayed = pacerType.GetMethod("OwnerPlayed", SP, [typeof(long), typeof(long), typeof(long), typeof(long)])!;
		bool OwnerAt(long steamNow, long ranNow) => (bool) ownerPlayed.Invoke(null, [steamNow, 1000L, 50L, ranNow])!;
		bool nightIsOwner = OwnerAt(1600, 650);
		bool ownerIsOwner = OwnerAt(1600, 50);
		Check("pacer stops: ten hours idled overnight by the app aren't the owner playing; the same ten hours with the app not running it are",
			!nightIsOwner && ownerIsOwner
			&& pacerSrc.Contains("foreach (uint idled in Bot.PlayingApps.Distinct()) {", StringComparison.Ordinal) && pacerSrc.Contains("g.StuckOwnMins = RanAtLibRead(g);", StringComparison.Ordinal));

		// 5. Saved under the old human-mode bit: read without it, so a game whose holds didn't change stays held.
		File.WriteAllText(Path.Combine(tmpRoot, "config", "state", "cheevo-harness-f66.json"), """
			[
			  { "App": 10, "PlayedMins": 50, "Last": 10, "Rules": 3, "Unlocked": 5, "Total": 20 },
			  { "App": 11, "PlayedMins": 70, "Last": 7, "Rules": 1, "Unlocked": 5, "Total": 20, "Strikes": { "ACH_X": [ "2026-09-30T00:00:00Z" ] } },
			  { "App": 12, "PlayedMins": 30, "RanMins": 400 }
			]
			""");
		pacerType.GetMethod("EnsureLoaded", IP)!.Invoke(pacer, []);
		IDictionary pacerGames = (IDictionary) pacerType.GetField("_games", IP)!.GetValue(pacer)!;
		MethodInfo rulesChanged = pacerType.GetMethod("RulesChanged", IP)!;
		object g10 = pacerGames[10u]!, g11 = pacerGames[11u]!, g12 = pacerGames[12u]!;
		Check("pacer rules: a game held under human mode + the skip (3) reads as 2 and stays held; one held without the skip is let go now the skip is on",
			(StateOf<int>(g10, "Rules") == 2) && !(bool) rulesChanged.Invoke(pacer, [g10])! && (StateOf<int>(g11, "Rules") == 0) && (bool) rulesChanged.Invoke(pacer, [g11])!);
		Check("pacer state: the app's own minutes start from the played ones in an older file, and strikes come back",
			(StateOf<long>(g10, "RanMins") == 50) && (StateOf<long>(g12, "RanMins") == 400)
			&& StateOf<Dictionary<string, List<DateTime>>>(g11, "Strikes").ContainsKey("ACH_X"));
	} finally {
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
			// left for the temp folder's own clean-up
		}
	}

	// 14. How fast during a grind: a slower pace never puts back what the grind pulled forward; every game's wait re-spaced.
	MethodInfo respaced = pacerType.GetMethod("Respaced", SP)!;
	DateTime Re(int was, int nowPace, bool pulled) => (DateTime) respaced.Invoke(null, [s0, s0.AddMinutes(20), was, nowPace, pulled])!;
	Check("how fast: pulled forward by a grind, careful keeps the grind's time and brisk still shortens it; not pulled, it's re-spaced as before",
		(Re(2, 0, pulled: true) == s0.AddMinutes(20)) && (Re(0, 2, pulled: true) == s0.AddMinutes(5)) && (Re(2, 0, pulled: false) == s0.AddMinutes(80))
		&& pacerSrc.Contains("foreach (GameState each in _games.Values) {", StringComparison.Ordinal) && pacerSrc.Contains("g.Pulled = true;", StringComparison.Ordinal));
	string appJs = Src("wwwroot/app.js");
	Check("hour lists: the browser's clock and its formatter are asked once, not twice per option on every redraw",
		appJs.Contains("if (hourClock) return hourClock.twelve;", StringComparison.Ordinal) && appJs.Contains("return hourClock.format.format(new Date(2000, 0, 1, h));", StringComparison.Ordinal)
		&& !System.Text.RegularExpressions.Regex.Match(appJs, @"function hourLabel\(h\) \{[\s\S]*?\n\}\n").Value.Contains("new Intl.DateTimeFormat", StringComparison.Ordinal));

	// 7. Bans: only counted once the watch has looked; the most ever seen is kept, so a ban back after a lift isn't new.
	MethodInfo banStep = typeof(NocatFarm.Core.DailyReport).GetMethod("BanStep", SP)!;
	(int? Keep, bool New) Ban(int? nowCount, int? before) => ((int?, bool)) banStep.Invoke(null, [nowCount, before])!;
	Check("daily summary bans: not looked at yet - nothing kept, nothing new; first look - noted, not new; a rise - new; lifted then back - not new",
		(Ban(null, null) == (null, false)) && (Ban(null, 2) == (2, false)) && (Ban(2, null) == (2, false)) && (Ban(3, 2) == (3, true))
		&& (Ban(1, 2) == (2, false)) && (Ban(2, 2) == (2, false)) && (Ban(3, 2).Keep == 3)
		&& Src("Core/DailyReport.cs").Contains("is { CheckedAt: not null, Last: { } bans }", StringComparison.Ordinal));

	// 8. An update the owner skipped isn't "needs a look".
	Type uc = typeof(NocatFarm.Core.UpdateCheck);
	const BindingFlags US = BindingFlags.Static | BindingFlags.NonPublic | BindingFlags.Public;
	PropertyInfo available = uc.GetProperty("Available", US)!;
	object? wasAvailable = available.GetValue(null);
	object? wasSkipped = uc.GetField("_skipped", US)!.GetValue(null);
	object? wasRead = uc.GetField("_skipRead", US)!.GetValue(null);
	void SkipOnly(string? v) { uc.GetField("_skipped", US)!.SetValue(null, v); uc.GetField("_skipRead", US)!.SetValue(null, true); }

	try {
		available.SetValue(null, "v9.9.9");
		SkipOnly("9.9.9");
		bool quiet = ((List<NocatFarm.Core.ReportCard.Row>) typeof(NocatFarm.Core.ReportCard).GetMethod("Attention", US)!.Invoke(null, [new List<NocatFarm.Core.Bot>(), false, null, DateTime.UtcNow])!).Count == 0;
		SkipOnly(null);
		bool said = ((List<NocatFarm.Core.ReportCard.Row>) typeof(NocatFarm.Core.ReportCard).GetMethod("Attention", US)!.Invoke(null, [new List<NocatFarm.Core.Bot>(), false, null, DateTime.UtcNow])!).Count == 1;
		Check("summary attention: a new version the owner skipped isn't flagged; one not skipped is", quiet && said);
	} finally {
		available.SetValue(null, wasAvailable);
		uc.GetField("_skipped", US)!.SetValue(null, wasSkipped);
		uc.GetField("_skipRead", US)!.SetValue(null, wasRead);
	}

	// 9 and 10. Hours: no clock format in the explanations (the picker may be a 12-hour one), and full-width digits are no hour.
	string[] hourNames = ["AutoUpdateFromHour", "AutoUpdateUntilHour", "WeeklyReportHour",
		"FarmFromHour", "FarmUntilHour", "SendAroundHour", "Rep4RepStartHour", "Rep4RepEndHour"];
	string TipOf(string n) => (NocatFarm.Config.Settings.FindBot(n) ?? NocatFarm.Config.Settings.Global.First(d => d.Name == n)).Tooltip;
	List<string> withClock = [.. hourNames.Where(n => TipOf(n).Any(char.IsAsciiDigit) || TipOf(n).Contains("24-hour", StringComparison.Ordinal))];
	foreach (string lang in new[] { "de", "es", "fr", "ja", "ko", "pl", "pt-BR", "ru", "tr", "zh-CN" }) {
		using System.Text.Json.JsonDocument pack = System.Text.Json.JsonDocument.Parse(Src($"wwwroot/lang/{lang}.json"));
		withClock.AddRange(hourNames.Where(n => pack.RootElement.GetProperty("settings").GetProperty(n).GetProperty("tip").GetString()!.Any(char.IsAsciiDigit)).Select(n => $"{lang}:{n}"));
	}
	Check("hour settings: no explanation assumes a clock - no 24-hour, no 23 to 5, no 2 means 2am, in English or any pack", withClock.Count == 0, string.Join(", ", withClock));
	bool wideThrew = false;
	int? wide = null, wideClock = null;
	try {
		wide = NocatFarm.Config.Settings.ParseHour("２１");
		wideClock = NocatFarm.Config.Settings.ParseHour("２１:00");
	} catch (FormatException) {
		wideThrew = true;
	}
	Check("hour settings: full-width digits are not an hour, and don't throw", !wideThrew && (wide == null) && (wideClock == null) && (NocatFarm.Config.Settings.ParseHour("21:00") == 21));
}

// ── owner-played baselines, writes never asked, link quotes, old ban files, hour shares ─────────────────────
{
	const BindingFlags SP = BindingFlags.Static | BindingFlags.NonPublic;
	const BindingFlags IP = BindingFlags.Instance | BindingFlags.NonPublic;
	const BindingFlags F = BindingFlags.Instance | BindingFlags.Public;
	Type pacerType = typeof(NocatFarm.Modules.AchievementPacer);
	Type gs = pacerType.GetNestedType("GameState", BindingFlags.NonPublic)!;
	object NewState() => Activator.CreateInstance(gs, nonPublic: true)!;
	T StateOf<T>(object g, string field) => (T) gs.GetField(field, F)!.GetValue(g)!;
	void Set(object g, string field, object? value) => gs.GetField(field, F)!.SetValue(g, value);
	string root = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm");
	string Src(string rel) => File.ReadAllText(Path.Combine(root, rel)).Replace("\r\n", "\n");

	string realRoot = NocatFarm.Config.ConfigStore.Root;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-baselines-" + Guid.NewGuid().ToString("N"));
	Directory.CreateDirectory(Path.Combine(tmpRoot, "config", "state"));
	NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);

	try {
		await using var bot = new NocatFarm.Core.Bot("harness-f67", new NocatFarm.Config.BotConfig());
		var pacer = new NocatFarm.Modules.AchievementPacer(bot);
		DateTime now = DateTime.UtcNow;

		// 1. Steam's minutes and ours from the same library read: minutes idled before a stop aren't the owner's.
		Type libType = typeof(NocatFarm.Core.Library);
		void LibraryRead(int minutes, DateTime at) {
			libType.GetField("_byApp", IP)!.SetValue(bot.Library, new Dictionary<uint, NocatFarm.Core.Library.Entry> {
				[70u] = new(70u, "Game", minutes, DateTime.MinValue, 0)
			});
			libType.GetProperty("Ready")!.SetValue(bot.Library, true);
			libType.GetProperty("RefreshedAt")!.SetValue(bot.Library, at);
		}

		MethodInfo noteRead = pacerType.GetMethod("NoteLibraryRead", IP)!;
		MethodInfo stopUntil = pacerType.GetMethod("StopUntil", IP)!;
		MethodInfo ownerOf = pacerType.GetMethod("OwnerPlayed", IP, [gs])!;
		MethodInfo stopOver = pacerType.GetMethod("StopOver", IP)!;
		object g = NewState();
		Set(g, "App", 70u);
		Set(g, "RanMins", 50L);
		((IDictionary) pacerType.GetField("_games", IP)!.GetValue(pacer)!)[70u] = g;

		LibraryRead(1000, now.AddHours(-6));
		noteRead.Invoke(pacer, []);
		Set(g, "RanMins", 140L);   // the app ran it 90 minutes since that read, then it stopped
		stopUntil.Invoke(pacer, [70u, g, now.AddDays(3)]);
		bool baselines = (StateOf<long>(g, "StuckLibMins") == 1000) && (StateOf<long>(g, "StuckOwnMins") == 50);
		LibraryRead(1090, now.AddHours(-1));   // the next read has those 90 minutes on Steam's side
		bool beforeTick = (bool) ownerOf.Invoke(pacer, [g])!;
		noteRead.Invoke(pacer, []);
		bool afterTick = (bool) ownerOf.Invoke(pacer, [g])! || (bool) stopOver.Invoke(pacer, [g, now])!;
		LibraryRead(1150, now);   // and the owner played it an hour
		noteRead.Invoke(pacer, []);
		bool ownerPlayed = (bool) ownerOf.Invoke(pacer, [g])! && (bool) stopOver.Invoke(pacer, [g, now])!;
		Check("pacer stops: 90 minutes the app idled before the stop, counted by the next library read, aren't the owner playing; an hour of his after that is",
			baselines && !beforeTick && !afterTick && ownerPlayed,
			$"baselines {baselines}, before tick {beforeTick}, after tick {afterTick}, owner {ownerPlayed}");

		libType.GetProperty("Ready")!.SetValue(bot.Library, false);
		object early = NewState();
		Set(early, "RanMins", 10L);
		stopUntil.Invoke(pacer, [70u, early, now.AddDays(3)]);
		Check("pacer stops: stopped before the library was read, only its few days end it - no Steam minutes to start from",
			(StateOf<long>(early, "StuckLibMins") == -1) && !(bool) ownerOf.Invoke(pacer, [early])!);

		// 2. A write Steam was never asked about: no strike, not stepped past. Real answers still are.
		MethodInfo turnedDown = pacerType.GetMethod("TurnedDown", SP)!;
		object w = NewState();
		turnedDown.Invoke(null, [w, "ACH_A", NocatFarm.Core.Achievements.Refusal.NotAsked, false, now]);
		bool untouched = (StateOf<Dictionary<string, List<DateTime>>>(w, "Strikes").Count == 0) && (StateOf<string?>(w, "SkipOnce") == null)
			&& (StateOf<Dictionary<string, DateTime>>(w, "Refused").Count == 0);
		turnedDown.Invoke(null, [w, "ACH_A", NocatFarm.Core.Achievements.Refusal.Transient, false, now]);
		bool struck = (StateOf<Dictionary<string, List<DateTime>>>(w, "Strikes")["ACH_A"].Count == 1) && (StateOf<string?>(w, "SkipOnce") == "ACH_A");
		turnedDown.Invoke(null, [w, "ACH_B", NocatFarm.Core.Achievements.Refusal.PutBack, false, now]);
		bool parked = StateOf<Dictionary<string, DateTime>>(w, "Refused").ContainsKey("ACH_B");
		var notConnected = await NocatFarm.Core.Achievements.SetCheckedAsync(bot, new NocatFarm.Core.AchievementSet { AppId = 70, All = [], CrcStats = 0 }, [], true);
		string achSrc = Src("Core/Achievements.cs");
		Check("achievement writes: not asked (not connected, the read before failed, ownership changed) is no strike and no skip; a real refusal still strikes or parks",
			untouched && struck && parked && (notConnected.Refused == NocatFarm.Core.Achievements.Refusal.NotAsked)
			&& (System.Text.RegularExpressions.Regex.Matches(achSrc, @", 0, Refusal\.NotAsked\);").Count == 4)
			&& !achSrc.Contains(", 0, Refusal.Transient);", StringComparison.Ordinal),
			$"untouched {untouched}, struck {struck}, parked {parked}, not connected {notConnected.Refused}");
	} finally {
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
			// left for the temp folder's own clean-up
		}
	}

	// 3. A " in a link's address doesn't end its href.
	string link = (string) typeof(NocatFarm.Core.Notifier).GetMethod("LinkHtml", SP)!.Invoke(null, ["http://a.b/?x=\"y\"&z=<1>"])!;
	Check("telegram links: a quote in the address is &quot; inside href, and the shown text is escaped too",
		(link == "<a href=\"http://a.b/?x=&quot;y&quot;&amp;z=&lt;1&gt;\">http://a.b/?x=\"y\"&amp;z=&lt;1&gt;</a>") && !Src("Core/TelegramCommands.cs").Contains("href=\\\"{Html(url)}\\\"", StringComparison.Ordinal), link);

	// 4. A report file from before only checked accounts were kept: its 0s aren't known, its other counts are.
	MethodInfo bansBefore = typeof(NocatFarm.Core.DailyReport).GetMethod("BansBefore", SP)!;
	Dictionary<string, int>? Before(Dictionary<string, int>? stored, int? format) => (Dictionary<string, int>?) bansBefore.Invoke(null, [stored, format]);
	Dictionary<string, int> stored = new() { ["never"] = 0, ["banned"] = 2 };
	Dictionary<string, int>? oldFile = Before(stored, null), newFile = Before(stored, 2);
	MethodInfo banStep = typeof(NocatFarm.Core.DailyReport).GetMethod("BanStep", SP)!;
	(int? Keep, bool New) Step(int? n, int? before) => ((int?, bool)) banStep.Invoke(null, [n, before])!;
	bool oldNotNew = !Step(1, oldFile!.TryGetValue("never", out int was) ? was : null).New;
	Check("daily summary bans: an old file's 0 is not known (a ban it always had isn't new the first time); its 2 still counts; a new file's 0 is a real 0",
		oldNotNew && !oldFile.ContainsKey("never") && (oldFile["banned"] == 2) && (newFile!["never"] == 0) && (Before(null, null) == null)
		&& Src("Core/DailyReport.cs").Contains("_state.BansFormat = BansFormatNow;", StringComparison.Ordinal));

	// 5. The share of days he was on in an hour never passes every day: the day's weight, top and bottom.
	var habits = new NocatFarm.Modules.OwnerHabits();
	DateTime today = DateTime.Now.Date;

	for (int d = 1; d <= 8; d++) {
		// one sitting at 19:00 and a later, heavier one an hour on - and every other day one running past 5am into a day he didn't start one on
		habits.Add(new NocatFarm.Modules.OwnerHabits.Sitting { Start = today.AddDays(-2 * d).AddHours(19), Minutes = 60, App = 730 }, DateTime.Now);
		habits.Add(new NocatFarm.Modules.OwnerHabits.Sitting { Start = today.AddDays(-2 * d).AddHours(20).AddMinutes(30), Minutes = 60, App = 730 }, DateTime.Now);
		habits.Add(new NocatFarm.Modules.OwnerHabits.Sitting { Start = today.AddDays(-2 * d).AddDays(1).AddHours(3), Minutes = 180, App = 730 }, DateTime.Now);
	}

	double[] hourShares = habits.Picture(DateTime.Now, 3).HourShare;
	Check("learning: no hour is on more than every day, whatever the sittings' ages and however late they run; hours on every day are all of them",
		hourShares.All(static s => s is >= 0 and <= 1) && (Math.Abs(hourShares[19] - 1) < 1e-9) && (Math.Abs(hourShares[5] - 1) < 1e-9) && (hourShares[12] == 0),
		string.Join(" ", hourShares.Select(static s => s.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture))));
}

// ── mini mode: 5 rows closed, 10 open and scrolling, problems on top, never taller than the screen, one figure up top ─
{
	string? langBefore = NocatFarm.Config.Live.Global.Language;
	NocatFarm.Config.Live.Global.Language = "en";

	try {
		const int Screen = 1040;
		List<int> Rows(int n, int h = NocatFarm.Windows.MiniLayout.RowH) => [.. Enumerable.Repeat(h, n)];
		NocatFarm.Windows.MiniLayout.Plan Fit(int n, bool open, int scroll = 0, int screen = Screen) => NocatFarm.Windows.MiniLayout.Fit(Rows(n), open, scroll, screen);
		string Shape(NocatFarm.Windows.MiniLayout.Plan p) => $"{p.First}+{p.Count}{(p.Footer ? " bar" : "")} h{p.Height} max{p.MaxScroll}";

		bool rowsRight = true;
		List<string> rowsSeen = [];

		foreach ((int n, int closed, int opened) in new[] { (3, 3, 3), (5, 5, 5), (6, 5, 6), (12, 5, 10), (30, 5, 10) }) {
			NocatFarm.Windows.MiniLayout.Plan c = Fit(n, open: false), o = Fit(n, open: true);
			rowsSeen.Add($"{n}: {Shape(c)} / {Shape(o)}");
			rowsRight &= (c.Count == closed) && (o.Count == opened) && (c.First == 0) && (o.First == 0) && (c.Footer == (n > 5)) && (o.Footer == (n > 5))
				&& (c.MaxScroll == 0) && (o.MaxScroll == Math.Max(0, n - 10)) && (c.Hidden == n - closed);
		}

		Check("mini rows: closed shows 5 at most, open 10, the bar only past 5 - for 3, 5, 6, 12 and 30 accounts", rowsRight, string.Join("; ", rowsSeen));
		Check("mini rows: 5 or fewer look exactly as before - title and rows, no bar, open or closed alike",
			(Fit(3, false).Height == 30 + (3 * 30)) && (Fit(5, false).Height == 30 + (5 * 30)) && (Fit(5, true) == Fit(5, false)) && (Fit(0, false).Height == 60));
		Check("mini rows: the bar adds its own height", (Fit(6, false).Height == 30 + (5 * 30) + 24) && (Fit(12, true).Height == 30 + (10 * 30) + 24));

		NocatFarm.Windows.MiniLayout.Plan past = Fit(12, true, scroll: 99), before = Fit(12, true, scroll: -5), closedScroll = Fit(30, false, scroll: 7), few = Fit(8, true, scroll: 3);
		Check("mini scroll: open, past the end stops at the last 10; before the start stops at the top", (past.Scroll == 2) && (past.First == 2) && (past.Count == 10) && (before.Scroll == 0),
			$"{Shape(past)} / {Shape(before)}");
		Check("mini scroll: closed never scrolls (the top 5 is where the problems are), and 10 or fewer open don't either",
			(closedScroll.Scroll == 0) && (closedScroll.First == 0) && (few.Scroll == 0) && (few.MaxScroll == 0));

		NocatFarm.Windows.MiniLayout.Plan farming = NocatFarm.Windows.MiniLayout.Fit(Rows(30, NocatFarm.Windows.MiniLayout.FocusH), true, 0, 400);
		NocatFarm.Windows.MiniLayout.Plan farmingEnd = NocatFarm.Windows.MiniLayout.Fit(Rows(30, NocatFarm.Windows.MiniLayout.FocusH), true, 99, 400);
		NocatFarm.Windows.MiniLayout.Plan tiny = NocatFarm.Windows.MiniLayout.Fit(Rows(12), false, 0, 100);
		Check("mini height: never taller than the screen's work area - fewer rows fit and the rest scroll",
			(farming.Height <= 400) && (farming.Count == 5) && (farming.MaxScroll == 25) && (farmingEnd.First == 25) && (farmingEnd.Count == 5) && (tiny.Height <= 100) && (tiny.Count >= 1),
			$"{Shape(farming)} / {Shape(farmingEnd)} / {Shape(tiny)}");
		Check("mini height: a mix of farming and plain rows adds up", NocatFarm.Windows.MiniLayout.Fit([58, 30, 30], false, 0, Screen).Height == 30 + 58 + 30 + 30);

		List<string> order = NocatFarm.Windows.MiniLayout.ProblemsFirst(["a", "b", "guard", "c", "failed", "d"], static x => x is "guard" or "failed");
		Check("mini order: accounts that need you first, then the rest in the dashboard's order", order.SequenceEqual(["guard", "failed", "a", "b", "c", "d"]), string.Join(",", order));

		string[] groups = ["needsyou", "farming", "idling", "idling", "playing", "idling", "idling", "idling", "asleep", "idling", "idling", "idling"];
		var closedBar = NocatFarm.Windows.MiniLayout.Footer(Fit(12, false), false, groups);
		string closedText = NocatFarm.Windows.MiniLayout.Text(closedBar);
		string openText = NocatFarm.Windows.MiniLayout.Text(NocatFarm.Windows.MiniLayout.Footer(Fit(12, true), true, groups));
		string tieText = NocatFarm.Windows.MiniLayout.Text(NocatFarm.Windows.MiniLayout.Footer(Fit(9, false), false, ["idling", "idling", "idling", "idling", "idling", "asleep", "asleep", "farming", "farming"]));
		Check("mini bar: closed counts the hidden accounts by what they're doing, biggest first", closedText == "+7 more · 6 idling · 1 asleep", closedText);
		Check("mini bar: open says how many there are", openText == "12 accounts", openText);
		Check("mini bar: a tie goes in the dashboard's chip order", tieText == "+4 more · 2 farming · 2 asleep", tieText);
		Check("mini bar: only the numbers are drawn strong", closedBar.Where(static p => p.Strong).Select(static p => p.Text).SequenceEqual(["7", "6", "1"]));

		// The figure in the title bar: a single choice, game-hours today unless changed.
		// From the whole list rather than this OS's: on Linux, Mac and Docker there is no mini window, so it isn't offered there.
		var everyGlobal = (List<NocatFarm.Config.SettingDef>) typeof(NocatFarm.Config.Settings).GetMethod("BuildGlobal", BindingFlags.NonPublic | BindingFlags.Static)!.Invoke(null, null)!;
		NocatFarm.Config.SettingDef? stats = everyGlobal.FirstOrDefault(static d => d.Name == "MiniStats");
		Check("mini figure: offered only where there's a mini window", (NocatFarm.Config.Settings.FindGlobal("MiniStats") != null) == OperatingSystem.IsWindows());
		var probe = new NocatFarm.Config.GlobalConfig();
		string? hoursErr = stats == null ? "missing" : NocatFarm.Config.Settings.Apply(probe, stats, "hours today");
		int afterHours = probe.MiniStats;
		string? cardsErr = stats == null ? "missing" : NocatFarm.Config.Settings.Apply(probe, stats, "cards today");
		int afterCards = probe.MiniStats;
		string? numberErr = stats == null ? "missing" : NocatFarm.Config.Settings.Apply(probe, stats, "8");
		int afterNumber = probe.MiniStats;
		string? badErr = stats == null ? null : NocatFarm.Config.Settings.Apply(probe, stats, "lots");
		Check("mini figure: one choice, set by its words or its number from the console; anything else is refused",
			(stats is { Kind: NocatFarm.Config.SettingKind.Choice }) && (hoursErr == null) && (afterHours == 1) && (cardsErr == null) && (afterCards == 4)
			&& (numberErr == null) && (afterNumber == 8) && (badErr != null) && (probe.MiniStats == 8));
		Check("mini figure: game-hours today by default, and a config from before the setting gets the same",
			(NocatFarm.Config.Settings.GlobalDefaults.MiniStats == NocatFarm.Windows.MiniLayout.StatHoursToday)
			&& (System.Text.Json.JsonSerializer.Deserialize<NocatFarm.Config.GlobalConfig>("{}")!.MiniStats == 1)
			&& NocatFarm.Config.Settings.ChoiceLabel(stats!, 1) == "hours today" && NocatFarm.Config.Settings.ChoiceLabel(stats!, 0) == "nothing");

		// Game-hours exactly as the daily summary counts them: every running game, so 8 games for 24 hours is 192 hours.
		string one = "harness-mini-" + Guid.NewGuid().ToString("N")[..6], two = "harness-mini-" + Guid.NewGuid().ToString("N")[..6];
		uint[] eight = [.. Enumerable.Range(1, 8).Select(static i => (uint) (570 + i))];

		for (int i = 0; i < 24 * 12; i++) {
			NocatFarm.Core.History.AddPlay(one, 5, eight);   // 24 hours in five-minute ticks
			NocatFarm.Core.History.AddPlay(two, 5, eight);
		}

		var b1 = new NocatFarm.Core.Bot(one, new NocatFarm.Config.BotConfig());
		var b2 = new NocatFarm.Core.Bot(two, new NocatFarm.Config.BotConfig());
		string Stat(int pick, params NocatFarm.Core.Bot[] bots) => NocatFarm.Windows.MiniLayout.Stat(pick, bots);
		Check("mini figure: one account running 8 games for 24 hours is 192h today", Stat(1, b1) == "192h today", Stat(1, b1));
		Check("mini figure: two accounts are added up", Stat(1, b1, b2) == "384h today", Stat(1, b1, b2));
		Check("mini figure: the week and the month read the same day-by-day history", (Stat(2, b1) == "192h past week") && (Stat(3, b1, b2) == "384h past month"), $"{Stat(2, b1)} / {Stat(3, b1, b2)}");
		Check("mini figure: the hours are the same banked game-minutes the history and summaries use",
			Math.Abs(NocatFarm.Core.History.MinutesOver(1, [one]) - (192 * 60)) < 0.01 && (NocatFarm.Core.ReportCard.Hours(192 * 60) == "192h"));
		Check("mini figure: nothing is nothing; no hours yet is 0h; online and inventory value",
			(Stat(0, b1) == "") && (Stat(1, new NocatFarm.Core.Bot("harness-mini-none-" + Guid.NewGuid().ToString("N")[..6], new NocatFarm.Config.BotConfig())) == "0h today")
			&& (Stat(7, b1, b2) == "0/2 online") && (Stat(8, b1, b2) == NocatFarm.PriceBook.Symbol + "0.00 inventory")
			&& System.Text.RegularExpressions.Regex.IsMatch(Stat(4, b1), @"^(1 card|\d+ cards) today$") && System.Text.RegularExpressions.Regex.IsMatch(Stat(5, b1), @"^(1 achievement|\d+ achievements) today$"),
			$"{Stat(7, b1, b2)} / {Stat(8, b1, b2)} / {Stat(4, b1)} / {Stat(5, b1)}");
	} finally {
		NocatFarm.Config.Live.Global.Language = langBefore;
	}

	string root = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm");
	string mw = File.ReadAllText(Path.Combine(root, "Windows", "MainWindow.cs")).Replace("\r\n", "\n");
	string settingsSrc = File.ReadAllText(Path.Combine(root, "Config", "Settings.cs"));
	Check("mini window: the old untranslated '+N more' line is gone, the bar replaces it, and the width never changes",
		!mw.Contains("'full window' for all of them", StringComparison.Ordinal) && mw.Contains("PaintMiniFooter(dc, y, plan,", StringComparison.Ordinal)
		&& mw.Contains("private const int MiniW = 300;", StringComparison.Ordinal) && (System.Text.RegularExpressions.Regex.Matches(mw, @"\bMiniW\s*=[^=]").Count == 1));
	Check("mini window: a figure too long for the title bar ends in an ellipsis instead of widening anything",
		mw.Contains("Clipped(dc, figure, titleEnd + 10, 8, room, _fontSmall, TextDim);", StringComparison.Ordinal));
	Check("mini window: problems are said in yellow, open/closed is remembered, the wheel scrolls only while open",
		mw.Contains("Clipped(dc, doing, textX, y + 8, buttonX - textX - 6, _fontSmall, trouble != null ? Amber", StringComparison.Ordinal)
		&& mw.Contains("Live.Global.MiniExpanded = !Live.Global.MiniExpanded;", StringComparison.Ordinal)
		&& mw.Contains("if (Live.Global.MiniExpanded && (notches != 0)) {", StringComparison.Ordinal));
	Check("mini window: the figure is a Windows-only setting, hidden on Linux, Mac and Docker",
		settingsSrc.Contains("\"MiniOnTop\", \"MiniStats\",", StringComparison.Ordinal));
	Check("summaries and mini mode share one 'needs you' answer",
		File.ReadAllText(Path.Combine(root, "Core", "ReportCard.cs")).Contains("List<Said?> wrong = [Trouble(b, nowUtc)];", StringComparison.Ordinal)
		&& mw.Contains("ReportCard.Trouble(b, now)", StringComparison.Ordinal));
	Check("achievements today: every way of unlocking one counts it",
		File.ReadAllText(Path.Combine(root, "Modules", "AchievementPacer.cs")).Contains("Stats.Record(Stats.KindAchievement, Bot.Name);", StringComparison.Ordinal)
		&& File.ReadAllText(Path.Combine(root, "Commands.cs")).Contains("Stats.Record(Stats.KindAchievement, bot.Name, changed);", StringComparison.Ordinal)
		&& File.ReadAllText(Path.Combine(root, "Core", "UnlockEverything.cs")).Contains("Stats.Record(Stats.KindAchievement, bot.Name, changed);", StringComparison.Ordinal));
}

// ── Linux, Mac and Docker: what differs off Windows ─────────────────────────
{
	const BindingFlags S = BindingFlags.Static | BindingFlags.NonPublic | BindingFlags.Public;
	Type su = typeof(NocatFarm.Core.SelfUpdate);
	string root = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm");

	// The line that starts the swap script reaches sh with \n alone. Built on Windows (where the Linux zips are made) the
	// source has \r\n, and sh ran each \r as a command - "not found" errors on the console at every update.
	string detached = (string) su.GetProperty("DetachedStart", S)!.GetValue(null)!;
	Check("update: the line that starts the swap script has no \\r in it, whatever the source's line endings",
		!detached.Contains('\r') && detached.StartsWith("if command -v setsid", StringComparison.Ordinal) && detached.EndsWith("fi", StringComparison.Ordinal)
		&& File.ReadAllText(Path.Combine(root, "Core", "SelfUpdate.cs")).Contains("swap.ArgumentList.Add(DetachedStart);", StringComparison.Ordinal));

	// A copy that failed: robocopy's 8-15 is "files in use" on Windows; the sh script's 8 off Windows is any copy that
	// failed - a folder it can't write to or a full disk - and never a file in use or antivirus.
	string Why(string code, bool windows) => su.GetMethod("SwapFailure", S)!.Invoke(null, [code, windows])!.ToString()!;
	string langWas = NocatFarm.Config.Live.Global.Language;

	try {
		NocatFarm.Config.Live.Global.Language = "en";
		NocatFarm.Core.Loc.Refresh();
		Check("update failed (Windows): robocopy's 8 to 15 is files in use",
			Why("8", true).Contains("files in use", StringComparison.Ordinal) && Why("11", true).Contains("files in use", StringComparison.Ordinal), Why("8", true));
		Check("update failed (Linux, Mac): the script's 8 is read-only or a full disk, not antivirus",
			Why("8", false).Contains("read-only? disk full?", StringComparison.Ordinal) && !Why("8", false).Contains("antivirus", StringComparison.Ordinal), Why("8", false));
		Check("update failed: robocopy's 16 and the backup copy say what they always did",
			Why("16", true).Contains("copy error 16", StringComparison.Ordinal) && Why("backup 112", false).Contains("backup copy error 112", StringComparison.Ordinal));
	} finally {
		NocatFarm.Config.Live.Global.Language = langWas;
		NocatFarm.Core.Loc.Refresh();
	}

	// Copies from this folder are known by the program file. Started as "dotnet nocatFarm.dll" that's the .NET host, and
	// the script took every .NET program on the machine for another nocat.farm here.
	string ProgramOf(string? running, string here) => (string) su.GetMethod("ProgramPath", S)!.Invoke(null, [running, here, "nocatFarm"])!;
	Check("update: the swap script knows this copy by its own program, not the .NET host it was started with",
		(ProgramOf("/usr/lib/dotnet/dotnet", "/opt/nf") == Path.Combine("/opt/nf", "nocatFarm"))
		&& (ProgramOf("/usr/local/share/dotnet/dotnet", "/Users/me/nf") == Path.Combine("/Users/me/nf", "nocatFarm"))
		&& (ProgramOf(null, "/opt/nf") == Path.Combine("/opt/nf", "nocatFarm"))
		&& (ProgramOf("/home/me/nocat.farm (1)/nocatFarm", "/home/me/nocat.farm (1)") == "/home/me/nocat.farm (1)/nocatFarm")
		&& File.ReadAllText(Path.Combine(root, "Core", "SelfUpdate.cs")).Contains("swap.Environment[\"NF_EXE\"] = ProgramPath(Environment.ProcessPath, here, ExeName);", StringComparison.Ordinal));

	// Example folders in the shape of a path on the machine it runs on: the dashboard's import box went by "can it update
	// itself", which a Linux desktop and a Mac can - so they were shown C:\...\folder.
	string jsSrc = File.ReadAllText(Path.Combine(root, "wwwroot", "app.js"));
	string webSrc = File.ReadAllText(Path.Combine(root, "Web", "WebHost.cs"));
	Check("import: the dashboard's folder example follows the system, not whether it can update itself",
		jsSrc.Contains("function folderHint() { return state && state.Windows === false ? '/path/to/folder' : 'C:\\\\...\\\\folder'; }", StringComparison.Ordinal)
		&& webSrc.Contains("CanSelfUpdate = SelfUpdate.Supported,", StringComparison.Ordinal) && webSrc.Contains("\t\t\tWindows = OperatingSystem.IsWindows(),", StringComparison.Ordinal));
	Check("import: the console's 'point at it' example is a path for this system",
		File.ReadAllText(Path.Combine(root, "Commands.cs")).Contains("import {args[0]} {(OperatingSystem.IsWindows() ? @\"C:\\path\\to\\it\" : \"/path/to/it\")}", StringComparison.Ordinal));
}

// ── a sitting ends with its game, metas don't wait on each other, 'dlc leave' is kept on disk, hours typed ─────
{
	const BindingFlags SP = BindingFlags.Static | BindingFlags.NonPublic;
	string repoSrc = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm");
	string pacerSrc = File.ReadAllText(Path.Combine(repoSrc, "Modules", "AchievementPacer.cs")).Replace("\r\n", "\n");

	// A sitting: a game stopped for a break, the night or a sign-out starts a new one when it runs again.
	MethodInfo keepSittings = typeof(NocatFarm.Modules.AchievementPacer).GetMethod("KeepSittings", SP)!;
	Dictionary<uint, DateTime> sittings = new() { [730] = DateTime.UtcNow.AddHours(-9), [440] = DateTime.UtcNow.AddMinutes(-40) };
	keepSittings.Invoke(null, [sittings, new List<uint> { 440 }]);
	bool keptRunning = sittings.Keys.SequenceEqual([440u]);
	keepSittings.Invoke(null, [sittings, new List<uint>()]);
	int step = pacerSrc.IndexOf("private async Task StepAsync(", StringComparison.Ordinal);
	string stepSrc = step < 0 ? "" : pacerSrc[step..pacerSrc.IndexOf("private List<uint> CurrentGames()", step, StringComparison.Ordinal)];
	int kept = stepSrc.IndexOf("KeepSittings(_sittingSince, running);", StringComparison.Ordinal);
	int nothing = stepSrc.IndexOf("if (running.Count == 0) {", StringComparison.Ordinal);
	Check("pacer sittings: a game that stopped ends its sitting - also while nothing runs (a break, the night), so it can't unlock in its first minute back",
		keptRunning && (sittings.Count == 0) && (kept > 0) && (nothing > kept)
		&& stepSrc.Contains("_status = new Said(\"waiting\");\n\n\t\t\t// Nothing of ours is running now, so whatever runs next is a new sitting.\n\t\t\tKeepSittings(_sittingSince, []);", StringComparison.Ordinal)
		&& stepSrc.Contains("if (elapsed > 3) {\n\t\t\t// A gap (the PC asleep, a stall): no telling what ran in it - start every sitting again.\n\t\t\tKeepSittings(_sittingSince, []);", StringComparison.Ordinal)
		&& (System.Text.RegularExpressions.Regex.Matches(stepSrc, @"_sittingSince\.Remove").Count == 0));

	// "For having the others": two of them never wait on each other for good.
	MethodInfo inOrder = typeof(NocatFarm.Modules.AchievementPacer).GetMethod("InOrder", SP)!;
	NocatFarm.Core.Achievement A(string name, string desc, double pct, bool unlocked = false) =>
		new() { Name = name, Display = name, Description = desc, StatId = 1, Bit = 0, Unlocked = unlocked, Protected = false, GlobalPercent = pct };
	bool Ordered(NocatFarm.Core.Achievement a, List<NocatFarm.Core.Achievement> all) =>
		(bool) inOrder.Invoke(null, [a, all, all, all.Count(static x => x.Unlocked), 500.0, null])!;
	NocatFarm.Core.Achievement everyOther = A("ALL", "Obtain all other achievements", 2), baseOnes = A("BASE", "Obtain all base game achievements", 3);
	List<NocatFarm.Core.Achievement> both = [everyOther, baseOnes, A("ONE", "Find a hat", 80, unlocked: true), A("TWO", "Pet the dog", 60, unlocked: true)];
	List<NocatFarm.Core.Achievement> baseDone = [everyOther, baseOnes with { Unlocked = true }, A("ONE", "Find a hat", 80, unlocked: true)];
	List<NocatFarm.Core.Achievement> twoAll = [everyOther, A("PLAT", "Unlock every achievement", 1), A("ONE", "Find a hat", 80, unlocked: true)];
	List<NocatFarm.Core.Achievement> oneLeft = [everyOther, baseOnes, A("ONE", "Find a hat", 80)];
	Check("pacer metas: 'all base game achievements' goes while 'all other achievements' waits for it, then that one goes - neither held for good",
		Ordered(baseOnes, both) && !Ordered(everyOther, both) && Ordered(everyOther, baseDone));
	Check("pacer metas: two 'every achievement' ones don't hold each other for good; any ordinary one still locked holds both",
		Ordered(everyOther, twoAll) && Ordered(twoAll[1], twoAll) && !Ordered(everyOther, oneLeft) && !Ordered(baseOnes, oneLeft));

	// Typed hours: only the dots of a.m. and p.m. are taken out.
	int? Hr(string raw) => NocatFarm.Config.Settings.ParseHour(raw);
	Check("hour settings: '1.5' or '0.9' isn't 15 or 9; '9 p.m.', '9pm.' and '9 a.m.' still are",
		(Hr("1.5") == null) && (Hr("0.9") == null) && (Hr("9.00") == null) && (Hr("9 p.m.") == 21) && (Hr("9pm.") == 21) && (Hr("9 a.m.") == 9) && (Hr("12 p.m") == 12),
		$"{Hr("1.5")} {Hr("0.9")} {Hr("9.00")} {Hr("9 p.m.")} {Hr("9pm.")} {Hr("9 a.m.")}");

	// 'dlc leave' on an account whose file still has the old "carry on" list (1.6.4-1.6.9): left alone, kept on disk with
	// the add-ons it owned then - and the old list, read by nothing, gone from the file.
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	NocatFarm.Config.GlobalConfig realGlobal = NocatFarm.Config.Live.Global;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-sitting-" + Guid.NewGuid().ToString("N"));
	Directory.CreateDirectory(Path.Combine(tmpRoot, "config", "state"));
	NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);

	try {
		File.WriteAllText(Path.Combine(tmpRoot, "config", "state", "cheevo-rollme.json"), """
			[ { "App": 950, "Last": 1, "Total": 50, "Unlocked": 10, "Unclear": true, "DlcOwned": [951], "DlcKey": "951" },
			  { "App": 960, "Last": 1, "Total": 50, "Unlocked": 10, "Unclear": true, "DlcOwned": [], "DlcKey": "" } ]
			""");
		var mgr = new NocatFarm.Core.BotManager(new NocatFarm.Config.GlobalConfig { WebEnabled = false });
		var bots = (System.Collections.Concurrent.ConcurrentDictionary<string, NocatFarm.Core.Bot>) typeof(NocatFarm.Core.BotManager)
			.GetField("_bots", BindingFlags.NonPublic | BindingFlags.Instance)!.GetValue(mgr)!;
		File.WriteAllText(Path.Combine(tmpRoot, "config", "rollme.json"), """{ "UnlockAchievements": true, "AchievementDlcTrusted": [950, 960] }""");
		var rollme = new NocatFarm.Core.Bot("rollme", NocatFarm.Config.ConfigStore.LoadBot("rollme")!);
		rollme.AddModule(new NocatFarm.Modules.AchievementPacer(rollme));
		bots["rollme"] = rollme;

		string left = await Commands.RunAsync(mgr, "dlc leave rollme 950");
		string onDisk = File.ReadAllText(Path.Combine(tmpRoot, "config", "rollme.json"));
		string undone = await Commands.RunAsync(mgr, "dlc undo rollme 950");
		string undoneDisk = File.ReadAllText(Path.Combine(tmpRoot, "config", "rollme.json"));
		Check("dlc leave: kept on disk with the add-ons it owned then, the old 'carry on' list gone from the file; undo takes it off again",
			left.Contains("is left alone for achievements now", StringComparison.Ordinal)
			&& System.Text.RegularExpressions.Regex.IsMatch(onDisk, @"""AchievementDlcLeft"":\s*\{\s*""950"":\s*""951""")
			&& !onDisk.Contains("AchievementDlcTrusted", StringComparison.Ordinal) && rollme.Cfg.UnlockAchievements
			&& undone.Contains("earns achievements again", StringComparison.Ordinal) && !undoneDisk.Contains("\"950\"", StringComparison.Ordinal),
			left + " / " + onDisk);
	} finally {
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);
		NocatFarm.Config.Live.Global = realGlobal;

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
			// temp - it goes when Windows tidies up
		}
	}
}

// ── the rep4rep preview says the window the account keeps ──────────────────────────────────────────────────
{
	// An end at or before the start is no window at all - the account comments around the clock. The preview said
	// "between 10 PM and 6 AM" for that, a window it never keeps.
	var bot = new NocatFarm.Core.Bot("harness-r4rwin-" + Guid.NewGuid().ToString("N")[..6],
		new NocatFarm.Config.BotConfig { Rep4RepStartHour = 22, Rep4RepEndHour = 6 });
	using var api = new NocatFarm.Rep4Rep.Rep4RepApi();
	var r4r = new NocatFarm.Modules.Rep4RepModule(bot, api);
	MethodInfo wait = typeof(NocatFarm.Modules.Rep4RepModule).GetMethod("WindowWaitSeconds", BindingFlags.NonPublic | BindingFlags.Instance)!;
	bool reversedIsOpen = (int) wait.Invoke(r4r, [])! == 0;
	bot.Cfg.Rep4RepStartHour = 9;
	bot.Cfg.Rep4RepEndHour = 9;
	bool sameIsOpen = (int) wait.Invoke(r4r, [])! == 0;
	string js = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "wwwroot", "app.js")).Replace("\r\n", "\n");
	Check("rep4rep preview: an end at or before the start reads 'around the clock', as the account comments then",
		reversedIsOpen && sameIsOpen
		&& js.Contains("const hours = Number(from) >= Number(to)\n      ? t('around the clock')", StringComparison.Ordinal)
		&& !js.Contains("const hours = from === to", StringComparison.Ordinal));
	await bot.DisposeAsync();
}

// ── 'cheevo unlock' on one of two "for having the others" ones goes by the pacer's rule ──────────────────────
{
	// Asked as a batch of one, "all other achievements" and "unlock every achievement" each waited on the other: both
	// refused for good, with everything else unlocked - while the pacer itself unlocks them.
	MethodInfo whyNotOne = typeof(NocatFarm.Commands).GetMethod("WhyNotOne", BindingFlags.NonPublic | BindingFlags.Static)!;
	NocatFarm.Core.Achievement A(string name, string desc, double pct, bool unlocked = false) =>
		new() { Name = name, Display = name, Description = desc, StatId = 1, Bit = 0, Unlocked = unlocked, Protected = false, GlobalPercent = pct };
	string WhyNot(List<NocatFarm.Core.Achievement> all, NocatFarm.Core.Achievement one) =>
		whyNotOne.Invoke(null, [new NocatFarm.Core.Bot("h4why", new NocatFarm.Config.BotConfig()),
			new NocatFarm.Core.AchievementSet { AppId = 5, All = all, CrcStats = 0 }, one])!.ToString()!;
	NocatFarm.Core.Achievement allOther = A("ALL", "Obtain all other achievements", 2), every = A("PLAT", "Unlock every achievement", 1);
	NocatFarm.Core.Achievement baseAll = A("BASE", "Obtain all base game achievements", 3), plain = A("ONE", "Find a hat", 80);
	Check("cheevo unlock: two 'every achievement' ones don't refuse each other for good; an ordinary one locked still holds them",
		(WhyNot([allOther, every, plain with { Unlocked = true }], allOther).Length == 0)
		&& (WhyNot([allOther, every, plain with { Unlocked = true }], every).Length == 0)
		&& WhyNot([allOther, every, plain], allOther).Contains("is for having the others", StringComparison.Ordinal)
		&& WhyNot([allOther, baseAll, plain with { Unlocked = true }], allOther).Contains("is for having the others", StringComparison.Ordinal)
		&& (WhyNot([allOther, baseAll, plain with { Unlocked = true }], baseAll).Length == 0)
		&& File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Commands.cs"))
			.Contains("if (AchievementPacer.MetaBlocked(one, set.All)) {", StringComparison.Ordinal),
		WhyNot([allOther, every, plain with { Unlocked = true }], allOther));
}

// ── "for having the others" achievements go the moment they're earned, as a game awards them ──────────────────
{
	const BindingFlags SP = BindingFlags.Static | BindingFlags.NonPublic;
	Type pacerType = typeof(NocatFarm.Modules.AchievementPacer);
	MethodInfo readyMetas = pacerType.GetMethod("ReadyMetas", SP)!;
	MethodInfo withoutMetas = pacerType.GetMethod("WithoutWaitingMetas", SP)!;
	NocatFarm.Core.Achievement A(string name, string desc, double pct, bool unlocked = false) =>
		new() { Name = name, Display = name, Description = desc, StatId = 1, Bit = 0, Unlocked = unlocked, Protected = false, GlobalPercent = pct };
	string Ready(List<NocatFarm.Core.Achievement> candidates, List<NocatFarm.Core.Achievement> all, params string[] just) =>
		string.Join(",", ((List<NocatFarm.Core.Achievement>) readyMetas.Invoke(null, [candidates, all, new HashSet<string>(just, StringComparer.Ordinal)])!).Select(static a => a.Name));
	int Waiting(List<NocatFarm.Core.Achievement> all, List<NocatFarm.Core.Achievement> going) {
		object r = withoutMetas.Invoke(null, [all, going])!;
		return (int) r.GetType().GetField("Item2")!.GetValue(r)!;
	}

	NocatFarm.Core.Achievement allOther = A("ALL", "Obtain all other achievements", 2), every = A("PLAT", "Unlock every achievement", 1);
	NocatFarm.Core.Achievement baseAll = A("BASE", "Obtain all base game achievements", 3);
	NocatFarm.Core.Achievement one = A("ONE", "Find a hat", 80, unlocked: true), last = A("TWO", "Pet the dog", 0.5), other = A("THREE", "Ride the boat", 40);

	// The last ordinary one makes both metas ready - "all base game" and then "all other", which only waited on it - and
	// they go together; with anything ordinary still locked, nothing is ready; nothing goes before what it waits on.
	List<NocatFarm.Core.Achievement> game = [allOther, baseAll, one, last];
	Check("pacer metas: the unlock that completes them makes both ready together ('all base game', then 'all other' that waited on it); before it, none",
		(Ready([allOther, baseAll, last], game, "TWO") == "BASE,ALL") && (Ready([allOther, baseAll, last], game) == "")
		&& (Ready([allOther, baseAll, last, other], [.. game, other], "TWO") == ""),
		Ready([allOther, baseAll, last], game, "TWO"));

	// Already everything else (unlocked before this version): ready with nothing just unlocked - the next tick's look.
	Check("pacer metas: everything else already unlocked - ready on the look, with no unlock first; two 'every achievement' ones together",
		(Ready([allOther], [allOther, one]) == "ALL") && (Ready([allOther, every], [allOther, every, one]) == "ALL,PLAT"));

	// Only candidates go: one held for DLC, refused or Steam's own isn't unlocked - and "all base game" held keeps "all other"
	// locked (it is one of the others); another "every achievement" one held doesn't.
	Check("pacer metas: a held 'all base game' one keeps 'all other' locked; a held 'every achievement' one doesn't; a counter short or Steam's own never goes",
		(Ready([allOther], [allOther, baseAll, one]) == "") && (Ready([allOther], [allOther, every, one]) == "ALL")
		&& (Ready([allOther with { ProgressMax = 10, ProgressNow = 1 }], [allOther with { ProgressMax = 10, ProgressNow = 1 }, one]) == ""));

	// Bulk unlocks the same: a meta isn't kept locked by another one that can never be unlocked, but "all base game"
	// staying locked still holds "all other".
	Check("unlock everything metas: another 'every achievement' one staying locked doesn't hold one; 'all base game' staying locked holds 'all other'",
		(Waiting([allOther, every, one], [allOther]) == 0) && (Waiting([allOther, baseAll, one], [allOther]) == 1)
		&& (Waiting([allOther, baseAll, one], [allOther, baseAll]) == 0) && (Waiting([baseAll, A("B2", "Earn all main game achievements", 4), one], [baseAll]) == 0));

	// Wiring: the look outside the spacing, metas first and never an ordinary pick, the follow-up within the ceiling and
	// without a slot of its own, 'cheevo unlock' asking for a look.
	string src = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Modules", "AchievementPacer.cs")).Replace("\r\n", "\n");
	string cmds = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Commands.cs")).Replace("\r\n", "\n");
	int look = src.IndexOf("if (metaLook && await MetaLookAsync(app, g, prof, ct).ConfigureAwait(false)) {", StringComparison.Ordinal);
	int due = src.IndexOf("if ((now < _sittingSince[app]) || !Due(g, prof)) {", StringComparison.Ordinal);
	int mayNot = src.IndexOf("\t\t\tif (!mayUnlock) {\n\t\t\t\tcontinue;\n\t\t\t}", StringComparison.Ordinal);
	Check("pacer metas: looked for on the tick before the spacing and the sitting, after the stand-down and awake checks; within the ceiling; no slot used",
		(mayNot > 0) && (look > mayNot) && (due > look)
		&& src.Contains("if ((ready.Count > 0) && (already + ready.Count <= ceilingCount)) {", StringComparison.Ordinal)
		&& src.Contains("if ((follow.Count > 0) && (nowUnlocked + follow.Count <= ceilingCount)) {", StringComparison.Ordinal)
		&& src.Contains("&& (already + ready.Count <= CeilingCount(sorted.Reachable, ceiling, prof.OnboardCount))", StringComparison.Ordinal)
		&& src.Contains("List<Achievement> eligible = [.. Eligible(sorted, set.All, already, floor, hours, typical).Where(static a => TraitsOf(a).Meta == Meta.None)];", StringComparison.Ordinal)
		&& src.Contains("Sorted sorted = Sort(set, dlc, Bot.Cfg.AchievementSkipMultiplayer, refused);", StringComparison.Ordinal)
		&& (src[src.IndexOf("private async Task<int> UnlockMetasAsync(", StringComparison.Ordinal)..].Split("\n\t}\n")[0] is string body)
		&& !body.Contains("NextAllow", StringComparison.Ordinal) && !body.Contains("MinsAtLastUnlock", StringComparison.Ordinal) && !body.Contains("BurstLeft", StringComparison.Ordinal)
		&& cmds.Contains("BotManager.ModuleOf<AchievementPacer>(bot)?.LookForMetas(appId);", StringComparison.Ordinal));

	// Kept over a restart: an older state file (no MetasLooked) gets one look per game; a look done is saved as done.
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-metas-" + Guid.NewGuid().ToString("N"));
	Directory.CreateDirectory(Path.Combine(tmpRoot, "config", "state"));
	NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);

	try {
		string statePath = Path.Combine(tmpRoot, "config", "state", "cheevo-h4metas.json");
		File.WriteAllText(statePath, """
			[ { "App": 970, "Last": 1, "Total": 10, "Unlocked": 9 },
			  { "App": 980, "Last": 1, "Total": 10, "Unlocked": 9, "MetasLooked": true } ]
			""");
		var bot = new NocatFarm.Core.Bot("h4metas", new NocatFarm.Config.BotConfig { UnlockAchievements = true });
		var pacer = new NocatFarm.Modules.AchievementPacer(bot);
		pacerType.GetMethod("EnsureLoaded", BindingFlags.NonPublic | BindingFlags.Instance)!.Invoke(pacer, []);
		var h4Known = (System.Collections.IDictionary) pacerType.GetField("_games", BindingFlags.NonPublic | BindingFlags.Instance)!.GetValue(pacer)!;
		FieldInfo lookField = h4Known[970u]!.GetType().GetField("MetaLook")!;
		bool oldFileLooks = (bool) lookField.GetValue(h4Known[970u])! && !(bool) lookField.GetValue(h4Known[980u])!;
		lookField.SetValue(h4Known[970u], false);   // looked
		pacer.LookForMetas(980);                  // 'cheevo unlock' in it
		var saved = System.Text.Json.JsonDocument.Parse(File.ReadAllText(statePath)).RootElement.EnumerateArray()
			.ToDictionary(static e => e.GetProperty("App").GetUInt32(), static e => e.GetProperty("MetasLooked").GetBoolean());
		Check("pacer metas: an older state file gets one look per game; a look done is kept as done over a restart, 'cheevo unlock' asks again",
			oldFileLooks && saved[970] && !saved[980], string.Join(" ", saved.Select(static kv => $"{kv.Key}={kv.Value}")));
		await bot.DisposeAsync();
	} finally {
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
			// temp - it goes when Windows tidies up
		}
	}
}

// ── Steam chat, bans, drops, hours, trades and gifts while you play, free games, dashboard, Windows update ──────
{
	const BindingFlags AnyInst = BindingFlags.NonPublic | BindingFlags.Public | BindingFlags.Instance;
	const BindingFlags AnyStatic = BindingFlags.NonPublic | BindingFlags.Public | BindingFlags.Static;
	string Src5(string rel) => File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", rel)).Replace("\r\n", "\n");
	void Prop5(NocatFarm.Core.Bot b, string p, object? v) => typeof(NocatFarm.Core.Bot).GetProperty(p, AnyInst)!.SetValue(b, v);

	string realRoot = NocatFarm.Config.ConfigStore.Root;
	NocatFarm.Config.GlobalConfig realGlobal = NocatFarm.Config.Live.Global;
	PropertyInfo currentWeb = typeof(NocatFarm.Web.WebHost).GetProperty("Current")!;
	object? realWeb = currentWeb.GetValue(null);
	NocatFarm.Core.BotManager? realHost = NocatFarm.Commands.Host;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-while-playing-" + Guid.NewGuid().ToString("N"));
	Directory.CreateDirectory(Path.Combine(tmpRoot, "config", "state"));
	NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);
	NocatFarm.Core.Visitors.Reload();
	List<NocatFarm.Core.Bot> made = [];

	NocatFarm.Core.Bot NewBot(string name, NocatFarm.Config.BotConfig cfg, NocatFarm.Core.BotState state = NocatFarm.Core.BotState.Online) {
		var b = new NocatFarm.Core.Bot(name, cfg);
		Prop5(b, "State", state);
		made.Add(b);
		return b;
	}

	try {
		// 1. Steam chat: 'log' and 'stats' are for the PC (the log has other accounts' 2fa answers and the Telegram connect
		// link; 'stats' opens with the report), and a command that means every account without a name means this one.
		var mgr = new NocatFarm.Core.BotManager(new NocatFarm.Config.GlobalConfig { WebEnabled = false });
		var bots = (System.Collections.Concurrent.ConcurrentDictionary<string, NocatFarm.Core.Bot>) typeof(NocatFarm.Core.BotManager)
			.GetField("_bots", BindingFlags.NonPublic | BindingFlags.Instance)!.GetValue(mgr)!;
		bots["kylro"] = NewBot("kylro", new NocatFarm.Config.BotConfig());
		bots["other"] = NewBot("other", new NocatFarm.Config.BotConfig());
		NocatFarm.Commands.Host = mgr;
		string chatLog = await NocatFarm.Commands.RunAsync("log 1000", "kylro");
		string chatLogs = await NocatFarm.Commands.RunAsync("logs", "kylro");
		string chatStats = await NocatFarm.Commands.RunAsync("stats", "kylro");
		Check("steam chat: 'log' (and 'logs') and 'stats' are refused - the PC, Telegram or Discord only",
			chatLog.Contains("has to be done at the PC", StringComparison.Ordinal) && chatLogs.Contains("has to be done at the PC", StringComparison.Ordinal)
			&& chatStats.Contains("has to be done at the PC", StringComparison.Ordinal), chatLog + " / " + chatStats);
		string Fill(string line) => NocatFarm.Commands.ThisBotFilledIn(mgr, line, "kylro");
		Check("steam chat: a bare 'freeitems', 'queue', 'offers', 'confirmations', 'balance', 'bans', 'booster' mean this account",
			Fill("freeitems") == "freeitems kylro" && Fill("queue") == "queue kylro" && Fill("offers") == "offers kylro" && Fill("confirmations") == "confirmations kylro"
			&& Fill("balance") == "balance kylro" && Fill("bans") == "bans kylro" && Fill("booster") == "booster kylro" && Fill("wallet") == "wallet kylro",
			Fill("freeitems") + " / " + Fill("wallet"));
		Check("steam chat: words after the command with no account named get this account first ('value refresh', 'pause 30')",
			Fill("value refresh") == "value kylro refresh" && Fill("inv refresh") == "inv kylro refresh" && Fill("pause 30") == "pause kylro 30", Fill("value refresh"));
		Check("steam chat: an account already named, or a command that takes none, is left as it is",
			Fill("offers kylro") == "offers kylro" && Fill("help") == "help" && Fill("version") == "version" && Fill("status") == "status kylro", Fill("offers kylro"));

		// 2. Ban watch: a ban stepping down to probation isn't new; "Multiple" + the days going down is; a notice page keeps the counts.
		static NocatFarm.Modules.BanWatch.Bans Ban(int vac, int game, bool community, string economy, int days) => new(vac, game, community, economy, days);
		static string NewsOf(NocatFarm.Modules.BanWatch.Bans before, NocatFarm.Modules.BanWatch.Bans now) =>
			string.Join(" | ", NocatFarm.Modules.BanWatch.News(before, now).Select(static s => s.ToEnglish()));
		Check("bans: a trade ban that steps down to probation isn't reported as a NEW problem", NewsOf(Ban(0, 0, false, "banned", 0), Ban(0, 0, false, "probation", 0)).Length == 0);
		Check("bans: probation after none still is", NewsOf(Ban(0, 0, false, "none", 0), Ban(0, 0, false, "probation", 0)).Contains("NEW trade probation", StringComparison.Ordinal));
		string multi = NewsOf(Ban(2, 0, false, "none", 400), Ban(2, 0, false, "none", 2));
		Check("bans: 'Multiple' VAC bans and another lands - the days since the last one went down, so it's said", multi.Contains("NEW ban", StringComparison.Ordinal) && multi.Contains("2", StringComparison.Ordinal), multi);
		string countUp = NewsOf(Ban(1, 0, false, "none", 400), Ban(2, 0, false, "none", 0));
		Check("bans: the days only going up says nothing; a count going up is said once, not twice",
			(NewsOf(Ban(2, 0, false, "none", 400), Ban(2, 0, false, "none", 401)).Length == 0) && !countUp.Contains('|') && countUp.Contains("NEW VAC ban", StringComparison.Ordinal), countUp);
		var notice = NocatFarm.Modules.BanWatch.ParseProfile("<html><body>This account has been community banned</body></html>")!;
		var kept = NocatFarm.Modules.BanWatch.OnNoticePage(notice, Ban(1, 1, false, "banned", 900));
		Check("bans: the community-ban notice page keeps the VAC, game and trade ban already known - no false NEW later",
			(kept.Vac == 1) && (kept.Game == 1) && (kept.Economy == "banned") && (kept.DaysSinceLast == 900) && kept.Community
			&& (NewsOf(Ban(1, 1, false, "banned", 900), kept) == "NEW community ban - Steam has community banned this account"), kept.ToString());

		// 3. A sign-in's own item count isn't a drop; the playtime batch reads the card pages before calling one.
		DateTime nowUtc = DateTime.UtcNow;
		Check("drops: the item count a sign-in asked for (within a minute) isn't a drop; a later push or none asked is",
			NocatFarm.Core.Bot.IsStandingCount(nowUtc.AddSeconds(-5).Ticks, nowUtc) && !NocatFarm.Core.Bot.IsStandingCount(0, nowUtc)
			&& !NocatFarm.Core.Bot.IsStandingCount(nowUtc.AddMinutes(-2).Ticks, nowUtc));
		string bot5 = Src5(Path.Combine("Core", "Bot.cs"));
		Check("drops: the sign-in's ask is marked just before it goes, and the answer to it doesn't set the latch",
			bot5.Contains("Interlocked.Exchange(ref _itemCountAskedTicks, DateTime.UtcNow.Ticks);\n\t\t\tNotifications?.RequestItemAnnouncements();", StringComparison.Ordinal)
			&& bot5.Contains("if (!standing) {\n\t\t\tSignalItemDrop();", StringComparison.Ordinal));
		string farm5 = Src5(Path.Combine("Modules", "CardFarmer.cs"));
		int bumpAt = farm5.IndexOf("private async Task BumpLoopAsync(", StringComparison.Ordinal);
		int pushAt = farm5.IndexOf("if (await Bot.WaitForItemDropAsync(slice, ct).ConfigureAwait(false)) {", bumpAt, StringComparison.Ordinal);
		int lookAt = farm5.IndexOf("bool? dropped = await DroppedInAsync(batch, ct)", pushAt, StringComparison.Ordinal);
		int rewardAt = farm5.IndexOf("Log.Reward(\"card dropped early - switching to farming\"", pushAt, StringComparison.Ordinal);
		Check("drops: a new item during the playtime batch is looked up on the card pages before 'card dropped early'; nothing new and it carries on",
			(bumpAt > 0) && (pushAt > bumpAt) && (lookAt > pushAt) && (rewardAt > lookAt) && farm5.Contains("if (dropped == false) {\n\t\t\t\t\tcontinue;", StringComparison.Ordinal)
			&& farm5.Contains("if (dropped == true) {\n\t\t\t\t\tLog.Reward(", StringComparison.Ordinal));

		// 4. Hours and the stuck alarm while you play with "stand down when I play" off.
		var hb = NewBot("h5-hours", new NocatFarm.Config.BotConfig { PauseWhenYouPlay = false });
		Prop5(hb, "PlayingApps", (IReadOnlyList<uint>) [440u, 570u]);
		bool banksAlone = NocatFarm.Modules.Heartbeat.Banks(hb);
		Prop5(hb, "OtherSessionApp", 730u);
		Check("hours: our games banked - not while you're playing on the account yourself (Steam ignores ours then)", banksAlone && !NocatFarm.Modules.Heartbeat.Banks(hb));
		Type sw = typeof(NocatFarm.Core.StuckWatch);
		Type watchT = sw.GetNestedType("Watch", BindingFlags.NonPublic | BindingFlags.Public)!;
		MethodInfo excuse = sw.GetMethod("Excuse", AnyStatic)!;
		string ExcuseOf(NocatFarm.Core.Bot b) => ((NocatFarm.Core.Said) excuse.Invoke(null, [b, Activator.CreateInstance(watchT, true)!, new DateTime(2026, 10, 1, 12, 0, 0, DateTimeKind.Utc)])!).ToEnglish();
		Check("stuck alarm: you playing with 'stand down when I play' off is still you playing", ExcuseOf(hb) == "you're playing on it", ExcuseOf(hb));
		var gone = NewBot("h5-gone", new NocatFarm.Config.BotConfig(), NocatFarm.Core.BotState.Reconnecting);
		Prop5(gone, "PlayingBlocked", true);
		string goneWhy = ExcuseOf(gone);
		Prop5(gone, "State", NocatFarm.Core.BotState.Online);
		Check("stuck alarm: bumped off by you and never back on isn't excused as 'you're playing on it'; signed in, it is",
			(goneWhy != "you're playing on it") && (ExcuseOf(gone) == "you're playing on it"), goneWhy);
		Check("stuck alarm: our game list isn't 'played' while somebody else's session is playing",
			Src5(Path.Combine("Core", "StuckWatch.cs")).Contains("(bot.IsOnline && (bot.OtherSessionApp == 0) && bot.PlayingApps.Any(static a => a != 0))", StringComparison.Ordinal));

		// 5. Trades, gifts, keys and answers on a human-mode account wait while you play on it, or while it finishes up.
		var human = NewBot("h5-human", new NocatFarm.Config.BotConfig { LegitMode = true });
		var robot = NewBot("h5-robot", new NocatFarm.Config.BotConfig());
		bool freeNow = !NocatFarm.Modules.HumanGate.StandsBack(human);
		Prop5(human, "PlayingBlocked", true);
		Prop5(robot, "PlayingBlocked", true);
		Check("you on it: a human-mode account stands back; a robot (which stands down by itself) doesn't",
			freeNow && NocatFarm.Modules.HumanGate.StandsBack(human) && !NocatFarm.Modules.HumanGate.StandsBack(robot));
		Check("you on it: an answer to a friend request or message waits; the auto-reply doesn't go at all",
			NocatFarm.Modules.Social.Holds(human) && !NocatFarm.Modules.Social.ReplyStillGoes(human));
		Prop5(human, "PlayingBlocked", false);
		Check("you on it: ...and once you're off, both go", !NocatFarm.Modules.Social.Holds(human) && NocatFarm.Modules.Social.ReplyStillGoes(human));
		Prop5(robot, "PlayingBlocked", false);
		Prop5(robot, "Stopping", true);
		Check("finishing up: trades and gifts wait on any account", NocatFarm.Modules.HumanGate.StandsBack(robot));
		Prop5(robot, "Stopping", false);
		string trading5 = Src5(Path.Combine("Modules", "Trading.cs"));
		Check("trades: wait while you play or it finishes up, wait while paused, and night arrivals get the after-waking wait",
			trading5.Contains("bool you = HumanGate.StandsBack(Bot);\n\t\t\tbool awake = !you && (!Bot.Cfg.ActOnlyWhileAwake || HumanMode.ReadyFor(Bot));", StringComparison.Ordinal)
			&& trading5.Contains("bool nightDonations = !you && ", StringComparison.Ordinal)
			&& trading5.Contains("Bot.IsOnline && Bot.Web.Ready && !Bot.Paused && (awake || nightDonations)", StringComparison.Ordinal)
			&& trading5.Contains("DateTime.UtcNow + TradeWait() + (Bot.Cfg.LegitMode && _wasHeld ? AfterWaking() : TimeSpan.Zero)", StringComparison.Ordinal)
			&& trading5.Contains("_waiting.Hold();\n\t\t\t\t_wasHeld = true;", StringComparison.Ordinal));
		Check("gifts and queued keys: wait while you play on a human-mode account, or it finishes up",
			Src5(Path.Combine("Modules", "Gifts.cs")).Contains("if (!HumanMode.ReadyFor(Bot) || HumanGate.StandsBack(Bot)) {", StringComparison.Ordinal)
			&& Src5(Path.Combine("Core", "Redeeming.cs")).Contains("NocatFarm.Modules.HumanMode.ReadyFor(b) && !NocatFarm.Modules.HumanGate.StandsBack(b)", StringComparison.Ordinal));

		// 6. Free games: a giveaway's package already on the account isn't asked for again; the library is waited for.
		var owner = NewBot("h5-free", new NocatFarm.Config.BotConfig());
		Type licT = typeof(NocatFarm.Core.Bot).GetNestedType("Licence", BindingFlags.NonPublic)!;
		var lic = (IDictionary) typeof(NocatFarm.Core.Bot).GetField("_licenses", AnyInst)!.GetValue(owner)!;
		lic[1234u] = Activator.CreateInstance(licT, [DateTime.UtcNow, 0UL, false, true, false, true])!;
		MethodInfo has = typeof(NocatFarm.Modules.FreeGames).GetMethod("AlreadyHas", AnyStatic)!;
		Check("free games: a free package the account already has is known; none (0) or another isn't",
			(bool) has.Invoke(null, [owner, 1234u])! && !(bool) has.Invoke(null, [owner, 0u])! && !(bool) has.Invoke(null, [owner, 99u])!);
		string free5 = Src5(Path.Combine("Modules", "FreeGames.cs"));
		int subAt = free5.IndexOf("uint freeSub = giveaway ? await FreeSubAsync(id, ct)", StringComparison.Ordinal);
		Check("free games: the owned check comes before the activation is counted, and app giveaways wait for the library",
			(subAt > 0) && (free5.IndexOf("if (AlreadyHas(Bot, freeSub)) {", subAt, StringComparison.Ordinal) is > 0 and int ownedAt)
			&& (ownedAt < free5.IndexOf("_claims.Add(DateTime.UtcNow);", subAt, StringComparison.Ordinal))
			&& free5.Contains("if ((app || pics) && !Bot.Library.Ready) {\n\t\t\t\t\tcontinue;", StringComparison.Ordinal)
			&& free5.Contains("if (AlreadyHas(Bot, baseSub)) {", StringComparison.Ordinal));

		// 7. Dashboard: a cross-site GET to the API is refused, a network share is never looked at, the switched-off check
		// sees through a proxy, the brake survives a restart, and the turned-away list can't be flooded.
		Microsoft.AspNetCore.Http.DefaultHttpContext Req(string path, string? site) {
			var ctx = new Microsoft.AspNetCore.Http.DefaultHttpContext();
			ctx.Request.Path = path;
			ctx.Request.Method = "GET";
			ctx.Request.Host = new Microsoft.AspNetCore.Http.HostString("localhost", 7242);
			ctx.Connection.RemoteIpAddress = System.Net.IPAddress.Loopback;
			if (site != null) {
				ctx.Request.Headers["Sec-Fetch-Site"] = site;
			}
			return ctx;
		}
		Check("dashboard: an /api GET another website made is refused; this page's own, a typed address and the page itself aren't",
			NocatFarm.Web.WebHost.CrossSiteApi(Req("/api/import/scan", "cross-site").Request) && !NocatFarm.Web.WebHost.CrossSiteApi(Req("/api/import/scan", "same-origin").Request)
			&& !NocatFarm.Web.WebHost.CrossSiteApi(Req("/api/status", null).Request) && !NocatFarm.Web.WebHost.CrossSiteApi(Req("/", "cross-site").Request));
		Check("import scan: a network share is never looked at (Windows would sign in to it); a local folder is",
			(NocatFarm.Config.IdlerImport.Clean(@"\\attacker.example\share\x") == null) && (NocatFarm.Config.IdlerImport.Clean("//attacker.example/share/x") == null)
			&& (NocatFarm.Config.IdlerImport.Clean(tmpRoot) == Path.GetFullPath(tmpRoot)));

		const string Right = "h5-brake-right-password-1234";
		var wmgr = new NocatFarm.Core.BotManager(new NocatFarm.Config.GlobalConfig { WebEnabled = false, WebPassword = Right, WebRemoteOffAfter = 0, WebSignInCode = false });
		var web = new NocatFarm.Web.WebHost(wmgr, wmgr.Global);
		MethodInfo refusal = typeof(NocatFarm.Web.WebHost).GetMethod("Refusal", AnyInst)!;
		FieldInfo shut = typeof(NocatFarm.Web.WebHost).GetField("_internetShut", AnyInst)!;
		var proxied = Req("/api/config", null);
		proxied.Request.Headers["X-Forwarded-For"] = "203.0.113.9";
		string? openWhy = (string?) refusal.Invoke(web, [proxied]);
		shut.SetValue(web, true);
		string? shutWhy = (string?) refusal.Invoke(web, [proxied]);
		string? homeWhy = (string?) refusal.Invoke(web, [Req("/api/config", null)]);
		shut.SetValue(web, false);
		Check("switched itself off: a visitor from the internet through a proxy on this PC is turned away too; this PC isn't",
			(openWhy == null) && (shutWhy?.Contains("Open from anywhere is off", StringComparison.Ordinal) == true) && (homeWhy == null), $"{openWhy} / {shutWhy} / {homeWhy}");

		MethodInfo tryLogin = typeof(NocatFarm.Web.WebHost).GetMethod("TryLogin", AnyInst)!;
		bool Guess(NocatFarm.Web.WebHost w, string from, string password) {
			var ctx = new Microsoft.AspNetCore.Http.DefaultHttpContext();
			ctx.Connection.RemoteIpAddress = System.Net.IPAddress.Parse(from);
			return (bool) tryLogin.Invoke(w, [ctx, password, null, null, null])!;
		}
		for (int i = 0; i < 5; i++) {
			Guess(web, "192.168.7.7", "wrong");
		}
		for (int i = 0; i < 3; i++) {
			Guess(web, $"198.51.100.{i + 1}", "wrong");
		}
		var again = new NocatFarm.Web.WebHost(wmgr, wmgr.Global);   // the restart
		var failures = (System.Collections.Concurrent.ConcurrentDictionary<string, (int Count, DateTime Until)>) typeof(NocatFarm.Web.WebHost).GetField("_failures", AnyInst)!.GetValue(again)!;
		var today = (Queue<DateTime>) typeof(NocatFarm.Web.WebHost).GetField("_internetMissesToday", AnyInst)!.GetValue(again)!;
		bool lockedKept = failures.TryGetValue("192.168.7.7", out var locked) && (locked.Count == 5);
		int dayKept = today.Count;
		Check("sign-in brake: a restart keeps an address locked out and the day's wrong guesses from the internet",
			lockedKept && (dayKept == 3) && !Guess(again, "192.168.7.7", Right), $"{locked.Count} / {dayKept}");
		again.ClearLockouts();
		var third = new NocatFarm.Web.WebHost(wmgr, wmgr.Global);
		Check("sign-in brake: ...and an unlock is kept too", Guess(third, "192.168.7.7", Right));

		object written = typeof(NocatFarm.Core.Visitors).GetField("TurnedAwayWritten", AnyStatic)!.GetValue(null)!;
		written.GetType().GetMethod("Clear")!.Invoke(written, []);
		((IDictionary) typeof(NocatFarm.Core.Visitors).GetField("TurnedAwaySaid", AnyStatic)!.GetValue(null)!).Clear();
		NocatFarm.Core.Visitors.Note(NocatFarm.Core.Visitors.What.SignedIn, "203.0.113.50", false, "Mozilla/5.0 (iPhone)");
		for (int i = 0; i < 300; i++) {
			NocatFarm.Core.Visitors.Note(NocatFarm.Core.Visitors.What.TurnedAway, $"2001:db8:{i:x}::1", false, null);
		}
		List<NocatFarm.Core.Visitors.Visit> visits = NocatFarm.Core.Visitors.Recent(500);
		int away = visits.Count(static v => (v.What == NocatFarm.Core.Visitors.What.TurnedAway) && v.Ip.StartsWith("2001:db8:", StringComparison.Ordinal));
		Check("visitors: 300 addresses turned away in a burst write 20, and the sign-in from outside is still in the list",
			(away == NocatFarm.Core.Visitors.TurnedAwayPerQuiet) && visits.Exists(static v => v.What == NocatFarm.Core.Visitors.What.SignedIn), $"{away}");

		// 8. Windows update: the script starts whatever the temp folder is called, has \r\n lines, and only "gone" rolls back.
		Check("update: cmd gets the script's path inside the quotes /s takes off, and no start-up hooks",
			NocatFarm.Core.SelfUpdate.SwapArguments(@"C:\Users\Paul (Home)\AppData\Local\Temp\nocatfarm-update-1\swap.cmd")
				== "/d /s /c \"\"C:\\Users\\Paul (Home)\\AppData\\Local\\Temp\\nocatfarm-update-1\\swap.cmd\"\"");
		string winScript = NocatFarm.Core.SelfUpdate.WindowsScript(4242);
		Check("update: the Windows script has \\r\\n on every line, whatever the source's line endings",
			(winScript.Replace("\r\n", "", StringComparison.Ordinal).IndexOf('\n') < 0) && winScript.Contains("\r\n:verify\r\n", StringComparison.Ordinal));
		Check("update: PowerShell missing or blocked isn't 'the new version is gone' - only an answer of 1 is",
			!winScript.Contains("|| goto gone", StringComparison.Ordinal) && winScript.Contains("if errorlevel 2 goto verify\r\nif errorlevel 1 goto gone\r\n", StringComparison.Ordinal));

		if (OperatingSystem.IsWindows()) {
			// For real: a script in a folder named like "Paul (Home) & co" runs through cmd with these arguments.
			string odd = Path.Combine(tmpRoot, "Paul (Home) & co ^1");
			Directory.CreateDirectory(odd);
			string script = Path.Combine(odd, "swap.cmd");
			string marker = Path.Combine(tmpRoot, "ran.txt");
			File.WriteAllText(script, "@echo off\r\n>\"%NF_MARK%\" echo ran\r\n");
			var psi = new System.Diagnostics.ProcessStartInfo("cmd.exe", NocatFarm.Core.SelfUpdate.SwapArguments(script)) { UseShellExecute = false, CreateNoWindow = true };
			psi.Environment["NF_MARK"] = marker;
			using (var p = System.Diagnostics.Process.Start(psi)!) {
				p.WaitForExit(15000);
			}
			Check("update: cmd really runs a swap script from a folder with ( ) & ^ in its name", File.Exists(marker));

			// And the errorlevel lines as cmd reads them: 9009 (no PowerShell) carries on waiting, 1 is gone, 0 is still there.
			string probe = Path.Combine(tmpRoot, "probe.cmd");
			File.WriteAllText(probe, "@echo off\r\ncmd /c exit %1\r\nif errorlevel 2 goto verify\r\nif errorlevel 1 goto gone\r\ngoto verify\r\n:gone\r\nexit /b 11\r\n:verify\r\nexit /b 22\r\n");
			int Probe(int code) {
				using var p = System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("cmd.exe", $"/d /s /c \"\"{probe}\" {code}\"") { UseShellExecute = false, CreateNoWindow = true })!;
				p.WaitForExit(15000);
				return p.ExitCode;
			}
			(int g, int z, int n) = (Probe(1), Probe(0), Probe(9009));
			Check("update: cmd reads 1 as gone, 0 and 9009 as keep waiting", (g == 11) && (z == 22) && (n == 22), $"{g} {z} {n}");
		}
	} finally {
		NocatFarm.Commands.Host = realHost;
		currentWeb.SetValue(null, realWeb);
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);
		NocatFarm.Config.Live.Global = realGlobal;
		NocatFarm.Core.Visitors.Reload();

		foreach (NocatFarm.Core.Bot b in made) {
			await b.DisposeAsync();
		}

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
			// temp - it goes when Windows tidies up
		}
	}
}

// ── the after-waking wait ends, the sign-in brake on disk after a right password and a clock put back, answers re-checked ──
{
	const BindingFlags AnyInst = BindingFlags.NonPublic | BindingFlags.Public | BindingFlags.Instance;
	string Src6(string rel) => File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", rel)).Replace("\r\n", "\n");

	// 1. Trades: a hold with nothing arriving is over once the account is up - not carried to an offer hours later.
	Check("trades: up again, nothing queued and Steam says none waiting - the hold is over",
		!NocatFarm.Modules.Trading.StillHeld(true, true, 0, 0));
	Check("trades: ...but not while still held, with offers queued, or with Steam saying some (or not saying yet)",
		NocatFarm.Modules.Trading.StillHeld(true, false, 0, 0) && NocatFarm.Modules.Trading.StillHeld(true, true, 1, 0)
		&& NocatFarm.Modules.Trading.StillHeld(true, true, 0, 2) && NocatFarm.Modules.Trading.StillHeld(true, true, 0, -1)
		&& !NocatFarm.Modules.Trading.StillHeld(false, false, 3, 3));
	Check("trades: the loop asks it every time round, after the hold",
		Src6(Path.Combine("Modules", "Trading.cs")).Contains("_wasHeld = true;\n\t\t\t}\n\n\t\t\t_wasHeld = StillHeld(_wasHeld, awake, _waiting.Count, Bot.TradeOffersWaiting);", StringComparison.Ordinal));

	// 2. Friend requests and replies: looked at again after the wait after waking, not only before it.
	string social6 = Src6(Path.Combine("Modules", "Social.cs"));
	int waitAt = social6.IndexOf("private async Task WaitUntilAwakeAsync(", StringComparison.Ordinal);
	int loopAt = social6.IndexOf("while (true) {", waitAt, StringComparison.Ordinal);
	int afterAt = social6.IndexOf("await Task.Delay(afterWaking(), ct).ConfigureAwait(false);\n\t\t}\n\t}", waitAt, StringComparison.Ordinal);
	Check("you on it: the wait after waking goes round again, so you coming on during it holds the answer too",
		(waitAt > 0) && (loopAt > waitAt) && (afterAt > loopAt) && social6.Contains("if (!held || ct.IsCancellationRequested) {\n\t\t\t\treturn;", StringComparison.Ordinal));

	// 3. The sign-in brake on disk.
	string realRoot6 = NocatFarm.Config.ConfigStore.Root;
	PropertyInfo currentWeb6 = typeof(NocatFarm.Web.WebHost).GetProperty("Current")!;
	object? realWeb6 = currentWeb6.GetValue(null);
	string tmp6 = Path.Combine(Path.GetTempPath(), "nf-after-waking-" + Guid.NewGuid().ToString("N"));
	Directory.CreateDirectory(Path.Combine(tmp6, "config", "state"));
	NocatFarm.Config.ConfigStore.UseRoot(tmp6);

	try {
		const string Right6 = "h6-brake-right-password-1234";
		var wmgr6 = new NocatFarm.Core.BotManager(new NocatFarm.Config.GlobalConfig { WebEnabled = false, WebPassword = Right6, WebRemoteOffAfter = 0, WebSignInCode = false });
		MethodInfo tryLogin6 = typeof(NocatFarm.Web.WebHost).GetMethod("TryLogin", AnyInst)!;
		bool Guess6(NocatFarm.Web.WebHost w, string from, string password) {
			var ctx = new Microsoft.AspNetCore.Http.DefaultHttpContext();
			ctx.Connection.RemoteIpAddress = System.Net.IPAddress.Parse(from);
			return (bool) tryLogin6.Invoke(w, [ctx, password, null, null, null])!;
		}
		System.Collections.Concurrent.ConcurrentDictionary<string, (int Count, DateTime Until)> Failures6(NocatFarm.Web.WebHost w) =>
			(System.Collections.Concurrent.ConcurrentDictionary<string, (int Count, DateTime Until)>) typeof(NocatFarm.Web.WebHost).GetField("_failures", AnyInst)!.GetValue(w)!;

		var web6 = new NocatFarm.Web.WebHost(wmgr6, wmgr6.Global);
		for (int i = 0; i < 4; i++) {
			Guess6(web6, "192.168.8.8", "wrong");
		}
		bool rightIn = Guess6(web6, "192.168.8.8", Right6);
		var restarted6 = new NocatFarm.Web.WebHost(wmgr6, wmgr6.Global);
		Check("sign-in brake: the right password clears the wrong ones on disk too - a restart doesn't bring them back",
			rightIn && !Failures6(restarted6).ContainsKey("192.168.8.8"), Failures6(restarted6).TryGetValue("192.168.8.8", out var left6) ? $"{left6.Count}" : "");

		// Written by a clock two days ahead of the one reading it back.
		DateTime ahead = DateTime.UtcNow.AddDays(2);
		File.WriteAllText(Path.Combine(tmp6, "config", "state", "signin-brake.json"), System.Text.Json.JsonSerializer.Serialize(new {
			Hour = new[] { ahead.Ticks }, Day = new[] { ahead.Ticks, ahead.Ticks }, PausedUntil = ahead.AddMinutes(30).Ticks,
			Failures = new Dictionary<string, long[]> { ["203.0.113.7"] = [5, ahead.AddMinutes(60).Ticks] }
		}));
		var back = new NocatFarm.Web.WebHost(wmgr6, wmgr6.Global);
		DateTime readAt = DateTime.UtcNow;
		var paused = (DateTime) typeof(NocatFarm.Web.WebHost).GetField("_internetPausedUntil", AnyInst)!.GetValue(back)!;
		var day = (Queue<DateTime>) typeof(NocatFarm.Web.WebHost).GetField("_internetMissesToday", AnyInst)!.GetValue(back)!;
		bool lockedStill = Failures6(back).TryGetValue("203.0.113.7", out var lockout6);
		Check("sign-in brake: with the clock put back since, a lockout and the hour's pause last no longer than they could have",
			lockedStill && (lockout6.Until <= readAt.AddMinutes(61)) && (paused > readAt) && (paused <= readAt.AddMinutes(61)), $"{lockout6.Until:O} / {paused:O}");
		Check("sign-in brake: ...and the day's wrong guesses count from now, not from two days ahead",
			(day.Count == 2) && day.All(t => t <= DateTime.UtcNow), string.Join(",", day.Select(static t => t.ToString("O"))));
	} finally {
		currentWeb6.SetValue(null, realWeb6);
		NocatFarm.Config.ConfigStore.UseRoot(realRoot6);

		try {
			Directory.Delete(tmp6, true);
		} catch (IOException) {
			// temp - it goes when Windows tidies up
		}
	}
}

// ── human mode: a restart carries on with the sitting in progress, not a fresh game ──
{
	const BindingFlags Inst = BindingFlags.NonPublic | BindingFlags.Instance;
	Type ht = typeof(NocatFarm.Modules.HumanMode);
	Type bt = typeof(NocatFarm.Core.Bot);
	FieldInfo HF(string f) => ht.GetField(f, Inst) ?? throw new MissingFieldException(f);
	T HGet<T>(object h, string f) => (T) HF(f).GetValue(h)!;
	void Set(object h, string f, object? v) => HF(f).SetValue(h, v);
	object? HCall(object h, string m, params object?[] args) => ht.GetMethod(m, Inst)!.Invoke(h, args);
	void BotSet(NocatFarm.Core.Bot b, string p, object? v) => bt.GetProperty(p)!.SetValue(b, v);
	NocatFarm.Modules.HumanMode.Phase PhaseOf(object h) => (NocatFarm.Modules.HumanMode.Phase) HF("_phase").GetValue(h)!;
	const NocatFarm.Modules.HumanMode.Phase Playing = NocatFarm.Modules.HumanMode.Phase.Playing;

	string rname = "harness-resume-" + Guid.NewGuid().ToString("N")[..6];
	var rcfg = new NocatFarm.Config.BotConfig { LegitMode = true, GameWeights = "730:75, 1085660:25" };
	var rbot = new NocatFarm.Core.Bot(rname, rcfg);
	BotSet(rbot, "State", NocatFarm.Core.BotState.Online);
	BotSet(rbot, "OnlineSince", DateTime.UtcNow.AddMinutes(-20));

	// A sitting in progress, saved as it plays: 36 minutes into 1h09m of Counter-Strike 2, 2h already banked today.
	NocatFarm.Modules.HumanMode Playing36(uint game, DateTime ends) {
		var h = new NocatFarm.Modules.HumanMode(rbot);
		Set(h, "_dayStamp", DateTime.Now.DayOfYear);
		Set(h, "_wakeMinuteOfDay", 0);
		Set(h, "_bedHour", 23);
		Set(h, "_bedMinute", 59);
		Set(h, "_bedIsTomorrow", true);
		Set(h, "_targetMinutes", 480);
		Set(h, "_playedMinutesToday", 120);
		Set(h, "_phase", Playing);
		Set(h, "_game", game);
		Set(h, "_sessionStarted", DateTime.UtcNow.AddMinutes(-36));
		Set(h, "_sessionEnds", ends);
		HCall(h, "Persist");
		return h;
	}

	// ...and the app restarts: a new module reads the saved day back.
	NocatFarm.Modules.HumanMode Restarted() {
		var h = new NocatFarm.Modules.HumanMode(rbot);
		Set(h, "_dayStamp", DateTime.Now.DayOfYear);
		HCall(h, "Restore", NocatFarm.Modules.HumanDay.Load(rname, DateTime.Now)!);
		return h;
	}

	NocatFarm.Log.Suppressed = true;
	DateTime ends = DateTime.UtcNow.AddMinutes(33);
	Playing36(730, ends);
	NocatFarm.Modules.HumanDay? saved = NocatFarm.Modules.HumanDay.Load(rname, DateTime.Now);
	Check("restart mid-sitting: the sitting is in the saved day", (saved?.SittingGame == 730) && (Math.Abs((saved.SittingEnds - ends).TotalSeconds) < 1));
	var back = Restarted();
	Check("restart mid-sitting: nothing plays before the warm-up", (PhaseOf(back) != Playing) && (HGet<uint>(back, "_game") == 0));
	HCall(back, "Persist");   // a second restart during the warm-up still finds the sitting
	Check("restart mid-sitting: still saved through the warm-up", NocatFarm.Modules.HumanDay.Load(rname, DateTime.Now)?.SittingGame == 730);
	bool resumed = (bool) HCall(back, "TryResume")!;
	Check("restart mid-sitting: carries on with the same game and the same end", resumed && (PhaseOf(back) == Playing) && (HGet<uint>(back, "_game") == 730)
		&& (Math.Abs((HGet<DateTime>(back, "_sessionEnds") - ends).TotalSeconds) < 1), $"{PhaseOf(back)} {HGet<uint>(back, "_game")}");
	Check("restart mid-sitting: the minutes already banked aren't counted again", (HGet<int>(back, "_playedMinutesToday") == 120)
		&& (Math.Abs((HGet<DateTime>(back, "_bankedTo") - DateTime.UtcNow).TotalSeconds) < 5));
	Check("restart mid-sitting: carried on with once, not again", !(bool) HCall(back, "TryResume")!);

	// Its end came and went during the restart and the warm-up: a fresh pick, as before.
	Playing36(730, DateTime.UtcNow.AddMinutes(-1));
	var late = Restarted();
	Check("restart mid-sitting: one that's already over rolls fresh", !(bool) HCall(late, "TryResume")! && (PhaseOf(late) != Playing) && (HGet<uint>(late, "_game") == 0));

	// A game it no longer plays: out of "Games and how often", or blacklisted since.
	Playing36(440, DateTime.UtcNow.AddMinutes(33));
	Check("restart mid-sitting: a game no longer in its games rolls fresh", !(bool) HCall(Restarted(), "TryResume")!);
	Playing36(730, DateTime.UtcNow.AddMinutes(33));
	rcfg.BlacklistedGames.Add(730);
	Check("restart mid-sitting: a game blacklisted since rolls fresh", !(bool) HCall(Restarted(), "TryResume")!);
	rcfg.BlacklistedGames.Clear();

	// You're on the account: it doesn't carry on underneath you.
	Playing36(730, DateTime.UtcNow.AddMinutes(33));
	var owner = Restarted();
	BotSet(rbot, "PlayingBlocked", true);
	Check("restart mid-sitting: not while you're playing", !(bool) HCall(owner, "TryResume")! && (PhaseOf(owner) != Playing));
	BotSet(rbot, "PlayingBlocked", false);

	// A meal break carries on to its end - no extra meal, no early game.
	var meal = Playing36(730, DateTime.UtcNow.AddMinutes(33));
	Set(meal, "_mealsUsed", 1);
	Set(meal, "_phase", NocatFarm.Modules.HumanMode.Phase.MealBreak);
	Set(meal, "_game", 0u);
	DateTime mealEnds = DateTime.UtcNow.AddMinutes(40);
	Set(meal, "_phaseEnds", mealEnds);
	HCall(meal, "Persist");
	var fed = Restarted();
	Check("restart mid-meal: the meal carries on to its end", (bool) HCall(fed, "TryResume")! && (PhaseOf(fed) == NocatFarm.Modules.HumanMode.Phase.MealBreak)
		&& (Math.Abs((HGet<DateTime>(fed, "_phaseEnds") - mealEnds).TotalSeconds) < 1) && (HGet<int>(fed, "_mealsUsed") == 1) && (HGet<uint>(fed, "_game") == 0));

	// A file from before this, with none of it, loads as before - and one with it is read fine by an older version.
	string path = Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", $"human-{rname}.json");
	var node = System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(path))!.AsObject();
	foreach (string k in new[] { "SittingGame", "SittingStarted", "SittingEnds", "SittingFarm", "Break", "BreakEnds" }) {
		node.Remove(k);
	}
	File.WriteAllText(path, node.ToJsonString());
	var old = Restarted();
	Check("restart: an older saved day without the sitting loads, and rolls fresh", (HGet<int>(old, "_playedMinutesToday") == 120) && !(bool) HCall(old, "TryResume")!);
	NocatFarm.Log.Suppressed = false;

	BotSet(rbot, "State", NocatFarm.Core.BotState.Stopped);
	NocatFarm.Modules.HumanDay.Forget(rname);
	await rbot.DisposeAsync();
}

// ── human mode: a sitting a restart cut off doesn't come back after the day moved on (you, a grind, bedtime, the farmer) ──
{
	const BindingFlags Inst = BindingFlags.NonPublic | BindingFlags.Instance;
	Type ht = typeof(NocatFarm.Modules.HumanMode);
	FieldInfo HF(string f) => ht.GetField(f, Inst) ?? throw new MissingFieldException(f);
	void Set(object h, string f, object? v) => HF(f).SetValue(h, v);
	object? HCall(object h, string m, params object?[] args) => ht.GetMethod(m, Inst)!.Invoke(h, args);
	void BotSet(NocatFarm.Core.Bot b, string p, object? v) => typeof(NocatFarm.Core.Bot).GetProperty(p)!.SetValue(b, v);

	string cname = "harness-cutoff-" + Guid.NewGuid().ToString("N")[..6];
	var ccfg = new NocatFarm.Config.BotConfig { LegitMode = true, GameWeights = "730:75, 1085660:25" };
	var cbot = new NocatFarm.Core.Bot(cname, ccfg);
	BotSet(cbot, "State", NocatFarm.Core.BotState.Online);
	BotSet(cbot, "OnlineSince", DateTime.UtcNow.AddMinutes(-20));

	// Saved mid-sitting, 33 minutes of Counter-Strike 2 still to go, then the app restarts.
	NocatFarm.Modules.HumanMode Restarted() {
		var p = new NocatFarm.Modules.HumanMode(cbot);
		Set(p, "_dayStamp", DateTime.Now.DayOfYear);
		Set(p, "_wakeMinuteOfDay", 0);
		Set(p, "_bedHour", 23);
		Set(p, "_bedMinute", 59);
		Set(p, "_bedIsTomorrow", true);
		Set(p, "_targetMinutes", 480);
		Set(p, "_playedMinutesToday", 120);
		Set(p, "_phase", NocatFarm.Modules.HumanMode.Phase.Playing);
		Set(p, "_game", 730u);
		Set(p, "_sessionStarted", DateTime.UtcNow.AddMinutes(-36));
		Set(p, "_sessionEnds", DateTime.UtcNow.AddMinutes(33));
		HCall(p, "Persist");

		var h = new NocatFarm.Modules.HumanMode(cbot);
		Set(h, "_dayStamp", DateTime.Now.DayOfYear);
		HCall(h, "Restore", NocatFarm.Modules.HumanDay.Load(cname, DateTime.Now)!);
		return h;
	}

	NocatFarm.Log.Suppressed = true;

	// Still warming up: kept.
	var warming = Restarted();
	Set(warming, "_phase", NocatFarm.Modules.HumanMode.Phase.WarmingUp);
	HCall(warming, "DropCutOffResume");
	Check("restart, still warming up: the cut-off sitting is still waiting", (bool) HCall(warming, "TryResume")!);

	// You sat down at the account during the warm-up (or a grind, bedtime, the day's hours, the farmer): gone, and gone
	// from the saved day too - your own session ended it, as it would have without the restart.
	foreach (NocatFarm.Modules.HumanMode.Phase cut in new[] { NocatFarm.Modules.HumanMode.Phase.StoodDown, NocatFarm.Modules.HumanMode.Phase.Playing,
		NocatFarm.Modules.HumanMode.Phase.Asleep, NocatFarm.Modules.HumanMode.Phase.DoneForToday, NocatFarm.Modules.HumanMode.Phase.ShortBreak }) {
		var h = Restarted();
		Set(h, "_phase", cut);
		BotSet(cbot, "PlayingBlocked", cut == NocatFarm.Modules.HumanMode.Phase.StoodDown);   // you, 20 minutes after the sign-in
		HCall(h, "DropCutOffResume");
		BotSet(cbot, "PlayingBlocked", false);
		Set(h, "_phase", NocatFarm.Modules.HumanMode.Phase.Off);
		HCall(h, "Persist");
		Check($"restart, then {cut} before the warm-up was over: the old sitting doesn't come back", !(bool) HCall(h, "TryResume")!
			&& (NocatFarm.Modules.HumanDay.Load(cname, DateTime.Now)?.SittingGame == 0));
	}

	var farmed = Restarted();
	Set(farmed, "_wasFarming", true);
	HCall(farmed, "DropCutOffResume");
	Check("restart, then the card farmer took the account: the old sitting doesn't come back after it", !(bool) HCall(farmed, "TryResume")!);

	// Steam's first report after signing in is the session that just ended - on a restart mid-sitting, our own, "blocked"
	// on that sitting's game - so it stands down for a few seconds. That isn't you: the sitting still carries on after.
	var echo = Restarted();
	BotSet(cbot, "OnlineSince", DateTime.UtcNow.AddSeconds(-5));
	BotSet(cbot, "PlayingBlocked", true);
	Set(echo, "_phase", NocatFarm.Modules.HumanMode.Phase.StoodDown);
	HCall(echo, "DropCutOffResume");
	BotSet(cbot, "PlayingBlocked", false);
	BotSet(cbot, "OnlineSince", DateTime.UtcNow.AddMinutes(-20));
	HCall(echo, "DropCutOffResume");   // a later tick, still stood down for the courtesy wait after it
	Set(echo, "_phase", NocatFarm.Modules.HumanMode.Phase.WarmingUp);
	Check("restart mid-sitting, Steam's report of our own ended session right after sign-in: the sitting still carries on", (bool) HCall(echo, "TryResume")!);
	NocatFarm.Log.Suppressed = false;

	BotSet(cbot, "State", NocatFarm.Core.BotState.Stopped);
	NocatFarm.Modules.HumanDay.Forget(cname);
	await cbot.DisposeAsync();
}

// ── bedtime: no new game with less than a sitting left ─────────────────────────────────────
{
	Check("bedtime: 20 seconds before bed starts no game (it read as no bedtime once the minutes rounded to 0)",
		NocatFarm.Modules.HumanMode.BedTooCloseToStart(false, 0.33, 20) && NocatFarm.Modules.HumanMode.BedTooCloseToStart(false, 19.5, 20)
		&& !NocatFarm.Modules.HumanMode.BedTooCloseToStart(false, 25, 20) && !NocatFarm.Modules.HumanMode.BedTooCloseToStart(true, 0.33, 20)
		&& NocatFarm.Modules.HumanMode.BedTooCloseToStart(false, 4, 0) && !NocatFarm.Modules.HumanMode.BedTooCloseToStart(false, 6, 0)
		&& !NocatFarm.Modules.HumanMode.BedTooCloseToStart(false, 0, 20) && !NocatFarm.Modules.HumanMode.BedTooCloseToStart(false, -30, 20));
}

// ── first start: the language comes from the computer ─────────────────────────────────────
{
	string? L(string? s) => NocatFarm.Config.SystemLanguage.FromLocale(s);
	string? Env(params (string Name, string Value)[] vars) =>
		NocatFarm.Config.SystemLanguage.FromEnvironment(n => vars.FirstOrDefault(v => v.Name == n).Value);

	Check("language: LANG values read as their pack", L("de_DE.UTF-8") == "de" && L("pt_BR") == "pt-BR" && L("fr_FR.UTF-8@euro") == "fr"
		&& L("ja_JP.eucJP") == "ja" && L("ko_KR.UTF-8") == "ko" && L("tr_TR") == "tr" && L("pl_PL.UTF-8") == "pl" && L("ru_RU.KOI8-R") == "ru"
		&& L("es_MX.UTF-8") == "es" && L("en_GB.UTF-8") == "en" && L("de") == "de" && L("de-AT") == "de");
	Check("language: C, POSIX and C.UTF-8 are English; a language with no pack is English; nothing is nothing",
		L("C") == "en" && L("POSIX") == "en" && L("C.UTF-8") == "en" && L("fi_FI.UTF-8") == "en" && L("nl-NL") == "en"
		&& L(null) == null && L("") == null && L("  ") == null);
	Check("language: close variants - any Portuguese is pt-BR, Simplified Chinese is zh-CN, Traditional is English",
		L("pt_PT.UTF-8") == "pt-BR" && L("pt-BR") == "pt-BR" && L("pt") == "pt-BR"
		&& L("zh-Hans") == "zh-CN" && L("zh_CN.UTF-8") == "zh-CN" && L("zh-SG") == "zh-CN" && L("zh-Hans-CN") == "zh-CN" && L("zh") == "zh-CN"
		&& L("zh-Hant") == "en" && L("zh_TW.UTF-8") == "en" && L("zh-HK") == "en" && L("zh-Hant-TW") == "en");
	Check("language: LC_ALL beats LC_MESSAGES beats LANG, and an empty one is skipped",
		Env(("LC_ALL", "ru_RU.UTF-8"), ("LC_MESSAGES", "fr_FR"), ("LANG", "de_DE.UTF-8")) == "ru"
		&& Env(("LC_MESSAGES", "fr_FR"), ("LANG", "de_DE.UTF-8")) == "fr"
		&& Env(("LC_ALL", ""), ("LANG", "de_DE.UTF-8")) == "de"
		&& Env(("LC_ALL", "fi_FI.UTF-8"), ("LANG", "de_DE.UTF-8")) == "en"
		&& Env(("LANG", "C")) == "en" && Env() == null);
	Check("language: a Mac's AppleLanguages list - the first one counts",
		NocatFarm.Config.SystemLanguage.FromAppleLanguages("(\n    \"de-DE\",\n    en\n)\n") == "de"
		&& NocatFarm.Config.SystemLanguage.FromAppleLanguages("(\n    \"zh-Hans-CN\"\n)") == "zh-CN"
		&& NocatFarm.Config.SystemLanguage.FromAppleLanguages("(\n)") == null && NocatFarm.Config.SystemLanguage.FromAppleLanguages("") == null);
	Check("language: every pack is one the Language setting offers",
		NocatFarm.Config.SystemLanguage.Packs.All(p => NocatFarm.Config.SystemLanguage.NameOf(p) != p) && NocatFarm.Config.SystemLanguage.NameOf("de") == "Deutsch");
	string? here = NocatFarm.Config.SystemLanguage.Detect();
	Check("language: asking this computer never throws - and Windows always says (its display language)",
		(here == null || NocatFarm.Config.SystemLanguage.Packs.Contains(here)) && (!OperatingSystem.IsWindows() || here != null), here ?? "(nothing)");

	string realRoot = NocatFarm.Config.ConfigStore.Root;
	Func<string?> realProbe = NocatFarm.Config.SystemLanguage.Probe;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-lang-" + Guid.NewGuid().ToString("N"));
	NocatFarm.Config.SystemLanguage.Probe = static () => "de";
	Action<bool> realStartup = NocatFarm.Config.SetupChoices.StartWithWindows;
	NocatFarm.Config.SetupChoices.StartWithWindows = static _ => { };   // never the real startup entry

	try {
		// A brand-new install: the computer's language, written into the file like any other default.
		NocatFarm.Config.ConfigStore.UseRoot(Path.Combine(tmpRoot, "fresh"));
		NocatFarm.Config.GlobalConfig fresh = NocatFarm.Config.ConfigStore.LoadGlobal();
		Check("language: a brand-new config takes the computer's language, saved in the file", fresh.Language == "de"
			&& NocatFarm.Config.ConfigStore.LanguageFromComputer == "de" && NocatFarm.Config.ConfigStore.LoadGlobal().Language == "de"
			&& NocatFarm.Config.ConfigStore.LanguageFromComputer == null);

		// An existing config keeps what it says - English left at the default included.
		NocatFarm.Config.ConfigStore.UseRoot(Path.Combine(tmpRoot, "existing"));
		Directory.CreateDirectory(NocatFarm.Config.ConfigStore.ConfigDir);
		File.WriteAllText(NocatFarm.Config.ConfigStore.GlobalPath, "{ \"Language\": \"en\" }");
		string before = File.ReadAllText(NocatFarm.Config.ConfigStore.GlobalPath);
		NocatFarm.Config.GlobalConfig kept = NocatFarm.Config.ConfigStore.LoadGlobal();
		File.WriteAllText(NocatFarm.Config.ConfigStore.GlobalPath, "{ }");
		NocatFarm.Config.GlobalConfig keptDefault = NocatFarm.Config.ConfigStore.LoadGlobal();
		Check("language: an existing config isn't changed", kept.Language == "en" && keptDefault.Language == "en" && before.Contains("\"en\"")
			&& NocatFarm.Config.ConfigStore.LanguageFromComputer == null);

		// The installer's pick wins over the computer's - and a setup that doesn't name one keeps the computer's.
		NocatFarm.Config.ConfigStore.UseRoot(Path.Combine(tmpRoot, "installer"));
		// "Start with Windows" is a choice only Windows has - anywhere else the setup rightly refuses it.
		string[] startup = OperatingSystem.IsWindows() ? ["StartWithWindows=false"] : [];
		int code = NocatFarm.Config.SetupChoices.Run(["Language=ja", .. startup]);
		Check("language: the installer's Language= wins over the computer's", (code == 0) && NocatFarm.Config.ConfigStore.LoadGlobal().Language == "ja", $"exit {code}");
		NocatFarm.Config.ConfigStore.UseRoot(Path.Combine(tmpRoot, "installer-keeping"));
		int keeping = NocatFarm.Config.SetupChoices.Run(startup);
		Check("language: a setup that names no language leaves the computer's", (keeping == 0) && NocatFarm.Config.ConfigStore.LoadGlobal().Language == "de", $"exit {keeping}");

		// Nothing to go on: English, as before.
		NocatFarm.Config.SystemLanguage.Probe = static () => null;
		NocatFarm.Config.ConfigStore.UseRoot(Path.Combine(tmpRoot, "silent"));
		Check("language: a computer that doesn't say starts in English", NocatFarm.Config.ConfigStore.LoadGlobal().Language == "en"
			&& NocatFarm.Config.ConfigStore.LanguageFromComputer == null);
	} finally {
		NocatFarm.Config.SystemLanguage.Probe = realProbe;
		NocatFarm.Config.SetupChoices.StartWithWindows = realStartup;
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);

		try {
			Directory.Delete(tmpRoot, true);
		} catch {
			// best effort
		}
	}
}

// ── DLC rule 8: a real DLC can be nearly all of a small game - only another game's page is "the whole game" ───────
{
	const NocatFarm.Core.DlcAchievements.Hold None = NocatFarm.Core.DlcAchievements.Hold.None;
	const NocatFarm.Core.DlcAchievements.Hold NotOwned = NocatFarm.Core.DlcAchievements.Hold.NotOwned;
	NocatFarm.Core.DlcAchievements.Hold HoldOf(NocatFarm.Core.DlcAchievements.Map m, string name, params uint[] owned) =>
		NocatFarm.Core.DlcAchievements.HoldOf(m, name, new HashSet<uint>(owned));

	// 20 achievements: 2 the game's own, 18 a story DLC's (positions 2-19). Rule 7 took any 18 of 20 as another game's
	// copy, held nothing, and an account without the DLC had its 18 unlocked.
	List<NocatFarm.Core.DlcAchievements.Entry> small = [.. Enumerable.Range(0, 20).Select(static i => new NocatFarm.Core.DlcAchievements.Entry($"S_{i}", $"Story {i}", "Do a thing.", false))];
	NocatFarm.Core.DlcAchievements.Map Small(int total, string type, uint storeApp = 81) => NocatFarm.Core.DlcAchievements.Assemble(80, "Small Game", small,
		NocatFarm.Core.DlcAchievements.Merge(80, [new(81, storeApp, "Small Game - The Long Story", total,
			[.. Enumerable.Range(20 - total, Math.Min(10, total)).Select(static i => $"Story {i}")], Type: type)], "Small Game"), 1, 1, DateTime.UtcNow);

	NocatFarm.Core.DlcAchievements.Map story = Small(18, "dlc");
	Check("dlc rule 8: an 18-achievement DLC page in a 20-achievement game is a DLC - its 18 held without it, the game's own 2 not",
		(story.Owners.Count == 18) && story.StoreSays && (HoldOf(story, "S_2") == NotOwned) && (HoldOf(story, "S_19") == NotOwned)
		&& (HoldOf(story, "S_0") == None) && (HoldOf(story, "S_1") == None) && (HoldOf(story, "S_10", 81) == None),
		$"{story.Owners.Count} held");
	NocatFarm.Core.DlcAchievements.Map allDlc = Small(20, "DLC");
	Check("dlc rule 8: a DLC page with every achievement (a game with none of its own) holds them all without it",
		(allDlc.Owners.Count == 20) && (HoldOf(allDlc, "S_0") == NotOwned), $"{allDlc.Owners.Count} held");

	// A DLC the store sends to a game's page, as Call of Duty's Modern Warfare II: nearly all of a launcher-like game is
	// still a DLC; only all of it is another game's.
	NocatFarm.Core.DlcAchievements.Map sent = Small(18, "game", 3595230);
	NocatFarm.Core.DlcAchievements.Map sentWhole = Small(20, "game", 3595230);
	Check("dlc rule 8: a DLC sent to a game's page - 18 of 20 held; all 20 is another game's and holds nothing",
		(sent.Owners.Count == 18) && (HoldOf(sent, "S_5") == NotOwned) && (NocatFarm.Core.DlcAchievements.HoldOf(sent, "S_5", NocatFarm.Core.DlcAchievements.OwnedGroups(sent, static id => id == 3595230)) == None)
		&& (sentWhole.Owners.Count == 0) && (sentWhole.Groups.Count == 0), $"{sent.Owners.Count}, {sentWhole.Owners.Count}");

	Check("dlc rule 8: the line by the page's type - never for a DLC page, all of it for another type, all but a tenth unknown",
		!NocatFarm.Core.DlcAchievements.WholeGame(18, 20, "dlc") && !NocatFarm.Core.DlcAchievements.WholeGame(20, 20, "DLC")
		&& !NocatFarm.Core.DlcAchievements.WholeGame(500, 20, "dlc")
		&& !NocatFarm.Core.DlcAchievements.WholeGame(19, 20, "game") && NocatFarm.Core.DlcAchievements.WholeGame(20, 20, "game")
		&& NocatFarm.Core.DlcAchievements.WholeGame(15, 15, "game") && NocatFarm.Core.DlcAchievements.WholeGame(18, 20, "")
		&& !NocatFarm.Core.DlcAchievements.WholeGame(17, 20, "") && !NocatFarm.Core.DlcAchievements.WholeGame(0, 0, "game"));

	// Two ids for one DLC: one of them a DLC page is enough to make it one.
	List<NocatFarm.Core.DlcAchievements.Dlc> joined = NocatFarm.Core.DlcAchievements.Merge(80, [
		new(82, 90, "Small Game - Pack", 18, ["Story 2"], Type: "game"), new(90, 90, "Small Game - Pack", 18, ["Story 2"], Type: "dlc")], "Small Game");
	Check("dlc rule 8: the type goes with the DLC through the merge, a DLC page's winning",
		(joined.Count == 1) && (joined[0].Type == "dlc") && joined[0].Ids.SequenceEqual([82u, 90u])
		&& (NocatFarm.Core.DlcAchievements.Join(new(1, [1], "", 0, [], Type: ""), new(2, [2], "", 0, [], Type: "game")).Type == "game"),
		string.Join(",", joined.Select(static d => d.Type)));

	NocatFarm.Core.DlcAchievements.Map rule7 = new() { App = 80, BuiltAt = DateTime.UtcNow, Rule = 7, Names = ["s_0"] };
	Check("dlc rule 8: the rules moved on - a map built under rule 7 is built again",
		(NocatFarm.Core.DlcAchievements.RuleNow == 8) && NocatFarm.Core.DlcAchievements.Stale(rule7) && !NocatFarm.Core.DlcAchievements.Stale(story));
}

// ── accounts: removing one deletes its own files, in any case, and nobody else's ───────────────────────────────
{
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	NocatFarm.Config.GlobalConfig realGlobal = NocatFarm.Config.Live.Global;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-rmfiles-" + Guid.NewGuid().ToString("N"));
	string cfg = Path.Combine(tmpRoot, "config");
	Directory.CreateDirectory(Path.Combine(cfg, "state", "history"));
	Directory.CreateDirectory(Path.Combine(cfg, "tokens"));
	Directory.CreateDirectory(Path.Combine(cfg, "authenticators"));
	NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);

	try {
		void Put(string rel) => File.WriteAllText(Path.Combine(cfg, rel), "{}");
		bool Has(string rel) => File.Exists(Path.Combine(cfg, rel));

		// main's own, written under several spellings of its name.
		string[] mains = ["state/human-Main.json", "state/cheevo-main.json", "state/overnight-MAIN.seen", "state/trades-announced-mAin.json",
			"state/queue-main.txt", "state/rep4rep-Main.json", "tokens/main.token", "tokens/MAIN.access"];
		// Other accounts' whose names start (or end) the same, the app's own files, and main's authenticator.
		string[] others = ["state/human-main2.json", "state/human-main-alt.json", "state/hunt-mainx.json", "state/cheevo-xmain.json",
			"state/owner-ma.json", "tokens/main2.token", "tokens/main-alt.access", "state/lifetime.json", "state/lifetime-games.json",
			"state/dlc-achievements.json", "state/history/2026-10.json", "authenticators/main.maFile", "main2.json", "state/human-main.json.bak"];

		foreach (string rel in mains.Concat(others)) {
			Put(rel);
		}

		int gone = NocatFarm.Config.ConfigStore.DeleteAccountFiles("main");
		Check("remove files: all of main's own state and tokens go, whatever their case",
			(gone == mains.Length) && mains.All(r => !Has(r)), $"{gone} deleted, left: {string.Join(", ", mains.Where(Has))}");
		Check("remove files: an account whose name starts the same keeps its files, and so do the app's own and main's authenticator",
			others.All(Has), $"missing: {string.Join(", ", others.Where(r => !Has(r)))}");
		Check("remove files: a name that isn't one deletes nothing",
			(NocatFarm.Config.ConfigStore.DeleteAccountFiles("..") == 0) && (NocatFarm.Config.ConfigStore.DeleteAccountFiles("") == 0) && others.All(Has));
		Check("remove files: only exactly the name between start and end",
			NocatFarm.Config.ConfigStore.IsAccountFile("human-MAIN.json", "main", "human-", ".json")
			&& !NocatFarm.Config.ConfigStore.IsAccountFile("human-main2.json", "main", "human-", ".json")
			&& !NocatFarm.Config.ConfigStore.IsAccountFile("xhuman-main.json", "main", "human-", ".json")
			&& !NocatFarm.Config.ConfigStore.IsAccountFile("human-main.json.tmp", "main", "human-", ".json")
			&& !NocatFarm.Config.ConfigStore.IsAccountFile("human-main.seen", "main", "human-", ".json"));

		// Every per-account file the app writes is on the list, and no two starts can claim the same file.
		string src = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm");
		HashSet<string> written = [.. Directory.EnumerateFiles(src, "*.cs", SearchOption.AllDirectories)
			.SelectMany(static f => System.Text.RegularExpressions.Regex.Matches(File.ReadAllText(f),
				@"\$""([a-z0-9][a-z0-9-]*-)\{(?:Bot\.Name|bot\.Name|Name|bot|name|botName)\}(\.[a-zA-Z]+)""").Select(static m => m.Groups[1].Value + "|" + m.Groups[2].Value))
			.Where(static k => k != "netlog-|.txt")];   // the network log, beside the app - a log, not state
		HashSet<string> listed = [.. NocatFarm.Config.ConfigStore.AccountFiles.Where(static f => f.Dir == "state").Select(static f => f.Start + "|" + f.End)];
		var starts = NocatFarm.Config.ConfigStore.AccountFiles.Where(static f => f.Start.Length > 0).ToList();
		Check("remove files: every per-account state file the app writes is deleted with the account",
			(written.Count >= 18) && written.IsSubsetOf(listed), $"{written.Count} found, not listed: {string.Join(", ", written.Except(listed))}");
		Check("remove files: no start is the start of another (one file, one kind)",
			!starts.Any(a => starts.Any(b => (a != b) && (a.Dir == b.Dir) && b.Start.StartsWith(a.Start, StringComparison.OrdinalIgnoreCase))));

		// The real thing: removed, added back as "MIXED", and the backup has each file once.
		var mgr = new NocatFarm.Core.BotManager(new NocatFarm.Config.GlobalConfig { WebEnabled = false });
		await mgr.AddAsync("mixed", new NocatFarm.Config.BotConfig { Enabled = false });
		Put("state/human-mixed.json");
		Put("state/hunt-Mixed.json");
		Put("state/human-mixed2.json");
		bool removed = await mgr.RemoveAsync("MIXED");
		Check("remove: the account's state goes with it, another account's stays",
			removed && !Has("mixed.json") && !Has("state/human-mixed.json") && !Has("state/hunt-Mixed.json") && Has("state/human-mixed2.json"));
		await mgr.AddAsync("MIXED", new NocatFarm.Config.BotConfig { Enabled = false });
		Put("state/human-MIXED.json");
		NocatFarm.Core.Backup.Inspection back = NocatFarm.Core.Backup.Inspect(NocatFarm.Core.Backup.Create());
		Check("remove: added back in another case, the backup still restores", back.Ok && back.Accounts.Contains("MIXED"), back.Error ?? "");
		await mgr.RemoveAsync("MIXED");
	} finally {
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);
		NocatFarm.Config.Live.Global = realGlobal;

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
		}
	}
}

// ── user count: the hourly ping to nocat.lol, never the real network here ────────────────────────────────
{
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	NocatFarm.Config.GlobalConfig realGlobal = NocatFarm.Config.Live.Global;
	string? realPingUrl = Environment.GetEnvironmentVariable("NOCATFARM_PING_URL");
	string ucRoot = Path.Combine(Path.GetTempPath(), "nf-usercount-" + Guid.NewGuid().ToString("N"));
	string ucOther = Path.Combine(Path.GetTempPath(), "nf-usercount-b-" + Guid.NewGuid().ToString("N"));
	Type uc = typeof(NocatFarm.Core.UserCount);
	bool wasSuppressed = NocatFarm.Log.Suppressed;
	NocatFarm.Log.Suppressed = true;

	try {
		Environment.SetEnvironmentVariable("NOCATFARM_PING_URL", null);
		NocatFarm.Config.ConfigStore.UseRoot(ucRoot);
		NocatFarm.Config.ConfigStore.SaveGlobal(new NocatFarm.Config.GlobalConfig());

		// The install id: made once, 32 lowercase hex, kept in state/ and nowhere else.
		Check("user count: no id until one is needed", !File.Exists(NocatFarm.Core.UserCount.IdPath));
		string id = NocatFarm.Core.UserCount.InstallId();
		Check("user count: the install id is 32 lowercase hex", (id.Length == 32) && id.All(c => char.IsAsciiDigit(c) || c is >= 'a' and <= 'f'), id.Length.ToString());
		Check("user count: asked again it's the same id, kept on disk", (NocatFarm.Core.UserCount.InstallId() == id) && (File.ReadAllText(NocatFarm.Core.UserCount.IdPath).Trim() == id));
		Check("user count: the id isn't in the settings file", !File.ReadAllText(NocatFarm.Config.ConfigStore.GlobalPath).Contains(id, StringComparison.Ordinal));

		string? Kind(string rel) => (string?) typeof(NocatFarm.Core.Backup).GetMethod("Kind", BindingFlags.Static | BindingFlags.NonPublic | BindingFlags.Public)!.Invoke(null, [rel]);
		byte[] zip = NocatFarm.Core.Backup.Create();
		NocatFarm.Core.Backup.Inspection look = NocatFarm.Core.Backup.Inspect(zip);
		bool idInZip = false;
		using (var za = new System.IO.Compression.ZipArchive(new MemoryStream(zip))) {
			foreach (var entry in za.Entries) {
				using var sr = new StreamReader(entry.Open());
				idInZip |= sr.ReadToEnd().Contains(id, StringComparison.Ordinal);
			}
		}
		Check("user count: the id isn't in a backup (another PC restoring it gets its own)", look.Ok && (Kind("state/install-id.txt") == null)
			&& !look.Files.Any(f => f.Contains("install-id", StringComparison.Ordinal)) && !idInZip, string.Join(",", look.Files));

		NocatFarm.Config.ConfigStore.UseRoot(ucOther);
		Check("user count: another install makes its own id", NocatFarm.Core.UserCount.InstallId() is { } other && (other != id) && NocatFarm.Core.UserCount.IsId(other));
		File.WriteAllText(NocatFarm.Core.UserCount.IdPath, "not an id\n");
		Check("user count: a spoilt id file gets a fresh id", NocatFarm.Core.UserCount.IsId(NocatFarm.Core.UserCount.InstallId())
			&& NocatFarm.Core.UserCount.IsId(File.ReadAllText(NocatFarm.Core.UserCount.IdPath).Trim()));
		NocatFarm.Config.ConfigStore.UseRoot(ucRoot);

		// What's sent: the id, the version, the platform and how many accounts are signed in - nothing else.
		using (System.Text.Json.JsonDocument body = System.Text.Json.JsonDocument.Parse(NocatFarm.Core.UserCount.Body())) {
			string[] keys = [.. body.RootElement.EnumerateObject().Select(p => p.Name)];
			Check("user count: the body is the id, the version, the platform and the accounts signed in, nothing else", keys.SequenceEqual(["id", "v", "os", "a"])
				&& (body.RootElement.GetProperty("id").GetString() == id) && (body.RootElement.GetProperty("v").GetString() == NocatFarm.Build.Version)
				&& new[] { "windows", "linux", "mac", "docker" }.Contains(body.RootElement.GetProperty("os").GetString())
				&& (body.RootElement.GetProperty("a").ValueKind == System.Text.Json.JsonValueKind.Number)
				&& (body.RootElement.GetProperty("a").GetInt32() == NocatFarm.Core.UserCount.SignedIn()), string.Join(",", keys));
		}
		int SentA(int n) {
			using System.Text.Json.JsonDocument b = System.Text.Json.JsonDocument.Parse(NocatFarm.Core.UserCount.Body(n));
			return b.RootElement.GetProperty("a").GetInt32();
		}
		Check("user count: the accounts signed in go as a plain number", SentA(3) == 3 && SentA(0) == 0 && SentA(1000) == 1000
			&& NocatFarm.Core.UserCount.Body(3).Contains("\"a\":3", StringComparison.Ordinal), NocatFarm.Core.UserCount.Body(3));
		Check("user count: the accounts signed in are kept to 0..1000", SentA(-5) == 0 && SentA(1001) == 1000 && SentA(int.MaxValue) == 1000 && SentA(int.MinValue) == 0);
		Check("user count: nothing about an account but the number (no names, no ids)", !NocatFarm.Core.UserCount.Body(2).Contains("765611", StringComparison.Ordinal)
			&& (System.Text.Json.JsonDocument.Parse(NocatFarm.Core.UserCount.Body(2)).RootElement.EnumerateObject().Count() == 4));
		Check("user count: Windows says windows", !OperatingSystem.IsWindows() || (NocatFarm.Core.UserCount.Os == "windows"));
		Check("user count: HTTPS to nocat.lol", NocatFarm.Core.UserCount.Endpoint == "https://nocat.lol/api/farm/ping" && NocatFarm.Core.UserCount.Target == NocatFarm.Core.UserCount.Endpoint);
		Environment.SetEnvironmentVariable("NOCATFARM_PING_URL", "https://example.com/steal");
		Check("user count: a test address that isn't this PC is ignored", NocatFarm.Core.UserCount.Target == NocatFarm.Core.UserCount.Endpoint);
		Environment.SetEnvironmentVariable("NOCATFARM_PING_URL", "http://127.0.0.1:9/api/farm/ping");
		Check("user count: a test address on this PC is used (the browser test's stub)", NocatFarm.Core.UserCount.Target == "http://127.0.0.1:9/api/farm/ping");
		Environment.SetEnvironmentVariable("NOCATFARM_PING_URL", null);

		// The answer.
		NocatFarm.Core.UserCount.Counts? Reply(string json) => NocatFarm.Core.UserCount.ParseReply(System.Net.HttpStatusCode.OK, json);
		Check("user count: reads the copies and the Steam accounts", Reply("""{"users":212,"accounts":1240}""") is { Users: 212, Accounts: 1240 });
		Check("user count: an older nocat.lol (no accounts) - the copies, the accounts unknown", Reply("""{"users":212}""") is { Users: 212, Accounts: null });
		Check("user count: accounts without copies are still read", Reply("""{"accounts":1240}""") is { Users: null, Accounts: 1240 });
		Check("user count: accounts that aren't a whole number above 0 are unknown", Reply("""{"users":212,"accounts":0}""") is { Users: 212, Accounts: null }
			&& Reply("""{"users":212,"accounts":"1240"}""") is { Accounts: null } && Reply("""{"users":212,"accounts":2.5}""") is { Accounts: null }
			&& Reply("""{"users":212,"accounts":-4}""") is { Accounts: null } && Reply("""{"users":212,"accounts":null}""") is { Accounts: null });
		Check("user count: bad JSON is unknown", Reply("<html>oops") == null);
		Check("user count: a number that isn't one is unknown", Reply("""{"users":"212"}""") == null
			&& Reply("""{"users":2.5}""") == null && Reply("""{"users":0}""") == null && Reply("""{"users":0,"accounts":0}""") == null
			&& Reply("""[212]""") == null && Reply("""{"count":212}""") == null);
		Check("user count: anything but a 200 is unknown", NocatFarm.Core.UserCount.ParseReply(System.Net.HttpStatusCode.ServiceUnavailable, """{"users":212,"accounts":1240}""") == null
			&& NocatFarm.Core.UserCount.ParseReply(System.Net.HttpStatusCode.NoContent, "") == null);

		// The ping itself, through a fake handler.
		FakePing Answer(System.Net.HttpStatusCode code, string text) =>
			new((_, _) => Task.FromResult(new HttpResponseMessage(code) { Content = new StringContent(text) }));
		NocatFarm.Config.GlobalConfig on = new(), off = new() { CountMeAsUser = false };
		Check("user count: Count me as a user is on by default", on.CountMeAsUser);

		NocatFarm.Core.UserCount.Forget();
		FakePing silent = Answer(System.Net.HttpStatusCode.OK, """{"users":212,"accounts":1240}""");
		using (HttpClient http = NocatFarm.Core.UserCount.MakeClient(silent)) {
			bool sent = await NocatFarm.Core.UserCount.PingAsync(http, off);
			Check("user count: off sends nothing at all", !sent && (silent.Calls == 0));
		}

		FakePing good = Answer(System.Net.HttpStatusCode.OK, """{"users":212,"accounts":1240}""");
		using (HttpClient http = NocatFarm.Core.UserCount.MakeClient(good)) {
			bool ok = await NocatFarm.Core.UserCount.PingAsync(http, on);
			Check("user count: a good answer is kept", ok && (good.Calls == 1) && (NocatFarm.Core.UserCount.Accounts(on, DateTime.UtcNow) == 1240)
				&& (NocatFarm.Core.UserCount.Current(on, DateTime.UtcNow) is { Users: 212, Accounts: 1240 }));
			Check("user count: one POST of JSON to nocat.lol, as nocat.farm/<version>", (good.Method == "POST") && (good.Url == NocatFarm.Core.UserCount.Endpoint)
				&& (good.ContentType == "application/json") && (good.UserAgent == "nocat.farm/" + NocatFarm.Build.Version) && good.Body.Contains(id, StringComparison.Ordinal)
				&& good.Body.Contains("\"a\":", StringComparison.Ordinal),
				$"{good.Method} {good.Url} {good.ContentType} {good.UserAgent} {good.Body.Length}");
		}
		Check("user count: off hides the count it has", NocatFarm.Core.UserCount.Current(off, DateTime.UtcNow) == null && NocatFarm.Core.UserCount.Accounts(off, DateTime.UtcNow) == null);

		NocatFarm.Core.UserCount.Forget();
		FakePing older = Answer(System.Net.HttpStatusCode.OK, """{"users":212}""");
		using (HttpClient http = NocatFarm.Core.UserCount.MakeClient(older)) {
			bool ok = await NocatFarm.Core.UserCount.PingAsync(http, on);
			Check("user count: an older nocat.lol's answer is kept, with the accounts unknown (nothing shown)", ok
				&& (NocatFarm.Core.UserCount.Current(on, DateTime.UtcNow) is { Users: 212, Accounts: null }) && (NocatFarm.Core.UserCount.Accounts(on, DateTime.UtcNow) == null));
		}

		foreach ((string what, FakePing bad) in new[] {
			("bad JSON", Answer(System.Net.HttpStatusCode.OK, "not json {")),
			("a 503", Answer(System.Net.HttpStatusCode.ServiceUnavailable, """{"users":999}""")),
			("a 404", Answer(System.Net.HttpStatusCode.NotFound, "")),
			("no connection", new FakePing((_, _) => throw new HttpRequestException("no route"))) }) {
			NocatFarm.Core.UserCount.Forget();
			using HttpClient http = NocatFarm.Core.UserCount.MakeClient(bad);
			bool ok = await NocatFarm.Core.UserCount.PingAsync(http, on);
			Check($"user count: {what} is skipped quietly, once, and the count stays unknown", !ok && (bad.Calls == 1) && (NocatFarm.Core.UserCount.Current(on, DateTime.UtcNow) == null));
		}

		FakePing slow = new(async (_, ct) => { await Task.Delay(TimeSpan.FromSeconds(30), ct); return new HttpResponseMessage(System.Net.HttpStatusCode.OK); });
		using (HttpClient http = NocatFarm.Core.UserCount.MakeClient(slow)) {
			Check("user count: the client gives up after 10 seconds", http.Timeout == TimeSpan.FromSeconds(10));
			http.Timeout = TimeSpan.FromMilliseconds(200);
			bool timeoutThrew = false, ok = true;
			try {
				ok = await NocatFarm.Core.UserCount.PingAsync(http, on);
			} catch (Exception) {
				timeoutThrew = true;
			}
			Check("user count: a timeout (a cancellation nobody asked for) doesn't escape", !timeoutThrew && !ok);
		}
		using (HttpClient http = NocatFarm.Core.UserCount.MakeClient(Answer(System.Net.HttpStatusCode.OK, """{"users":5,"accounts":9}"""))) {
			using CancellationTokenSource closing = new();
			closing.Cancel();
			bool closeThrew = false;
			try {
				await NocatFarm.Core.UserCount.PingAsync(http, on, closing.Token);
			} catch (Exception) {
				closeThrew = true;
			}
			Check("user count: closing mid-ping doesn't throw either", !closeThrew);
		}

		// Stale counts are hidden.
		DateTime nowUtc = DateTime.UtcNow;
		NocatFarm.Core.UserCount.Remember(new(212, 1240), nowUtc.AddHours(-2));
		Check("user count: two hours old is still shown", NocatFarm.Core.UserCount.Accounts(on, nowUtc) == 1240);
		NocatFarm.Core.UserCount.Remember(new(212, 1240), nowUtc.AddHours(-3.5));
		Check("user count: older than three hours is hidden", NocatFarm.Core.UserCount.Current(on, nowUtc) == null && NocatFarm.Core.UserCount.Accounts(on, nowUtc) == null);
		TimeSpan[] pingGaps = [.. Enumerable.Range(0, 500).Select(_ => NocatFarm.Core.UserCount.NextGap())];
		Check("user count: an hour apart, give or take a few minutes", pingGaps.All(g => (g >= TimeSpan.FromMinutes(55)) && (g <= TimeSpan.FromMinutes(65))) && (pingGaps.Distinct().Count() > 10));

		// The Discord card's second line, and the Overview's wording - the same sentence.
		string? langWas = NocatFarm.Config.Live.Global.Language;
		NocatFarm.Config.Live.Global.Language = "en";
		string Line(int choice, int? accounts) => NocatFarm.Core.DiscordPresence.SecondLine(choice, accounts, "5 cards today", _ => 600);
		Check("discord card: the short form (the card already says Playing nocat.farm), with a thousands separator", Line(NocatFarm.Core.DiscordPresence.LineAccounts, 1240) == "1,240 Steam accounts", Line(3, 1240));
		Check("discord card: just one Steam account", Line(3, 1) == "1 Steam account", Line(3, 1));
		Check("discord card: a few, and a lot", Line(3, 7) == "7 Steam accounts" && Line(3, 1234567) == "1,234,567 Steam accounts", Line(3, 1234567));
		Check("discord card: with the counter it fits Discord's line", NocatFarm.Core.DiscordPresence.WithCounter(Line(3, 1240), 3, 3) == "1,240 Steam accounts · 3 linked"
			&& NocatFarm.Core.DiscordPresence.WithCounter(Line(3, 12345), 3, 3) == "12,345 Steam accounts · 3 linked"
			&& NocatFarm.Core.DiscordPresence.WithCounter(Line(3, 12345), 3, 3).Length <= NocatFarm.Core.DiscordPresence.LineFits,
			NocatFarm.Core.DiscordPresence.WithCounter(Line(3, 12345), 3, 3));
		Check("user count: the Overview's line is the same sentence", NocatFarm.Core.UserCount.AccountsLine(1240) == "1,240 Steam accounts on nocat.farm"
			&& NocatFarm.Core.UserCount.AccountsLine(1) == "1 Steam account on nocat.farm");
		Check("discord card: count unknown (or Count me as a user off) falls back to the cards today", Line(3, null) == "5 cards today"
			&& Line(3, NocatFarm.Core.UserCount.Accounts(off, DateTime.UtcNow)) == "5 cards today");
		NocatFarm.Core.UserCount.Remember(new(212, null), DateTime.UtcNow);
		Check("discord card: an older nocat.lol (copies only) falls back to the cards today too", Line(3, NocatFarm.Core.UserCount.Accounts(on, DateTime.UtcNow)) == "5 cards today");
		NocatFarm.Core.UserCount.Forget();
		Check("discord card: the other choices are untouched", (Line(0, 212) == "5 cards today") && (Line(1, 212) == "10 hrs past week") && (Line(2, null) == "10 hrs past month"));
		Check("discord card: Steam accounts on nocat.farm is the default, still choice 3", (new NocatFarm.Config.GlobalConfig().DiscordSecondLine == NocatFarm.Core.DiscordPresence.LineAccounts)
			&& (NocatFarm.Core.DiscordPresence.LineAccounts == 3));
		Check("discord card: the choice is named for the Steam accounts, no people any more",
			NocatFarm.Config.Settings.FindGlobal("DiscordSecondLine") is { } secondLine
			&& NocatFarm.Config.Settings.ParseChoices(secondLine).Any(o => (o.Value == 3) && (o.Label == "Steam accounts on nocat.farm"))
			&& !(secondLine.Choices ?? "").Contains("people", StringComparison.OrdinalIgnoreCase) && !secondLine.Tooltip.Contains("people", StringComparison.OrdinalIgnoreCase));
		Check("settings: Count me as a user says the accounts signed in go too, as a number only",
			NocatFarm.Config.Settings.FindGlobal("CountMeAsUser") is { } countMe && countMe.Tooltip.Contains("how many of your Steam accounts are signed in (just the number)", StringComparison.Ordinal));

		// Grouped the way each language writes a number - the same as the dashboard's toLocaleString.
		Check("numbers: English, Chinese, Japanese and Korean group with a comma", NocatFarm.Fmt.Grouped(1240, "en") == "1,240" && NocatFarm.Fmt.Grouped(1240, "zh-CN") == "1,240"
			&& NocatFarm.Fmt.Grouped(1240, "ja") == "1,240" && NocatFarm.Fmt.Grouped(1240, "ko") == "1,240" && NocatFarm.Fmt.Grouped(1234567, "en") == "1,234,567");
		Check("numbers: German, Portuguese and Turkish with a dot", NocatFarm.Fmt.Grouped(1240, "de") == "1.240" && NocatFarm.Fmt.Grouped(1240, "pt-BR") == "1.240"
			&& NocatFarm.Fmt.Grouped(1234567, "tr") == "1.234.567");
		Check("numbers: French with a narrow space, Russian with a space", NocatFarm.Fmt.Grouped(1240, "fr") == "1\u202F240" && NocatFarm.Fmt.Grouped(1234567, "ru") == "1\u00A0234\u00A0567");
		Check("numbers: Spanish and Polish leave four digits whole, group five", NocatFarm.Fmt.Grouped(1240, "es") == "1240" && NocatFarm.Fmt.Grouped(12400, "es") == "12.400"
			&& NocatFarm.Fmt.Grouped(1240, "pl") == "1240" && NocatFarm.Fmt.Grouped(12400, "pl") == "12\u00A0400");
		Check("numbers: small ones and an unknown language", NocatFarm.Fmt.Grouped(0, "de") == "0" && NocatFarm.Fmt.Grouped(999, "en") == "999"
			&& NocatFarm.Fmt.Grouped(1240, "xx") == "1,240" && NocatFarm.Fmt.Grouped(-1240, "en") == "-1,240");
		NocatFarm.Config.Live.Global.Language = "de";
		Check("numbers: the language picked is the one used", NocatFarm.Fmt.Grouped(1240) == "1.240" && NocatFarm.Core.UserCount.AccountsLine(1240).StartsWith("1.240 ", StringComparison.Ordinal),
			NocatFarm.Core.UserCount.AccountsLine(1240));
		NocatFarm.Config.Live.Global.Language = langWas;
		NocatFarm.Core.Loc.T("Steam accounts on nocat.farm");
		Check("settings: Count me as a user is there, Show account names is gone",
			(NocatFarm.Config.Settings.FindGlobal("CountMeAsUser") is { Kind: NocatFarm.Config.SettingKind.Bool, Advanced: false })
			&& (NocatFarm.Config.Settings.FindGlobal("DiscordShowNames") == null) && (typeof(NocatFarm.Config.GlobalConfig).GetProperty("DiscordShowNames") == null)
			&& NocatFarm.Config.Settings.ParseChoices(NocatFarm.Config.Settings.FindGlobal("DiscordSecondLine")!).Select(o => o.Value).Order().SequenceEqual([0, 1, 2, 3]));

		// An old config with DiscordShowNames still loads: names on take the new default, a count picked is kept.
		NocatFarm.Config.GlobalConfig LoadOld(string json) {
			File.WriteAllText(NocatFarm.Config.ConfigStore.GlobalPath, json);
			return NocatFarm.Config.ConfigStore.LoadGlobal();
		}
		NocatFarm.Config.GlobalConfig named = LoadOld("""{ "StatusEveryMinutes": 7, "DiscordShowNames": true, "DiscordSecondLine": 1 }""");
		Check("old config: DiscordShowNames on still loads, and takes Steam accounts on nocat.farm", !NocatFarm.Config.ConfigStore.GlobalBroken
			&& (named.StatusEveryMinutes == 7) && (named.DiscordSecondLine == NocatFarm.Core.DiscordPresence.LineAccounts));
		Check("old config: ...and is written back without the old key", !File.ReadAllText(NocatFarm.Config.ConfigStore.GlobalPath).Contains("DiscordShowNames", StringComparison.Ordinal)
			&& (NocatFarm.Config.ConfigStore.LoadGlobal().DiscordSecondLine == NocatFarm.Core.DiscordPresence.LineAccounts));
		Check("old config: names off with a count picked keeps the count", LoadOld("""{ "DiscordShowNames": false, "DiscordSecondLine": 2 }""").DiscordSecondLine == 2
			&& LoadOld("""{ "discordShowNames": false, "DiscordSecondLine": 0 }""").DiscordSecondLine == 0);
		Check("old config: names off with no count written keeps what it showed (hours past week)", LoadOld("""{ "DiscordShowNames": false }""").DiscordSecondLine == 1);
		Check("old config: names on with no count written takes the new default", LoadOld("""{ "DiscordShowNames": true }""").DiscordSecondLine == NocatFarm.Core.DiscordPresence.LineAccounts);
		Check("new config: a count picked since is never touched", LoadOld("""{ "DiscordSecondLine": 0 }""").DiscordSecondLine == 0
			&& LoadOld("""{ "CountMeAsUser": false }""") is { CountMeAsUser: false, DiscordSecondLine: NocatFarm.Core.DiscordPresence.LineAccounts });
		Check("old config: a Second line set to the people count (3) now shows the Steam accounts", LoadOld("""{ "DiscordSecondLine": 3 }""").DiscordSecondLine == NocatFarm.Core.DiscordPresence.LineAccounts);
	} finally {
		NocatFarm.Core.UserCount.Forget();
		Environment.SetEnvironmentVariable("NOCATFARM_PING_URL", realPingUrl);
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);
		NocatFarm.Config.Live.Global = realGlobal;
		NocatFarm.Log.Suppressed = wasSuppressed;

		foreach (string dir in new[] { ucRoot, ucOther }) {
			try {
				Directory.Delete(dir, true);
			} catch (IOException) {
				// a temp folder
			}
		}
	}
}

// ── web token: a failed mint waits 10 minutes (per account) before the next; renewing and re-minting still work ─────
{
	DateTime now = DateTime.UtcNow;
	NocatFarm.Core.Bot.TokenStep Step(bool rejected, string? access, DateTime? until, DateTime? failedAt) =>
		NocatFarm.Core.Bot.NextTokenStep(rejected, access, until, failedAt, now);
	const NocatFarm.Core.Bot.TokenStep Reuse = NocatFarm.Core.Bot.TokenStep.Reuse, Mint = NocatFarm.Core.Bot.TokenStep.Mint, Wait = NocatFarm.Core.Bot.TokenStep.Wait;

	Check("web token: the wait after a failed mint is 10 minutes", NocatFarm.Core.Bot.MintRetryAfter == TimeSpan.FromMinutes(10));
	Check("web token: one with hours left is reused, no mint", Step(false, "tok", now.AddHours(20), null) == Reuse);
	Check("web token: ...even just after a failed mint", Step(false, "tok", now.AddHours(20), now.AddMinutes(-1)) == Reuse);
	Check("web token: 5 minutes before it runs out it's renewed", Step(false, "tok", now.AddMinutes(4), null) == Mint && Step(false, "tok", now.AddMinutes(6), null) == Reuse);
	Check("web token: none held, or run out - a mint", Step(false, null, null, null) == Mint && Step(false, "tok", now.AddMinutes(-1), null) == Mint);
	Check("web token: one Steam turned away (the login bounce, help site included) is re-minted at once", Step(true, "tok", now.AddHours(20), null) == Mint);
	Check("web token: a mint that failed 3 minutes ago - no new try, renewing or re-minting",
		Step(false, "tok", now.AddMinutes(4), now.AddMinutes(-3)) == Wait && Step(true, "tok", now.AddHours(20), now.AddMinutes(-3)) == Wait
		&& Step(false, null, null, now.AddMinutes(-3)) == Wait);
	Check("web token: 10 minutes after the failure it tries again", Step(false, "tok", now.AddMinutes(4), now.AddMinutes(-10)) == Mint
		&& Step(true, "tok", now.AddHours(20), now.AddMinutes(-11)) == Mint && Step(false, null, null, now.AddMinutes(-9.9)) == Wait);
	Check("web token: while waiting, a token with minutes left keeps being used", NocatFarm.Core.Bot.HeldWhileWaiting(false, "tok", now.AddMinutes(4), now) == "tok");
	Check("web token: ...but not one that ran out, one Steam turned away, or none",
		NocatFarm.Core.Bot.HeldWhileWaiting(false, "tok", now.AddMinutes(-1), now) == null && NocatFarm.Core.Bot.HeldWhileWaiting(true, "tok", now.AddHours(20), now) == null
		&& NocatFarm.Core.Bot.HeldWhileWaiting(false, null, null, now) == null);

	// On an account: per account, and a sign-in since lifts it.
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	string tokRoot = Path.Combine(Path.GetTempPath(), "nf-minttest-" + Guid.NewGuid().ToString("N"));
	bool wasSuppressed = NocatFarm.Log.Suppressed;
	NocatFarm.Log.Suppressed = true;

	try {
		NocatFarm.Config.ConfigStore.UseRoot(tokRoot);
		const BindingFlags I = BindingFlags.Instance | BindingFlags.NonPublic;
		var failing = new NocatFarm.Core.Bot("minttest-a", new NocatFarm.Config.BotConfig());
		var other = new NocatFarm.Core.Bot("minttest-b", new NocatFarm.Config.BotConfig());
		Check("web token: nothing held back before anything failed", failing.MintRetryAt == null && other.MintRetryAt == null);
		long gen = (long) typeof(NocatFarm.Core.Bot).GetField("_tokenGeneration", I)!.GetValue(failing)!;
		typeof(NocatFarm.Core.Bot).GetMethod("NoteMintFailed", I)!.Invoke(failing, [gen, now]);
		Check("web token: a failed mint holds that account back 10 minutes", failing.MintRetryAt == now + TimeSpan.FromMinutes(10), failing.MintRetryAt?.ToString("O") ?? "none");
		Check("web token: ...only that account", other.MintRetryAt == null);
		typeof(NocatFarm.Core.Bot).GetMethod("ReplaceTokens", I)!.Invoke(failing, ["a-new-refresh-token", null]);
		Check("web token: a sign-in since (new tokens) lifts the wait", failing.MintRetryAt == null);
		typeof(NocatFarm.Core.Bot).GetMethod("NoteMintFailed", I)!.Invoke(failing, [(long) typeof(NocatFarm.Core.Bot).GetField("_tokenGeneration", I)!.GetValue(failing)!, now]);
		typeof(NocatFarm.Core.Bot).GetMethod("ClearMintFailed", I)!.Invoke(failing, null);
		Check("web token: a mint that works lifts it too", failing.MintRetryAt == null);

		// The real path, on an account that looks signed in but isn't connected - nothing can reach Steam. The first ask tries
		// a mint, which fails; the next asks, straight after, don't try again.
		var offline = new NocatFarm.Core.Bot("minttest-c", new NocatFarm.Config.BotConfig());
		typeof(NocatFarm.Core.Bot).GetProperty("State")!.SetValue(offline, NocatFarm.Core.BotState.Online);
		typeof(NocatFarm.Core.Bot).GetProperty("SteamId")!.SetValue(offline, 76561197960265729UL);
		typeof(NocatFarm.Core.Bot).GetField("_refreshToken", I)!.SetValue(offline, "not-a-real-token");
		MethodInfo get = typeof(NocatFarm.Core.Bot).GetMethod("GetAccessTokenAsync", I)!;
		Task<string?> first = (Task<string?>) get.Invoke(offline, [false])!;
		bool firstDone = await Task.WhenAny(first, Task.Delay(TimeSpan.FromSeconds(90))) == first;
		DateTime? retryAt = offline.MintRetryAt;
		Check("web token: a mint that fails gives no token, and holds the next back", firstDone && (first.Result == null) && (retryAt != null)
			&& (retryAt > DateTime.UtcNow.AddMinutes(9)), $"done {firstDone}, retry at {retryAt:O}");
		System.Diagnostics.Stopwatch quick = System.Diagnostics.Stopwatch.StartNew();
		bool noneTried = true;
		for (int i = 0; i < 20; i++) {
			noneTried &= (await (Task<string?>) get.Invoke(offline, [i % 2 == 0])!) == null;
		}
		Check("web token: 20 more asks straight after (renewing and re-minting) don't try again", noneTried && (offline.MintRetryAt == retryAt)
			&& (quick.Elapsed < TimeSpan.FromSeconds(2)), $"{quick.Elapsed.TotalMilliseconds:0}ms, retry at {offline.MintRetryAt:O}");
		typeof(NocatFarm.Core.Bot).GetProperty("State")!.SetValue(offline, NocatFarm.Core.BotState.Stopped);
	} finally {
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);
		NocatFarm.Log.Suppressed = wasSuppressed;

		try {
			Directory.Delete(tokRoot, true);
		} catch (IOException) {
			// a temp folder
		}
	}
}

// ── user count: only switching it on brings the ping forward; no test copy ever pings nocat.lol ─────────────────────
{
	const BindingFlags S = BindingFlags.Static | BindingFlags.NonPublic | BindingFlags.Public;
	Type uc = typeof(NocatFarm.Core.UserCount);
	FieldInfo stopField = uc.GetField("_stop", S)!, nextField = uc.GetField("_next", S)!, wasOnField = uc.GetField("_wasOn", S)!;
	object? stopBefore = stopField.GetValue(null), nextBefore = nextField.GetValue(null), wasOnBefore = wasOnField.GetValue(null);
	string? pingUrlBefore = Environment.GetEnvironmentVariable("NOCATFARM_PING_URL");

	try {
		// Running (a stop handle there, as Start leaves it - nothing is started here), the next ping an hour away.
		Environment.SetEnvironmentVariable("NOCATFARM_PING_URL", null);
		using CancellationTokenSource running = new();
		stopField.SetValue(null, running);
		NocatFarm.Core.UserCount.Forget();
		DateTime now = DateTime.UtcNow;
		void HourAway() => nextField.SetValue(null, now.AddHours(1));

		HourAway();
		NocatFarm.Core.UserCount.Nudge(false, now);
		bool switchedOn = NocatFarm.Core.UserCount.Nudge(true, now);
		Check("user count: switching Count me as a user on brings the ping forward (1-3 minutes)", switchedOn
			&& (DateTime) nextField.GetValue(null)! <= DateTime.UtcNow.AddMinutes(3));

		// The dashboard runs it on every save, for every setting: it was on already, so nothing moves - with nocat.lol not
		// answering, every save used to send another ping.
		int moved = 0;
		for (int i = 0; i < 5; i++) {
			HourAway();
			moved += NocatFarm.Core.UserCount.Nudge(true, now) ? 1 : 0;
		}
		Check("user count: saving other settings with it on doesn't send another ping", (moved == 0) && ((DateTime) nextField.GetValue(null)! == now.AddHours(1)), $"{moved} moved");

		HourAway();
		NocatFarm.Core.UserCount.Nudge(false, now);
		Check("user count: switched off, nothing is brought forward", (DateTime) nextField.GetValue(null)! == now.AddHours(1));
		NocatFarm.Core.UserCount.Remember(new(212, 1240), now);
		Check("user count: switched back on with a count still showing, nothing is brought forward", !NocatFarm.Core.UserCount.Nudge(true, now)
			&& ((DateTime) nextField.GetValue(null)! == now.AddHours(1)));
		NocatFarm.Core.UserCount.Forget();
		NocatFarm.Core.UserCount.Nudge(false, now);
		Check("user count: off and on again (no count), it's brought forward again", NocatFarm.Core.UserCount.Nudge(true, now));
	} finally {
		stopField.SetValue(null, stopBefore);
		nextField.SetValue(null, nextBefore);
		wasOnField.SetValue(null, wasOnBefore);
		NocatFarm.Core.UserCount.Forget();
		Environment.SetEnvironmentVariable("NOCATFARM_PING_URL", pingUrlBefore);
	}

	// Every config a test script or workflow writes switches the ping off, and the CI runs and test containers point it at a
	// dead port here as well - a test run never counts itself on nocat.lol. (The browser test points it at its stub.)
	string repo = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..");
	string workflows = Path.Combine(repo, ".github", "workflows");
	IEnumerable<string> scripts = Directory.GetFiles(Path.Combine(repo, "tests"), "*.sh")
		.Concat(Directory.GetFiles(Path.Combine(repo, "tools", "release-tests"), "*.ps1"))
		.Concat(Directory.Exists(workflows) ? Directory.GetFiles(workflows, "*.yml") : []);
	System.Text.RegularExpressions.Regex configLiteral = new(@"WebPort[\\""`']*\s*:");
	System.Text.RegularExpressions.Regex pingOff = new(@"CountMeAsUser[\\""`']*\s*:\s*false");
	List<string> counting = [];
	int literals = 0;
	foreach (string file in scripts) {
		string[] lines = File.ReadAllLines(file);
		for (int i = 0; i < lines.Length; i++) {
			if (configLiteral.IsMatch(lines[i]) && !lines[i].Contains("grep", StringComparison.Ordinal)) {
				literals++;
				if (!pingOff.IsMatch(lines[i])) {
					counting.Add($"{Path.GetFileName(file)}:{i + 1}");
				}
			}
		}
	}
	string install = File.ReadAllText(Path.Combine(repo, "tools", "release-tests", "install.ps1"));
	Check("user count: every config a test writes has Count me as a user off", (literals >= 10) && (counting.Count == 0)
		&& install.Contains("-NotePropertyName CountMeAsUser -NotePropertyValue $false", StringComparison.Ordinal),
		$"{literals} configs, on in: {string.Join(", ", counting)}");

	const string deadPort = "NOCATFARM_PING_URL: http://127.0.0.1:9/api/farm/ping";
	string Read(params string[] parts) => File.ReadAllText(Path.Combine([repo, .. parts])).Replace("\r\n", "\n");
	bool workflowsChecked = !Directory.Exists(workflows) || (Read(".github", "workflows", "linux.yml").Contains("\nenv:\n  " + deadPort + "\n", StringComparison.Ordinal)
		&& Read(".github", "workflows", "macos.yml").Contains("\nenv:\n  " + deadPort + "\n", StringComparison.Ordinal)
		&& Read(".github", "workflows", "linux.yml").Contains("docker run -d --name nf --init -e NOCATFARM_WEB_PASSWORD=a-long-test-password-123 -e TZ=Europe/London -e NOCATFARM_PING_URL ", StringComparison.Ordinal));
	Check("user count: the CI runs, their Docker container and the compose test ping a dead port here, not nocat.lol", workflowsChecked
		&& Read("tests", "docker-compose.sh").Contains("      " + deadPort + "\n", StringComparison.Ordinal)
		&& Read("tests", "update-from-release.sh").Contains("NOCATFARM_PING_URL=\"http://127.0.0.1:9/api/farm/ping\"", StringComparison.Ordinal)
		&& Read("tools", "release-tests", "update-from-release.ps1").Contains("$env:NOCATFARM_PING_URL = 'http://127.0.0.1:9/api/farm/ping'", StringComparison.Ordinal));
}

// ── 'wake' just before bed, and a Mac set to Simplified Chinese outside mainland China ─────────────
{
	Check("wake: with bed closer than the shortest sitting it stays up for one (a plain wake started nothing and was done for the day)",
		NocatFarm.Modules.HumanMode.WakeStaysUp(false, true, false, true) && !NocatFarm.Modules.HumanMode.WakeStaysUp(false, true, false, false)
		&& NocatFarm.Modules.HumanMode.WakeStaysUp(true, true, false, false) && NocatFarm.Modules.HumanMode.WakeStaysUp(false, false, false, false)
		&& NocatFarm.Modules.HumanMode.WakeStaysUp(false, true, true, false));
	string wakeSrc = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Modules", "HumanMode.cs")).Replace("\r\n", "\n");
	Check("wake: WakeNow asks whether bed is too close, by the same rule a new game is held back by",
		wakeSrc.Contains("bool bedClose = !lastNight && BedTooCloseToStart(false, (PlanBed() - now).TotalMinutes, Bot.Cfg.SessionMinMinutes);", StringComparison.Ordinal)
		&& wakeSrc.Contains("if (WakeStaysUp(lastNight, InPlannedHours(now), _playedMinutesToday >= _targetMinutes, bedClose)) {", StringComparison.Ordinal));
	Check("language: a script said outright beats the region - zh-Hans-HK, zh-Hans-TW and zh-Hans-MO are Simplified",
		NocatFarm.Config.SystemLanguage.FromLocale("zh-Hans-HK") == "zh-CN" && NocatFarm.Config.SystemLanguage.FromLocale("zh-Hans-TW") == "zh-CN"
		&& NocatFarm.Config.SystemLanguage.FromLocale("zh-Hans-MO") == "zh-CN" && NocatFarm.Config.SystemLanguage.FromLocale("zh-Hant-HK") == "en"
		&& NocatFarm.Config.SystemLanguage.FromLocale("zh-HK") == "en"
		&& NocatFarm.Config.SystemLanguage.FromAppleLanguages("(\n    \"zh-Hans-HK\",\n    en\n)\n") == "zh-CN");
}

// ── a night's sleep is "Sleeps at least" (6-9 hours by default): a 05:23 bedtime no longer gets up at 09:31 ─────
{
	MethodInfo rollSleep = typeof(NocatFarm.Modules.HumanMode).GetMethod("RollDay", BindingFlags.NonPublic | BindingFlags.Static)!;
	DateTime day = new(2026, 10, 4);
	DateTime lateBed = new(2026, 10, 4, 5, 23, 0);

	int Earliest(NocatFarm.Config.BotConfig cfg) {
		int earliest = int.MaxValue;

		for (int seed = 0; seed < 400; seed++) {
			object roll = rollSleep.Invoke(null, [cfg, day, 75, true, lateBed, new Random(seed)])!;
			earliest = Math.Min(earliest, (int) roll.GetType().GetProperty("WakeMinute")!.GetValue(roll)!);
		}

		return earliest;
	}

	int byDefault = Earliest(new NocatFarm.Config.BotConfig { LegitMode = true });
	int longer = Earliest(new NocatFarm.Config.BotConfig { LegitMode = true, SleepMinHours = 8, SleepMaxHours = 10 });
	Check("sleep: after a 05:23 bedtime the next day starts 6 hours later at the earliest by default (it was 4)", byDefault >= (5 * 60) + 23 + (6 * 60), $"earliest {byDefault / 60:00}:{byDefault % 60:00}");
	Check("sleep: \"Sleeps at least\" 8 holds it to 13:23 at the earliest", longer >= (5 * 60) + 23 + (8 * 60), $"earliest {longer / 60:00}:{longer % 60:00}");
	Check("sleep: a range typed backwards still reads lowest to highest", NocatFarm.Modules.HumanMode.SleepMinutes(new NocatFarm.Config.BotConfig { SleepMinHours = 9, SleepMaxHours = 6 }) == (360, 540));
}

// ── rep4rep: the profile is looked at first - no comment box for this account, no post and no strike ─────────
{
	const BindingFlags lookAny = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.Instance;
	MethodInfo lookRead = typeof(NocatFarm.Modules.Rep4RepModule).GetMethod("ReadCommentBox", lookAny)!;
	const ulong lookViewer = 76561190000000001, lookTarget = 76561190000000002;   // below Steam's first real account id
	string LookBox(string? html, ulong onProfile = lookTarget, ulong asAccount = lookViewer) => lookRead.Invoke(null, [html, onProfile, asAccount])!.ToString()!;

	// Built from the shape of real steamcommunity.com profile pages, with made-up ids and names (public repo).
	string lookSamples = Path.Combine(AppContext.BaseDirectory, "samples");
	string LookSample(string kind) => File.ReadAllText(Path.Combine(lookSamples, $"r4r-profile-{kind}.html"));
	string boxOpen = LookSample("open"), boxFriend = LookSample("friend"), boxStranger = LookSample("friendsonly"), boxPrivate = LookSample("private"), boxOdd = LookSample("odd");
	string signedIn = $"g_steamID = \"{lookViewer}\";";

	Check("rep4rep look: comments open - the box is there, it posts", LookBox(boxOpen) == "Open", LookBox(boxOpen));
	Check("rep4rep look: friends-only and this account IS a friend - Steam shows it the box, it posts", LookBox(boxFriend) == "Open", LookBox(boxFriend));
	Check("rep4rep look: friends-only and NOT a friend - no box, skipped", LookBox(boxStranger) == "Closed", LookBox(boxStranger));
	Check("rep4rep look: a private profile - no box, skipped", LookBox(boxPrivate) == "Closed", LookBox(boxPrivate));
	Check("rep4rep look: Steam's error page isn't a profile - unreadable, so it posts as before", LookBox(boxOdd) == "Unreadable", LookBox(boxOdd));
	Check("rep4rep look: nothing came back - unreadable", LookBox(null) == "Unreadable" && LookBox("") == "Unreadable");
	Check("rep4rep look: a signed-out page shows nobody the box - it says nothing, so it posts as before",
		boxOpen.Contains(signedIn, StringComparison.Ordinal)
		&& LookBox(boxOpen.Replace(signedIn, "g_steamID = false;", StringComparison.Ordinal)) == "Unreadable"
		&& LookBox(boxStranger.Replace(signedIn, "g_steamID = false;", StringComparison.Ordinal)) == "Unreadable");
	Check("rep4rep look: a page signed in as another account, or about another profile, says nothing either",
		LookBox(boxStranger, asAccount: 76561190000000009) == "Unreadable" && LookBox(boxStranger, onProfile: 76561190000000009) == "Unreadable");
	Check("rep4rep look: a box Steam renders with only its class still counts as open",
		LookBox(boxStranger.Replace("<div style=\"\" class=\"commentthread_comment_container\"", "<textarea class=\"commentthread_textarea\"></textarea><div style=\"\" class=\"commentthread_comment_container\"", StringComparison.Ordinal)) == "Open");

	bool lookRealIds = Directory.GetFiles(lookSamples, "r4r-profile-*.html").Any(file =>
		System.Text.RegularExpressions.Regex.Matches(File.ReadAllText(file), @"7656\d{13}").Any(id => ulong.Parse(id.Value) >= 76561197960265728));
	Check("rep4rep look: the saved samples carry no real Steam ids", !lookRealIds);

	string r4look = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Modules", "Rep4RepModule.cs")).Replace("\r\n", "\n");
	int lookAt = r4look.IndexOf("private async Task<bool> CommentsClosedAsync(", StringComparison.Ordinal);
	string lookBody = lookAt > 0 ? r4look[lookAt..r4look.IndexOf("// ── posting", lookAt, StringComparison.Ordinal)] : "";
	int lookStep = r4look.IndexOf("private async Task<int> StepAsync(", StringComparison.Ordinal);
	int lookCheck = r4look.IndexOf("if (await CommentsClosedAsync(task, ct)", lookStep, StringComparison.Ordinal);
	int lookPost = r4look.IndexOf("await PostCommentAsync(task, ct)", lookStep, StringComparison.Ordinal);
	Check("rep4rep look: the scheduled post looks first, inside its turn, and a skip posts nothing",
		(lookCheck > lookStep) && (lookPost > lookCheck) && (r4look.IndexOf("await _posting.WaitAsync(ct)", lookStep, StringComparison.Ordinal) < lookCheck)
		&& r4look[lookCheck..lookPost].Contains("return Rng.Next(60, 4 * 60);", StringComparison.Ordinal));
	Check("rep4rep look: a skip is no strike - the profile is set aside like a refused one, one Info line, one GET",
		(lookBody.Length > 0) && !lookBody.Contains("Strikes", StringComparison.Ordinal) && lookBody.Contains("MarkDeadTarget(task.TargetSteamId", StringComparison.Ordinal)
		&& lookBody.Contains("Log.Info(new Said(\"{0} doesn't take comments · skipped\"", StringComparison.Ordinal)
		&& (System.Text.RegularExpressions.Regex.Matches(lookBody, @"Bot\.Web\.\w+Async\(").Count == 1) && lookBody.Contains("Bot.Web.GetAsync(", StringComparison.Ordinal));
	Check("rep4rep look: an unreadable page only asks the friends list in memory, and still posts",
		lookBody.Contains("Bot.Friends?.GetFriendRelationship(", StringComparison.Ordinal) && lookBody.Contains("return false;", StringComparison.Ordinal));
	Check("rep4rep look: a long run of closed profiles gets one real try, so a blocked account still reaches its rest",
		lookBody.Contains("_closedRun >= ClosedRunToDoubt", StringComparison.Ordinal)
		&& r4look.Contains("private async Task<int> OnTargetRefusedAsync(Rep4RepTask task) {\n\t\t_closedRun = 0;", StringComparison.Ordinal)
		&& r4look.Contains("_state!.RecordPost(task.TaskId);\n\t\t_closedRun = 0;", StringComparison.Ordinal));
}

// ── inventory value moves live: each price that lands is in the total and off the "still pricing" count at once ─────
{
	const BindingFlags All = BindingFlags.NonPublic | BindingFlags.Public | BindingFlags.Static | BindingFlags.Instance;
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	NocatFarm.Config.GlobalConfig liveBefore = NocatFarm.Config.Live.Global;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-liveinv-" + Guid.NewGuid().ToString("N"));
	Type invT = typeof(NocatFarm.Core.InventoryValue);
	MethodInfo remember = typeof(NocatFarm.PriceBook).GetMethod("Remember", All)!;
	string tag = Guid.NewGuid().ToString("N")[..8];
	string A = "live-a-" + tag, B = "live-b-" + tag, C = "live-c-" + tag;
	const uint Game = 990001, Skipped = 990002;

	try {
		NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);
		NocatFarm.Config.Live.Global = new NocatFarm.Config.GlobalConfig { MarketGapSeconds = 10 };
		var lbot = new NocatFarm.Core.Bot("harness-liveinv", new NocatFarm.Config.BotConfig { InventoryIgnoreGames = [Skipped] });
		NocatFarm.Core.InventoryValue inv = lbot.Inventory;

		// What a read found, as the snapshot a read leaves behind: 3 of A and 2 of B in a game, 1 of C in a skipped one.
		void Holds(int countA) {
			Directory.CreateDirectory(Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state"));
			File.WriteAllText(Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", "invvalue-harness-liveinv.json"), System.Text.Json.JsonSerializer.Serialize(new {
				ReadAt = DateTime.UtcNow.Ticks,
				Games = new object[] {
					new { App = Game, Game = "Live Game", Items = new Dictionary<string, int[]> { [A] = [countA, 5], [B] = [2, 5] } },
					new { App = Skipped, Game = "Skipped Game", Items = new Dictionary<string, int[]> { [C] = [1, 5] } }
				}
			}));
			invT.GetMethod("LoadSnapshot", All)!.Invoke(inv, [TimeSpan.FromHours(6)]);
			invT.GetMethod("Recount", All)!.Invoke(inv, []);
		}

		void Price(uint app, string hash, decimal usd) => remember.Invoke(null, [app, hash, usd]);

		Holds(3);
		bool startsAtNothing = (inv.Total == 0) && (inv.Pending == 2);

		Price(Game, A, 1.50m);
		bool firstLanded = (inv.Total == 4.50m) && (inv.Pending == 1) && (inv.ByGame.First(g => g.AppId == Game).Value == 4.50m);
		Check("live inventory: a price landing adds quantity x price and takes one off the count at once", startsAtNothing && firstLanded, $"{inv.Total} / {inv.Pending}");

		// A failed lookup: the market is pausing, so the book returns nothing - nothing counts as priced.
		Type pb = typeof(NocatFarm.PriceBook);
		FieldInfo coolUntil = pb.GetField("_coolUntil", All)!;
		pb.GetField("_coolLoaded", All)!.SetValue(null, true);
		object coolBefore = coolUntil.GetValue(null)!;
		coolUntil.SetValue(null, DateTime.UtcNow.AddMinutes(15));
		decimal? failed = await NocatFarm.PriceBook.FetchAsync(Game, B, CancellationToken.None);
		coolUntil.SetValue(null, coolBefore);
		Check("live inventory: a failed lookup changes neither the total nor the count", (failed == null) && (inv.Total == 4.50m) && (inv.Pending == 1), $"{inv.Total} / {inv.Pending}");

		Price(Skipped, C, 100m);
		Price(Game, "not-held-" + tag, 50m);
		Check("live inventory: a price for a skipped game or for something not held moves nothing", (inv.Total == 4.50m) && (inv.Pending == 1), $"{inv.Total} / {inv.Pending}");

		Price(Game, B, 0.25m);
		Price(Game, A, 2.00m);   // asked again later: moves by the difference, not by the whole price again
		Check("live inventory: the last price empties the count; a price asked again moves by the difference", (inv.Total == 6.50m) && (inv.Pending == 0), $"{inv.Total} / {inv.Pending}");

		invT.GetMethod("Recount", All)!.Invoke(inv, []);
		bool sameAfterRecount = (inv.Total == 6.50m) && (inv.Pending == 0);
		Holds(1);   // a full read finds one A now (two traded away)
		Check("live inventory: a full recount replaces the running total - nothing counted twice", sameAfterRecount && (inv.Total == 2.50m) && (inv.Pending == 0), $"{inv.Total} / {inv.Pending}");

		// Many prices landing from several threads while recounts run alongside: every one is counted exactly once.
		string[] many = [.. Enumerable.Range(0, 200).Select(i => $"live-m{i}-{tag}")];
		File.WriteAllText(Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", "invvalue-harness-liveinv.json"), System.Text.Json.JsonSerializer.Serialize(new {
			ReadAt = DateTime.UtcNow.Ticks,
			Games = new object[] { new { App = Game, Game = "Live Game", Items = many.ToDictionary(static h => h, static _ => new[] { 2, 5 }) } }
		}));
		invT.GetMethod("LoadSnapshot", All)!.Invoke(inv, [TimeSpan.FromHours(6)]);
		invT.GetMethod("Recount", All)!.Invoke(inv, []);
		int pendingBefore = inv.Pending;
		using (CancellationTokenSource stopRecounts = new()) {
			Task recounts = Task.Run(() => {
				while (!stopRecounts.IsCancellationRequested) {
					invT.GetMethod("Recount", All)!.Invoke(inv, []);
				}
			});
			Parallel.ForEach(many, h => Price(Game, h, 0.10m));
			stopRecounts.Cancel();
			await recounts;
		}
		Check("live inventory: 200 prices from many threads while it recounts - the total and count are exact", (pendingBefore == 200) && (inv.Total == 40.00m) && (inv.Pending == 0), $"{pendingBefore} -> {inv.Total} / {inv.Pending}");

		// The currency changed: a price in the new one starts the total again from the book, as a recount always did.
		NocatFarm.Config.Live.Global = new NocatFarm.Config.GlobalConfig { MarketGapSeconds = 10, MarketCurrency = 3 };
		Price(Game, many[0], 1.00m);
		Check("live inventory: a price in a new currency starts again - nothing in the old one mixed in", (inv.Total == 2.00m) && (inv.Pending == 199), $"{inv.Total} / {inv.Pending}");

		Check("live inventory: the time left reads ~25m, ~2h or ~3h, nothing when done",
			(NocatFarm.Core.InventoryValue.Eta(150, 10) == "~25m") && (NocatFarm.Core.InventoryValue.Eta(720, 10) == "~2h")
			&& (NocatFarm.Core.InventoryValue.Eta(931, 10) == "~3h") && (NocatFarm.Core.InventoryValue.Eta(1, 10) == "~1m")
			&& (NocatFarm.Core.InventoryValue.Eta(0, 10) == "") && (NocatFarm.Core.InventoryValue.Eta(60, 600) == "~1h")
			&& (NocatFarm.Core.InventoryValue.EtaSeconds(931) == 9310),
			$"{NocatFarm.Core.InventoryValue.Eta(150, 10)} {NocatFarm.Core.InventoryValue.Eta(720, 10)} {NocatFarm.Core.InventoryValue.Eta(931, 10)}");

		string appJs = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "wwwroot", "app.js")).Replace("\r\n", "\n");
		Check("live inventory: the tile says pricing, how many items, about how many requests and how long - or that Steam asked it to wait",
			appJs.Contains("return tf('pricing · {0} · {1} · {2}', things, requests === 1 ? t('about 1 request') : tf('about {0} requests', requests), eta(secs));", StringComparison.Ordinal)
			&& appJs.Contains("if (paused) return tf('pricing · {0} · Steam asked it to wait until {1}', things, clock(paused));", StringComparison.Ordinal)
			&& appJs.Contains("const mins = Math.ceil(secs / 60);\n  return '~' + (mins < 60 ? mins + t('m') : Math.round(mins / 60) + t('h'));", StringComparison.Ordinal)
			&& appJs.Contains("state.InventoryPending > 0 ? pricingLine(state.InventoryPending, state.InventoryRequests, state.InventoryEtaSeconds, state.InventoryPausedUntil, state.InventoryStale) : ''", StringComparison.Ordinal));
	} finally {
		NocatFarm.Config.Live.Global = liveBefore;
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
		}
	}
}

// ── prices by the page: a whole game's cards, or every wear of a skin, from one market search ─────────────────────────
{
	const BindingFlags All = BindingFlags.NonPublic | BindingFlags.Public | BindingFlags.Static | BindingFlags.Instance;
	Type pb = typeof(NocatFarm.PriceBook);
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	NocatFarm.Config.GlobalConfig liveBefore = NocatFarm.Config.Live.Global;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-page-prices-" + Guid.NewGuid().ToString("N"));
	FieldInfo httpF = pb.GetField("Http", All)!, httpBF = pb.GetField("HttpB", All)!;
	object httpBefore = httpF.GetValue(null)!, httpBBefore = httpBF.GetValue(null)!;
	PropertyInfo gapP = pb.GetProperty("GapForTests", All)!;
	FieldInfo askedF = pb.GetField("Asked", All)!;
	FieldInfo coolUntilF = pb.GetField("_coolUntil", All)!, coolMinutesF = pb.GetField("_coolSeconds", All)!, saidF = pb.GetField("_saidRefused", All)!;
	int Asked() => (int) askedF.GetValue(null)!;
	string tag = Guid.NewGuid().ToString("N")[..6];

	// A pretend market: listings per (search app), each with what the search can filter on, most listed first as Steam
	// sorts them. Pages of ten, as Steam sends signed out whatever count is asked for.
	int fakePage = 10;
	List<(uint App, uint Game, int Class, int Border, string Hash, int Cents, int Listings)> market = [];
	string Json(object o) => System.Text.Json.JsonSerializer.Serialize(o);
	HttpResponseMessage Answer(HttpRequestMessage request) {
		string url = Uri.UnescapeDataString(request.RequestUri!.Query.TrimStart('?'));
		Dictionary<string, List<string>> q = [];
		foreach (string part in url.Split('&')) {
			int eq = part.IndexOf('=');
			string k = eq < 0 ? part : part[..eq], v = eq < 0 ? "" : part[(eq + 1)..];
			if (!q.TryGetValue(k, out List<string>? list)) q[k] = list = [];
			list.Add(v);
		}
		string One(string k) => q.TryGetValue(k, out List<string>? v) ? v[0] : "";
		uint app = uint.Parse(One("appid"));

		if (request.RequestUri.AbsolutePath.StartsWith("/market/priceoverview", StringComparison.Ordinal)) {
			var hit = market.FirstOrDefault(m => (m.App == app) && (m.Hash == One("market_hash_name")));
			return new HttpResponseMessage(System.Net.HttpStatusCode.OK) { Content = new StringContent(hit.Hash == null ? "{\"success\":false}"
				: Json(new { success = true, lowest_price = $"${hit.Cents / 100m:0.00}", median_price = $"${(hit.Cents - 1) / 100m:0.00}" })) };
		}

		IEnumerable<(uint App, uint Game, int Class, int Border, string Hash, int Cents, int Listings)> found = market.Where(m => m.App == app);
		if (q.TryGetValue("category_753_Game[]", out List<string>? games)) found = found.Where(m => games.Contains($"tag_app_{m.Game}"));
		if (q.TryGetValue("category_753_item_class[]", out List<string>? classes)) found = found.Where(m => classes.Contains($"tag_item_class_{m.Class}"));
		if (q.TryGetValue("category_753_cardborder[]", out List<string>? borders)) found = found.Where(m => (m.Class == 2) && borders.Contains($"tag_cardborder_{m.Border}"));
		if (One("query") is { Length: > 0 } words) found = found.Where(m => words.Split(' ').All(w => m.Hash.Contains(w, StringComparison.OrdinalIgnoreCase)));
		var all = found.OrderByDescending(static m => m.Listings).ToList();
		int start = int.Parse(One("start"));
		return new HttpResponseMessage(System.Net.HttpStatusCode.OK) { Content = new StringContent(Json(new {
			success = true, start, pagesize = fakePage, total_count = all.Count,
			results = all.Skip(start).Take(fakePage).Select(m => new { name = m.Hash, hash_name = m.Hash, sell_listings = m.Listings, sell_price = m.Cents, sell_price_text = "", app_name = "Steam" })
		})) };
	}
	bool refuse = false;
	List<DateTime> sent = [];
	FakePing fake = new((request, _) => {
		lock (sent) {
			sent.Add(DateTime.UtcNow);
		}
		return Task.FromResult(refuse ? new HttpResponseMessage(System.Net.HttpStatusCode.TooManyRequests) : Answer(request));
	});
	MethodInfo setPrice = typeof(NocatFarm.Core.LevelPlanner).GetMethod("PriceAsync", All)!;
	string plannerSrc0() => File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Core", "LevelPlanner.cs")).Replace("\r\n", "\n");
	async Task<(object? Set, bool Asked)> PlannerPrice(NocatFarm.Core.Bot b, uint app) {
		Task t = (Task) setPrice.Invoke(null, [b, app, CancellationToken.None])!;
		await t;
		object result = t.GetType().GetProperty("Result")!.GetValue(t)!;
		return (result.GetType().GetField("Item1")!.GetValue(result), (bool) result.GetType().GetField("Item2")!.GetValue(result)!);
	}

	try {
		NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);
		NocatFarm.Config.Live.Global = new NocatFarm.Config.GlobalConfig { MarketGapSeconds = 8 };
		httpF.SetValue(null, new HttpClient(fake));
		httpBF.SetValue(null, new HttpClient(fake));   // both ways answered here
		gapP.SetValue(null, 0d);
		coolUntilF.SetValue(null, DateTime.MinValue);
		coolMinutesF.SetValue(null, 0);
		pb.GetField("_coolLoaded", All)!.SetValue(null, true);
		pb.GetField("_checkFirst", All)!.SetValue(null, false);   // counted from a market that has answered before
		pb.GetField("_refusedInRow", All)!.SetValue(null, 0);
		pb.GetField("_searchOffUntil", All)!.SetValue(null, DateTime.MinValue);
		var planner = new NocatFarm.Core.Bot("harness-planner", new NocatFarm.Config.BotConfig());

		// The planner's account has a signed-in session that answers here - so a request through it would be counted,
		// never sent. Every price is read signed out: this stays at nothing.
		var plannerWeb = (NocatFarm.Core.WebSession) typeof(NocatFarm.Core.Bot).GetProperty("Web", All)!.GetValue(planner)!;
		FakePing plannerSession = new((_, _) => Task.FromResult(new HttpResponseMessage(System.Net.HttpStatusCode.OK) {
			Content = new StringContent("""{"success":true,"pagesize":100,"total_count":0,"results":[]}""")
		}));
		typeof(NocatFarm.Core.WebSession).GetField("_http", All)!.SetValue(plannerWeb, new HttpClient(plannerSession));
		string plannerExp = DateTimeOffset.UtcNow.AddHours(20).ToUnixTimeSeconds().ToString(System.Globalization.CultureInfo.InvariantCulture);
		plannerWeb.Init(76561190000000002, "e30." + Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes("{\"exp\":" + plannerExp + "}")).TrimEnd('=').Replace('+', '-').Replace('/', '_') + ".x");

		// 1. Reading a search page (made-up names): what's for sale is priced, what isn't is left for priceoverview.
		var page1 = NocatFarm.PriceBook.ParseSearch("""{"success":true,"start":0,"pagesize":10,"total_count":23,"results":[{"hash_name":"111-Fake Hero (Trading Card)","sell_listings":40,"sell_price":12},{"hash_name":"111-:fakesmile:","sell_listings":0,"sell_price":0},{"hash_name":"111-Fake Hills (Profile Background)","sell_listings":3,"sell_price":45}]}""");
		Check("market search: a page gives the total, the page size and the lowest listing of each item for sale",
			page1 is { Total: 23, PageSize: 10, Count: 3 } p && (p.Prices.Count == 2) && (p.Prices[0] == ("111-Fake Hero (Trading Card)", 12)) && (p.Prices[1] == ("111-Fake Hills (Profile Background)", 45))
			&& (NocatFarm.PriceBook.ParseSearch("""{"success":false}""") == null) && (NocatFarm.PriceBook.ParseSearch("<html>") == null)
			&& (NocatFarm.PriceBook.ParseSearch("""{"success":true,"total_count":0,"results":[]}""") is { Count: 0 }));

		// 2. Which items share a search.
		Check("market search: a game's Steam items share one search; every wear and StatTrak of a skin share one; anything else is alone",
			(NocatFarm.PriceBook.GroupOf(753, "111-Fake Hero (Trading Card)")?.Key == "753:111") && (NocatFarm.PriceBook.GroupOf(753, "111-:fakesmile:")?.Key == "753:111")
			&& (NocatFarm.PriceBook.GroupOf(753, "753-Sack of Gems") == null)
			&& (NocatFarm.PriceBook.GroupOf(730, "StatTrak™ Fake-9 | Testline (Field-Tested)")?.Key == "730:Fake-9 | Testline")
			&& (NocatFarm.PriceBook.GroupOf(730, "★ StatTrak™ Fake Knife | Testfade (Factory New)")?.Key == "730:Fake Knife | Testfade")
			&& (NocatFarm.PriceBook.GroupOf(730, "Fake Case 3") == null));

		List<(uint App, string Hash)> L(params (uint, string)[] items) => [.. items];
		var normalOnly = NocatFarm.PriceBook.NextAsk(L((753, "222-A (Trading Card)"), (753, "222-B (Trading Card)")));
		var mixed = NocatFarm.PriceBook.NextAsk(L((753, "222-A (Trading Card)"), (753, "222-Hills (Profile Background)")));
		var skin = NocatFarm.PriceBook.NextAsk(L((730, "Fake-9 | Testline (Field-Tested)"), (730, "StatTrak™ Fake-9 | Testline (Minimal Wear)")));
		var alone = NocatFarm.PriceBook.NextAsk(L((753, "222-A (Trading Card)"), (753, "333-B (Trading Card)")));
		Check("market search: narrowed to the kinds wanted - normal cards alone also by border; the skin searched by its plain name; one item asked alone",
			(normalOnly.Search == "/market/search/render/?norender=1&appid=753&category_753_Game[]=tag_app_222&category_753_item_class[]=tag_item_class_2&category_753_cardborder[]=tag_cardborder_0")
			&& (mixed.Search == "/market/search/render/?norender=1&appid=753&category_753_Game[]=tag_app_222&category_753_item_class[]=tag_item_class_2&category_753_item_class[]=tag_item_class_3")
			&& (skin.Search == "/market/search/render/?norender=1&appid=730&search_descriptions=0&query=Fake-9%20Testline") && (skin.SearchApp == 730)
			&& (alone.Search == null) && (alone.Hash == "222-A (Trading Card)"),
			$"{normalOnly.Search} / {mixed.Search} / {skin.Search} / {alone.Search}");

		// 3. Through the pretend market.
		uint g1 = 5100;
		for (int i = 0; i < 9; i++) market.Add((753, g1, 2, 0, $"{g1}-Card{i}-{tag} (Trading Card)", 5 + i, 100));
		for (int i = 0; i < 9; i++) market.Add((753, g1, 2, 1, $"{g1}-Card{i}-{tag} (Foil Trading Card)", 50 + i, 10));
		for (int i = 0; i < 5; i++) market.Add((753, g1, 3, 0, $"{g1}-Bg{i}-{tag} (Profile Background)", 20 + i, 30));
		market.Add((730, 0, 0, 0, $"Fake-9 | Line{tag} (Field-Tested)", 3488, 900));
		market.Add((730, 0, 0, 0, $"StatTrak™ Fake-9 | Line{tag} (Minimal Wear)", 41609, 9));
		market.Add((730, 0, 0, 0, $"Fake-9 | Line{tag} (Battle-Scarred)", 2629, 80));
		market.Add((730, 0, 0, 0, $"Fake Case {tag}", 77, 5000));

		List<(uint App, string Hash)> wanted = [
			(753, $"{g1}-Card0-{tag} (Trading Card)"), (753, $"{g1}-Card3-{tag} (Trading Card)"), (753, $"{g1}-Card8-{tag} (Trading Card)"),
			(753, $"{g1}-Gone-{tag} (Trading Card)"),   // not on the market at all: the search won't have it
			(730, $"Fake-9 | Line{tag} (Field-Tested)"), (730, $"StatTrak™ Fake-9 | Line{tag} (Minimal Wear)"), (730, $"Fake Case {tag}")];
		int before = Asked();
		bool done = await NocatFarm.PriceBook.PriceAsync(wanted, 100, CancellationToken.None);
		int used = Asked() - before;
		Check("market search: 3 cards, 2 wears of a skin, a case and one unlisted card - 4 requests, not 7, every one priced",
			done && (used == 4) && wanted.All(w => !NocatFarm.PriceBook.NeedsRefresh(w.App, w.Hash)) && (fake.Calls == used), $"{used} requests");
		Check("market search: every price a page returns is kept, asked for or not; lowest listing everywhere",
			(NocatFarm.PriceBook.Known(753, $"{g1}-Card5-{tag} (Trading Card)") == 0.10m) && (NocatFarm.PriceBook.Known(753, $"{g1}-Card8-{tag} (Trading Card)") == 0.13m)
			&& (NocatFarm.PriceBook.Known(730, $"Fake-9 | Line{tag} (Battle-Scarred)") == 26.29m) && (NocatFarm.PriceBook.Known(730, $"Fake Case {tag}") == 0.77m)
			&& (NocatFarm.PriceBook.Known(753, $"{g1}-Gone-{tag} (Trading Card)") == 0m));

		// The same items for a second account, and items a page already priced for the first: nothing is asked again.
		before = Asked();
		await NocatFarm.PriceBook.PriceAsync([.. wanted, (753, $"{g1}-Card5-{tag} (Trading Card)"), (730, $"Fake-9 | Line{tag} (Battle-Scarred)")], 100, CancellationToken.None);
		Check("market search: the same items again, or ones another search priced - no request at all", Asked() == before, $"{Asked() - before}");

		// Read on only while the pages left are fewer than the items left: two foils that aren't on the first of three
		// pages are asked one each, not by reading two more pages.
		for (int i = 0; i < 25; i++) market.Add((753, 5200, 2, 1, $"5200-Filler{i}-{tag} (Foil Trading Card)", 1, 50));
		market.Add((753, 5200, 2, 1, $"5200-Late1-{tag} (Foil Trading Card)", 300, 2));   // fewest listed: on the last page
		market.Add((753, 5200, 2, 1, $"5200-Late2-{tag} (Foil Trading Card)", 301, 2));
		before = Asked();
		await NocatFarm.PriceBook.PriceAsync([(753, $"5200-Late1-{tag} (Foil Trading Card)"), (753, $"5200-Late2-{tag} (Foil Trading Card)")], 100, CancellationToken.None);
		Check("market search: two items on a 3-page search - one page, then one each rather than two more pages",
			(Asked() - before == 3) && (NocatFarm.PriceBook.Known(753, $"5200-Late2-{tag} (Foil Trading Card)") == 3.01m), $"{Asked() - before}");

		// 4. Told 429 by the way that was answering a moment ago - the market's limit: it stops at once, says until when,
		// and asks nothing more until then.
		refuse = true;
		before = Asked();
		bool stopped = !await NocatFarm.PriceBook.PriceAsync([(730, $"Nothing Yet {tag}")], 100, CancellationToken.None);
		bool paused = NocatFarm.PriceBook.PausedUntil is { } until && (until > DateTime.UtcNow.AddSeconds(85));
		bool quiet = !await NocatFarm.PriceBook.PriceAsync([(730, $"Nothing Yet {tag}")], 100, CancellationToken.None);
		Check("market: a 429 from the way that was answering stops pricing after that one request, pauses every market request and says until when",
			stopped && paused && quiet && (Asked() - before == 1), $"{Asked() - before} requests");
		refuse = false;
		coolUntilF.SetValue(null, DateTime.MinValue);
		coolMinutesF.SetValue(null, 0);
		saidF.SetValue(null, false);
		pb.GetField("_checkFirst", All)!.SetValue(null, false);
		NocatFarm.Core.Limiters.Remember("market", DateTime.MinValue, 0);

		// 5. The gap is between EVERY request, search pages included.
		gapP.SetValue(null, 0.3d);
		market.Add((730, 0, 0, 0, $"Gap One {tag}", 5, 5));
		market.Add((730, 0, 0, 0, $"Gap Two {tag}", 5, 5));
		var watch = System.Diagnostics.Stopwatch.StartNew();
		await NocatFarm.PriceBook.PriceAsync([(730, $"Gap One {tag}"), (730, $"Gap Two {tag}")], 100, CancellationToken.None);
		Check("market: the gap is kept between every request - give or take a quarter", watch.Elapsed >= TimeSpan.FromSeconds(0.22), $"{watch.ElapsedMilliseconds}ms for 2");

		// The level planner's card set prices ask in the SAME queue: one gap between all of them, not two paces side by side.
		uint setGame = 5300;
		for (int i = 0; i < 6; i++) market.Add((753, setGame, 2, 0, $"{setGame}-Set{i}-{tag} (Trading Card)", 7 + i, 200));
		market.Add((730, 0, 0, 0, $"Gap Three {tag}", 5, 5));
		market.Add((730, 0, 0, 0, $"Gap Four {tag}", 5, 5));
		lock (sent) sent.Clear();
		before = Asked();
		Task<(object? Set, bool Asked)> planning = PlannerPrice(planner, setGame);
		Task pricing = NocatFarm.PriceBook.PriceAsync([(730, $"Gap Three {tag}"), (730, $"Gap Four {tag}")], 100, CancellationToken.None);
		await Task.WhenAll(planning, pricing);
		List<DateTime> times;
		lock (sent) times = [.. sent.Order()];
		bool spaced = times.Zip(times.Skip(1)).All(static p => p.Second - p.First >= TimeSpan.FromSeconds(0.22));
		Check("level planner: its market searches and the pricing queue keep one gap between all of them",
			(planning.Result.Set != null) && (times.Count == 3) && (Asked() - before == 3) && spaced,
			string.Join(", ", times.Zip(times.Skip(1)).Select(static p => $"{(p.Second - p.First).TotalMilliseconds:0}ms")));
		Check("level planner: its market reads go signed out - nothing through the account's session",
			(plannerSession.Calls == 0) && (fake.Calls > 0), $"{plannerSession.Calls} through the session");
		Check("level planner: the card prices its search saw are in the price book - pricing won't ask for them again",
			(NocatFarm.PriceBook.Known(753, $"{setGame}-Set3-{tag} (Trading Card)") == 0.10m) && !NocatFarm.PriceBook.NeedsRefresh(753, $"{setGame}-Set5-{tag} (Trading Card)"));
		gapP.SetValue(null, 0d);

		// Told 429 by a price lookup: the planner asks nothing until the pause is over - and says it asked nothing, so no
		// lookup of its budget is spent on it.
		refuse = true;
		before = Asked();
		await NocatFarm.PriceBook.PriceAsync([(730, $"Refused Thing {tag}")], 100, CancellationToken.None);
		(object? noSet, bool noSetAsked) = await PlannerPrice(planner, 5301);
		Check("level planner: while the market's pause stands it asks nothing, and says so", (noSet == null) && !noSetAsked && (Asked() - before == 1) && (NocatFarm.PriceBook.PausedUntil != null), $"{Asked() - before}");

		// 'levelup' asked meanwhile: it says when the market can be asked, and works nothing out - nothing cached either.
		Type plannerT = typeof(NocatFarm.Core.LevelPlanner);
		var plans = (System.Collections.IDictionary) plannerT.GetField("Plans", All)!.GetValue(null)!;
		var working = (HashSet<string>) plannerT.GetField("Working", All)!.GetValue(null)!;
		int callsBefore = fake.Calls;
		string duringPause = NocatFarm.Core.LevelPlanner.Ask(planner, 60);
		string pauseClock = NocatFarm.PriceBook.PausedUntil!.Value.ToLocalTime().ToString("HH:mm");
		bool nothingKept;
		lock (plans) nothingKept = !plans.Contains(planner.Name) && !working.Contains(planner.Name);
		Check("levelup: during the market's pause it says so and when it can be asked - nothing worked out, nothing cached, nothing sent",
			duringPause.Contains("Steam asked the market lookups to wait - try again after " + pauseClock, StringComparison.Ordinal) && nothingKept && (fake.Calls == callsBefore),
			duringPause);
		Check("levelup: a plan that met a market that didn't answer isn't kept - shown once, then worked out again",
			plannerSrc0().Contains("if (set == null) {\n\t\t\t\treturn (Stopped(bot), false);", StringComparison.Ordinal)
			&& plannerSrc0().Contains("if (done.Once) {\n\t\t\t\t\tPlans.Remove(bot.Name);", StringComparison.Ordinal));
		refuse = false;
		coolUntilF.SetValue(null, DateTime.MinValue);
		coolMinutesF.SetValue(null, 0);
		saidF.SetValue(null, false);
		pb.GetField("_checkFirst", All)!.SetValue(null, false);
		NocatFarm.Core.Limiters.Remember("market", DateTime.MinValue, 0);
		string plannerSrc = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Core", "LevelPlanner.cs"));
		Check("level planner: no pace of its own left - every market request goes through the price book",
			!plannerSrc.Contains("Task.Delay", StringComparison.Ordinal) && !plannerSrc.Contains("Web.GetAsync", StringComparison.Ordinal)
			&& plannerSrc.Contains("PriceBook.MarketGetAsync(", StringComparison.Ordinal) && !plannerSrc.Contains("bot.Web, ct", StringComparison.Ordinal));
		Check("level planner: still read signed out after a 429 - nothing through the account's session", plannerSession.Calls == 0, $"{plannerSession.Calls}");

		// Searches never use a session: no way to hand one in, and nothing in the price book picks an account's.
		string bookSrc = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Core", "PriceBook.cs"));
		Check("market: every price search and lookup is signed out - no session can be passed in or picked",
			pb.GetMethods(All).Where(static m => m.Name is "MarketGetAsync" or "AskLockedAsync" or "SearchLockedAsync" or "FetchLockedAsync")
				.All(static m => m.GetParameters().All(static p => p.ParameterType != typeof(NocatFarm.Core.WebSession)))
			&& (pb.GetMethod("SearchSession", All) == null) && (pb.GetProperty("SignedOutForTests", All) == null)
			&& !bookSrc.Contains("BotManager", StringComparison.Ordinal) && !bookSrc.Contains(".Web", StringComparison.Ordinal)
			&& !bookSrc.Contains("GetAsync(new Uri(WebSession", StringComparison.Ordinal));

		// The page size is what Steam's answer says, not what was asked for: count=100 asked, a page of ten told.
		FieldInfo pageSizeF = pb.GetField("_pageSize", All)!;
		pageSizeF.SetValue(null, 100);   // as if a bigger page had been seen once
		market.Add((730, 0, 0, 0, $"Size Probe {tag} (Field-Tested)", 5, 5));
		market.Add((730, 0, 0, 0, $"Size Probe {tag} (Minimal Wear)", 6, 5));
		await NocatFarm.PriceBook.PriceAsync([(730, $"Size Probe {tag} (Field-Tested)"), (730, $"Size Probe {tag} (Minimal Wear)")], 100, CancellationToken.None);
		int told = (int) pageSizeF.GetValue(null)!;
		bool askedHundred = fake.Url.Contains("count=100", StringComparison.Ordinal);
		fakePage = 20;
		market.Add((730, 0, 0, 0, $"Size Probe Two {tag} (Field-Tested)", 5, 5));
		market.Add((730, 0, 0, 0, $"Size Probe Two {tag} (Minimal Wear)", 6, 5));
		await NocatFarm.PriceBook.PriceAsync([(730, $"Size Probe Two {tag} (Field-Tested)"), (730, $"Size Probe Two {tag} (Minimal Wear)")], 100, CancellationToken.None);
		Check("market: the page size is taken from Steam's answer - ten signed out, and whatever it says if that changes",
			(told == 10) && ((int) pageSizeF.GetValue(null)! == 20) && askedHundred, $"{told}, then {pageSizeF.GetValue(null)}");
		fakePage = 10;
		pageSizeF.SetValue(null, 10);

		// 6. Requests left and the time it takes.
		List<(uint App, string Hash)> nine = [.. Enumerable.Range(0, 9).Select(i => ((uint) 753, $"6100-Est{i}-{tag} (Trading Card)"))];
		Check("market: requests left - 9 normal cards of one game about 3, a lone item 1, nothing 0; ~2m at 8 seconds for 14",
			(NocatFarm.PriceBook.RequestsFor(nine) == 3) && (NocatFarm.PriceBook.RequestsFor([(730, $"Lone {tag}")]) == 1) && (NocatFarm.PriceBook.RequestsFor([]) == 0)
			&& (NocatFarm.Core.InventoryValue.Eta(14, 8) == "~2m") && (NocatFarm.Core.InventoryValue.EtaSeconds(14) == 112),
			$"{NocatFarm.PriceBook.RequestsFor(nine)}");

		// 7. Measured: a realistic inventory - Steam items from 110 games (about half of each game's normal cards, now and
		// then a foil, backgrounds, emoticons and a booster; 1 in 20 held with nobody selling one), 12 CS2 skins held in
		// 2-3 wears, 25 CS2 cases and stickers, 20 TF2 items and 16 more from 8 other games. Signed out: 10 a page.
		foreach (int size in (int[]) [10]) {
			fakePage = size;
			market.Clear();
			string run = tag + size;
			Random rng = new(7);
			List<(uint App, string Hash)> real = [];
			for (uint g = 0; g < 110; g++) {
				uint game = 900000 + ((uint) size * 1000) + g;
				int set = rng.Next(5, 16), bgs = rng.Next(3, 9), emotes = rng.Next(3, 9);
				for (int i = 0; i < set; i++) {
					market.Add((753, game, 2, 0, $"{game}-C{i}-{run} (Trading Card)", rng.Next(3, 20), rng.Next(300, 4000)));
					market.Add((753, game, 2, 1, $"{game}-C{i}-{run} (Foil Trading Card)", rng.Next(20, 300), rng.Next(1, 60)));
				}
				for (int i = 0; i < bgs; i++) market.Add((753, game, 3, 0, $"{game}-B{i}-{run} (Profile Background)", rng.Next(3, 40), rng.Next(5, 300)));
				for (int i = 0; i < emotes; i++) market.Add((753, game, 4, 0, $"{game}-:e{i}{run}:", rng.Next(3, 40), rng.Next(5, 300)));
				market.Add((753, game, 5, 0, $"{game}-Pack{run} Booster Pack", rng.Next(20, 120), rng.Next(5, 300)));

				foreach (int i in Enumerable.Range(0, set).OrderBy(_ => rng.Next()).Take((set + 1) / 2)) real.Add((753, $"{game}-C{i}-{run} (Trading Card)"));
				if (rng.Next(5) == 0) real.Add((753, $"{game}-C{rng.Next(set)}-{run} (Foil Trading Card)"));
				foreach (int i in Enumerable.Range(0, bgs).OrderBy(_ => rng.Next()).Take(rng.Next(0, 3))) real.Add((753, $"{game}-B{i}-{run} (Profile Background)"));
				foreach (int i in Enumerable.Range(0, emotes).OrderBy(_ => rng.Next()).Take(rng.Next(0, 3))) real.Add((753, $"{game}-:e{i}{run}:"));
				if (rng.Next(5) == 0) real.Add((753, $"{game}-Pack{run} Booster Pack"));
			}
			foreach (int i in Enumerable.Range(0, real.Count).Where(_ => rng.Next(20) == 0).ToList()) {
				market.RemoveAll(m => m.Hash == real[i].Hash);   // held, but nobody is selling one
			}
			string[] wearsOf = ["Factory New", "Minimal Wear", "Field-Tested", "Well-Worn", "Battle-Scarred"];
			for (int k = 0; k < 12; k++) {
				foreach (string w in wearsOf) {
					market.Add((730, 0, 0, 0, $"Skin{k}{run} | Paint ({w})", rng.Next(100, 90000), 50));
					market.Add((730, 0, 0, 0, $"StatTrak™ Skin{k}{run} | Paint ({w})", rng.Next(100, 90000), 5));
				}
				foreach (string w in wearsOf.OrderBy(_ => rng.Next()).Take(rng.Next(2, 4))) real.Add((730, $"Skin{k}{run} | Paint ({w})"));
			}
			for (int i = 0; i < 25; i++) { market.Add((730, 0, 0, 0, $"Box{i} {run}", rng.Next(3, 500), 900)); real.Add((730, $"Box{i} {run}")); }
			for (int i = 0; i < 20; i++) { market.Add((440, 0, 0, 0, $"Hat{i} {run}", rng.Next(3, 500), 90)); real.Add((440, $"Hat{i} {run}")); }
			for (uint a = 0; a < 8; a++) for (int i = 0; i < 2; i++) { market.Add((800000 + a, 0, 0, 0, $"Thing{i} {run}", rng.Next(3, 500), 9)); real.Add((800000 + a, $"Thing{i} {run}")); }
			real = [.. real.Distinct().OrderBy(_ => rng.Next())];

			pb.GetField("_pageSize", All)!.SetValue(null, size);
			int estimated = NocatFarm.PriceBook.RequestsFor(real);
			before = Asked();
			await NocatFarm.PriceBook.PriceAsync(real, 100000, CancellationToken.None);
			int after = Asked() - before;
			bool allPriced = real.All(w => !NocatFarm.PriceBook.NeedsRefresh(w.App, w.Hash));
			int gameCount = real.Select(static r => r.App == 753 ? "753/" + r.Hash[..r.Hash.IndexOf('-')] : r.App.ToString()).Distinct().Count();
			Console.WriteLine($"         measured, {size} a page: {real.Count} items from {gameCount} games - before {real.Count} requests ({real.Count * 8 / 60}m at 8s), now {after} ({Math.Ceiling(after * 8 / 60.0)}m), estimated beforehand {estimated}");
			Check($"market: a realistic {real.Count}-item inventory, {size} results a page - every item priced in a fraction of the requests",
				allPriced && (after * 2 < real.Count), $"{real.Count} -> {after}");
			Check("market: the estimate beforehand is within a fifth of the requests it took, at ten a page",
				Math.Abs(estimated - after) * 5 <= after, $"estimated {estimated}, took {after}");
		}
		pb.GetField("_pageSize", All)!.SetValue(null, 10);
	} finally {
		httpF.SetValue(null, httpBefore);
		httpBF.SetValue(null, httpBBefore);
		gapP.SetValue(null, null);
		coolUntilF.SetValue(null, DateTime.MinValue);
		coolMinutesF.SetValue(null, 0);
		NocatFarm.Config.Live.Global = liveBefore;
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
		}
	}
}

// ── order, checked against real games' full lists (names, descriptions and Steam's global figures - no account data) ──
// Found by feeding 26 games' whole lists through the pacer's own Sort, Eligible and NextPick, with the wobble, and
// checking every order: a lower rung worded a little differently, an ending ahead of its last boss on a tie, the wobble
// stepping onto the next beat of a story, PAYDAY 2's difficulty names, a DLC's ending waiting on a Death March run.
{
	const BindingFlags S = BindingFlags.Static | BindingFlags.NonPublic | BindingFlags.Public;
	Type pacer = typeof(NocatFarm.Modules.AchievementPacer);
	// API name | stat | bit | global % | hidden (h or empty) | name | description - as Steam lists them.
	NocatFarm.Core.Achievement R(string row, bool unlocked = false) {
		string[] p = row.Split('|');
		return new() {
			Name = p[0], StatId = uint.Parse(p[1], System.Globalization.CultureInfo.InvariantCulture), Bit = int.Parse(p[2], System.Globalization.CultureInfo.InvariantCulture),
			GlobalPercent = double.Parse(p[3], System.Globalization.CultureInfo.InvariantCulture), Hidden = p[4] == "h", Display = p[5], Description = p[6],
			Unlocked = unlocked, Protected = false
		};
	}
	bool Rule(string rule, NocatFarm.Core.Achievement a, params NocatFarm.Core.Achievement[] others) =>
		(bool) pacer.GetMethod(rule, S)!.Invoke(null, [a, new List<NocatFarm.Core.Achievement>([a, .. others])])!;
	string Pick(bool wobble, params NocatFarm.Core.Achievement[] eligible) =>
		((NocatFarm.Core.Achievement) pacer.GetMethod("NextPick", S)!.Invoke(null, [eligible.ToList(), (Func<NocatFarm.Core.Achievement, bool>) (static _ => false), wobble, null])!).Name;
	bool Ending(NocatFarm.Core.Achievement a) => (bool) pacer.GetMethod("IsEnding", S)!.Invoke(null, [a])!;

	// The pacer's loop: sort, what's eligible (every hour open, 1% floor), the pick - with the wobble on EVERY look.
	List<string> Earn(uint app, params NocatFarm.Core.Achievement[] game) {
		List<NocatFarm.Core.Achievement> all = [.. game];
		NocatFarm.Core.DlcAchievements.View view = new() {
			Map = new NocatFarm.Core.DlcAchievements.Map { App = app, Rule = NocatFarm.Core.DlcAchievements.RuleNow, BuiltAt = DateTime.UtcNow, Names = [.. all.Select(static a => a.Name.ToLowerInvariant())] },
			Trusted = true
		};
		List<string> order = [];
		for (int step = 0; step < all.Count; step++) {
			object sorted = pacer.GetMethod("Sort", S)!.Invoke(null, [new NocatFarm.Core.AchievementSet { AppId = app, All = all, CrcStats = 0 }, view, false, new HashSet<string>(StringComparer.Ordinal)])!;
			var eligible = (List<NocatFarm.Core.Achievement>) pacer.GetMethod("Eligible", S)!.Invoke(null, [sorted, all, all.Count(static a => a.Unlocked), 1, 1_000_000.0, null])!;
			if (eligible.Count == 0) {
				break;
			}
			string pick = Pick(true, [.. eligible]);
			order.Add(pick);
			int at = all.FindIndex(a => a.Name == pick);
			all[at] = all[at] with { Unlocked = true };
		}
		return order;
	}

	// Destiny 2 (1085660): "15" waited for nothing - its "or pieces of armor" made it another ladder - and went first, 12.4% to 12.2%.
	var d2Ten = R("ACH_15|1|14|12.2||Exotique|Collect 10 Forsaken Exotic weapons or armor.");
	var d2Fifteen = R("ACH_19|1|18|12.4|h|An Exotic Journey|Collect 15 Forsaken Exotic weapons or pieces of armor.");
	var d2RedWar = R("ACH_9|1|8|19.1||The Life Exotic|Collect 15 Red War exotic weapons or armor.");
	string d2Order = string.Join(",", Earn(1085660, d2Fifteen, d2Ten, d2RedWar));
	Check("real order: Destiny 2's 'Collect 15 Forsaken Exotic weapons or pieces of armor' waits for 'Collect 10 ... or armor'",
		Rule("TierBlocked", d2Fifteen, d2Ten) && !Rule("TierBlocked", d2Ten, d2Fifteen) && !Rule("TierBlocked", d2RedWar, d2Ten) && (d2Order == "ACH_9,ACH_15,ACH_19"), d2Order);
	Check("real order: a count with more asked isn't the same ladder - Metro's 'Kill 30 human enemies with headshots', Left 4 Dead 2's Versus Survival",
		!Rule("TierBlocked", R("2033_warior|2|12|43.3||Warrior|Kill 100 Human Enemies."), R("2033_sniper_33|2|2|42.0||Sniper|Kill 30 human enemies with headshots."))
		&& !Rule("TierBlocked", R("ACH_SURVIVAL_X_MINUTES|533|3|1.2||SUPREME SURVIVALIST|Survive for 30 minutes on any official survival map."),
			R("ACH_SURVIVAL_VERSUS_X_MINUTES|517|28|0.8||THE BIG TEN|Survive for 10 minutes on any official map in Versus Survival.")));
	var grubsHalf = R("GRUBFRIEND|3|22|38.4||Grubfriend|Rescue half of the imprisoned grubs");
	var grubsAll = R("METAMORPHOSIS|3|23|26.0||Metamorphosis|Rescue all of the imprisoned grubs");
	Check("real order: Hollow Knight's 'Rescue all of the imprisoned grubs' waits for 'Rescue half of' them",
		Rule("TierBlocked", grubsAll, grubsHalf) && !Rule("TierBlocked", grubsHalf, grubsAll));

	var fourMaps = R("PORTAL_BEAT_4ADVANCEDMAPS|0|7|12.0||Fruitcake|Beat four Portal advanced maps.");
	var sixMaps = R("PORTAL_BEAT_6ADVANCEDMAPS|0|8|9.3||Vanilla Crazy Cake|Beat all six Portal advanced maps.");
	Check("real order: Portal's 'Beat all six Portal advanced maps' is rung six, after 'Beat four'",
		Rule("TierBlocked", sixMaps, fourMaps) && !Rule("TierBlocked", fourMaps, sixMaps));

	// Endings by name, and an ending never ahead of the last boss on a tie (Steam gives a tenth of a percent).
	var isshin = R("ACH30|1|30|19.2|h|Isshin Ashina|Defeated \"Isshin Ashina\"");
	var shura = R("ACH12|1|12|19.2|h|Shura|Attained the \"Shura\" ending");
	Check("real order: endings by name are endings - Sekiro's 'Attained the \"Shura\" ending', NieR's 'Achieve ending A.', Elden Ring's - not 'All endings achieved.'",
		Ending(shura) && Ending(R("ACH11|1|11|19.0|h|Dragon's Homecoming|Attained the \"Return\" ending")) && Ending(R("ACH_CLEAR_A|1|9|36.4|h|One Battle Ends|Achieve ending A."))
		&& Ending(R("ACH01|1|1|23.9|h|Elden Lord|Achieved the \"Elden Lord\" ending")) && !Ending(R("ACH_BAD_END|2|25|5.3|h|Transcendent Being|All endings achieved.")) && !Ending(isshin));
	var spider = R("ach_3|1|2|32.2|h|Who's Next?|Defeat the Spider Mastermind");
	var kneeDeep = R("ach_6|1|5|32.3||Knee-Deep in the Dead|Complete the campaign on 'I'm Too Young to Die', 'Hurt Me Plenty', 'Ultra Violence', or 'Nightmare'.");
	Check("real order: the last boss before the ending it leads to, on a tie or a tenth of a percent - Sekiro's Isshin Ashina (19.2%) before Shura (19.2%), DOOM's Spider Mastermind (32.2%) before the campaign (32.3%)",
		(Pick(false, shura, isshin) == "ACH30") && (Pick(false, isshin, shura) == "ACH30") && (Pick(true, shura, isshin) == "ACH30")
		&& (Pick(false, kneeDeep, spider) == "ach_3") && (Pick(true, kneeDeep, spider) == "ach_3"));
	Check("real order: ...while an ending clearly more common still goes first (NieR's ending A, 36.4%, before a 34.8% one)",
		Pick(false, R("ACH_CLEAR_HACKING_9S|1|30|34.8|h|Fighting's Not My Thing|Play your first hacking game."), R("ACH_CLEAR_A|1|9|36.4|h|One Battle Ends|Achieve ending A.")) == "ACH_CLEAR_A");

	// The wobble: never onto the next beat of a story - hidden, or listed after the first.
	var warHero = R("NEW_ACHIEVEMENT_22_0|1|24|11.1||War Hero|Capture Fort Sungard or Fort Greenwall");
	var heroOfSkyrim = R("NEW_ACHIEVEMENT_23_0|1|25|11.0||Hero of Skyrim|Capture Solitude or Windhelm");
	var godfrey = R("ACH29|2|14|50.0|h|Godfrey, First Elden Lord|Defeated Godfrey, First Elden Lord");
	var morgott = R("ACH06|1|6|49.6|h|Shardbearer Morgott|Defeated Shardbearer Morgott");
	var heKillsYou = R("ACH.WHEATLEY_TRIES_TO|0|13|34.4||The Part Where He Kills You|This is that part");
	var lunacy = R("ACH.SHOOT_THE_MOON|0|14|34.1||Lunacy|That just happened");
	Check("real order: the wobble never steps onto the next beat - Skyrim's capital before its fort, Portal 2's last chapter, Elden Ring's (hidden) Morgott before Godfrey",
		(Pick(true, warHero, heroOfSkyrim) == "NEW_ACHIEVEMENT_22_0") && (Pick(true, heKillsYou, lunacy) == "ACH.WHEATLEY_TRIES_TO") && (Pick(true, godfrey, morgott) == "ACH29"));
	Check("real order: ...but still steps to one the game lists first (Portal 2's Tater Tote, 41%, after Vertically Unchallenged, 42.9%)",
		Pick(true, R("ACH.BLUE_GEL|0|8|42.9||Vertically Unchallenged|Master the Repulsion Gel"), R("ACH.ADDICTED_TO_SPUDS|0|7|41.0||Tater Tote|Carry science forward")) == "ACH.ADDICTED_TO_SPUDS");
	Check("real order: a tie goes in the game's own order, whichever way round it comes",
		(Pick(false, heroOfSkyrim with { GlobalPercent = 11.1 }, warHero) == "NEW_ACHIEVEMENT_22_0") && (Pick(false, warHero, heroOfSkyrim with { GlobalPercent = 11.1 }) == "NEW_ACHIEVEMENT_22_0"));

	// PAYDAY 2 (218620): its difficulty names, and the job's name ("Gold") isn't the difficulty.
	string[] goldRows = [
		"death_17|415|1|17.3||Striking Gold|Complete the Bank Heist: Gold job on the Death Wish difficulty or above.",
		"pick_18|1881|9|17.2||Gold Rush|Complete the Bank Heist: Gold job on the Mayhem difficulty or above.",
		"trk_bg_3|2240|29|17.5||Came for the Money, Stayed for the Gold|Complete the Bank Heist: Gold job on the OVERKILL difficulty or above.",
		"trk_bg_2|2240|28|19.4||Goldmember|Complete the Bank Heist: Gold job on the Very Hard difficulty or above.",
		"trk_bg_1|2240|27|22.4||We are Golden|Complete the Bank Heist: Gold job on the Hard difficulty or above.",
		"trk_bg_0|2240|26|26.8||Taking the Bars|Complete the Bank Heist: Gold job on the Normal difficulty or above."];
	NocatFarm.Core.Achievement[] gold = [.. goldRows.Select(r => R(r))];
	string goldOrder = string.Join(",", Earn(218620, gold));
	Check("real order: PAYDAY 2's Death Wish (17.3%) waits for Mayhem (17.2%), Very Hard for Hard - read off the difficulty, not the Gold job",
		Rule("DifficultyBlocked", gold[0], gold[1]) && !Rule("DifficultyBlocked", gold[1], gold[0]) && Rule("DifficultyBlocked", gold[3], gold[4]) && Rule("DifficultyBlocked", gold[4], gold[5])
		&& (goldOrder == "trk_bg_0,trk_bg_1,trk_bg_2,trk_bg_3,pick_18,death_17"), goldOrder);

	// PAYDAY 2's ranks of Infamy: "the eleventh" up to "the twenty-fifth" are rungs too - many of them tied at 6.2%.
	NocatFarm.Core.Achievement[] infamy = [.. new[] {
		"ignominy_10|949|24|7.0||Becoming Mean|Reach the tenth rank of Infamy.",
		"ignominy_11|949|25|6.8||Becoming Dangerous|Reach the eleventh rank of Infamy.",
		"ignominy_20|990|2|6.3||Becoming Sly|Reach the twentieth rank of Infamy.",
		"ignominy_21|990|3|6.2||Becoming Crafty|Reach the twenty-first rank of Infamy.",
		"ignominy_22|990|4|6.2||Becoming Shameless|Reach the twenty-second rank of Infamy.",
		"ignominy_23|990|5|6.2||Becoming Diabolical|Reach the twenty-third rank of Infamy." }.Select(r => R(r))];
	// Listed backwards, so only the rungs can put them right.
	string infamyOrder = string.Join(",", Earn(218620, [.. infamy.Select((a, i) => a with { StatId = 1, Bit = 10 - i })]));
	Check("real order: PAYDAY 2's 'twenty-third rank of Infamy' waits for the twenty-second, the eleventh for the tenth - a tie or not",
		Rule("TierBlocked", infamy[1], infamy[0]) && Rule("TierBlocked", infamy[3], infamy[2]) && Rule("TierBlocked", infamy[5], infamy[4]) && !Rule("TierBlocked", infamy[4], infamy[5])
		&& (infamyOrder == "ignominy_10,ignominy_11,ignominy_20,ignominy_21,ignominy_22,ignominy_23"), infamyOrder);

	// Terraria (105600): the Moon Lord (24.7%) is more common than the four towers before him (23.2%) - the game lists the
	// towers right before him, and both are about the moon. Elden Ring lists Godskin Duo (43.2%) before Fire Giant (45.0%),
	// who comes first: about different things, so the figures decide there. And a blood moon (51.6%), listed right after the
	// Moon Lord, is nowhere near as rare - it isn't held.
	var cultist = R("OBSESSIVE_DEVOTION|4|3|26.6||Obsessive Devotion|Defeat the Ancient Cultist, fanatical leader of the dungeon coven.");
	var towers = R("STAR_DESTROYER|4|4|23.2||Star Destroyer|Defeat the four celestial towers of the moon.");
	var moonLord = R("CHAMPION_OF_TERRARIA|4|5|24.7||Champion of Terraria|Defeat the Moon Lord.");
	var bloodMoon = R("BLOODBATH|4|6|51.6||Bloodbath|Survive a blood moon, a nocturnal event where the rivers run red and monsters swarm aplenty.");
	string terrariaOrder = string.Join(",", Earn(105600, moonLord, bloodMoon, towers, cultist));
	string eldenOrder = string.Join(",", Earn(1245620, R("ACH20|1|21|43.2|h|Godskin Duo|Defeated Godskin Duo"), R("ACH21|2|6|45.0|h|Fire Giant|Defeated Fire Giant")));
	Check("real order: Terraria's Moon Lord after the four celestial towers listed right before him - the game's list decides two about as common and about the same thing",
		terrariaOrder == "BLOODBATH,OBSESSIVE_DEVOTION,STAR_DESTROYER,CHAMPION_OF_TERRARIA", terrariaOrder);
	Check("real order: ...but not two about different things - Elden Ring's Fire Giant (45.0%) still before Godskin Duo (43.2%), listed first",
		eldenOrder == "ACH21,ACH20", eldenOrder);

	// The Witcher 3 (292030): one of the game's endings is enough for an add-on's - not every one of them.
	var passed = R("PASSED_THE_TRIAL|1|8|22.0||Passed the Trial|Finish the game on any difficulty.");
	var gauntlet = R("RAN_THE_GAUNTLET|1|9|6.5||Ran the Gauntlet|Finish the game on the \"Blood and Broken Bones!\" or \"Death March!\" difficulty levels.");
	var pacta = R("EP1_5|2|25|16.4|h|Pacta Sunt Servanda|Finish the \"Hearts of Stone\" expansion.");
	Check("real order: 'Finish the Hearts of Stone expansion' waits for 'Finish the game', not for it on Death March as well",
		Rule("VariantBlocked", pacta, passed, gauntlet) && !Rule("VariantBlocked", pacta, passed with { Unlocked = true }, gauntlet));

	Check("real order: the hidden flag is read from the game's schema",
		File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Core", "Achievements.cs")).Contains("Hidden = bitNode[\"display\"][\"hidden\"].AsInteger() != 0", StringComparison.Ordinal));

	// "Ending" the verb, a collection of endings or the tutorial's isn't an ending: taken as one, an early unlock of it
	// was "one of the game's own endings" and let an add-on's ending go before "Finish the game".
	var turn = R("COMBO|1|3|60.0||Untouchable|Reach wave 10 without ending your turn.", unlocked: true);
	var round = R("SPEEDY|1|4|55.0||Speedy|Earn 100 points before ending the round.", unlocked: true);
	var tutorial = R("TUTORIAL|1|1|80.0||First Steps|See the tutorial ending.", unlocked: true);
	var every = R("ALL_ENDS|1|20|4.0||Completionist|See every ending.");
	Check("real order: 'without ending your turn', 'before ending the round', 'every ending' and the tutorial's ending aren't endings",
		!Ending(turn) && !Ending(round) && !Ending(tutorial) && !Ending(every)
		&& Ending(R("GOOD|1|7|30.0||Good|Get the good ending.")) && Ending(R("TRUE|1|8|9.0||Truth|Unlock the true ending in New Game+.")));
	Check("real order: ...so earning one of them early doesn't let 'Finish the Hearts of Stone expansion' go before 'Finish the game'",
		Rule("VariantBlocked", pacta, passed, turn) && Rule("VariantBlocked", pacta, passed, round) && Rule("VariantBlocked", pacta, passed, tutorial));
}

// ── the market's pause: an answer resets it, a request never sent doesn't lengthen it, a 429 holds everything ──────────
{
	const BindingFlags All = BindingFlags.NonPublic | BindingFlags.Public | BindingFlags.Static | BindingFlags.Instance;
	Type pb = typeof(NocatFarm.PriceBook);
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	NocatFarm.Config.GlobalConfig liveBefore = NocatFarm.Config.Live.Global;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-mktpause-" + Guid.NewGuid().ToString("N"));
	PropertyInfo gapP = pb.GetProperty("GapForTests", All)!;
	FieldInfo coolUntilF = pb.GetField("_coolUntil", All)!, coolMinutesF = pb.GetField("_coolSeconds", All)!, saidF = pb.GetField("_saidRefused", All)!;
	FieldInfo lastCallF = pb.GetField("_lastCall", All)!;
	FieldInfo httpF = pb.GetField("Http", All)!, httpBF = pb.GetField("HttpB", All)!;
	object httpBefore = httpF.GetValue(null)!, httpBBefore = httpBF.GetValue(null)!;
	string host = NocatFarm.Core.WebSession.Community.Host;
	string Src(string rel) => File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", rel)).Replace("\r\n", "\n");
	void OpenHost() {
		((System.Collections.IDictionary) typeof(NocatFarm.Core.Limiters).GetField("WebBackoff", All)!.GetValue(null)!).Remove(host);
		NocatFarm.Core.Limiters.Remember(host, DateTime.MinValue, 0);
	}

	try {
		NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);
		NocatFarm.Config.Live.Global = new NocatFarm.Config.GlobalConfig { MarketGapSeconds = 8, WebRequestGapMs = 0 };
		gapP.SetValue(null, 0d);
		pb.GetField("_coolLoaded", All)!.SetValue(null, true);
		coolUntilF.SetValue(null, DateTime.MinValue);
		coolMinutesF.SetValue(null, 3600);   // after a run of 429s
		pb.GetField("_refusedInRow", All)!.SetValue(null, 0);
		pb.GetField("_searchOffUntil", All)!.SetValue(null, DateTime.MinValue);
		pb.GetField("_searchDoubt", All)!.SetValue(null, -1);
		saidF.SetValue(null, false);
		OpenHost();

		// The price book's own signed-out client, answered here - nothing reaches Steam.
		FakePing fake = new((_, _) => Task.FromResult(new HttpResponseMessage(System.Net.HttpStatusCode.OK) {
			Content = new StringContent("""{"success":true,"pagesize":10,"total_count":0,"results":[]}""")
		}));
		httpF.SetValue(null, new HttpClient(fake));
		httpBF.SetValue(null, new HttpClient(fake));
		const string Path1 = "/market/search/render/?norender=1&appid=753&start=0&count=100&currency=1";

		(string? answered, bool answeredSent) = await NocatFarm.PriceBook.MarketGetAsync(Path1, CancellationToken.None);
		Check("market: an answer starts the pause ladder again from its shortest",
			(answered != null) && answeredSent && (fake.Calls == 1) && fake.Url.StartsWith("https://steamcommunity.com/market/search/", StringComparison.Ordinal) && ((int) coolMinutesF.GetValue(null)! == 0),
			$"{fake.Calls} call(s), pause {coolMinutesF.GetValue(null)}m");

		// An account's own 429 shuts the host while the market request waits out its gap: it isn't sent, and the market's
		// pause is the host's wait - not one more doubling for a refusal that never happened.
		coolMinutesF.SetValue(null, 900);
		gapP.SetValue(null, 0.5d);
		lastCallF.SetValue(null, DateTime.UtcNow);
		Task<(string? Json, bool Asked)> queued = NocatFarm.PriceBook.MarketGetAsync(Path1, CancellationToken.None);
		await Task.Delay(100);
		NocatFarm.Core.Limiters.NoteRateLimited(host);
		(string? unsent, bool unsentAsked) = await queued;
		Check("market: the host shut by an account's 429 during the gap - nothing sent, the pause waits it out without a step up",
			(unsent == null) && !unsentAsked && (fake.Calls == 1) && ((int) coolMinutesF.GetValue(null)! == 900) && (NocatFarm.PriceBook.PausedUntil != null),
			$"{fake.Calls} call(s), pause {coolMinutesF.GetValue(null)}m");

		// A 429 on a signed-out request: the pause starts, and every other market request waits it out - the planner's too.
		OpenHost();
		gapP.SetValue(null, 0d);
		coolUntilF.SetValue(null, DateTime.MinValue);
		coolMinutesF.SetValue(null, 0);
		FakePing refusing = new((_, _) => Task.FromResult(new HttpResponseMessage(System.Net.HttpStatusCode.TooManyRequests)));
		httpF.SetValue(null, new HttpClient(refusing));
		httpBF.SetValue(null, new HttpClient(refusing));
		// The planner's search refused: no second search (the next request is a single lookup, to tell searches refused
		// from the market's limit); that one refused too - the limit: the pause, and every market request waits it out.
		(string? refused, bool refusedSent) = await NocatFarm.PriceBook.MarketGetAsync(Path1, CancellationToken.None);
		(string? held, bool heldSent) = await NocatFarm.PriceBook.MarketGetAsync(Path1, CancellationToken.None);
		bool pricedNothing = !await NocatFarm.PriceBook.PriceAsync([(730, "Pause Probe Case")], 10, CancellationToken.None);
		(string? afterPause, bool afterPauseSent) = await NocatFarm.PriceBook.MarketGetAsync(Path1, CancellationToken.None);
		Check("market: a refused search then a refused single lookup pause every market request - searches, lookups and the planner's alike",
			(refused == null) && refusedSent && (held == null) && !heldSent && pricedNothing && (afterPause == null) && !afterPauseSent && (refusing.Calls == 2)
			&& ((int) coolMinutesF.GetValue(null)! == 90) && (NocatFarm.PriceBook.PausedUntil is { } pausedTo) && (pausedTo > DateTime.UtcNow.AddSeconds(85)),
			$"{refusing.Calls} call(s), pause {coolMinutesF.GetValue(null)}m");

		Check("inventory: the fleet's \"pricing N items\" counts each item once, from the accounts being valued - the same list its requests come from",
			Src(Path.Combine("Web", "WebHost.cs")).Contains("InventoryPending = fleetWaiting.Count,", StringComparison.Ordinal)
			&& Src(Path.Combine("Web", "WebHost.cs")).Contains("bots.Where(static b => b.Cfg.ShowInventoryValue).SelectMany(static b => b.Inventory.Waiting()).Distinct()];", StringComparison.Ordinal)
			&& !Src(Path.Combine("Web", "WebHost.cs")).Contains("bots.Sum(static b => b.Inventory.Pending)", StringComparison.Ordinal)
			&& Src("Commands.cs").Contains("({waiting.Count} still being priced{Left(PriceBook.RequestsFor(waiting))})", StringComparison.Ordinal));

		Check("market: the remembered pause is read under a lock and marked read only once it is",
			Src(Path.Combine("Core", "PriceBook.cs")).Contains("lock (CoolGate) {\n\t\t\tif (!_coolLoaded) {", StringComparison.Ordinal)
			&& Src(Path.Combine("Core", "PriceBook.cs")).Contains("Volatile.Write(ref _coolLoaded, true);", StringComparison.Ordinal));
	} finally {
		OpenHost();
		httpF.SetValue(null, httpBefore);
		httpBF.SetValue(null, httpBBefore);
		gapP.SetValue(null, null);
		coolUntilF.SetValue(null, DateTime.MinValue);
		coolMinutesF.SetValue(null, 0);
		saidF.SetValue(null, false);
		NocatFarm.Core.Limiters.Remember("market", DateTime.MinValue, 0);
		NocatFarm.Config.Live.Global = liveBefore;
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
		}
	}
}

// ── market prices ask as "nocat.farm/<version>": the market answers 429 to the browser string every time ─────────
{
	var market = NocatFarm.Core.Browser.Market(TimeSpan.FromSeconds(5));
	string sent = string.Join(" ", market.DefaultRequestHeaders.UserAgent.Select(static p => p.ToString()));
	Check("market: price lookups go under the app's own name, never the browser string", sent == NocatFarm.Core.Browser.MarketAgent
		&& NocatFarm.Core.Browser.MarketAgent.StartsWith("nocat.farm/", StringComparison.Ordinal) && !sent.Contains("Chrome", StringComparison.Ordinal), sent);
	string book = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Core", "PriceBook.cs"));
	Check("market: price lookups send an Accept header - without one the market answers 429 every time", market.DefaultRequestHeaders.Accept.Count > 0,
		string.Join(", ", market.DefaultRequestHeaders.Accept));
	Check("market: the price book's client is the market one", book.Contains("Http = Browser.Market(", StringComparison.Ordinal) && !book.Contains("Browser.Anonymous(", StringComparison.Ordinal));
}

// ── the market, asked two ways: a refusal one way turns the next request the other way; both refused is the pause ────
{
	const BindingFlags All = BindingFlags.NonPublic | BindingFlags.Public | BindingFlags.Static | BindingFlags.Instance;
	Type pb = typeof(NocatFarm.PriceBook);
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	NocatFarm.Config.GlobalConfig liveBefore = NocatFarm.Config.Live.Global;
	NocatFarm.Core.BotManager? hostBefore = NocatFarm.Core.BotManager.Instance;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-market-ways-" + Guid.NewGuid().ToString("N"));
	FieldInfo F(string n) => pb.GetField(n, All)!;
	T Field<T>(string n) => (T) F(n).GetValue(null)!;
	PropertyInfo gapP = pb.GetProperty("GapForTests", All)!;
	object httpBefore = F("Http").GetValue(null)!, httpBBefore = F("HttpB").GetValue(null)!;
	string host = NocatFarm.Core.WebSession.Community.Host;
	string tag = Guid.NewGuid().ToString("N")[..6];
	string Src(string rel) => File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", rel)).Replace("\r\n", "\n");

	void OpenHost() {
		((System.Collections.IDictionary) typeof(NocatFarm.Core.Limiters).GetField("WebBackoff", All)!.GetValue(null)!).Remove(host);
		NocatFarm.Core.Limiters.Remember(host, DateTime.MinValue, 0);
	}

	// A market that has answered before, the app's own way, nothing pausing.
	void Fresh() {
		OpenHost();
		F("_coolLoaded").SetValue(null, true);
		F("_coolUntil").SetValue(null, DateTime.MinValue);
		F("_coolSeconds").SetValue(null, 0);
		F("_saidRefused").SetValue(null, false);
		F("_way").SetValue(null, 0);
		F("_goodWay").SetValue(null, 0);
		F("_refusedInRow").SetValue(null, 0);
		F("_checkFirst").SetValue(null, false);
		F("_searchOffUntil").SetValue(null, DateTime.MinValue);
		F("_searchOffMinutes").SetValue(null, 0);
		F("_searchDoubt").SetValue(null, -1);
		Quiet();
		((System.Collections.IDictionary) F("Suspects").GetValue(null)!).Clear();
		F("_marketDown").SetValue(null, false);
		F("_lastCall").SetValue(null, DateTime.MinValue);
		NocatFarm.Core.Limiters.Remember("market", DateTime.MinValue, 0);
		NocatFarm.Core.Limiters.Remember("market-way", DateTime.UtcNow, 0);
	}

	// When each way last got an answer - none since the start, or a few minutes ago.
	DateTime[] AnsweredAt() => (DateTime[]) F("AnsweredAt").GetValue(null)!;
	void Quiet() => Array.Fill(AnsweredAt(), DateTime.MinValue);
	void AnsweredLately(int way) => AnsweredAt()[way] = DateTime.UtcNow.AddMinutes(-3);

	// The pretend market. Each way answers as `answer` says; every request sent is noted - which way, what, when, and the
	// headers it went with. Nothing reaches Steam.
	List<(char Way, string Path, string Query, DateTime At, string Accept, string Agent)> sent = [];
	List<string> stock = [];   // what a search page lists, each at 12 cents
	HttpResponseMessage Status(int code) => new((System.Net.HttpStatusCode) code);
	HttpResponseMessage Json(string json) => new(System.Net.HttpStatusCode.OK) { Content = new StringContent(json) };
	HttpResponseMessage Price(HttpRequestMessage r) => r.RequestUri!.AbsolutePath.StartsWith("/market/priceoverview", StringComparison.Ordinal)
		? Json("""{"success":true,"lowest_price":"$1.23","median_price":"$1.20"}""")
		: Json(System.Text.Json.JsonSerializer.Serialize(new {
			success = true, start = 0, pagesize = 10, total_count = stock.Count,
			results = stock.Select(static h => new { hash_name = h, sell_listings = 5, sell_price = 12 })
		}));
	bool IsSearch(HttpRequestMessage r) => r.RequestUri!.AbsolutePath.StartsWith("/market/search/", StringComparison.Ordinal);
	Func<char, HttpRequestMessage, HttpResponseMessage> answer = (_, r) => Price(r);
	FakePing Way(char w) => new((request, _) => {
		lock (sent) {
			sent.Add((w, request.RequestUri!.AbsolutePath, Uri.UnescapeDataString(request.RequestUri.Query), DateTime.UtcNow, request.Headers.Accept.ToString(), request.Headers.UserAgent.ToString()));
		}
		return Task.FromResult(answer(w, request));
	});
	// Each pretend client goes out with the real one's headers, so what is checked is what each way really sends.
	HttpClient Dressed(HttpMessageHandler handler, HttpClient real) {
		HttpClient c = new(handler);
		foreach (KeyValuePair<string, IEnumerable<string>> h in real.DefaultRequestHeaders) {
			c.DefaultRequestHeaders.TryAddWithoutValidation(h.Key, h.Value);
		}
		return c;
	}
	string Ways() {
		lock (sent) {
			return string.Concat(sent.Select(static s => s.Way));
		}
	}
	Task<bool> PriceAll(params (uint, string)[] wanted) => NocatFarm.PriceBook.PriceAsync([.. wanted], 100, CancellationToken.None);
	decimal? Known(uint app, string hash) => NocatFarm.PriceBook.Known(app, hash);

	try {
		NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);
		NocatFarm.Config.Live.Global = new NocatFarm.Config.GlobalConfig { MarketGapSeconds = 8, WebRequestGapMs = 0 };
		gapP.SetValue(null, 0d);
		F("Http").SetValue(null, Dressed(Way('A'), NocatFarm.Core.Browser.Market(TimeSpan.FromSeconds(5))));
		F("HttpB").SetValue(null, Dressed(Way('B'), NocatFarm.Core.Browser.MarketAsBrowser(TimeSpan.FromSeconds(5))));

		// 1. A 429 the app's own way: the next request goes as the browser, gets its answer, and that way is kept.
		Fresh();
		answer = (w, r) => w == 'A' ? Status(429) : Price(r);
		bool one = await PriceAll((730, $"Way One {tag}"));
		Check("market ways: a 429 one way - the next request goes the other way and is answered, no pause at all",
			one && (Ways() == "AB") && (Known(730, $"Way One {tag}") == 1.23m) && (NocatFarm.PriceBook.PausedUntil == null) && (Field<int>("_coolSeconds") == 0), Ways());
		Check("market ways: the way that answered is remembered - in the state file too, like the pause",
			(Field<int>("_goodWay") == 1) && (NocatFarm.Core.Limiters.Remembered("market-way").Minutes == 1));

		lock (sent) sent.Clear();
		await PriceAll((730, $"Way Two {tag}"));
		F("_coolLoaded").SetValue(null, false);   // as after a restart
		F("_way").SetValue(null, 0);
		F("_goodWay").SetValue(null, 0);
		pb.GetMethod("LoadCool", All)!.Invoke(null, []);
		Check("market ways: the next request goes the way that last got an answer first - and still does after a restart",
			(Ways() == "B") && (Field<int>("_way") == 1) && (Field<int>("_goodWay") == 1), Ways());

		// 403, and a web page where the prices should be: refusals too - each from a way that hasn't answered lately.
		lock (sent) sent.Clear();
		Quiet();
		answer = (w, r) => w == 'B' ? Status(403) : Price(r);
		await PriceAll((730, $"Way Three {tag}"));
		string forbidden = Ways();
		lock (sent) sent.Clear();
		Quiet();
		answer = (w, r) => w == 'A' ? Json("<!DOCTYPE html>\n<html><body>Access Denied</body></html>") : Price(r);
		await PriceAll((730, $"Way Four {tag}"));
		Check("market ways: a 403, or a block page instead of prices, from a way not answering lately turns the next request the other way - and the page is no price",
			(forbidden == "BA") && (Ways() == "AB") && (Known(730, $"Way Three {tag}") == 1.23m) && (Known(730, $"Way Four {tag}") == 1.23m) && (Field<int>("_goodWay") == 1),
			$"{forbidden} / {Ways()}");

		// 2. Both refused in a row - neither had answered lately: the market refusing, 90 seconds and a little, nothing asked meanwhile.
		Fresh();
		lock (sent) sent.Clear();
		answer = (_, _) => Status(429);
		bool went = await PriceAll((730, $"Ladder {tag}"));
		DateTime? firstPause = NocatFarm.PriceBook.PausedUntil;
		bool held = !await PriceAll((730, $"Ladder {tag}"));
		Check("market ways: refused both ways in a row - a 90-second pause (a little more at random, never less), nothing asked meanwhile",
			!went && held && (Ways() == "AB") && (Field<int>("_coolSeconds") == 90) && (firstPause is { } fp) && (fp >= DateTime.UtcNow.AddSeconds(88)) && (fp <= DateTime.UtcNow.AddSeconds(113)),
			$"{Ways()} / {firstPause:HH:mm:ss}");
		Check("market ways: after both were refused, the request at the pause's end goes the other way from the last refused", (Field<int>("_way") == 0) && (Field<int>("_refusedInRow") == 0));

		List<int> steps = [];
		lock (sent) sent.Clear();
		for (int i = 0; i < 8; i++) {
			F("_coolUntil").SetValue(null, DateTime.MinValue);   // the pause is over - and the market still refuses
			await PriceAll((730, $"Ladder {tag}"));
			steps.Add(Field<int>("_coolSeconds"));
		}
		Check("market ways: still refused - 5, 15, 30, 60, 120, 240 minutes, then twice a day, said once",
			steps.SequenceEqual([300, 900, 1800, 3600, 7200, 14400, 43200, 43200]) && Field<bool>("_saidRefused"), string.Join(",", steps));
		Check("market ways: one request at the end of each pause, the ways taking turns", Ways() == "ABABABAB", Ways());

		F("_coolUntil").SetValue(null, DateTime.MinValue);
		answer = (_, r) => Price(r);
		bool back = await PriceAll((730, $"Ladder {tag}"));
		Check("market ways: an answer either way starts the ladder again from 90 seconds",
			back && (Field<int>("_coolSeconds") == 0) && !Field<bool>("_saidRefused"));

		// 3. The first request after a pause - or at the start - is one real wanted item on its own; then searches again.
		Fresh();
		F("_checkFirst").SetValue(null, true);
		stock.Clear();
		stock.AddRange([$"7700-First{tag} (Trading Card)", $"7700-Second{tag} (Trading Card)", $"7700-Third{tag} (Trading Card)"]);
		lock (sent) sent.Clear();
		bool firstDone = await PriceAll([.. stock.Select(static h => ((uint) 753, h))]);
		Check("market ways: the first request after a pause is the first wanted item alone (priceoverview) - a real price, never a probe; then a search page",
			firstDone && (sent.Count == 2) && (sent[0].Path == "/market/priceoverview/") && sent[0].Query.Contains($"7700-First{tag}", StringComparison.Ordinal)
			&& sent[1].Path.StartsWith("/market/search/", StringComparison.Ordinal) && stock.All(h => Known(753, h) is not null),
			string.Join(" ", sent.Select(static s => s.Path)));

		// 4. A search refused, then the single lookup after it answered the same way: it's the searches - priced one at a
		// time, no pause; searches later.
		Fresh();
		AnsweredLately(0);
		answer = (_, r) => IsSearch(r) ? Status(429) : Price(r);
		List<(uint, string)> cards = [.. Enumerable.Range(0, 4).Select(i => ((uint) 753, $"7800-Card{i}{tag} (Trading Card)"))];
		lock (sent) sent.Clear();
		bool fellBack = await PriceAll([.. cards]);
		int searches = sent.Count(static s => s.Path.StartsWith("/market/search/", StringComparison.Ordinal)), singles = sent.Count(static s => s.Path == "/market/priceoverview/");
		Check("market ways: a search 429 followed by an answered single lookup - searches off, no pause; every item priced by itself",
			fellBack && (searches == 1) && (singles == 4) && (sent[1].Path == "/market/priceoverview/") && (sent[1].Way == sent[0].Way) && NocatFarm.PriceBook.SearchOff
			&& (NocatFarm.PriceBook.PausedUntil == null) && cards.All(c => Known(c.Item1, c.Item2) == 1.23m) && (Field<int>("_searchOffMinutes") == 30),
			$"{searches} searches, {singles} single, {Ways()}");
		List<(uint App, string Hash)> nineCards = [.. Enumerable.Range(0, 9).Select(i => ((uint) 753, $"7810-Est{i}{tag} (Trading Card)"))];
		int sentBefore = sent.Count;
		(string? plannerSearch, bool plannerSent) = await NocatFarm.PriceBook.MarketGetAsync("/market/search/render/?norender=1&appid=753&start=0&count=100&currency=1", CancellationToken.None);
		Check("market ways: meanwhile a request is one item, the estimate counts one each, and the planner's searches aren't sent",
			(NocatFarm.PriceBook.NextAsk(nineCards).Search == null) && (NocatFarm.PriceBook.RequestsFor(nineCards) == 9) && (plannerSearch == null) && !plannerSent && (sent.Count == sentBefore));

		F("_searchOffUntil").SetValue(null, DateTime.UtcNow.AddSeconds(-1));   // the time is up
		answer = (_, r) => Price(r);
		stock.Clear();
		stock.AddRange([$"7900-A{tag} (Trading Card)", $"7900-B{tag} (Trading Card)", $"7900-C{tag} (Trading Card)"]);
		lock (sent) sent.Clear();
		await PriceAll([.. stock.Select(static h => ((uint) 753, h))]);
		Check("market ways: searches are tried again once the time is up - answered, they're back in use",
			(sent.Count == 1) && sent[0].Path.StartsWith("/market/search/", StringComparison.Ordinal) && !NocatFarm.PriceBook.SearchOff && (Field<int>("_searchOffMinutes") == 0),
			string.Join(" ", sent.Select(static s => s.Path)));

		// Refused again and again: left alone longer each time.
		answer = (_, r) => IsSearch(r) ? Status(429) : Price(r);
		List<int> offFor = [];
		for (int i = 0; i < 2; i++) {
			F("_searchOffUntil").SetValue(null, DateTime.MinValue);
			await PriceAll([.. Enumerable.Range(0, 3).Select(k => ((uint) 753, $"80{i}0-Again{k}{tag} (Trading Card)"))]);
			offFor.Add(Field<int>("_searchOffMinutes"));
		}
		Check("market ways: searches still refused when tried again - left alone 30 minutes, then 60", offFor.SequenceEqual([30, 60]) && (NocatFarm.PriceBook.PausedUntil == null), string.Join(",", offFor));

		// A search refused and the single lookup after it refused too: the market's limit on the connection, not searches -
		// a pause after those two, and searches stay on. Its end asks one item, the other way.
		Fresh();
		AnsweredLately(0);
		answer = (_, _) => Status(429);
		List<(uint, string)> late = [.. Enumerable.Range(0, 3).Select(i => ((uint) 753, $"8100-Late{i}{tag} (Trading Card)"))];
		lock (sent) sent.Clear();
		bool paused = !await PriceAll([.. late]);
		string limitRun = string.Join(" ", sent.Select(static s => $"{s.Way}{s.Path}"));
		bool limitTold = paused && (sent.Count == 2) && sent[0].Path.StartsWith("/market/search/", StringComparison.Ordinal) && (sent[1].Path == "/market/priceoverview/")
			&& (sent[0].Way == 'A') && (sent[1].Way == 'A') && (Field<int>("_coolSeconds") == 90) && !NocatFarm.PriceBook.SearchOff && (Field<int>("_searchOffMinutes") == 0);
		F("_coolUntil").SetValue(null, DateTime.MinValue);
		answer = (_, r) => Price(r);
		stock.Clear();
		stock.AddRange(late.Select(static l => l.Item2));
		lock (sent) sent.Clear();
		bool resumed = await PriceAll([.. late]);
		Check("market ways: a search 429 followed by a refused single lookup - a pause after two requests, searches kept on",
			limitTold, limitRun);
		Check("market ways: ...and the pause's end asks one item the other way, then searches again",
			resumed && (sent.Count == 2) && (sent[0].Path == "/market/priceoverview/") && (sent[0].Way == 'B') && sent[1].Path.StartsWith("/market/search/", StringComparison.Ordinal)
			&& !NocatFarm.PriceBook.SearchOff && (NocatFarm.PriceBook.PausedUntil == null) && late.All(c => Known(c.Item1, c.Item2) is not null),
			string.Join(" ", sent.Select(static s => $"{s.Way}{s.Path}")));

		// The market's limit on the connection: way A was answering until a moment ago (and B a little before), and is
		// refused - the same whichever way is asked, so it pauses at once on ONE request, not two.
		Fresh();
		AnsweredLately(0);
		AnsweredLately(1);
		answer = (_, _) => Status(429);
		lock (sent) sent.Clear();
		bool limited = !await PriceAll((730, $"Limit One {tag}"), (730, $"Limit Two {tag}"));
		string limitedWays = Ways();
		int limitPause = Field<int>("_coolSeconds");
		F("_coolUntil").SetValue(null, DateTime.MinValue);   // the pause is over
		lock (sent) sent.Clear();
		bool stillLimited = !await PriceAll((730, $"Limit One {tag}"), (730, $"Limit Two {tag}"));
		Check("market ways: a 429 from a way that was answering - the IP limit: ONE request, then the pause",
			limited && (limitedWays == "A") && (limitPause == 90) && stillLimited, $"{limitedWays} / {limitPause}");
		Check("market ways: ...and the end of the pause sends ONE request, the other way", (Ways() == "B") && (NocatFarm.PriceBook.PausedUntil != null) && (Field<int>("_coolSeconds") == 300), Ways());
		answer = (_, r) => Price(r);
		F("_coolUntil").SetValue(null, DateTime.MinValue);
		lock (sent) sent.Clear();
		bool limitOver = await PriceAll((730, $"Limit One {tag}"), (730, $"Limit Two {tag}"));
		Check("market ways: once the limit is over, the request at the pause's end is answered and that way is kept",
			limitOver && (Ways() == "AA") && (Field<int>("_goodWay") == 0) && (Field<int>("_coolSeconds") == 0), Ways());

		// No answer from either way lately (or ever, this run): a refusal may be how the request is written - the next
		// request goes the other way at once.
		Fresh();
		answer = (w, r) => w == 'A' ? Status(429) : Price(r);
		lock (sent) sent.Clear();
		bool switched = await PriceAll((730, $"Switch Now {tag}"));
		Check("market ways: a 429 with no recent answer from either way - the other way asked at once, no pause",
			switched && (Ways() == "AB") && (NocatFarm.PriceBook.PausedUntil == null) && (Field<int>("_goodWay") == 1), Ways());

		// 5. The gap wanders: 10 seconds give or take a quarter, and every four add up to exactly forty.
		gapP.SetValue(null, 10d);
		Field<Queue<double>>("Wobble").Clear();
		MethodInfo nextGap = pb.GetMethod("NextGap", All)!;
		List<double> wobbleGaps = [.. Enumerable.Range(0, 4000).Select(_ => ((TimeSpan) nextGap.Invoke(null, [])!).TotalSeconds)];
		Check("market jitter: the gap is 10s give or take a quarter - never under 7.5s, never over 12.5s, never the same rhythm",
			wobbleGaps.All(static g => (g >= 7.5 - 1e-9) && (g <= 12.5 + 1e-9)) && (wobbleGaps.Distinct().Count() > 100) && (wobbleGaps.Min() < 8) && (wobbleGaps.Max() > 12),
			$"{wobbleGaps.Min():0.000}-{wobbleGaps.Max():0.000}s, {wobbleGaps.Distinct().Count()} different");
		Check("market jitter: every four gaps add up to exactly four - on average never faster than one request per gap",
			wobbleGaps.Chunk(4).All(static c => Math.Abs(c.Sum() - 40) < 1e-6) && (Math.Abs(wobbleGaps.Average() - 10) < 1e-6), $"average {wobbleGaps.Average():0.000000}s");

		// 6. The rate, with both ways and a retry for every item: never over one request per gap.
		Fresh();
		const double Gap = 0.1;
		gapP.SetValue(null, Gap);
		Field<Queue<double>>("Wobble").Clear();
		int aCalls = 0, bCalls = 0;
		// Each way refuses every other request it gets - never both in a row - so every item takes a refusal and a retry:
		// neither is ever counted as answering lately, so each refusal turns the next request the other way.
		answer = (w, r) => {
			bool no = w == 'A' ? (++aCalls % 2 == 1) : (++bCalls % 2 == 0);
			Quiet();
			return no ? Status(429) : Price(r);
		};
		lock (sent) sent.Clear();
		bool paced = await PriceAll([.. Enumerable.Range(0, 10).Select(i => ((uint) 730, $"Pace {i} {tag}"))]);
		List<DateTime> at;
		lock (sent) at = [.. sent.Select(static s => s.At)];
		List<double> intervals = [.. at.Zip(at.Skip(1)).Select(static p => (p.Second - p.First).TotalSeconds)];
		Check("market rate: 10 items, each refused one way and answered the other - 20 requests, each one at least three quarters of a gap after the last",
			paced && (at.Count == 20) && intervals.All(static i => i >= (Gap * 0.75) - 0.002) && (NocatFarm.PriceBook.PausedUntil == null),
			$"{at.Count} requests, {Ways()}, shortest {intervals.DefaultIfEmpty().Min() * 1000:0}ms");
		Check("market rate: the 19 gaps between them took at least 18.75 gaps' time - on average never more than one request per gap",
			intervals.Sum() >= (Gap * 18.75) - 0.04, $"{intervals.Sum():0.000}s");

		// 7. Both ways ask with an Accept header - and say different things.
		var mA = NocatFarm.Core.Browser.Market(TimeSpan.FromSeconds(5));
		var mB = NocatFarm.Core.Browser.MarketAsBrowser(TimeSpan.FromSeconds(5));
		string agentB = mB.DefaultRequestHeaders.UserAgent.ToString();
		Check("market ways: both send Accept (none at all was answered 429 every time), the browser way with Accept-Language too",
			(mA.DefaultRequestHeaders.Accept.Count > 0) && (mB.DefaultRequestHeaders.Accept.Count > 0)
			&& mB.DefaultRequestHeaders.AcceptLanguage.Count > 0
			&& (agentB == NocatFarm.Core.Browser.MarketBrowserAgent) && agentB.Contains("Firefox/", StringComparison.Ordinal) && !agentB.Contains("Chrome", StringComparison.Ordinal)
			&& (mA.DefaultRequestHeaders.UserAgent.ToString() != agentB), $"{mA.DefaultRequestHeaders.Accept} | {mB.DefaultRequestHeaders.Accept} | {agentB}");
		Check("market ways: neither asks for a compressed answer (priceoverview answered 429 to every request with Accept-Encoding, 2026-10-13)",
			(mA.DefaultRequestHeaders.AcceptEncoding.Count == 0) && (mB.DefaultRequestHeaders.AcceptEncoding.Count == 0)
			&& (NocatFarm.Core.Browser.MarketHandler().AutomaticDecompression == System.Net.DecompressionMethods.None));
		Check("market ways: the app's own way sends no Accept-Language (with en-US,en;q=0.9 the market answered 429 every time, 2026-10-13)",
			mA.DefaultRequestHeaders.AcceptLanguage.Count == 0);
		bool sentA = false, sentB = false, allAccept;
		lock (sent) {
			sentA = sent.Any(static s => s.Way == 'A');
			sentB = sent.Any(static s => s.Way == 'B');
			allAccept = sent.All(static s => (s.Accept.Length > 0) && (s.Way == 'A' ? s.Agent.StartsWith("nocat.farm/", StringComparison.Ordinal) : s.Agent.Contains("Firefox/", StringComparison.Ordinal)));
		}
		Check("market ways: every request actually sent, either way, carried its Accept header and its own name", sentA && sentB && allAccept);
		gapP.SetValue(null, 0d);

		// 7b. A pause written down by an older version is dropped on the first start of a new one: up to 1.6.9 every request
		// was refused for want of an Accept header, and 1.7.0 sat out the twelve-hour pause those refusals had built up.
		{
			FieldInfo vpRememberedF = typeof(NocatFarm.Core.Limiters).GetField("_remembered", All)!;
			string vpBackoffFile = Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", "backoff.json");
			string vpMe = NocatFarm.Build.Version;
			long vpHoursAhead = DateTime.UtcNow.AddHours(9).Ticks;

			// What a restart does: the file is all there is - read afresh, the book's pause loaded from it.
			void vpRestart(params string[] lines) {
				Fresh();
				Directory.CreateDirectory(Path.GetDirectoryName(vpBackoffFile)!);
				File.WriteAllText(vpBackoffFile, string.Join(Environment.NewLine, lines));
				lock (typeof(NocatFarm.Core.Limiters).GetField("RememberGate", All)!.GetValue(null)!) {
					vpRememberedF.SetValue(null, null);
				}
				F("_coolLoaded").SetValue(null, false);
				F("_coolUntil").SetValue(null, DateTime.MinValue);
				F("_coolSeconds").SetValue(null, 0);
				F("_way").SetValue(null, 0);
				F("_goodWay").SetValue(null, 0);
				pb.GetMethod("LoadCool", All)!.Invoke(null, []);
			}

			// The very file 1.6.9 left behind: the market at the twelve-hour step, another host's own wait, the way kept.
			vpRestart($"market|{vpHoursAhead}|720", $"{host}|{vpHoursAhead}|60", $"market-way|{DateTime.UtcNow.Ticks}|1");
			bool vpDropped = (NocatFarm.PriceBook.PausedUntil == null) && (Field<int>("_coolSeconds") == 0) && !Field<bool>("_saidRefused") && (NocatFarm.PriceBook.Stale == null);
			bool vpHostKept = NocatFarm.Core.Limiters.Remembered(host) is { Minutes: 60 } vpHk && (vpHk.Until.Ticks == vpHoursAhead);
			bool vpWayKept = (Field<int>("_way") == 1) && (Field<int>("_goodWay") == 1);
			string vpAfterDrop = File.ReadAllText(vpBackoffFile);
			Check("market pause: one saved by 1.6.9 (no version on it) is dropped on load - other hosts' waits and the way that answered are kept",
				vpDropped && vpHostKept && vpWayKept && !vpAfterDrop.Contains($"market|{vpHoursAhead}", StringComparison.Ordinal) && vpAfterDrop.Contains($"{host}|{vpHoursAhead}|60", StringComparison.Ordinal),
				vpAfterDrop.Replace(Environment.NewLine, " ; "));

			// ...and pricing asks straight away. The host's own wait is lifted here so only the market's is being tested.
			OpenHost();
			answer = (_, r) => Price(r);
			lock (sent) sent.Clear();
			bool vpAskedNow = await PriceAll((730, $"Old Pause {tag}"));
			Check("market pause: after an older version's pause is dropped, pricing asks the market right away",
				vpAskedNow && (sent.Count == 1) && (Known(730, $"Old Pause {tag}") == 1.23m), Ways());

			// Refused at once: the ladder starts again from its bottom step, not from where 1.6.9 left it.
			vpRestart($"market|{vpHoursAhead}|720");
			answer = (_, _) => Status(429);
			lock (sent) sent.Clear();
			await PriceAll((730, $"Old Pause Refused {tag}"));
			Check("market pause: refused straight after the dropped pause - the ladder starts from 90 seconds, written down with this version",
				(Field<int>("_coolSeconds") == 90) && (NocatFarm.Core.Limiters.RememberedBy("market").By == vpMe) && File.ReadAllText(vpBackoffFile).Contains($"|{vpMe}", StringComparison.Ordinal),
				$"{Field<int>("_coolSeconds")} / {Ways()}");

			// Another version's stamp - older or newer - is dropped the same way.
			vpRestart($"market|{vpHoursAhead}|720|1.7.0-not-this");
			Check("market pause: one written by a different version is dropped too", (NocatFarm.PriceBook.PausedUntil == null) && (Field<int>("_coolSeconds") == 0));

			// This version's own pause binds a restart, exactly as before.
			vpRestart($"market|{vpHoursAhead}|720|{vpMe}");
			answer = (_, r) => Price(r);
			lock (sent) sent.Clear();
			bool vpHeldOwn = !await PriceAll((730, $"Own Pause {tag}"));
			Check("market pause: one written by this same version still holds after a restart - nothing asked, the refusal remembered",
				vpHeldOwn && (sent.Count == 0) && (NocatFarm.PriceBook.PausedUntil is { } vpOwnUntil) && (vpOwnUntil.Ticks == vpHoursAhead)
				&& (Field<int>("_coolSeconds") == 720 * 60) && Field<bool>("_saidRefused"), Ways());

			// The new line format: written, read back from the file, the same - and a host's line stays the old three fields.
			DateTime vpUntil = new(DateTime.UtcNow.AddMinutes(37).Ticks, DateTimeKind.Utc);
			vpRestart();
			NocatFarm.Core.Limiters.Remember("market", vpUntil, 15, vpMe);
			NocatFarm.Core.Limiters.Remember(host, vpUntil, 4);
			string vpWritten = File.ReadAllText(vpBackoffFile);
			lock (typeof(NocatFarm.Core.Limiters).GetField("RememberGate", All)!.GetValue(null)!) {
				vpRememberedF.SetValue(null, null);
			}
			var vpBack = NocatFarm.Core.Limiters.RememberedBy("market");
			var vpHostBack = NocatFarm.Core.Limiters.RememberedBy(host);
			Check("market pause: the versioned line round-trips - until, minutes and version - and a host's line keeps no version",
				(vpBack.Until == vpUntil) && (vpBack.Minutes == 15) && (vpBack.By == vpMe) && (vpHostBack.Until == vpUntil) && (vpHostBack.Minutes == 4) && (vpHostBack.By == null)
				&& vpWritten.Contains($"market|{vpUntil.Ticks}|15|{vpMe}", StringComparison.Ordinal) && vpWritten.Contains($"{host}|{vpUntil.Ticks}|4", StringComparison.Ordinal)
				&& !vpWritten.Contains($"{host}|{vpUntil.Ticks}|4|", StringComparison.Ordinal), vpWritten.Replace(Environment.NewLine, " ; "));
			Fresh();
		}

		// 8. Old prices while the market refuses: the book says from when, and when it asks again - the tile and the command too.
		Fresh();
		pb.GetMethod("Remember", All)!.Invoke(null, [(uint) 730, $"Stale Thing {tag}", 2.50m]);
		Check("stale prices: no word of old prices while the market answers", NocatFarm.PriceBook.Stale == null);
		F("_coolUntil").SetValue(null, DateTime.UtcNow.AddMinutes(2));   // Steam's own trouble (a 500): a pause, but no refusal
		bool notForTrouble = NocatFarm.PriceBook.Stale == null;
		DateTime retry = DateTime.UtcNow.AddMinutes(45);
		F("_coolSeconds").SetValue(null, 300);
		F("_coolUntil").SetValue(null, retry);
		var stale = NocatFarm.PriceBook.Stale;
		Check("stale prices: refused both ways and pausing - the newest price's time and when the market is asked again",
			notForTrouble && (stale is { } st) && (Math.Abs((st.From - DateTime.UtcNow).TotalSeconds) < 5) && (st.RetryAt == retry), stale?.ToString() ?? "null");

		var mgr = new NocatFarm.Core.BotManager(new NocatFarm.Config.GlobalConfig { WebEnabled = false, MarketGapSeconds = 8 });
		var bots = (System.Collections.Concurrent.ConcurrentDictionary<string, NocatFarm.Core.Bot>) typeof(NocatFarm.Core.BotManager).GetField("_bots", All)!.GetValue(mgr)!;
		var holder = new NocatFarm.Core.Bot("stale-holder", new NocatFarm.Config.BotConfig());
		bots["stale-holder"] = holder;
		typeof(NocatFarm.Core.Bot).GetProperty("State")!.SetValue(holder, NocatFarm.Core.BotState.Online);   // signed in, so being priced
		Directory.CreateDirectory(Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state"));
		File.WriteAllText(Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", "invvalue-stale-holder.json"), System.Text.Json.JsonSerializer.Serialize(new {
			ReadAt = DateTime.UtcNow.Ticks,
			Games = new object[] { new { App = 730, Game = "Stale Game", Items = new Dictionary<string, int[]> { [$"Stale Thing {tag}"] = [1, 5], [$"Unpriced Thing {tag}"] = [1, 5] } } }
		}));
		Type invT = typeof(NocatFarm.Core.InventoryValue);
		invT.GetMethod("LoadSnapshot", All)!.Invoke(holder.Inventory, [TimeSpan.FromHours(6)]);
		invT.GetMethod("Recount", All)!.Invoke(holder.Inventory, []);

		// A stopped account holding two items nothing has priced: it isn't pricing anything, so they aren't "being priced".
		var stopped = new NocatFarm.Core.Bot("stale-stopped", new NocatFarm.Config.BotConfig());
		bots["stale-stopped"] = stopped;
		File.WriteAllText(Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", "invvalue-stale-stopped.json"), System.Text.Json.JsonSerializer.Serialize(new {
			ReadAt = DateTime.UtcNow.Ticks,
			Games = new object[] { new { App = 730, Game = "Stale Game", Items = new Dictionary<string, int[]> { [$"Stopped Thing {tag}"] = [1, 5], [$"Stopped Other {tag}"] = [2, 5] } } }
		}));
		invT.GetMethod("LoadSnapshot", All)!.Invoke(stopped.Inventory, [TimeSpan.FromHours(6)]);
		invT.GetMethod("Recount", All)!.Invoke(stopped.Inventory, []);
		F("_coolUntil").SetValue(null, retry);   // the manager's settings don't lift it
		string inventory = await Commands.RunAsync(mgr, "inventory stale-holder");
		// As the command writes them: the time today, the date too past midnight (45 minutes ahead can be tomorrow).
		static string StaleStamp(DateTime utc) {
			DateTime local = utc.ToLocalTime();

			return local.ToString(local.Date == DateTime.Today ? "HH:mm" : "yyyy-MM-dd HH:mm", System.Globalization.CultureInfo.InvariantCulture);
		}
		string expected = $"prices from {StaleStamp(stale!.Value.From)} · Steam's market isn't answering, trying again at {StaleStamp(retry)}";
		Check("stale prices: 'inventory' says from when the prices are and when the market is asked again",
			(holder.Inventory.Pending > 0) && inventory.Contains(expected, StringComparison.Ordinal) && inventory.Contains("$2.50", StringComparison.Ordinal), inventory);

		string stoppedText = await Commands.RunAsync(mgr, "inventory stale-stopped");
		string allText = await Commands.RunAsync(mgr, "inventory all");
		bool stoppedOut = (stopped.Inventory.Pending == 2) && (stopped.Inventory.Pricing == 0) && (stopped.Inventory.Waiting().Count == 0) && (stopped.Inventory.RequestsLeft == 0);
		Check("stopped account: its items leave the waiting totals - not 'still being priced' in 'inventory', alone or with the rest",
			stoppedOut && !stoppedText.Contains("still being priced", StringComparison.Ordinal) && !stoppedText.Contains("prices from", StringComparison.Ordinal)
			&& allText.Contains("all: $2.50   (1 still being priced", StringComparison.Ordinal) && (holder.Inventory.Pricing == 1),
			$"{stoppedText} || {allText}");
		typeof(NocatFarm.Core.Bot).GetProperty("State")!.SetValue(stopped, NocatFarm.Core.BotState.Online);
		Check("stopped account: back online, its items are being priced again", (stopped.Inventory.Pricing == 2) && (stopped.Inventory.Waiting().Count == 2), $"{stopped.Inventory.Pricing}");
		typeof(NocatFarm.Core.Bot).GetProperty("State")!.SetValue(stopped, NocatFarm.Core.BotState.Stopped);
		Check("stopped account: the dashboard counts what's being priced the same way - the fleet from Waiting(), each account from Pricing",
			Src(Path.Combine("Web", "WebHost.cs")).Contains("InventoryPending = b.Inventory.Pricing,", StringComparison.Ordinal)
			&& Src(Path.Combine("Web", "WebHost.cs")).Contains("SelectMany(static b => b.Inventory.Waiting())", StringComparison.Ordinal)
			&& Src("Commands.cs").Contains("bot.Inventory.Pricing > 0 ?", StringComparison.Ordinal));
		typeof(NocatFarm.Core.Bot).GetProperty("State")!.SetValue(holder, NocatFarm.Core.BotState.Stopped);

		string appJs = Src(Path.Combine("wwwroot", "app.js"));
		Check("stale prices: the tile says the same - from when, and when it tries again - on the fleet tile and each account's line",
			appJs.Contains("if (stale) return tf(\"prices from {0} · Steam's market isn't answering, trying again at {1}\", stamp(stale.From), clock(stale.RetryAt));", StringComparison.Ordinal)
			&& appJs.Contains("state.InventoryPausedUntil, state.InventoryStale) : ''", StringComparison.Ordinal)
			&& appJs.Contains("b.InventoryEtaSeconds, state.InventoryPausedUntil, state.InventoryStale))", StringComparison.Ordinal)
			&& Src(Path.Combine("Web", "WebHost.cs")).Contains("InventoryStale = PriceBook.Stale is { } stale ? new { stale.From, stale.RetryAt } : null,", StringComparison.Ordinal));
	} finally {
		Fresh();
		F("_checkFirst").SetValue(null, true);
		Quiet();
		F("Http").SetValue(null, httpBefore);
		F("HttpB").SetValue(null, httpBBefore);
		gapP.SetValue(null, null);
		NocatFarm.Config.Live.Global = liveBefore;
		typeof(NocatFarm.Core.BotManager).GetProperty("Instance", All)?.SetValue(null, hostBefore);
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
		}
	}
}

// ── one item the market can't price never holds up the queue: twice no use in a row and it is set aside ───────────────
{
	const BindingFlags All = BindingFlags.NonPublic | BindingFlags.Public | BindingFlags.Static | BindingFlags.Instance;
	Type pb = typeof(NocatFarm.PriceBook);
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	NocatFarm.Config.GlobalConfig liveBefore = NocatFarm.Config.Live.Global;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-aside-" + Guid.NewGuid().ToString("N"));
	FieldInfo F(string n) => pb.GetField(n, All)!;
	T Field<T>(string n) => (T) F(n).GetValue(null)!;
	PropertyInfo gapP = pb.GetProperty("GapForTests", All)!;
	object httpBefore = F("Http").GetValue(null)!, httpBBefore = F("HttpB").GetValue(null)!;
	string host = NocatFarm.Core.WebSession.Community.Host;
	string tag = Guid.NewGuid().ToString("N")[..6];
	System.Collections.IDictionary troubled = (System.Collections.IDictionary) F("Troubled").GetValue(null)!;
	System.Collections.IDictionary cache = (System.Collections.IDictionary) F("Cache").GetValue(null)!;
	string KeyOf(uint app, string hash) => $"{app}/{NocatFarm.PriceBook.CurrencyId}/{hash}";
	(int Fails, long Until, int Times)? Trouble(uint app, string hash) {
		lock (troubled) {
			return troubled.Contains(KeyOf(app, hash)) ? ((int, long, int)) troubled[KeyOf(app, hash)]! : null;
		}
	}
	void Expire(string key) {
		lock (troubled) {
			var (fails, _, times) = ((int, long, int)) troubled[key]!;
			troubled[key] = (fails, DateTimeOffset.UtcNow.AddSeconds(-1).ToUnixTimeSeconds(), times);
		}
	}
	double HoursAside(uint app, string hash) => Trouble(app, hash) is { } t ? (DateTimeOffset.FromUnixTimeSeconds(t.Until) - DateTimeOffset.UtcNow).TotalHours : 0;

	void Fresh() {
		((System.Collections.IDictionary) typeof(NocatFarm.Core.Limiters).GetField("WebBackoff", All)!.GetValue(null)!).Remove(host);
		NocatFarm.Core.Limiters.Remember(host, DateTime.MinValue, 0);
		F("_coolLoaded").SetValue(null, true);
		F("_coolUntil").SetValue(null, DateTime.MinValue);
		F("_coolSeconds").SetValue(null, 0);
		F("_saidRefused").SetValue(null, false);
		F("_way").SetValue(null, 0);
		F("_goodWay").SetValue(null, 0);
		F("_refusedInRow").SetValue(null, 0);
		F("_checkFirst").SetValue(null, false);
		F("_searchOffUntil").SetValue(null, DateTime.MinValue);
		F("_searchOffMinutes").SetValue(null, 0);
		F("_searchDoubt").SetValue(null, -1);
		Array.Fill((DateTime[]) F("AnsweredAt").GetValue(null)!, DateTime.MinValue);
		((System.Collections.IDictionary) F("Suspects").GetValue(null)!).Clear();
		F("_marketDown").SetValue(null, false);
		NocatFarm.Core.Limiters.Remember("market", DateTime.MinValue, 0);
	}

	// The pretend market, both ways: each item's single lookup answers as `trouble` says, else $1.23; a search answers
	// `searchJson`. Every request is noted. Nothing reaches Steam.
	Dictionary<string, Func<HttpResponseMessage>> trouble = new(StringComparer.Ordinal);
	string? searchJson = null;
	List<string> asked = [];
	HttpResponseMessage Json(string json) => new(System.Net.HttpStatusCode.OK) { Content = new StringContent(json) };
	HttpResponseMessage Answer(HttpRequestMessage r) {
		string path = r.RequestUri!.AbsolutePath;
		string query = Uri.UnescapeDataString(r.RequestUri.Query);
		lock (asked) asked.Add(path.StartsWith("/market/search/", StringComparison.Ordinal) ? "search" : query[(query.IndexOf("market_hash_name=", StringComparison.Ordinal) + 17)..]);
		if (path.StartsWith("/market/search/", StringComparison.Ordinal)) {
			return Json(searchJson ?? """{"success":true,"pagesize":10,"total_count":0,"results":[]}""");
		}
		string hash = query[(query.IndexOf("market_hash_name=", StringComparison.Ordinal) + 17)..];
		return trouble.TryGetValue(hash, out Func<HttpResponseMessage>? bad) ? bad() : Json("""{"success":true,"lowest_price":"$1.23","median_price":"$1.20"}""");
	}
	FakePing fake = new((request, _) => Task.FromResult(Answer(request)));
	Task<bool> Sweep(params (uint, string)[] wanted) => NocatFarm.PriceBook.PriceAsync([.. wanted], 100, CancellationToken.None);
	bool Due(uint app, string hash) => NocatFarm.PriceBook.NeedsRefresh(app, hash);
	void TimePasses() => F("_coolUntil").SetValue(null, DateTime.MinValue);   // the 2-minute pause after a 500 is over
	HttpResponseMessage Status(int code) => new((System.Net.HttpStatusCode) code);

	try {
		NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);
		NocatFarm.Config.Live.Global = new NocatFarm.Config.GlobalConfig { MarketGapSeconds = 8, WebRequestGapMs = 0 };
		gapP.SetValue(null, 0d);
		F("Http").SetValue(null, new HttpClient(fake));
		F("HttpB").SetValue(null, new HttpClient(fake));

		// 1. A 500 for one item, every time: the first sweep stops on it (and pauses two minutes) - nothing counted against
		// it yet, it may be the whole market. The next asks something else first, which is answered: then the item's 500
		// counts, it fails again, and it is set aside with everything behind it priced in the same sweep - no pause.
		Fresh();
		string bad = $"Aside Broken {tag}";
		(uint, string)[] line = [(730, bad), (730, $"Aside Fine One {tag}"), (730, $"Aside Fine Two {tag}"), (730, $"Aside Fine Three {tag}")];
		trouble[bad] = () => Status(500);
		bool first = await Sweep(line);
		bool firstPaused = NocatFarm.PriceBook.PausedUntil != null;
		bool notYet = Due(730, bad) && (Trouble(730, bad) == null) && line.Skip(1).All(q => Due(q.Item1, q.Item2));
		TimePasses();
		bool second = await Sweep(line);
		Check("set aside: a 500 for one item - the first sweep stops on it, the second sets it aside and prices the rest in the SAME sweep, no pause",
			!first && firstPaused && notYet && second && !Due(730, bad) && line.Skip(1).All(q => NocatFarm.PriceBook.Known(q.Item1, q.Item2) == 1.23m)
			&& (NocatFarm.PriceBook.PausedUntil == null) && (NocatFarm.PriceBook.Known(730, bad) == null) && (HoursAside(730, bad) is > 5.9 and <= 6.01),
			$"first={first} paused={firstPaused} notYet={notYet} second={second} aside={HoursAside(730, bad):0.00}h");

		// 2. "null", a bare number, a page with no prices in it: answers about the item with nothing in them - twice sets it aside.
		Fresh();
		string nul = $"Aside Null {tag}", empty = $"Aside Number {tag}", junk = $"Aside Junk {tag}", fine = $"Aside Fine Four {tag}";
		trouble[nul] = () => Json("null");
		trouble[empty] = () => Json("42");
		trouble[junk] = () => Json("not json at all");
		(uint, string)[] odd = [(730, nul), (730, empty), (730, junk), (730, fine)];
		int sweeps = 0;
		List<int> dueAfter = [];
		while ((sweeps < 20) && odd.Any(o => Due(o.Item1, o.Item2))) {
			await Sweep(odd);
			sweeps++;
			dueAfter.Add(odd.Count(o => Due(o.Item1, o.Item2)));
		}
		Check("set aside: \"null\", a bare number, or no price in it - set aside after twice, the rest priced; 3 bad items, 4 sweeps",
			(sweeps == 4) && new[] { nul, empty, junk }.All(h => !Due(730, h) && (Trouble(730, h)?.Times == 1) && (NocatFarm.PriceBook.Known(730, h) == null))
			&& (NocatFarm.PriceBook.Known(730, fine) == 1.23m) && (NocatFarm.PriceBook.PausedUntil == null), $"{sweeps} sweeps, due after each: {string.Join(",", dueAfter)}");

		// "No lowest listing": nobody sells it - worth nothing, kept like any price, never set aside or asked again.
		Fresh();
		string unsold = $"Aside Unsold {tag}";
		trouble[unsold] = () => Json("""{"success":true,"volume":"0"}""");
		lock (asked) asked.Clear();
		bool unsoldDone = await Sweep((730, unsold));
		bool unsoldAgain = await Sweep((730, unsold));
		Check("set aside: no lowest listing is a price of nothing - not due again, never set aside, asked once",
			unsoldDone && unsoldAgain && (NocatFarm.PriceBook.Known(730, unsold) == 0m) && !Due(730, unsold) && (Trouble(730, unsold) == null) && (asked.Count == 1),
			$"{asked.Count} asked");

		// A search with no results list, twice: its items are priced one at a time instead - not each one stuck in turn.
		Fresh();
		searchJson = """{"success":true}""";
		(uint, string)[] cards = [.. Enumerable.Range(0, 3).Select(i => ((uint) 753, $"8800-Aside{i}{tag} (Trading Card)"))];
		lock (asked) asked.Clear();
		bool s1 = await Sweep(cards);
		bool s2 = await Sweep(cards);
		List<string> searchRun;
		lock (asked) searchRun = [.. asked];
		List<(uint App, string Hash)> cardList = [.. Enumerable.Range(0, 3).Select(i => ((uint) 753, $"8800-Est{i}{tag} (Trading Card)"))];
		Check("set aside: a search with no results list twice - set aside, its items priced one at a time in the same sweep, and counted one each",
			!s1 && s2 && (searchRun.Count(static a => a == "search") == 2) && (searchRun.Count == 5) && cards.All(c => NocatFarm.PriceBook.Known(c.Item1, c.Item2) == 1.23m)
			&& (NocatFarm.PriceBook.NextAsk(cardList).Search == null) && (NocatFarm.PriceBook.RequestsFor(cardList) == 3),
			string.Join(" ", searchRun));
		searchJson = null;

		// 3. Back after its time: asked again, and an answer forgets the trouble. Failing again once back: a day, at once.
		Fresh();
		Expire(KeyOf(730, nul));
		trouble.Remove(nul);
		bool cameBack = Due(730, nul);
		await Sweep((730, nul));
		bool cleared = (NocatFarm.PriceBook.Known(730, nul) == 1.23m) && (Trouble(730, nul) == null);
		Expire(KeyOf(730, bad));
		bool badBack = Due(730, bad);
		string after = $"Aside Fine Five {tag}";
		bool goesOn = await Sweep((730, bad), (730, after));
		Check("set aside: back once its time is up - an answer clears it; failing again once back sets it aside a day at once, the rest still priced",
			cameBack && cleared && badBack && goesOn && !Due(730, bad) && (Trouble(730, bad)?.Times == 2) && (HoursAside(730, bad) is > 23.9 and <= 24.01)
			&& (NocatFarm.PriceBook.Known(730, after) == 1.23m), $"{HoursAside(730, bad):0.00}h, times {Trouble(730, bad)?.Times}");

		// 4. A 429 is the market's limit, never the item's: sweep after sweep refused both ways, nothing is marked.
		Fresh();
		string limited = $"Aside Limited {tag}";
		trouble[limited] = () => Status(429);
		for (int i = 0; i < 5; i++) {
			F("_coolUntil").SetValue(null, DateTime.MinValue);
			await Sweep((730, limited));
		}
		trouble[limited] = () => Status(403);
		F("_coolUntil").SetValue(null, DateTime.MinValue);
		await Sweep((730, limited));
		Check("set aside: a 429 (or 403) never marks the item - the pause's business; it is still due, nothing counted against it",
			Due(730, limited) && (Trouble(730, limited) == null) && (Field<int>("_coolSeconds") > 0), $"{Trouble(730, limited)}");

		// 5. The queue always gets on: a mix of bad and good - every sweep after the first either prices or sets aside
		// something, never two in a row without, until nothing is due. The 500s and empty answers too: each fails while
		// the market answers the good items between them.
		Fresh();
		Func<HttpResponseMessage>[] kinds = [() => Status(500), () => Status(502), () => Json("null"), () => Json(""), () => Json("[1,2]")];
		List<(uint, string)> mix = [];
		for (int i = 0; i < 15; i++) {
			string h = $"Aside Mix {i} {tag}";
			mix.Add((730, h));
			if (i % 3 != 2) trouble[h] = kinds[i % kinds.Length];
		}
		int stuck = 0, worstStuck = 0, rounds = 0, was = mix.Count;
		while ((rounds < 40) && mix.Any(m => Due(m.Item1, m.Item2))) {
			TimePasses();
			await Sweep([.. mix]);
			rounds++;
			int now = mix.Count(m => Due(m.Item1, m.Item2));
			stuck = now < was ? 0 : stuck + 1;
			worstStuck = Math.Max(worstStuck, stuck);
			was = now;
		}
		int badCount = mix.Count(m => trouble.ContainsKey(m.Item2));
		// Two 500s at the head of the queue cost two sweeps before anything is answered: neither is blamed until then.
		Check("set aside: the queue always gets on - never more than two sweeps in a row without progress, done in at most two sweeps per bad item",
			!mix.Any(m => Due(m.Item1, m.Item2)) && (worstStuck <= 2) && (rounds <= (2 * badCount) + 1)
			&& mix.Where(m => !trouble.ContainsKey(m.Item2)).All(m => NocatFarm.PriceBook.Known(m.Item1, m.Item2) == 1.23m),
			$"{rounds} sweeps for {badCount} bad, worst {worstStuck} without progress");

		// 6. Remembered across a restart, in the price book's own file.
		string file = Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", "prices.json");
		NocatFarm.PriceBook.Save();
		string saved = File.ReadAllText(file);
		var keep = Trouble(730, bad);
		lock (troubled) troubled.Clear();
		F("_loaded").SetValue(null, false);
		pb.GetMethod("Load", All)!.Invoke(null, []);
		Check("set aside: remembered across a restart, in the price book's file - and still not due",
			saved.Contains($"\"aside/{KeyOf(730, bad)}\"", StringComparison.Ordinal) && (Trouble(730, bad) is { } back) && (back.Until == keep?.Until) && (back.Times == 2)
			&& !Due(730, bad) && !cache.Contains($"aside/{KeyOf(730, bad)}"), $"{Trouble(730, bad)}");

		// 7. Off the "still to price" count: an account holding one item the market can't price and one it can ends at 0.
		Fresh();
		string held1 = $"Aside Held Bad {tag}", held2 = $"Aside Held Good {tag}";
		trouble[held1] = () => Json("null");
		var holder = new NocatFarm.Core.Bot("aside-holder", new NocatFarm.Config.BotConfig());
		Directory.CreateDirectory(Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state"));
		File.WriteAllText(Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", "invvalue-aside-holder.json"), System.Text.Json.JsonSerializer.Serialize(new {
			ReadAt = DateTime.UtcNow.Ticks,
			Games = new object[] { new { App = 730, Game = "Aside Game", Items = new Dictionary<string, int[]> { [held1] = [1, 5], [held2] = [1, 5] } } }
		}));
		Type invT = typeof(NocatFarm.Core.InventoryValue);
		invT.GetMethod("LoadSnapshot", All)!.Invoke(holder.Inventory, [TimeSpan.FromHours(6)]);
		invT.GetMethod("Recount", All)!.Invoke(holder.Inventory, []);
		int pendingBefore = holder.Inventory.Pending;
		await Sweep((730, held1), (730, held2));
		int pendingMid = holder.Inventory.Pending;
		await Sweep((730, held1), (730, held2));
		int pendingAfter = holder.Inventory.Pending, requestsAfter = holder.Inventory.RequestsLeft;
		invT.GetMethod("Recount", All)!.Invoke(holder.Inventory, []);
		Check("set aside: off the \"still to price\" count at once, and after a recount - the tile never waits on it",
			(pendingBefore == 2) && (pendingMid == 2) && (pendingAfter == 0) && (requestsAfter == 0) && (holder.Inventory.Pending == 0) && (holder.Inventory.Total == 1.23m),
			$"{pendingBefore} -> {pendingMid} -> {pendingAfter} / {holder.Inventory.Pending}, total {holder.Inventory.Total}");
		var historyPoints = (System.Collections.IDictionary) typeof(NocatFarm.Core.InventoryHistory).GetField("Points", All)!.GetValue(null)!;
		bool Banked(string bot) => historyPoints.Contains(bot);
		Check("set aside: an item set aside before it was ever priced keeps the total out of the history - it isn't worth $0, it isn't known",
			!Banked("aside-holder"), $"{holder.Inventory.Total}");

		// 8. Steam's maintenance: every request answers 503 or nothing, whatever it asks about. Twelve sweeps of it set
		// nothing aside - not the knife first, not anything - and save no point in the history. Once it answers again,
		// everything is priced and nothing has been counted against.
		Fresh();
		string[] outage = [$"★ Aside Knife {tag}", .. Enumerable.Range(0, 12).Select(i => $"Aside Case {i} {tag}")];
		for (int i = 0; i < outage.Length; i++) {
			trouble[outage[i]] = i % 2 == 0 ? () => Status(503) : () => Json("");
		}
		var outageHolder = new NocatFarm.Core.Bot("outage-holder", new NocatFarm.Config.BotConfig());
		File.WriteAllText(Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", "invvalue-outage-holder.json"), System.Text.Json.JsonSerializer.Serialize(new {
			ReadAt = DateTime.UtcNow.Ticks,
			Games = new object[] { new { App = 730, Game = "Outage Game", Items = outage.ToDictionary(static h => h, static h => new[] { 1, h.StartsWith('★') ? 0 : 5 }) } }
		}));
		invT.GetMethod("LoadSnapshot", All)!.Invoke(outageHolder.Inventory, [TimeSpan.FromHours(6)]);
		invT.GetMethod("Recount", All)!.Invoke(outageHolder.Inventory, []);
		lock (asked) asked.Clear();
		for (int i = 0; i < 12; i++) {
			TimePasses();
			await Sweep([.. outage.Select(static h => ((uint) 730, h))]);
		}
		invT.GetMethod("Recount", All)!.Invoke(outageHolder.Inventory, []);
		int outageAsked;
		lock (asked) outageAsked = asked.Count;
		Check("set aside: 12 sweeps of 503s and empty answers - nothing set aside, nothing counted against any item, one request a sweep",
			outage.All(h => Due(730, h) && (Trouble(730, h) == null)) && (outageAsked == 12) && (outageHolder.Inventory.Pending == 13),
			$"{outageAsked} asked, aside: {string.Join(", ", outage.Where(h => !Due(730, h)))}");
		Check("set aside: ...and no point saved in the history while it lasts", !Banked("outage-holder"));
		foreach (string h in outage) {
			trouble.Remove(h);
		}
		TimePasses();
		bool outageOver = await Sweep([.. outage.Select(static h => ((uint) 730, h))]);
		invT.GetMethod("Recount", All)!.Invoke(outageHolder.Inventory, []);
		Check("set aside: once the market answers again everything is priced, nothing was counted against, and the real total is banked",
			outageOver && outage.All(h => (NocatFarm.PriceBook.Known(730, h) == 1.23m) && (Trouble(730, h) == null)) && (outageHolder.Inventory.Pending == 0)
			&& Banked("outage-holder"), $"{outageHolder.Inventory.Total}");
	} finally {
		Fresh();
		F("_checkFirst").SetValue(null, true);
		F("Http").SetValue(null, httpBefore);
		F("HttpB").SetValue(null, httpBBefore);
		gapP.SetValue(null, null);
		lock (troubled) troubled.Clear();
		F("_coolUntil").SetValue(null, DateTime.MinValue);
		NocatFarm.Config.Live.Global = liveBefore;
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
		}
	}
}

// ── freegames: the free-games look on demand, against a pretend store and change feed ───────────────────────────────
{
	const BindingFlags AnyInst = BindingFlags.NonPublic | BindingFlags.Public | BindingFlags.Instance;
	const BindingFlags AnyStatic = BindingFlags.NonPublic | BindingFlags.Public | BindingFlags.Static;
	Type fgT = typeof(NocatFarm.Modules.FreeGames);
	PropertyInfo fetchP = fgT.GetProperty("Fetch", AnyStatic)!, claimP = fgT.GetProperty("Claim", AnyStatic)!, pausesP = fgT.GetProperty("NoPauses", AnyStatic)!;
	object? fetchBefore = fetchP.GetValue(null), claimBefore = claimP.GetValue(null);
	FieldInfo giveawaysF = fgT.GetField("_giveaways", AnyStatic)!;
	var verdicts = (IDictionary) fgT.GetField("Verdicts", AnyStatic)!.GetValue(null)!;
	Type picsT = typeof(NocatFarm.Modules.FreeGames).Assembly.GetType("NocatFarm.Core.PicsWatch")!;
	var picsFound = (IDictionary) picsT.GetField("Found", AnyStatic)!.GetValue(null)!;
	Type candT = picsT.GetNestedType("Candidate", AnyStatic)!;
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-freegames-" + Guid.NewGuid().ToString("N"));
	Directory.CreateDirectory(Path.Combine(tmpRoot, "config", "state"));
	NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);
	List<NocatFarm.Core.Bot> made = [];

	// The store, as the module asks it: its giveaway search, and each app's details and packages. Made-up apps, high numbers.
	string search = "";
	Dictionary<string, string> store = new(StringComparer.Ordinal) {
		["3999001|basic"] = """{"3999001":{"success":true,"data":{"type":"game","name":"Fake Giveaway","is_free":false,"price_overview":{"discount_percent":100}}}}""",
		["3999001|packages"] = """{"3999001":{"success":true,"data":{"package_groups":[{"subs":[{"packageid":5999001,"price_in_cents_with_discount":0}]}]}}}""",
		["3999002|basic"] = """{"3999002":{"success":true,"data":{"type":"dlc","name":"Fake Supporter Pack","fullgame":{"appid":"3999003","name":"Fake Base"},"is_free":false,"price_overview":{"discount_percent":100}}}}""",
		["3999003|basic"] = """{"3999003":{"success":true,"data":{"type":"game","name":"Fake Base","is_free":false,"price_overview":{"discount_percent":0}}}}""",
		["3999004|basic"] = """{"3999004":{"success":true,"data":{"type":"game","name":"Fake Feed Game","is_free":false,"price_overview":{"discount_percent":100}}}}"""
	};
	int asked = 0;
	Task<string?> FakeStore(string url, CancellationToken ct) {
		Interlocked.Increment(ref asked);

		if (url.Contains("/search/results/", StringComparison.Ordinal)) {
			return Task.FromResult<string?>(search);
		}

		string app = System.Text.RegularExpressions.Regex.Match(url, @"appids=(\d+)").Groups[1].Value;
		string kind = url.Contains("filters=packages", StringComparison.Ordinal) ? "packages" : "basic";

		return Task.FromResult<string?>(store.TryGetValue(app + "|" + kind, out string? json) ? json : "{\"" + app + "\":{\"success\":false}}");
	}
	string Search(params uint[] apps) => System.Text.Json.JsonSerializer.Serialize(new {
		success = 1, results_html = string.Concat(apps.Select(static a => $"<a href=\"https://store.example/app/{a}/\" data-ds-appid=\"{a}\">x</a>")), total_count = apps.Length
	}, new System.Text.Json.JsonSerializerOptions { Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping });   // as the store sends it: \" and no <

	List<(string Bot, uint Id, bool App)> claims = [];
	// An account named here gets no usable answer to a claim - put off for hours, as a real one is.
	HashSet<string> noAnswer = new(StringComparer.Ordinal);
	// ...and this one's web sign-in drops while its claim is out.
	string dropWebOf = "";
	Task<NocatFarm.Modules.FreeGames.ClaimResult> FakeClaim(NocatFarm.Core.Bot b, uint id, bool app, CancellationToken ct) {
		lock (claims) {
			claims.Add((b.Name, id, app));
		}

		if (b.Name == dropWebOf) {
			typeof(NocatFarm.Core.WebSession).GetProperty("Ready")!.SetValue(typeof(NocatFarm.Core.Bot).GetProperty("Web", AnyInst)!.GetValue(b), false);
		}

		return Task.FromResult((b.Name == dropWebOf) || noAnswer.Contains(b.Name)
			? new NocatFarm.Modules.FreeGames.ClaimResult(false, SteamKit2.EPurchaseResultDetail.Timeout, new NocatFarm.Core.Said("no usable answer from Steam"))
			: new NocatFarm.Modules.FreeGames.ClaimResult(true, SteamKit2.EPurchaseResultDetail.NoDetail, default));
	}

	var mgr = new NocatFarm.Core.BotManager(new NocatFarm.Config.GlobalConfig { WebEnabled = false });
	var bots = (System.Collections.Concurrent.ConcurrentDictionary<string, NocatFarm.Core.Bot>) typeof(NocatFarm.Core.BotManager)
		.GetField("_bots", AnyInst)!.GetValue(mgr)!;
	FieldInfo failedF = fgT.GetField("_failed", AnyInst)!, quietF = fgT.GetField("_quietUntil", AnyInst)!, lookingF = fgT.GetField("_looking", AnyInst)!;
	string StateOf(string name) => Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", $"freegames-{name}.json");
	object Candidate(uint sub, uint app) => Activator.CreateInstance(candT, sub, app, DateTime.UtcNow)!;

	NocatFarm.Modules.FreeGames Ready(string name, int claimFree) {
		var b = new NocatFarm.Core.Bot(name, new NocatFarm.Config.BotConfig { ClaimFree = claimFree });
		typeof(NocatFarm.Core.Bot).GetProperty("State")!.SetValue(b, NocatFarm.Core.BotState.Online);
		typeof(NocatFarm.Core.WebSession).GetProperty("Ready")!.SetValue(typeof(NocatFarm.Core.Bot).GetProperty("Web", AnyInst)!.GetValue(b), true);
		var owned = new List<NocatFarm.Core.Library.Entry> { new(730, "CS2", 100, DateTime.MinValue, 0) };
		typeof(NocatFarm.Core.Library).GetField("_games", AnyInst)!.SetValue(b.Library, owned);
		typeof(NocatFarm.Core.Library).GetField("_byApp", AnyInst)!.SetValue(b.Library, owned.ToDictionary(static e => e.AppId));
		typeof(NocatFarm.Core.Library).GetProperty("Ready")!.SetValue(b.Library, true);
		var free = new NocatFarm.Modules.FreeGames(b);
		b.AddModule(free);
		bots[name] = b;
		made.Add(b);

		return free;
	}
	void Fresh() {
		giveawaysF.SetValue(null, (DateTime.MinValue, new List<string>()));
		lock (verdicts) {
			verdicts.Clear();
		}
		lock (claims) {
			claims.Clear();
		}
	}

	try {
		fetchP.SetValue(null, (Func<string, CancellationToken, Task<string?>>) FakeStore);
		claimP.SetValue(null, (Func<NocatFarm.Core.Bot, uint, bool, CancellationToken, Task<NocatFarm.Modules.FreeGames.ClaimResult>>) FakeClaim);
		pausesP.SetValue(null, true);

		// 1. A giveaway on the store list, one in the change feed, and a free DLC of a game the account doesn't have.
		Fresh();
		Ready("fgclaim", NocatFarm.Modules.FreeClaims.GamesAndDlc);
		search = Search(3999001, 3999002);
		lock (picsFound) {
			picsFound[5999004u] = Activator.CreateInstance(candT, 5999004u, 3999004u, DateTime.UtcNow)!;
		}
		string claimed = await Commands.RunAsync(mgr, "freegames fgclaim");
		lock (picsFound) {
			picsFound.Remove(5999004u);
		}
		Check("freegames: claims what's free - the store's giveaway through its free package, the change feed's by its package",
			claimed.Contains("fgclaim: claimed Fake Giveaway, Fake Feed Game", StringComparison.Ordinal)
			&& claims.SequenceEqual([("fgclaim", 5999001u, false), ("fgclaim", 5999004u, false)]), claimed);
		Check("freegames: a DLC free only to owners of its game is said, with the game, and not asked for",
			claimed.Contains("fgclaim: free, but not claimed:", StringComparison.Ordinal)
			&& claimed.Contains("  Fake Supporter Pack - free only to owners of Fake Base", StringComparison.Ordinal)
			&& !claims.Any(static c => c.Id is 3999002 or 3999003), claimed);
		string again = await Commands.RunAsync(mgr, "freegames fgclaim");
		Check("freegames: what it claimed isn't asked for again", (claims.Count == 2) && !again.Contains("fgclaim: claimed", StringComparison.Ordinal), again);

		// 2. Nothing given away.
		Fresh();
		Ready("fgnone", NocatFarm.Modules.FreeClaims.Games);
		search = Search();
		string nothing = await Commands.RunAsync(mgr, "freegames fgnone");
		Check("freegames: nothing free - says so, and claims nothing", (nothing == "fgnone: nothing free right now") && (claims.Count == 0), nothing);

		// 3. "Claim free games" off on the account: asked for, it still looks - games only - and says how to turn it on.
		Fresh();
		Ready("fgoff", NocatFarm.Modules.FreeClaims.Off);
		search = Search(3999001, 3999002);
		string off = await Commands.RunAsync(mgr, "freegames fgoff");
		Check("freegames: with Claim free games off it still claims the game",
			off.Contains("fgoff: claimed Fake Giveaway", StringComparison.Ordinal) && claims.SequenceEqual([("fgoff", 5999001u, false)]), off);
		Check("freegames: ...but games only - the DLC is left, with why",
			off.Contains("  Fake Supporter Pack - it's DLC - only taken with \"Claim free games\" on games and DLC", StringComparison.Ordinal), off);
		Check("freegames: ...and one line on how to turn it on, by the setting's name",
			off.Contains("fgoff: \"Claim free games\" is off, so this looked for games only. To have it look by itself: Settings, fgoff, Free stuff, \"Claim free games\" (or: set fgoff ClaimFree games).", StringComparison.Ordinal), off);

		// 4. Steam's activation window already full: nothing is asked for, and it says until when.
		Fresh();
		var full = Ready("fgfull", NocatFarm.Modules.FreeClaims.Games);
		var window = (List<DateTime>) fgT.GetField("_claims", AnyInst)!.GetValue(full)!;
		DateTime oldest = DateTime.UtcNow.AddMinutes(-60);
		for (int i = 0; i < 20; i++) {
			window.Add(oldest.AddMinutes(i));
		}
		search = Search(3999001);
		string limited = await Commands.RunAsync(mgr, "freegames fgfull");
		Check("freegames: Steam's limit reached - nothing is claimed, and it says when the rest can go",
			(claims.Count == 0) && limited.Contains($"fgfull: Steam's limit: 20 added in the last 90 minutes, so the rest wait until about {Fmt.Clock(oldest.AddMinutes(90))}", StringComparison.Ordinal)
			&& !limited.Contains("nothing free", StringComparison.Ordinal), limited);

		// 5. A rate limit's pause is kept to as well.
		Fresh();
		var quiet = Ready("fgquiet", NocatFarm.Modules.FreeClaims.Games);
		DateTime back = DateTime.UtcNow.AddMinutes(40);
		fgT.GetField("_quietUntil", AnyInst)!.SetValue(quiet, back);
		string paused = await Commands.RunAsync(mgr, "freegames fgquiet");
		Check("freegames: while Steam has asked it to slow down it asks nothing, and says until when",
			(claims.Count == 0) && paused.Contains($"fgquiet: Steam asked it to slow down - it tries again after {Fmt.Clock(back)}", StringComparison.Ordinal), paused);

		// 6. Paused, like the loop: it waits.
		Fresh();
		Ready("fgpaused", NocatFarm.Modules.FreeClaims.Games);
		typeof(NocatFarm.Core.Bot).GetProperty("Paused", AnyInst)!.SetValue(bots["fgpaused"], true);
		search = Search(3999001);
		string waited = await Commands.RunAsync(mgr, "freegames fgpaused");
		Check("freegames: a paused account isn't touched - it says why", (claims.Count == 0) && waited.Contains("fgpaused: not now - it's paused", StringComparison.Ordinal), waited);

		// 7. Human mode: one typed while the loop's look is still going waits its turn - and that look claims two and spaces the
		// next 20-120 minutes. The command had already asked the gate, so it claimed two more straight after.
		Fresh();
		var spaced = Ready("fgspaced", NocatFarm.Modules.FreeClaims.Games);
		bots["fgspaced"].Cfg.LegitMode = true;
		bots["fgspaced"].Cfg.WakeDelayMinMinutes = 0;
		bots["fgspaced"].Cfg.WakeDelayMaxMinutes = 0;
		search = Search(3999001);
		var spacedLooking = (SemaphoreSlim) lookingF.GetValue(spaced)!;
		await spacedLooking.WaitAsync();
		Task<string> queued;

		try {
			queued = Commands.RunAsync(mgr, "freegames fgspaced");
			await Task.Delay(300);   // past its look at the gate, waiting for the loop's look
			((NocatFarm.Modules.HumanGate) fgT.GetProperty("Gate", AnyInst)!.GetValue(spaced)!).Space(20, 120);
		} finally {
			spacedLooking.Release();
		}

		string afterSpacing = await queued;
		Check("freegames: in human mode, one that waited behind a look keeps to the spacing that look started - nothing claimed, and it says why",
			(claims.Count == 0) && afterSpacing.Contains("fgspaced: not now - it did something at ", StringComparison.Ordinal)
			&& afterSpacing.Contains("human mode spaces things out", StringComparison.Ordinal), afterSpacing);

		// 8. The account's web sign-in drops while a claim is out: said as the sign-out it is, not "Steam didn't answer in time".
		Fresh();
		Ready("fgweb", NocatFarm.Modules.FreeClaims.Games);
		search = Search(3999001);
		dropWebOf = "fgweb";
		string webDropped = await Commands.RunAsync(mgr, "freegames fgweb");
		dropWebOf = "";
		Check("freegames: the web sign-in dropping partway is said plainly, as signed out",
			webDropped.Contains("fgweb: the look for free games stopped - fgweb signed out before it was done; 'freegames' looks again once it's signed in", StringComparison.Ordinal)
			&& !webDropped.Contains("didn't answer in time", StringComparison.Ordinal), webDropped);

		// 9. After a restart the store's answers are gone: what didn't work last time is said by the name kept with it, not
		// "p/5999005" - and one kept by the version before, with no name, in plain words.
		Fresh();
		var named = Ready("fgnames", NocatFarm.Modules.FreeClaims.Games);
		search = Search();
		store["3999005|basic"] = """{"3999005":{"success":true,"data":{"type":"game","name":"Fake Retry Game","is_free":false,"price_overview":{"discount_percent":100}}}}""";
		noAnswer.Add("fgnames");
		lock (picsFound) {
			picsFound[5999005u] = Candidate(5999005, 3999005);
		}

		string firstTry = await Commands.RunAsync(mgr, "freegames fgnames");
		lock (verdicts) {
			verdicts.Clear();
		}
		((System.Collections.Concurrent.ConcurrentDictionary<uint, string>) typeof(NocatFarm.Core.GameNames).GetField("Known", AnyStatic)!.GetValue(null)!).TryRemove(3999005u, out _);
		((IDictionary) failedF.GetValue(named)!).Clear();
		var onDisk = System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(StateOf("fgnames")))!;
		onDisk["Failed"]!["p/5999006"] = new System.Text.Json.Nodes.JsonObject { ["Tries"] = 1, ["NotBeforeTicks"] = DateTime.UtcNow.AddHours(2).Ticks };
		File.WriteAllText(StateOf("fgnames"), onDisk.ToJsonString());
		fgT.GetMethod("Load", AnyInst)!.Invoke(named, null);
		lock (picsFound) {
			picsFound[5999006u] = Candidate(5999006, 3999006);
		}

		string afterRestart = await Commands.RunAsync(mgr, "freegames fgnames");
		lock (picsFound) {
			picsFound.Remove(5999005u);
			picsFound.Remove(5999006u);
		}
		noAnswer.Clear();
		Check("freegames after a restart: what didn't work last time is said by its name, kept with it",
			afterRestart.Contains("  Fake Retry Game - it didn't work last time - it tries again after ", StringComparison.Ordinal) && !afterRestart.Contains("p/", StringComparison.Ordinal),
			firstTry + " || " + afterRestart);
		Check("freegames after a restart: ...and one kept by the version before, with no name, as a package in plain words",
			afterRestart.Contains("  package 5999006 - it didn't work last time - it tries again after ", StringComparison.Ordinal), afterRestart);

		// 10. Signed in again quickly while a look is still going: the loop starting over doesn't read the saved state in over
		// the one that look is using - only once it's done.
		Fresh();
		var reloaded = Ready("fgreload", NocatFarm.Modules.FreeClaims.Off);
		File.WriteAllText(StateOf("fgreload"), $$$"""{"Seen":[],"Failed":{"g/3999001":{"Tries":1,"NotBeforeTicks":{{{DateTime.UtcNow.AddHours(2).Ticks}}}}},"QuietUntilTicks":0}""");
		DateTime inUse = DateTime.UtcNow.AddMinutes(40);
		quietF.SetValue(reloaded, inUse);
		var reloadLooking = (SemaphoreSlim) lookingF.GetValue(reloaded)!;
		await reloadLooking.WaitAsync();
		bool untouched;

		try {
			await reloaded.StartAsync();
			await Task.Delay(300);
			untouched = ((DateTime) quietF.GetValue(reloaded)! == inUse) && (((IDictionary) failedF.GetValue(reloaded)!).Count == 0);
		} finally {
			reloadLooking.Release();
		}

		bool loadedAfter = false;
		for (int i = 0; (i < 100) && !loadedAfter; i++) {
			await Task.Delay(20);
			loadedAfter = ((IDictionary) failedF.GetValue(reloaded)!).Count == 1;
		}
		await reloaded.StopAsync();
		Check("freegames: starting over while a look is going leaves its state alone, and reads the saved one in once it's done", untouched && loadedAfter, $"{untouched} {loadedAfter}");

		Check("freegames: listed with the free commands, and a bare one from Steam chat means that account",
			(Commands.Resolve("freegames")?.Group == Commands.GroupFree) && Commands.DefaultsToThisBot("freegames") && !Commands.SteamChatRefuses("freegames")
			&& (Commands.ThisBotFilledIn(mgr, "freegames", "fgclaim") == "freegames fgclaim"));
	} finally {
		fetchP.SetValue(null, fetchBefore);
		claimP.SetValue(null, claimBefore);
		pausesP.SetValue(null, false);
		Fresh();

		foreach (NocatFarm.Core.Bot b in made) {
			await b.DisposeAsync();
		}

		NocatFarm.Config.ConfigStore.UseRoot(realRoot);

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
			// temp - it goes when Windows tidies up
		}
	}
}

// ── update file: a nocat.farm zip on this PC, installed the way an update is - only from this PC ──────────────────────
{
	const BindingFlags AnyStatic = BindingFlags.NonPublic | BindingFlags.Public | BindingFlags.Static;
	Type su = typeof(NocatFarm.Core.SelfUpdate);
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-update-file-" + Guid.NewGuid().ToString("N"));
	string zips = Path.Combine(tmpRoot, "dev builds (1)");
	Directory.CreateDirectory(Path.Combine(tmpRoot, "config", "state"));
	Directory.CreateDirectory(zips);
	NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);
	string exe = FakeProgram.ExeFor(FakeProgram.Here);

	// A zip the way the release script makes one (see FakeProgram): for this machine, or the kind of computer named.
	string Zip(string name, Version version, bool withExe = true, string? rid = null)
		=> FakeProgram.Zip(Path.Combine(zips, name), version, rid, withExe: withExe, extra: [("README.md", "readme")]);
	string Mine(string v) => OperatingSystem.IsWindows() ? $"nocat.farm-v{v}-portable.zip" : $"nocat.farm-v{v}_{NocatFarm.Core.Platform.ReleaseRid}.zip";
	string newer = Zip(Mine("9.9.9"), new Version(9, 9, 9));
	string older = Zip(Mine("1.6.0"), new Version(1, 6, 0));
	string same = Zip(Mine(Build.Version), Version.Parse(Build.Version));
	// For another kind of computer, really: a Mac's off Windows (told by its name there), Windows' own off it (nocatFarm.exe).
	string other = OperatingSystem.IsWindows() ? Zip("nocat.farm-v9.9.9_osx-arm64.zip", new Version(9, 9, 9), rid: "osx-arm64")
		: Zip("nocat.farm-v9.9.9-portable.zip", new Version(9, 9, 9), rid: "win-x64");
	// ...and off Windows the other chip, by what's in it - under this machine's own name. Apple silicon runs an Intel Mac's
	// program, so there it's Intel that has no other.
	string? otherChipRid = FakeProgram.Here switch {
		"linux-x64" => "linux-arm64", "linux-arm64" => "linux-x64", "osx-x64" => "osx-arm64", _ => null
	};
	string? otherChip = otherChipRid == null ? null : Zip(Mine("9.9.7"), new Version(9, 9, 7), rid: otherChipRid);
	string noExe = Zip(Mine("9.9.8"), new Version(9, 9, 8), withExe: false);
	MethodInfo look = su.GetMethod("LookInZip", AnyStatic)!;
	(string? V, NocatFarm.Core.Said Why) Look(string path) {
		var (v, why) = ((string?, NocatFarm.Core.Said)) look.Invoke(null, [path])!;
		return (v, why);
	}

	var mgr = new NocatFarm.Core.BotManager(new NocatFarm.Config.GlobalConfig { WebEnabled = false });
	NocatFarm.Core.BotManager? hostBefore = Commands.Host;
	PropertyInfo startP = su.GetProperty("StartSwap", AnyStatic)!, exitP = su.GetProperty("ExitForSwap", AnyStatic)!;
	object? startBefore = startP.GetValue(null), exitBefore = exitP.GetValue(null);
	Func<IEnumerable<NocatFarm.Core.Bot>>? fleetBefore = NocatFarm.Core.SelfUpdate.Fleet;

	try {
		string renamed = Path.Combine(zips, Mine("1.2.3"));
		File.Copy(newer, renamed);
		Check("update file: reads the version from the program in the zip, not the file name",
			(Look(newer).V == "9.9.9") && (Look(renamed).V == "9.9.9"), Look(renamed).Why.ToString());
		Check("update file: no file there - says so", (Look(Path.Combine(zips, "gone.zip")).V == null)
			&& Look(Path.Combine(zips, "gone.zip")).Why.ToString().Contains("there's no file at", StringComparison.Ordinal));
		Check("update file: a zip for another kind of computer is refused, and says which one this needs",
			(Look(other).V == null) && Look(other).Why.ToString().Contains("another kind of computer", StringComparison.Ordinal)
			&& ((otherChip == null) || ((Look(otherChip).V == null) && Look(otherChip).Why.ToString().Contains("another kind of computer", StringComparison.Ordinal))),
			$"{Look(other).Why} | {(otherChip == null ? "" : Look(otherChip).Why.ToString())}");
		Check("update file: a zip without the program in it is refused, like a download would be",
			(Look(noExe).V == null) && Look(noExe).Why.ToString().Contains($"there's no {exe} in it", StringComparison.Ordinal), Look(noExe).Why.ToString());

		// Only at this PC: Telegram, Discord and plugins run commands without it, Steam chat too, and a dashboard request
		// counts only when it really came from this PC.
		string fromChat = await Commands.RunAsync(mgr, $"update file {newer}");
		Commands.Host = mgr;
		string fromSteam = await Commands.RunAsync($"update file {newer}", "someaccount");
		Check("update file: refused from Telegram, Discord (and plugins), and from Steam chat - and says where it works",
			fromChat.Contains("only works at this PC", StringComparison.Ordinal) && fromSteam.Contains("only works at this PC", StringComparison.Ordinal), fromChat + " / " + fromSteam);
		Microsoft.AspNetCore.Http.DefaultHttpContext From(string ip, string? forwarded = null) {
			var ctx = new Microsoft.AspNetCore.Http.DefaultHttpContext();
			ctx.Connection.RemoteIpAddress = System.Net.IPAddress.Parse(ip);
			if (forwarded != null) {
				ctx.Request.Headers["X-Forwarded-For"] = forwarded;
			}
			return ctx;
		}
		MethodInfo atThisPc = typeof(NocatFarm.Web.WebHost).GetMethod("AtThisPc", AnyStatic)!;
		bool At(Microsoft.AspNetCore.Http.HttpContext c) => (bool) atThisPc.Invoke(null, [c])!;
		string web = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Web", "WebHost.cs")).Replace("\r\n", "\n");
		Check("update file: the dashboard counts as this PC only from this PC - not a phone, the internet, or the internet through a proxy here",
			At(From("127.0.0.1")) && At(From("::1")) && !At(From("192.168.1.20")) && !At(From("203.0.113.9")) && !At(From("127.0.0.1", "203.0.113.9"))
			&& web.Contains("string output = AtThisPc(ctx)\n\t\t\t\t? await Commands.RunAtThisPcAsync(_mgr, body.Line, \"dashboard on this PC\").ConfigureAwait(false)\n\t\t\t\t: await Commands.RunLoggedAsync(_mgr, body.Line, \"dashboard from another device\").ConfigureAwait(false);", StringComparison.Ordinal));

		if (NocatFarm.Core.SelfUpdate.Supported) {
			string old = await Commands.RunAtThisPcAsync(mgr, $"update file {older}");
			string sameSaid = await Commands.RunAtThisPcAsync(mgr, $"update file {same}");
			Check("update file: an older version needs force, and says so plainly",
				old.Contains($"has nocat.farm 1.6.0, and you have {Build.Version} - an older one", StringComparison.Ordinal) && old.Contains($"update file {older} force", StringComparison.Ordinal)
				&& !NocatFarm.Core.SelfUpdate.Busy, old);
			Check("update file: so does the same version", sameSaid.Contains("the same version", StringComparison.Ordinal) && sameSaid.Contains(" force", StringComparison.Ordinal), sameSaid);

			// Older than the first version that tells the swap script it came up: put in, every account signed out, it never said
			// "ok", and three minutes later it was put back as "didn't start". Refused before anything happens, force or not.
			string ancient = Zip(Mine("1.4.5"), new Version(1, 4, 5));
			startP.SetValue(null, (Action<System.Diagnostics.ProcessStartInfo>) (_ => throw new InvalidOperationException("no swap in the checks")));
			exitP.SetValue(null, (Action) (() => { }));
			MethodInfo? tooOldFor = su.GetMethod("TooOld", AnyStatic, [typeof(string), typeof(bool)]);
			string? TooOld(string v, bool terminal) => tooOldFor == null ? "(none)" : ((NocatFarm.Core.Said?) tooOldFor.Invoke(null, [v, terminal]))?.ToEnglish();
			string oldest = su.GetProperty("OldestInstallable", AnyStatic)?.GetValue(null) as string ?? "(none)";
			string tooOld = await Commands.RunAtThisPcAsync(mgr, $"update file {ancient} force");
			string tooOldUnforced = await Commands.RunAtThisPcAsync(mgr, $"update file {ancient}");
			Check("update file: a version too old to say it started is refused, force or not, and says which is the oldest that can go in",
				tooOld.Contains($"1.4.5 is too old to install this way - the oldest that can is {oldest}", StringComparison.Ordinal) && (tooOldUnforced == tooOld)
				&& !NocatFarm.Core.SelfUpdate.Busy, $"{tooOld} | {tooOldUnforced}");
			bool signingOut = false;
			NocatFarm.Core.SelfUpdate.Fleet = () => {
				signingOut = true;
				return [];
			};
			string? refused = await NocatFarm.Core.SelfUpdate.ApplyAsync(CancellationToken.None, fromFile: ancient);
			Check("update file: ...and the install itself refuses it too - before an account signs out or the settings are saved",
				(refused?.Contains("1.4.5 is too old to install this way", StringComparison.Ordinal) == true) && !signingOut
				&& (!Directory.Exists(NocatFarm.Core.Rollback.Folder) || (Directory.GetFiles(NocatFarm.Core.Rollback.Folder, "before-1.4.5-*").Length == 0)), refused ?? "null");
			NocatFarm.Core.SelfUpdate.Fleet = fleetBefore;
			Check("update file: the oldest is 1.4.6, the first to say \"ok\" - and 1.5.4 on a Mac started from start.command, the first to find where in a new Terminal window",
				(TooOld("1.4.5", false)?.Contains("the oldest that can is 1.4.6", StringComparison.Ordinal) == true) && (TooOld("v1.4.6", false) == null)
				&& (TooOld("1.5.3", false) == null) && (TooOld("1.5.3", true)?.Contains("1.5.3 is too old to install this way - the oldest that can is 1.5.4", StringComparison.Ordinal) == true)
				&& (TooOld("1.5.4", true) == null), $"{TooOld("1.4.5", false)} | {TooOld("1.5.3", true)}");

			string wrong = await Commands.RunAtThisPcAsync(mgr, $"update file {other}");
			Check("update file: at this PC, the wrong platform's zip is still refused", wrong.Contains("another kind of computer", StringComparison.Ordinal) && !NocatFarm.Core.SelfUpdate.Busy, wrong);

			// A newer one goes the normal way: copied, unpacked, the safety copy, the countdown, the swap - which is only
			// looked at here, never started.
			System.Diagnostics.ProcessStartInfo? swapped = null;
			bool exited = false;
			startP.SetValue(null, (Action<System.Diagnostics.ProcessStartInfo>) (p => swapped = p));
			exitP.SetValue(null, (Action) (() => exited = true));
			NocatFarm.Core.SelfUpdate.Fleet = static () => [];
			string going = await Commands.RunAtThisPcAsync(mgr, $"update file {newer}");
			for (int i = 0; (i < 120) && !exited; i++) {
				await Task.Delay(500);
			}
			string note = Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", "updated.txt");
			string staged = swapped?.Environment["NF_STAGED"] ?? "";
			Check("update file: a newer zip says what it installs, from which file",
				going.StartsWith($"installing nocat.farm 9.9.9 from {Path.GetFileName(newer)}", StringComparison.Ordinal), going);
			Check("update file: ...and goes down the normal swap: staged with the program, the note for \"updated A → B\", then nocat.farm closes",
				exited && (swapped != null) && File.Exists(Path.Combine(staged, exe)) && File.Exists(Path.Combine(staged, "nocatFarm.dll"))
				&& (swapped.Environment["NF_TAG"] == "file:9.9.9") && File.Exists(note) && File.ReadAllText(note).StartsWith($"{Build.Version}|9.9.9|", StringComparison.Ordinal),
				$"{exited} {swapped?.Environment["NF_TAG"]} {staged}");

			// Back as it was: nothing was started, so nothing owns the work folder.
			typeof(NocatFarm.Core.SelfUpdate).GetField("_busy", AnyStatic)!.SetValue(null, 0);
			typeof(NocatFarm.Core.SelfUpdate).GetField("_handedOver", AnyStatic)!.SetValue(null, false);
			if (swapped?.Environment["NF_WORK"] is { Length: > 0 } work) {
				try {
					Directory.Delete(work, true);
				} catch (IOException) {
				}
			}
			File.Delete(note);
			File.Delete(Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", "update-verify.txt"));
			File.Delete(Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", "update-notes.txt"));
		}

		// A version from a file that didn't start: put back, and not skipped - the release with that number is another build.
		NocatFarm.Core.UpdateCheck.Skipped = null;
		File.WriteAllText(Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", "update-failed.txt"), "crashed file:9.9.9");
		NocatFarm.Core.SelfUpdate.AnnounceIfJustUpdated();
		Check("update file: one that crashed is put back and said, but its version isn't skipped",
			(NocatFarm.Core.UpdateCheck.Skipped == null) && (NocatFarm.Core.SelfUpdate.LastFailure?.Contains("nocat.farm 9.9.9 from the file didn't start", StringComparison.Ordinal) == true),
			NocatFarm.Core.SelfUpdate.LastFailure ?? "null");

		// The same version from a file ('force'), whose files didn't all copy in: the note names the version that's running, and
		// that was read as done - "updated 1.7.3 → 1.7.3" and "Install complete" - before the copy's failure was looked at.
		long sameMark = Log.Recent(1).LastOrDefault()?.Seq ?? 0;
		string sameNote = Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", "updated.txt");
		File.WriteAllText(sameNote, $"{Build.Version}|{Build.Version}|12|3|{DateTime.UtcNow.Ticks}");
		File.WriteAllText(Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", "update-failed.txt"), "8");
		NocatFarm.Core.SelfUpdate.AnnounceIfJustUpdated();
		bool saidUpdated = Log.Since(sameMark).Any(static e => e.Said.ToEnglish().Contains($"updated {Build.Version} → {Build.Version}", StringComparison.Ordinal));
		Check("update file, the same version: files that didn't copy in are said as the failure - never \"updated A → A\" first",
			!saidUpdated && (NocatFarm.Core.SelfUpdate.LastFailure?.StartsWith("update failed:", StringComparison.Ordinal) == true) && !File.Exists(sameNote),
			$"{saidUpdated} | {NocatFarm.Core.SelfUpdate.LastFailure}");
	} finally {
		startP.SetValue(null, startBefore);
		exitP.SetValue(null, exitBefore);
		NocatFarm.Core.SelfUpdate.Fleet = fleetBefore;
		Commands.Host = hostBefore;
		NocatFarm.Core.UpdateCheck.Skipped = null;
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
			// temp - it goes when Windows tidies up
		}
	}
}

// ── update file: whose program it is, for every kind of computer - whichever one these checks run on ────────────────────
// A Mac's checks can't run here, so its side is checked from every machine: the program's start for each kind of computer
// put to SelfUpdate.RunsOn as each one, and the whole zip to LookInZipFor.
{
	MethodInfo runsOnM = typeof(NocatFarm.Core.SelfUpdate).GetMethod("RunsOn", BindingFlags.NonPublic | BindingFlags.Static)!;
	RunsOnCheck runsOn = runsOnM.CreateDelegate<RunsOnCheck>();
	string[] rids = ["linux-x64", "linux-arm64", "osx-x64", "osx-arm64"];
	byte[] MachOBigEndian(uint cpu) {
		byte[] b = new byte[32];
		System.Buffers.Binary.BinaryPrimitives.WriteUInt32BigEndian(b, 0xFEEDFACF);
		System.Buffers.Binary.BinaryPrimitives.WriteUInt32BigEndian(b.AsSpan(4), cpu);
		return b;
	}

	// What each program is, and the machines that run it: Apple silicon runs an Intel Mac's program too (Rosetta).
	(string What, byte[] Program, string[] RunsOn)[] programs = [
		("Linux x64 (ELF 62)", FakeProgram.For("linux-x64"), ["linux-x64"]),
		("Linux arm64 (ELF 183)", FakeProgram.For("linux-arm64"), ["linux-arm64"]),
		("Intel Mac (Mach-O 0x01000007)", FakeProgram.For("osx-x64"), ["osx-x64", "osx-arm64"]),
		("Apple silicon (Mach-O 0x0100000C)", FakeProgram.For("osx-arm64"), ["osx-arm64"]),
		("Apple silicon, big-endian Mach-O", MachOBigEndian(FakeProgram.AppleSilicon), ["osx-arm64"]),
		("universal, both", FakeProgram.Fat(false, FakeProgram.Intel, FakeProgram.AppleSilicon), ["osx-x64", "osx-arm64"]),
		("universal 64-bit list, Apple silicon only", FakeProgram.Fat(true, FakeProgram.AppleSilicon), ["osx-arm64"]),
	];
	List<string> wrong = [];
	foreach ((string what, byte[] program, string[] runsOnThese) in programs) {
		foreach (string rid in rids) {
			bool? said = runsOn(program, rid, $"nocat.farm-v1.7.4_{rid}.zip");
			if (said != runsOnThese.Contains(rid)) {
				wrong.Add($"{what} on {rid}: {said?.ToString() ?? "not a program"}");
			}
		}
	}
	foreach ((string what, byte[] program) in new[] { ("Windows' MZ", FakeProgram.For("win-x64")), ("nothing", Array.Empty<byte>()), ("text", "program"u8.ToArray()) }) {
		foreach (string rid in rids) {
			if (runsOn(program, rid, $"nocat.farm-v1.7.4_{rid}.zip") != null) {
				wrong.Add($"{what} on {rid}: taken for a Linux or Mac program");
			}
		}
	}
	Check("update file: whose program it is - ELF and Mach-O (plain, big-endian, universal) put to every Linux and Mac machine", wrong.Count == 0, string.Join(" | ", wrong));

	// The whole zip, as 'update file' reads it on each kind of computer: the pretend one for that machine is taken, version
	// read from its nocatFarm.dll - the same way on all of them.
	string zips = Path.Combine(Path.GetTempPath(), "nf-rids-" + Guid.NewGuid().ToString("N"));
	Directory.CreateDirectory(zips);
	try {
		List<string> refused = [];
		foreach (string rid in rids.Append("win-x64")) {
			string name = rid.StartsWith("win-", StringComparison.Ordinal) ? "nocat.farm-v1.7.4-portable.zip" : $"nocat.farm-v1.7.4_{rid}.zip";
			string path = FakeProgram.Zip(Path.Combine(zips, name), new Version(1, 7, 4), rid);
			var (v, why) = ((string?, NocatFarm.Core.Said)) typeof(NocatFarm.Core.SelfUpdate).GetMethod("LookInZipFor", BindingFlags.NonPublic | BindingFlags.Static)!.Invoke(null, [path, rid])!;
			if (v != "1.7.4") {
				refused.Add($"{rid}: {why.ToEnglish()}");
			}
		}
		Check("update file: the pretend nocat.farm for each kind of computer is taken there, its version read from nocatFarm.dll", refused.Count == 0, string.Join(" | ", refused));
	} finally {
		try {
			Directory.Delete(zips, true);
		} catch (IOException) {
			// temp - it goes when Windows tidies up
		}
	}
}

// ── update file with no path, update versions, update to: a window to pick the zip, and going back on a pretend GitHub ──
{
	const BindingFlags AnyStatic = BindingFlags.NonPublic | BindingFlags.Public | BindingFlags.Static;
	Type su = typeof(NocatFarm.Core.SelfUpdate);
	Type uc = typeof(NocatFarm.Core.UpdateCheck);
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-update-to-" + Guid.NewGuid().ToString("N"));
	string zips = Path.Combine(tmpRoot, "zips");
	Directory.CreateDirectory(Path.Combine(tmpRoot, "config", "state"));
	Directory.CreateDirectory(zips);
	NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);
	string exe = FakeProgram.ExeFor(FakeProgram.Here);
	string cur = Build.Version;

	// A release zip as the release script makes one, for this machine (see FakeProgram).
	byte[] ZipBytes(Version version) => FakeProgram.ZipBytes(version);
	string Mine(string v) => OperatingSystem.IsWindows() ? $"nocat.farm-v{v}-portable.zip" : $"nocat.farm-v{v}_{NocatFarm.Core.Platform.ReleaseRid}.zip";
	string notMine = OperatingSystem.IsWindows() ? "nocat.farm-v1.6.3_osx-arm64.zip" : "nocat.farm-v1.6.3-portable.zip";
	string olderZip = Path.Combine(zips, Mine("1.6.0"));
	File.WriteAllBytes(olderZip, ZipBytes(new Version(1, 6, 0)));

	// A pretend GitHub on this PC: the newest release, the list of them, one by its tag, and the zips - by path, like the real one.
	System.Net.Sockets.TcpListener listener = new(System.Net.IPAddress.Loopback, 0);
	listener.Start();
	int port = ((System.Net.IPEndPoint) listener.LocalEndpoint).Port;
	Dictionary<string, byte[]> served = new(StringComparer.Ordinal);
	List<string> askedFor = [];
	CancellationTokenSource stopServing = new();

	_ = Task.Run(async () => {
		while (!stopServing.IsCancellationRequested) {
			System.Net.Sockets.TcpClient client;

			try {
				client = await listener.AcceptTcpClientAsync(stopServing.Token);
			} catch {
				break;
			}

			using (client) {
				System.Net.Sockets.NetworkStream ns = client.GetStream();
				byte[] buffer = new byte[8192];
				string head = "";

				while (!head.Contains("\r\n\r\n", StringComparison.Ordinal)) {
					int read = await ns.ReadAsync(buffer);
					if (read <= 0) {
						break;
					}

					head += System.Text.Encoding.ASCII.GetString(buffer, 0, read);
				}

				string path = head.Split(' ').ElementAtOrDefault(1) ?? "";
				lock (askedFor) {
					askedFor.Add(path);
				}
				bool found = served.TryGetValue(path, out byte[]? body);
				body ??= System.Text.Encoding.UTF8.GetBytes("{\"message\":\"Not Found\"}");
				byte[] reply = System.Text.Encoding.ASCII.GetBytes($"HTTP/1.1 {(found ? "200 OK" : "404 Not Found")}\r\nContent-Type: application/octet-stream\r\nContent-Length: {body.Length}\r\nConnection: close\r\n\r\n");
				await ns.WriteAsync(reply);
				await ns.WriteAsync(body);
			}
		}
	});

	byte[] back = ZipBytes(new Version(1, 6, 1));
	served["/zips/" + Mine("1.6.1")] = back;
	object Release(string v, string[] assets, bool pre = false) => new {
		tag_name = "v" + v, html_url = "https://example.invalid/", body = "- a test", draft = false, prerelease = pre,
		assets = assets.Select(a => new { name = a, browser_download_url = $"http://127.0.0.1:{port}/zips/{a}", size = a == Mine("1.6.1") ? back.Length : 1234 }).ToArray()
	};
	byte[] Json(object o) => System.Text.Encoding.UTF8.GetBytes(System.Text.Json.JsonSerializer.Serialize(o));
	served["/latest.json"] = Json(Release(cur, [Mine(cur)]));
	served["/releases"] = Json(new[] {
		Release("1.6.4", [Mine("1.6.4")], pre: true), Release(cur, [Mine(cur)]), Release("1.6.1", [Mine("1.6.1")]),
		Release("1.6.3", [notMine]), Release("1.6.2", [Mine("1.6.2")]), Release("1.4.5", [Mine("1.4.5")])
	});
	served["/releases/tags/v1.6.1"] = Json(Release("1.6.1", [notMine, Mine("1.6.1")]));

	var mgr = new NocatFarm.Core.BotManager(new NocatFarm.Config.GlobalConfig { WebEnabled = false });
	NocatFarm.Core.BotManager? hostBefore = Commands.Host;
	PropertyInfo startP = su.GetProperty("StartSwap", AnyStatic)!, exitP = su.GetProperty("ExitForSwap", AnyStatic)!;
	PropertyInfo pickerP = typeof(Commands).GetProperty("FilePicker", AnyStatic)!, pickingP = typeof(Commands).GetProperty("Picking", AnyStatic)!;
	object? startBefore = startP.GetValue(null), exitBefore = exitP.GetValue(null);
	Func<IEnumerable<NocatFarm.Core.Bot>>? fleetBefore = NocatFarm.Core.SelfUpdate.Fleet;
	NocatFarm.Config.GlobalConfig globalBefore = NocatFarm.Config.Live.Global;
	long Mark() => Log.Recent(1).LastOrDefault()?.Seq ?? 0;
	bool Said(long since, string english) => Log.Since(since).Any(e => e.Said.ToEnglish().Contains(english, StringComparison.Ordinal));

	Environment.SetEnvironmentVariable("NOCATFARM_UPDATE_FEED", $"http://127.0.0.1:{port}/latest.json");

	try {
		// ── update file with no path ──
		string remote = await Commands.RunAsync(mgr, "update file");
		Commands.Host = mgr;
		string fromSteam = await Commands.RunAsync("update file force", "someaccount");
		Check("update file with no path: refused away from this PC - Telegram, Discord, a phone, Steam chat - and no window opens",
			remote.Contains("only works at this PC", StringComparison.Ordinal) && fromSteam.Contains("only works at this PC", StringComparison.Ordinal) && (pickingP.GetValue(null) == null),
			remote + " / " + fromSteam);
		string web = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Web", "WebHost.cs")).Replace("\r\n", "\n");
		Check("update file: the dashboard's \"Install from a file\" shows only on this PC",
			web.Contains("CanPick = here && Commands.CanPickFile,", StringComparison.Ordinal) && web.Contains("bool here = AtThisPc(ctx);", StringComparison.Ordinal));

		if (NocatFarm.Core.SelfUpdate.Supported) {
			pickerP.SetValue(null, null);
			string noGui = await Commands.RunAtThisPcAsync(mgr, "update file");
			Check("update file with no path: with no desktop to pick on (Linux, Mac, Docker, --no-gui) it says to type the path",
				noGui.Contains("update file <path to the zip>", StringComparison.Ordinal) && !Commands.CanPickFile && (pickingP.GetValue(null) == null), noGui);

			int opened = 0;
			pickerP.SetValue(null, (Func<Task<string?>>) (() => {
				Interlocked.Increment(ref opened);

				return Task.FromResult<string?>(null);
			}));
			long before = Mark();
			string pick = await Commands.RunAtThisPcAsync(mgr, "update file");
			await (Task) pickingP.GetValue(null)!;
			Check("update file with no path: a window to pick the file opens on this PC",
				(opened == 1) && pick.Contains("A window to pick the file opened on this PC", StringComparison.Ordinal) && Commands.CanPickFile, pick);
			Check("update file with no path: Cancel - nothing chosen, nothing changed", Said(before, "nothing chosen - nothing changed") && !NocatFarm.Core.SelfUpdate.Busy);

			pickerP.SetValue(null, (Func<Task<string?>>) (() => Task.FromResult<string?>(olderZip)));
			before = Mark();
			await Commands.RunAtThisPcAsync(mgr, "update file");
			await (Task) pickingP.GetValue(null)!;
			Check("update file with no path: the picked zip goes through the same checks as a typed one - an older one needs force",
				Said(before, $"has nocat.farm 1.6.0, and you have {cur} - an older one") && Said(before, $"update file {olderZip} force") && !NocatFarm.Core.SelfUpdate.Busy);
		}

		pickerP.SetValue(null, null);

		// ── update versions / update to ──
		_ = await NocatFarm.Core.UpdateCheck.LookAsync(force: true, quiet: true);
		string versions = await Commands.RunAsync(mgr, "update versions");
		Check("update versions: the older versions on GitHub with a zip for this computer, newest first - not this one, a test release, or one with no zip here",
			versions.Contains($"You have {cur}. You can go back to: 1.6.2, 1.6.1", StringComparison.Ordinal) && versions.Contains("update to 1.6.2", StringComparison.Ordinal)
			&& !versions.Contains("1.6.3", StringComparison.Ordinal) && !versions.Contains("1.6.4", StringComparison.Ordinal)
			&& (!NocatFarm.Core.SelfUpdate.Supported || !versions.Contains("1.4.5", StringComparison.Ordinal)), versions);
		Check("update versions: asks the same pretend GitHub the update check does", askedFor.Contains("/releases"), string.Join(" ", askedFor));

		string gone = await Commands.RunAsync(mgr, "update to 1.6.0");
		Check("update to: a version that's no longer on GitHub says so, and lists what is",
			gone.Contains("1.6.0 isn't on GitHub any more", StringComparison.Ordinal) && gone.Contains("You can go back to: 1.6.2, 1.6.1.", StringComparison.Ordinal) && !NocatFarm.Core.SelfUpdate.Busy, gone);

		if (NocatFarm.Core.SelfUpdate.Supported) {
			startP.SetValue(null, (Action<System.Diagnostics.ProcessStartInfo>) (_ => throw new InvalidOperationException("no swap in the checks")));
			exitP.SetValue(null, (Action) (() => { }));

			// On GitHub, but with no zip for this computer - yet: the Mac zips go up a while after the rest. "Isn't on GitHub any
			// more" sent somebody looking for a version that was right there.
			string noZip = await Commands.RunAsync(mgr, "update to 1.6.3");
			Check("update to: a version on GitHub with no download for this computer says so - not that it's gone",
				noZip.Contains("1.6.3 has no download for this computer (yet)", StringComparison.Ordinal) && !noZip.Contains("isn't on GitHub", StringComparison.Ordinal)
				&& !NocatFarm.Core.SelfUpdate.Busy, noZip);

			// Too old to say it started: refused straight away, before GitHub is even asked.
			int asked;
			lock (askedFor) {
				asked = askedFor.Count;
			}
			string ancient = await Commands.RunAsync(mgr, "update to 1.4.5");
			int askedAfter;
			lock (askedFor) {
				askedAfter = askedFor.Count;
			}
			Check("update to: a version too old to say it started is refused before anything is asked or downloaded",
				ancient.Contains("1.4.5 is too old to install this way - the oldest that can is ", StringComparison.Ordinal) && (askedAfter == asked) && !NocatFarm.Core.SelfUpdate.Busy, ancient);
		}

		string same = await Commands.RunAsync(mgr, "update to v" + cur);
		Check("update to: the version it's on already - nothing to do", same == $"You're on {cur} already.", same);
		string fromChat = await Commands.RunAsync("update to 1.6.1", "someaccount");
		Check("update to: never from Steam chat, as 'update accept' isn't", fromChat.Contains("has to be done at the PC", StringComparison.Ordinal) && !NocatFarm.Core.SelfUpdate.Busy, fromChat);

		if (NocatFarm.Core.SelfUpdate.Supported) {
			System.Diagnostics.ProcessStartInfo? swapped = null;
			bool exited = false;
			startP.SetValue(null, (Action<System.Diagnostics.ProcessStartInfo>) (p => swapped = p));
			exitP.SetValue(null, (Action) (() => exited = true));
			NocatFarm.Core.SelfUpdate.Fleet = static () => [];

			// Skipped once: asking for it by name is choosing it, as 'update accept' does. Typed from a phone: the same
			// rights as 'update accept' - signed in is enough.
			NocatFarm.Core.UpdateCheck.Skipped = "v1.6.1";
			string going = await Commands.RunAsync(mgr, "update to 1.6.1");
			for (int i = 0; (i < 120) && !exited; i++) {
				await Task.Delay(500);
			}

			string note = Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", "updated.txt");
			string staged = swapped?.Environment["NF_STAGED"] ?? "";
			Check("update to: going back says what it keeps, and which version won't install by itself",
				going.StartsWith("Going back to 1.6.1: downloading it now", StringComparison.Ordinal)
				&& going.Contains("Your settings are saved first, and the ones 1.6.1 doesn't know come back when you update again.", StringComparison.Ordinal)
				&& going.Contains($"{cur} won't install by itself until a newer one is out; 'update accept' brings it back.", StringComparison.Ordinal), going);
			Check("update to: that release's own zip for this computer, down the normal swap - marked as going back",
				exited && (swapped != null) && File.Exists(Path.Combine(staged, exe)) && File.Exists(Path.Combine(staged, "nocatFarm.dll"))
				&& (swapped.Environment["NF_TAG"] == "back:1.6.1") && askedFor.Contains("/releases/tags/v1.6.1") && askedFor.Contains("/zips/" + Mine("1.6.1"))
				&& File.Exists(note) && File.ReadAllText(note).StartsWith($"{cur}|1.6.1|", StringComparison.Ordinal),
				$"{exited} {swapped?.Environment["NF_TAG"]} {staged}");
			string[] copies = Directory.Exists(NocatFarm.Core.Rollback.Folder) ? Directory.GetFiles(NocatFarm.Core.Rollback.Folder, $"before-1.6.1-from-{cur}-*.zip") : [];
			Check("update to: the whole config folder was saved first, as a backup takes it",
				(copies.Length == 1) && NocatFarm.Core.Backup.Inspect(File.ReadAllBytes(copies[0])).Ok, string.Join(" ", copies));
			Check("update to: the version gone back to isn't skipped", NocatFarm.Core.UpdateCheck.Skipped?.TrimStart('v') != "1.6.1", NocatFarm.Core.UpdateCheck.Skipped ?? "null");
			Check("update to: the version it came from is, as GitHub tags it - so the older version doesn't offer it",
				NocatFarm.Core.UpdateCheck.Skipped == "v" + cur, NocatFarm.Core.UpdateCheck.Skipped ?? "null");

			// Back as it was: nothing was started, so nothing owns the work folder.
			su.GetField("_busy", AnyStatic)!.SetValue(null, 0);
			su.GetField("_handedOver", AnyStatic)!.SetValue(null, false);
			if (swapped?.Environment["NF_WORK"] is { Length: > 0 } work) {
				try {
					Directory.Delete(work, true);
				} catch (IOException) {
				}
			}
			File.Delete(note);
			File.Delete(Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", "update-verify.txt"));
			File.Delete(Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", "update-notes.txt"));

			// As the older version sees it once it's up: the version it came from is out and newer, and it would install by
			// itself in the night. Skipped, it isn't reminded of or installed - and once it's not, it would be.
			uc.GetProperty("Available")!.SetValue(null, "v" + cur);
			NocatFarm.Config.Live.Global = new NocatFarm.Config.GlobalConfig {
				UpdateMode = NocatFarm.Core.UpdateModes.AtNight, AutoUpdateFromHour = 0, AutoUpdateUntilHour = 24, AutoUpdateWaitHours = 0
			};
			uc.GetField("_remindedAt", AnyStatic)!.SetValue(null, DateTime.MinValue);
			uc.GetField("_autoTriedAt", AnyStatic)!.SetValue(null, DateTime.MinValue);
			long quiet = Mark();
			NocatFarm.Core.UpdateCheck.RemindIfDue();
			NocatFarm.Core.UpdateCheck.AutoInstallIfDue(mgr);
			Check("update to: the newer version isn't offered again, or put back by itself at night",
				!Said(quiet, $"nocat.farm v{cur} is out") && !Said(quiet, $"installing v{cur} by itself") && !NocatFarm.Core.SelfUpdate.Busy);
			NocatFarm.Core.UpdateCheck.Skipped = null;
			long loud = Mark();
			NocatFarm.Core.UpdateCheck.RemindIfDue();
			Check("update to: ...which it would be, without the skip", Said(loud, $"reminder: nocat.farm v{cur} is out"));
			uc.GetProperty("Available")!.SetValue(null, null);

			// The older version didn't start and the newer one was put back: said as going back, and nothing is skipped for it.
			File.WriteAllText(Path.Combine(NocatFarm.Config.ConfigStore.ConfigDir, "state", "update-failed.txt"), "crashed back:1.6.1");
			NocatFarm.Core.SelfUpdate.AnnounceIfJustUpdated();
			Check("update to: an older version that didn't start - put back, said plainly, and not skipped",
				(NocatFarm.Core.UpdateCheck.Skipped == null) && (NocatFarm.Core.SelfUpdate.LastFailure?.Contains($"going back didn't work: nocat.farm 1.6.1 didn't start, so you're on {cur} again", StringComparison.Ordinal) == true),
				NocatFarm.Core.SelfUpdate.LastFailure ?? "null");
		}
	} finally {
		Environment.SetEnvironmentVariable("NOCATFARM_UPDATE_FEED", null);
		stopServing.Cancel();
		listener.Stop();
		pickerP.SetValue(null, null);
		startP.SetValue(null, startBefore);
		exitP.SetValue(null, exitBefore);
		NocatFarm.Core.SelfUpdate.Fleet = fleetBefore;
		NocatFarm.Config.Live.Global = globalBefore;
		Commands.Host = hostBefore;
		NocatFarm.Core.UpdateCheck.Skipped = null;
		uc.GetProperty("Available")!.SetValue(null, null);
		uc.GetProperty("Latest", AnyStatic)!.SetValue(null, null);
		uc.GetField("_releases", AnyStatic)!.SetValue(null, null);
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
			// temp - it goes when Windows tidies up
		}
	}
}

// ── going back and forth: the settings an older version didn't know come back, once, and only those ──────────────────
{
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-going-back-" + Guid.NewGuid().ToString("N"));
	Directory.CreateDirectory(Path.Combine(tmpRoot, "config", "state"));
	NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);
	string cfg = NocatFarm.Config.ConfigStore.ConfigDir;
	string cur = Build.Version;

	// What an older version does to a file: reads the settings it knows, writes back only those.
	void OlderWrites(string file, string[] unknown, Action<System.Text.Json.Nodes.JsonObject>? change = null) {
		var json = (System.Text.Json.Nodes.JsonObject) System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(file))!;
		foreach (string key in unknown) {
			json.Remove(key);
		}
		change?.Invoke(json);
		File.WriteAllText(file, json.ToJsonString(new System.Text.Json.JsonSerializerOptions { WriteIndented = true }));
	}
	List<string> Good(List<NocatFarm.Core.Rollback.Note> notes) => [.. notes.Where(static n => (n.Detail == null) && !n.Problem).Select(static n => n.Line.ToEnglish())];

	try {
		// On this version: settings set away from their defaults, an account to keep and one that goes.
		NocatFarm.Config.ConfigStore.SaveGlobal(new NocatFarm.Config.GlobalConfig {
			UpdateCheckHours = 7, UpdateReminders = false, AutoUpdateFromHour = 4, DisabledPlugins = ["one"], Tray = true
		});
		NocatFarm.Config.ConfigStore.SaveBot("rbkeep", new NocatFarm.Config.BotConfig {
			IdleGames = [440, 570], HoursUntilCardDrops = 5, ClaimEventItems = false, DiscoveryQueue = 2, CraftBadges = false
		});
		NocatFarm.Config.ConfigStore.SaveBot("rbgone", new NocatFarm.Config.BotConfig { DiscoveryQueue = 2 });

		string copy = NocatFarm.Core.Rollback.Snapshot("v1.0.1");
		Check("going back: the copy is named for both versions, in config/backups",
			Path.GetDirectoryName(copy) == Path.Combine(cfg, "backups")
			&& System.Text.RegularExpressions.Regex.IsMatch(Path.GetFileName(copy), $@"^before-1\.0\.1-from-{System.Text.RegularExpressions.Regex.Escape(cur)}-\d{{8}}-\d{{6}}\.zip$"),
			copy);

		// On the older version: it drops what it doesn't know, a setting is changed there, an account removed, one added.
		OlderWrites(Path.Combine(cfg, "nocatFarm.json"), ["UpdateCheckHours", "UpdateReminders", "AutoUpdateFromHour", "DisabledPlugins"], static j => j["Tray"] = false);
		OlderWrites(Path.Combine(cfg, "rbkeep.json"), ["IdleGames", "HoursUntilCardDrops", "ClaimEventItems", "DiscoveryQueue"], static j => j["CraftBadges"] = true);
		File.Delete(Path.Combine(cfg, "rbgone.json"));
		string added = "{\n  \"SteamLogin\": \"rbnew\",\n  \"DiscoveryQueue\": 0\n}";
		File.WriteAllText(Path.Combine(cfg, "rbnew.json"), added);

		// A version in between - older than the one the copy came from: it fills in the settings it knows (here, all of them),
		// and the copy waits for a version that knows the rest.
		List<NocatFarm.Core.Rollback.Note> early = NocatFarm.Core.Rollback.RestoreMissing("1.0.2");
		Check("going back: a version in between fills in what it knows - and the copy waits, not marked as done",
			Good(early).SequenceEqual(["brought back 8 settings that 1.0.1 didn't know"]) && File.Exists(copy) && !File.Exists(copy[..^".zip".Length] + "-applied.zip")
			&& File.ReadAllText(Path.Combine(cfg, "nocatFarm.json")).Contains("UpdateCheckHours", StringComparison.Ordinal),
			string.Join(" | ", early.Select(static n => n.Detail ?? n.Line.ToEnglish())));

		// Dropped again, as the older version had them, for the rest.
		OlderWrites(Path.Combine(cfg, "nocatFarm.json"), ["UpdateCheckHours", "UpdateReminders", "AutoUpdateFromHour", "DisabledPlugins"]);
		OlderWrites(Path.Combine(cfg, "rbkeep.json"), ["IdleGames", "HoursUntilCardDrops", "ClaimEventItems", "DiscoveryQueue"]);

		// Started again as this version.
		List<NocatFarm.Core.Rollback.Note> notes = NocatFarm.Core.Rollback.RestoreMissing();
		Check("going back: back on this version, it says in plain words how many settings came back",
			Good(notes).SequenceEqual(["brought back 8 settings that 1.0.1 didn't know"]) && notes.Any(static n => n.Detail?.Contains("rbkeep.json: IdleGames", StringComparison.Ordinal) == true),
			string.Join(" | ", notes.Select(static n => n.Detail ?? n.Line.ToEnglish())));

		NocatFarm.Config.GlobalConfig g = NocatFarm.Config.ConfigStore.LoadGlobal();
		NocatFarm.Config.BotConfig? keep = NocatFarm.Config.ConfigStore.LoadBot("rbkeep");
		Check("going back: every global setting the older version dropped is back, as it was",
			(g.UpdateCheckHours == 7) && !g.UpdateReminders && (g.AutoUpdateFromHour == 4) && g.DisabledPlugins.SequenceEqual(["one"]));
		Check("going back: ...and every account setting", (keep != null) && keep.IdleGames.SequenceEqual([440u, 570u]) && (keep.HoursUntilCardDrops == 5)
			&& !keep.ClaimEventItems && (keep.DiscoveryQueue == 2));
		Check("going back: a setting changed on the older version keeps the change", !g.Tray && (keep?.CraftBadges == true));
		Check("going back: an account removed in between isn't brought back, and one added in between is left alone",
			!File.Exists(Path.Combine(cfg, "rbgone.json")) && (File.ReadAllText(Path.Combine(cfg, "rbnew.json")) == added));
		Check("going back: the copy is marked as done", !File.Exists(copy) && File.Exists(copy[..^".zip".Length] + "-applied.zip"));

		// Once only: dropped again later (an older version again, by hand), a done copy doesn't bring anything back.
		OlderWrites(Path.Combine(cfg, "rbkeep.json"), ["DiscoveryQueue"]);
		List<NocatFarm.Core.Rollback.Note> again = NocatFarm.Core.Rollback.RestoreMissing();
		Check("going back: done once - the next start brings nothing back from that copy",
			(Good(again).Count == 0) && !File.ReadAllText(Path.Combine(cfg, "rbkeep.json")).Contains("DiscoveryQueue", StringComparison.Ordinal),
			string.Join(" | ", again.Select(static n => n.Detail ?? n.Line.ToEnglish())));

		// Gone back to a version that knew every setting, and forward again by an update: nothing was missing, so nothing ever
		// marked the copy done - read at every start, with every saved login in it, and one more for each round trip.
		string full = NocatFarm.Core.Rollback.Snapshot("v1.6.1");
		NocatFarm.Core.Rollback.RestoreMissing("1.6.1");   // the older version starting: it knows them all, drops none
		NocatFarm.Core.Rollback.RestoreMissing();          // this one again
		bool waiting = File.Exists(full);
		string note = Path.Combine(cfg, "state", "updated.txt");
		File.WriteAllText(note, $"1.6.1|{cur}|12|3|{DateTime.UtcNow.Ticks}");
		NocatFarm.Core.SelfUpdate.AnnounceIfJustUpdated();
		Check("going back and forth: back from a version that knew every setting, the copy for that pair is done once the update is in",
			waiting && !File.Exists(full) && File.Exists(full[..^".zip".Length] + "-applied.zip"),
			string.Join(" ", Directory.GetFiles(NocatFarm.Core.Rollback.Folder).Select(Path.GetFileName)));

		// On trial, only once it has said it's fine: put back, the older version runs again and the copy is still needed then.
		const BindingFlags AnyStatic = BindingFlags.NonPublic | BindingFlags.Public | BindingFlags.Static;
		FieldInfo trialF = typeof(NocatFarm.Core.SelfUpdate).GetField("_trialOk", AnyStatic)!, confirmedF = typeof(NocatFarm.Core.SelfUpdate).GetField("_confirmed", AnyStatic)!;
		object? trialBefore = trialF.GetValue(null), confirmedBefore = confirmedF.GetValue(null);
		string trialCopy = NocatFarm.Core.Rollback.Snapshot("v1.6.2");
		NocatFarm.Core.Rollback.RestoreMissing();

		try {
			trialF.SetValue(null, Path.Combine(cfg, "state", "started.txt"));
			confirmedF.SetValue(null, false);
			typeof(NocatFarm.Core.Rollback).GetMethod("CameForward", AnyStatic)?.Invoke(null, ["1.6.2"]);
			bool heldOn = File.Exists(trialCopy);
			typeof(NocatFarm.Core.Rollback).GetMethod("ConfirmApplied", AnyStatic)!.Invoke(null, []);
			Check("going back and forth: on trial, the copy is done once the new version has said it's fine - not before",
				heldOn && !File.Exists(trialCopy) && File.Exists(trialCopy[..^".zip".Length] + "-applied.zip"), $"{heldOn}");
		} finally {
			trialF.SetValue(null, trialBefore);
			confirmedF.SetValue(null, confirmedBefore);
		}
	} finally {
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
			// temp - it goes when Windows tidies up
		}
	}
}

// ── human mode's wait, said as it is: the first sign-in since nocat.farm started is "signed in at", one after a reconnect
//    "signed in again at", each with when it opens ─────────────────────────────────────────────────────────────────
{
	var cfg = new NocatFarm.Config.BotConfig { LegitMode = true, WakeDelayMinMinutes = 30, WakeDelayMaxMinutes = 30 };
	var bot = new NocatFarm.Core.Bot("harness-gate-why", cfg);
	void SetProp(string name, object? value) => typeof(NocatFarm.Core.Bot).GetProperty(name)?.SetValue(bot, value);
	SetProp("State", NocatFarm.Core.BotState.Online);
	DateTime signedIn = DateTime.UtcNow.AddMinutes(-3);
	SetProp("SignIns", 1);
	SetProp("OnlineSince", signedIn);
	var gate = NocatFarm.Modules.HumanGate.OwnDay(bot);
	FieldInfo openAt = typeof(NocatFarm.Modules.HumanGate).GetField("_openAt", BindingFlags.NonPublic | BindingFlags.Instance)!;
	string why = gate.Waiting().ToEnglish();
	DateTime opens = (DateTime) openAt.GetValue(gate)!;
	Check("human gate: closed by the first sign-in since starting, it says so - when it signed in and when it can go ahead, not \"again\" or \"woken up\"",
		why.StartsWith($"it signed in at {Fmt.Clock(signedIn)} - human mode waits a little", StringComparison.Ordinal)
		&& why.EndsWith($"it can go ahead from about {Fmt.Clock(opens)}", StringComparison.Ordinal) && !why.Contains("woke", StringComparison.Ordinal)
		&& (opens > DateTime.UtcNow), why);
	Check("human gate: asking starts the wait the loop's next look would have", (opens != DateTime.MaxValue) && !gate.Open);

	var free = new NocatFarm.Modules.FreeGames(bot);
	string holding = free.Holding().ToEnglish();
	Check("freegames: holding says the same as the gate - signed in, with the times", holding.StartsWith($"it signed in at {Fmt.Clock(signedIn)}", StringComparison.Ordinal), holding);

	DateTime back = DateTime.UtcNow.AddMinutes(-1);
	SetProp("SignIns", 2);
	SetProp("OnlineSince", back);
	string again = gate.Waiting().ToEnglish();
	Check("human gate: a sign-in after a reconnect is \"signed in again\"", again.StartsWith($"it signed in again at {Fmt.Clock(back)} - human mode waits a little", StringComparison.Ordinal), again);

	openAt.SetValue(gate, DateTime.UtcNow.AddSeconds(-1));
	Check("human gate: open once its wait is over - nothing to say", gate.Waiting().IsEmpty);
	gate.Space(20, 20);
	string spaced = gate.Waiting().ToEnglish();
	Check("human gate: spaced out after doing something - said as that", spaced.StartsWith("it did something at ", StringComparison.Ordinal)
		&& spaced.Contains("human mode spaces things out; it can go ahead from about", StringComparison.Ordinal), spaced);

	await bot.DisposeAsync();
}

// ── every command typed goes in the log file with its reply, where it came from, and no secret ───────────────────
{
	string logRoot = Path.Combine(Path.GetTempPath(), "nf-cmdlog-" + Guid.NewGuid().ToString("N"));
	string? folderBefore = Log.Folder;
	bool debugBefore = Log.DebugEnabled;
	Log.Configure(fileLogging: true, debug: false, logRoot);
	var mgr = new NocatFarm.Core.BotManager(new NocatFarm.Config.GlobalConfig { WebEnabled = false });
	// Every day's file: a run across midnight wrote to one and, named from the clock when it read, looked in the next.
	string File() => string.Concat(Directory.GetFiles(Path.Combine(logRoot, "logs"), "nocatFarm-*.log").Order(StringComparer.Ordinal).Select(static f => System.IO.File.ReadAllText(f)));

	try {
		string reply = await Commands.RunAtThisPcAsync(mgr, "version", "window");
		string firstLine = reply.ReplaceLineEndings("\n").Split('\n')[0];
		string text = File();
		Check("command log: a command typed in the window and its reply land in the log file, marked where it came from",
			text.Contains("|INFO|command|window> version", StringComparison.Ordinal) && text.Contains($"|INFO|command|window  {firstLine}", StringComparison.Ordinal), text);

		string web = System.IO.File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Web", "WebHost.cs")).Replace("\r\n", "\n");
		string social = System.IO.File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Modules", "Social.cs")).Replace("\r\n", "\n");
		string telegram = System.IO.File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Core", "TelegramCommands.cs")).Replace("\r\n", "\n");
		string discord = System.IO.File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Core", "DiscordBot.cs")).Replace("\r\n", "\n");
		Check("command log: the dashboard, Steam chat, Telegram and Discord write theirs too, each named",
			web.Contains("RunAtThisPcAsync(_mgr, body.Line, \"dashboard on this PC\")", StringComparison.Ordinal)
			&& web.Contains("RunLoggedAsync(_mgr, body.Line, \"dashboard from another device\")", StringComparison.Ordinal)
			&& social.Contains("Commands.LogExchange($\"steam chat {Bot.Name} from {who}\", command, answer);", StringComparison.Ordinal)
			&& telegram.Contains("EchoToLog(line, output, \"telegram\");", StringComparison.Ordinal) && discord.Contains("EchoToLog(line, output, \"discord\");", StringComparison.Ordinal)
			&& telegram.Contains("Commands.LineForLog(trimmed)", StringComparison.Ordinal) && discord.Contains("Commands.LineForLog(line)", StringComparison.Ordinal));

		// Secrets: typed as an argument, or said back in a reply.
		(string Line, string Reply, string Secret, string What)[] secrets = [
			("set new SteamPassword hunter2pass", "saved", "hunter2pass", "a Steam password"),
			("set WebPassword dashpw-91827", "saved", "dashpw-91827", "the dashboard password"),
			("set TelegramBotToken 123456789:AAbbCCddEEffGGhhIIjjKKllMMnnOOpp", "saved", "AAbbCCddEEffGGhhIIjjKKllMMnnOOpp", "the Telegram bot token"),
			("set DiscordBotToken MTA5ODc2.discordbot.token-value", "saved", "discordbot.token-value", "the Discord bot token"),
			("set Rep4RepApiToken r4rtoken55667788", "saved", "r4rtoken55667788", "the rep4rep API token"),
			("set new SharedSecret c2hhcmVkc2VjcmV0eA==", "saved", "c2hhcmVkc2VjcmV0eA==", "an authenticator secret"),
			("answer K7B2X", "thanks", "K7B2X", "a Steam Guard code given as an answer"),
			("/answer mypassw0rd!", "thanks", "mypassw0rd!", "a password given as an answer"),
			("add alt altlogin MyPassw0rd", "Added 'alt'", "MyPassw0rd", "a password typed after 'add'"),
			("2fa", "Steam Guard codes (they change every 30 seconds):\n  new          K7B2X   (12s left)", "K7B2X", "a Steam Guard code in what '2fa' says"),
			("guard new", "new: CR4TF   (9s left)", "CR4TF", "a Steam Guard code from '2fa' under another name"),
			("redeem ABCDE-FGHIJ-KLMNO", "ABCDE-FGHIJ-KLMNO: activated on new", "ABCDE-FGHIJ-KLMNO", "a product key, typed and said back"),
			("import asf C:\\asf\\config apikey=0123456789ABCDEF", "imported", "0123456789ABCDEF", "an API key in an import line"),
			("log 5", "GET /api?access_token=eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiIxIn0.sig", "eyJhbGciOiJIUzI1NiJ9", "a token in a reply")
		];

		foreach ((string line, string said, string secret, string what) in secrets) {
			Commands.LogExchange("telegram", line, said);
		}

		text = File();

		foreach ((string line, string said, string secret, string what) in secrets) {
			Check($"command log: {what} comes out masked", !text.Contains(secret, StringComparison.Ordinal)
				&& !Commands.LineForLog(line).Contains(secret, StringComparison.Ordinal) && !string.Join("\n", Commands.ReplyForLog(line, said)).Contains(secret, StringComparison.Ordinal),
				Commands.LineForLog(line) + " / " + string.Join(" | ", Commands.ReplyForLog(line, said)));
		}

		Check("command log: ...and what isn't secret is still there to read",
			text.Contains("telegram> set new SteamPassword ***", StringComparison.Ordinal) && text.Contains("telegram> add alt altlogin ***", StringComparison.Ordinal)
			&& text.Contains("new          *****   (12s left)", StringComparison.Ordinal) && text.Contains("telegram> redeem [key]", StringComparison.Ordinal), text);

		// A long reply: one entry per line, all at one time, and past 200 lines counted, not written.
		string longReply = string.Join("\n", Enumerable.Range(1, 250).Select(static i => $"row {i}"));
		Commands.LogExchange("dashboard on this PC", "status", longReply);
		string[] rows = [.. File().ReplaceLineEndings("\n").Split('\n').Where(static l => l.Contains("|command|dashboard on this PC", StringComparison.Ordinal))];
		Check("command log: a long reply - a line each, the same time on every one, capped at 200 with how many more",
			(rows.Length == 202) && rows[1].EndsWith("dashboard on this PC  row 1", StringComparison.Ordinal) && rows[200].EndsWith("row 200", StringComparison.Ordinal)
			&& rows[201].EndsWith("dashboard on this PC  … 50 more lines", StringComparison.Ordinal) && (rows.Select(static r => r[..19]).Distinct().Count() == 1),
			$"{rows.Length} {rows.LastOrDefault()}");
	} finally {
		Log.Configure(folderBefore != null, debugBefore, folderBefore != null ? Path.GetDirectoryName(folderBefore)! : logRoot);

		try {
			Directory.Delete(logRoot, true);
		} catch (IOException) {
			// temp - it goes when Windows tidies up
		}
	}
}

// ── tables cut text on whole characters: an emoji at the cut is never left half there ───────────────────────────
{
	// A lone half of a surrogate pair is what a console draws as "�".
	static bool Whole(string s) {
		for (int i = 0; i < s.Length; i++) {
			if (char.IsHighSurrogate(s[i]) && (i + 1 < s.Length) && char.IsLowSurrogate(s[i + 1])) {
				i++;
			} else if (char.IsSurrogate(s[i]) || (s[i] == '�')) {
				return false;
			}
		}

		return true;
	}

	const string Skulls = "💀nocat.lol/nocatfarm💀 (+8)";
	Check("columns: an emoji is two columns, the rest one", (Columns.Width("💀nocat.lol/nocatfarm💀") == 23) && (Columns.Width("abc") == 3) && (Columns.Width("☠️x") == 3),
		$"{Columns.Width("💀nocat.lol/nocatfarm💀")} {Columns.Width("☠️x")}");

	bool fitOk = true, clipOk = true, charsOk = true;
	string fitBad = "", clipBad = "", charsBad = "";

	for (int w = 1; w <= 30; w++) {
		string fit = Columns.Fit(Skulls, w);

		if (!Whole(fit) || (Columns.Width(fit) != w)) {
			fitOk = false;
			fitBad = $"{w}: '{fit}' is {Columns.Width(fit)} wide";
		}

		string clip = Columns.Clip(Skulls, w);

		if (!Whole(clip) || (Columns.Width(clip) > w) || ((Columns.Width(Skulls) > w) && !clip.EndsWith('…'))) {
			clipOk = false;
			clipBad = $"{w}: '{clip}'";
		}

		string chars = Columns.ClipChars(Skulls, w);

		if (!Whole(chars) || (chars.Length > w)) {
			charsOk = false;
			charsBad = $"{w}: '{chars}'";
		}
	}

	Check("columns: cut to every width from 1 to 30, never half an emoji, always exactly that wide", fitOk, fitBad);
	Check("columns: clipped to every width, never half an emoji, never wider, '…' when cut", clipOk, clipBad);
	Check("columns: cut to a number of chars (a chat's limit), never half an emoji", charsOk, charsBad);
	Check("columns: the status table's cut is the whole skull or none of it", Columns.Fit(Skulls, 23) == "💀nocat.lol/nocatfarm… ", $"'{Columns.Fit(Skulls, 23)}'");
	Check("columns: what fits is left alone; padding counts the emoji as two", (Columns.Fit("💀ab", 6) == "💀ab  ") && (Columns.PadRight("💀", 4) == "💀  ") && (Columns.PadRight("toolong", 3) == "toolong"));

	var logPad = typeof(Log).GetMethod("Pad", BindingFlags.NonPublic | BindingFlags.Static)!;
	string padded = (string) logPad.Invoke(null, [Skulls, 23])!;
	Check("columns: Log.Pad (the status table's) cuts on the whole emoji", Whole(padded) && (Columns.Width(padded) == 23), padded);

	// The live board pads and trims with colour codes in the line, which take no columns.
	Type board = typeof(NocatFarm.Windows.LiveConsole);
	var boardPad = board.GetMethod("Pad", BindingFlags.NonPublic | BindingFlags.Static)!;
	var boardTrim = board.GetMethod("Trim", BindingFlags.NonPublic | BindingFlags.Static)!;
	var boardVisible = board.GetMethod("Visible", BindingFlags.NonPublic | BindingFlags.Static)!;
	string coloured = "\x1b[36m💀nocat\x1b[0m💀💀";
	bool boardOk = true;
	string boardBad = "";

	for (int w = 1; w <= 12; w++) {
		string p = (string) boardPad.Invoke(null, [coloured, w])!;
		string t = (string) boardTrim.Invoke(null, [coloured, w])!;

		if (!Whole(p) || !Whole(t) || ((int) boardVisible.Invoke(null, [p])! != w) || ((int) boardVisible.Invoke(null, [t])! > w)) {
			boardOk = false;
			boardBad = $"{w}: '{p.Replace("\x1b", "ESC")}' / '{t.Replace("\x1b", "ESC")}'";
		}
	}

	Check("live board: padded and trimmed around colour codes, never half an emoji, the width it was asked for", boardOk, boardBad);

	string realRoot = NocatFarm.Config.ConfigStore.Root;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-cut-" + Guid.NewGuid().ToString("N"));
	Directory.CreateDirectory(Path.Combine(tmpRoot, "config"));
	NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);

	try {
		var mgr = new NocatFarm.Core.BotManager(new NocatFarm.Config.GlobalConfig { WebEnabled = false });
		var bots = (System.Collections.Concurrent.ConcurrentDictionary<string, NocatFarm.Core.Bot>) typeof(NocatFarm.Core.BotManager)
			.GetField("_bots", BindingFlags.NonPublic | BindingFlags.Instance)!.GetValue(mgr)!;
		var skull = new NocatFarm.Core.Bot("skull", new NocatFarm.Config.BotConfig());
		typeof(NocatFarm.Core.Bot).GetProperty("Playing")!.SetValue(skull, Skulls);
		bots["skull"] = skull;
		string table = await Commands.RunAsync(mgr, "status");
		string row = table.Split('\n').First(static l => l.TrimStart().StartsWith("skull ", StringComparison.Ordinal));
		Check("status: a custom name with an emoji at the cut - no '�', the emoji whole or gone, the next column still a space away",
			Whole(table) && row.Contains("💀nocat.lol/nocatfarm… ", StringComparison.Ordinal), row);
	} finally {
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
			// temp - it goes when Windows tidies up
		}
	}
}

// ── money that went down reads "-$98.82", not "$-98.82" ────────────────────────────────────────────────────────
{
	string s = NocatFarm.PriceBook.Symbol;
	Check("money: a fall has its minus in front of the symbol", NocatFarm.PriceBook.Signed(-98.82m) == "-" + s + "98.82", NocatFarm.PriceBook.Signed(-98.82m));
	Check("money: a rise has a plus", NocatFarm.PriceBook.Signed(12.3m) == "+" + s + "12.30", NocatFarm.PriceBook.Signed(12.3m));
	Check("money: no change has no sign", NocatFarm.PriceBook.Signed(0m) == s + "0.00", NocatFarm.PriceBook.Signed(0m));
	Check("money: a fall of a fraction of a cent is no change, not '-$0.00'", NocatFarm.PriceBook.Signed(-0.004m) == s + "0.00", NocatFarm.PriceBook.Signed(-0.004m));
	Check("money: thousands grouped, either way", (NocatFarm.PriceBook.Signed(-1234.5m) == "-" + s + "1,234.50") && (NocatFarm.PriceBook.Signed(1234.5m) == "+" + s + "1,234.50"),
		NocatFarm.PriceBook.Signed(-1234.5m));
	Check("money: percentages likewise - -5.5%, +5.5%, 0.0% (never -0.0%)",
		(NocatFarm.PriceBook.SignedPercent(-5.5) == "-5.5%") && (NocatFarm.PriceBook.SignedPercent(5.5) == "+5.5%")
		&& (NocatFarm.PriceBook.SignedPercent(0) == "0.0%") && (NocatFarm.PriceBook.SignedPercent(-0.04) == "0.0%"),
		$"{NocatFarm.PriceBook.SignedPercent(-5.5)} {NocatFarm.PriceBook.SignedPercent(5.5)} {NocatFarm.PriceBook.SignedPercent(0)} {NocatFarm.PriceBook.SignedPercent(-0.04)}");
	var weeklyMoney = typeof(NocatFarm.Core.WeeklyReport).GetMethod("Money", BindingFlags.NonPublic | BindingFlags.Static)!;
	Check("money: the weekly report (Telegram, Discord) the same way",
		((string) weeklyMoney.Invoke(null, [-2.5m])! == "-" + s + "2.50") && ((string) weeklyMoney.Invoke(null, [2.5m])! == "+" + s + "2.50"),
		(string) weeklyMoney.Invoke(null, [-2.5m])!);

	string app = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "wwwroot", "app.js"));
	Check("money: the dashboard's money puts a minus in front of the symbol too",
		!app.Contains("cur() + (Number(n) || 0)", StringComparison.Ordinal) && app.Contains("(v < 0 && /[1-9]/.test(shown) ? '-' : '') + cur() + shown", StringComparison.Ordinal));
}

// ── help: a usage as wide as its column goes on its own line, never straight into the description ──────────────
{
	string help = await Commands.RunAsync(new NocatFarm.Core.BotManager(new NocatFarm.Config.GlobalConfig { WebEnabled = false }), "help");
	string[] helpLines = help.ReplaceLineEndings("\n").Split('\n');
	List<string> bad = [];

	foreach (CommandDef c in Commands.All) {
		string usage = (c.Display + " " + c.Args).TrimEnd();
		int at = Array.FindIndex(helpLines, l => l.StartsWith("  " + usage, StringComparison.Ordinal));

		if (at < 0) {
			bad.Add(usage + " (not found)");

			continue;
		}

		string line = helpLines[at];
		bool sameLine = line.EndsWith(c.Help, StringComparison.Ordinal) && line[..^c.Help.Length].EndsWith("  ", StringComparison.Ordinal)
			&& (line[..^c.Help.Length].TrimEnd() == "  " + usage);
		bool ownLine = (line == "  " + usage) && (at + 1 < helpLines.Length) && (helpLines[at + 1] == "  " + new string(' ', 44) + c.Help);

		if (!sameLine && !ownLine) {
			bad.Add(line);
		}
	}

	Check("help: every description at least two spaces after its usage, or on its own indented line below", bad.Count == 0, string.Join(" | ", bad));
	Check("help: joingroup's usage (exactly the column's width) wraps",
		helpLines.Contains("  joingroup <account|all> <group link or name>") && !help.Contains("<group link or name>Join", StringComparison.Ordinal));
	Check("help: a usage two short of the column fits with two spaces; one short wraps",
		(Commands.UsageLines(new string('x', 42), 44, "what").Single() == "  " + new string('x', 42) + "  what")
		&& (Commands.UsageLines(new string('x', 43), 44, "what").Length == 2) && (Commands.UsageLines(new string('x', 44), 44, "what")[1] == "  " + new string(' ', 44) + "what"));
}

// ── a '!' or '/' with no command after it says to type one, not "there's no '' command" ─────────────────────────
{
	var mgr = new NocatFarm.Core.BotManager(new NocatFarm.Config.GlobalConfig { WebEnabled = false });
	string bang = await Commands.RunAsync(mgr, "!");
	string slash = await Commands.RunAsync(mgr, "/");
	string spaced = await Commands.RunAsync(mgr, "! status");
	Check("empty command: '!' alone, or '! status' with a space, says to type a command after the '!'",
		(bang == "Type a command after the '!' - 'help' lists them.") && (spaced == bang), $"{bang} / {spaced}");
	Check("empty command: '/' alone says the same with '/'", slash == "Type a command after the '/' - 'help' lists them.", slash);
}

// ── slow commands answer at once, finish in the background, and aren't started twice ─────────────────────────────
{
	string realRoot = NocatFarm.Config.ConfigStore.Root;
	string tmpRoot = Path.Combine(Path.GetTempPath(), "nf-slow-" + Guid.NewGuid().ToString("N"));
	Directory.CreateDirectory(Path.Combine(tmpRoot, "config"));
	NocatFarm.Config.ConfigStore.UseRoot(tmpRoot);

	try {
		var mgr = new NocatFarm.Core.BotManager(new NocatFarm.Config.GlobalConfig { WebEnabled = false });
		var bots = (System.Collections.Concurrent.ConcurrentDictionary<string, NocatFarm.Core.Bot>) typeof(NocatFarm.Core.BotManager)
			.GetField("_bots", BindingFlags.NonPublic | BindingFlags.Instance)!.GetValue(mgr)!;
		var slowA = new NocatFarm.Core.Bot("slowa", new NocatFarm.Config.BotConfig());
		var slowB = new NocatFarm.Core.Bot("slowb", new NocatFarm.Config.BotConfig());
		bots["slowa"] = slowA;
		bots["slowb"] = slowB;

		var watch = System.Diagnostics.Stopwatch.StartNew();
		string queueAll = await Commands.RunAsync(mgr, "queue all");
		Check("queue: an account that isn't signed in says so at once", (watch.Elapsed < TimeSpan.FromSeconds(3))
			&& queueAll.Contains("slowa: not logged in", StringComparison.Ordinal) && queueAll.Contains("slowb: not logged in", StringComparison.Ordinal), queueAll);

		Commands.Slow job = new("testqueue", "going through today's discovery queue", "about 4 minutes");
		TaskCompletionSource<string> finishA = new(TaskCreationOptions.RunContinuationsAsynchronously);
		TaskCompletionSource<string> finishB = new(TaskCreationOptions.RunContinuationsAsynchronously);
		watch.Restart();
		string first = await Commands.SlowAsync(job, [slowA, slowB], b => b == slowA ? finishA.Task : finishB.Task, TimeSpan.Zero);
		Check("slow: answers straight away, a line per account, saying how long and where the answer goes",
			(watch.Elapsed < TimeSpan.FromSeconds(2))
			&& first.Contains("slowa: going through today's discovery queue now - about 4 minutes; the log says when it's done", StringComparison.Ordinal)
			&& first.Contains("slowb: going through today's discovery queue now - about 4 minutes; the log says when it's done", StringComparison.Ordinal), first);

		string again = await Commands.SlowAsync(job, [slowA], static _ => Task.FromResult("started twice"), TimeSpan.Zero);
		Check("slow: a second one while the first is going says it's already going, and starts nothing",
			again == "slowa: already going through today's discovery queue - the log says when it's done", again);

		finishA.SetResult("slowa: looked through 12 game(s) in the discovery queue");
		finishB.SetResult("slowb: looked through 12 game(s) in the discovery queue");
		bool logged = false;

		for (int i = 0; (i < 50) && !logged; i++) {
			await Task.Delay(20);
			logged = Log.Recent(500).Any(static e => (e.Source == "slowa") && (e.Text == "looked through 12 game(s) in the discovery queue"));
		}

		Check("slow: the answer goes to the log under the account's name when it's done - the name said once, not again in the line", logged
			&& !Log.Recent(500).Any(static e => (e.Source == "slowa") && e.Text.StartsWith("slowa: looked through", StringComparison.Ordinal)));

		string after = await Commands.SlowAsync(job, [slowA], static _ => Task.FromResult("slowa: quick"), TimeSpan.FromSeconds(5));
		Check("slow: once it's done it can run again - and a quick one is the reply itself", after == "slowa: quick", after);

		string mixed = await Commands.SlowAsync(job, [slowA, slowB], static b => Task.FromResult($"{b.Name}: done"), TimeSpan.FromSeconds(5),
			oneAtATime: true, cannot: b => b == slowA ? "slowa: not logged in" : null);
		Check("slow: accounts that can't answer in their place, in order", mixed == "slowa: not logged in" + Environment.NewLine + "slowb: done", mixed);

		string failed = await Commands.SlowAsync(job, [slowB], static async _ => {
			await Task.Delay(300);

			throw new InvalidOperationException("Steam went away");
		}, TimeSpan.FromMilliseconds(50));
		Check("slow: past its wait it says it's still going", failed == "slowb: still going through today's discovery queue - the log says when it's done", failed);

		// Polled, not a fixed wait: on a busy machine the background failure took longer than 600 ms to land.
		var going = (IEnumerable) typeof(Commands).GetField("Going", BindingFlags.NonPublic | BindingFlags.Static)!.GetValue(null)!;
		bool warned = false;

		for (int i = 0; (i < 250) && !warned; i++) {
			await Task.Delay(20);

			lock (going) {
				warned = !going.Cast<object>().Any(static o => o.ToString()!.Contains("testqueue slowb", StringComparison.Ordinal)) && Log.Recent(500).Any(static e => (e.Source == "slowb") && (e.Level == "WARN") && e.Text.Contains("Steam went away", StringComparison.Ordinal));
			}
		}

		string retried = await Commands.SlowAsync(job, [slowB], static _ => Task.FromResult("slowb: fine"), TimeSpan.FromSeconds(5));
		Check("slow: one that failed in the background is warned about and can be started again",
			(retried == "slowb: fine") && Log.Recent(500).Any(static e => (e.Source == "slowb") && (e.Level == "WARN") && e.Text.Contains("Steam went away", StringComparison.Ordinal)), retried);

		// From Steam chat the log can't be read - 'log' is refused there - so the answer goes back to the chat when it's done,
		// to every chat that asked. Anywhere else it still says the log has it.
		var lateReply = typeof(Commands).GetField("LateReply", BindingFlags.NonPublic | BindingFlags.Static)?.GetValue(null)
			as AsyncLocal<(Action<string>? Tell, (string Text, string As)[]? Hidden)>;
		List<string> told = [];

		async Task<string> FromChat(Func<Task<string>> run) {
			lateReply!.Value = (s => {
				lock (told) {
					told.Add(s);
				}
			}, null);

			return await run();
		}

		if (lateReply == null) {
			Check("slow: from Steam chat the answer is sent back there when it's done", false, "nothing to send it back with");
		} else {
			TaskCompletionSource<string> finishC = new(TaskCreationOptions.RunContinuationsAsynchronously);
			string chat = await FromChat(() => Commands.SlowAsync(job, [slowA], _ => finishC.Task, TimeSpan.Zero));
			string chatAgain = await FromChat(() => Commands.SlowAsync(job, [slowA], static _ => Task.FromResult("started twice"), TimeSpan.Zero));
			string pcAgain = await Commands.SlowAsync(job, [slowA], static _ => Task.FromResult("started twice"), TimeSpan.Zero);
			Check("slow: from Steam chat it says the answer comes back there, not that the log has it",
				(chat == "slowa: going through today's discovery queue now - about 4 minutes; the answer comes here when it's done")
				&& (chatAgain == "slowa: already going through today's discovery queue - the answer comes here when it's done"), $"{chat} / {chatAgain}");
			Check("slow: ...and from anywhere else, that the log has it", pcAgain == "slowa: already going through today's discovery queue - the log says when it's done", pcAgain);

			finishC.SetResult("slowa: looked through 9 game(s) in the discovery queue");
			int count = 0;

			for (int i = 0; (i < 250) && (count < 2); i++) {
				await Task.Delay(20);

				lock (told) {
					count = told.Count;
				}
			}

			await Task.Delay(100);   // and no third

			lock (told) {
				Check("slow: from Steam chat the answer is sent back when it's done - once to each chat that asked",
					(told.Count == 2) && told.All(static t => t == "slowa: looked through 9 game(s) in the discovery queue"), string.Join(" | ", told));
			}

			string quick = await FromChat(() => Commands.SlowAsync(job, [slowA], static _ => Task.FromResult("slowa: quick"), TimeSpan.FromSeconds(5)));
			await Task.Delay(100);

			lock (told) {
				Check("slow: one done within its wait is the reply itself, not sent again", (quick == "slowa: quick") && (told.Count == 2), $"{quick}; told {told.Count}");
			}
		}

		string social = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "src", "NocatFarm", "Modules", "Social.cs"));
		Check("steam chat: a command from it hands over where a late answer goes", social.Contains("Commands.RunAsync(command, Bot.Name, ", StringComparison.Ordinal));
	} finally {
		NocatFarm.Config.ConfigStore.UseRoot(realRoot);

		try {
			Directory.Delete(tmpRoot, true);
		} catch (IOException) {
			// temp - it goes when Windows tidies up
		}
	}
}

// ── persona <account> says what it shows, like gamename <account> ─────────────────────────────────────────────
{
