		!all.Contains("Process.GetCurrentProcess().StartTime", StringComparison.Ordinal) && program.Contains("Build.MarkStarted();", StringComparison.Ordinal)
		&& (DateTime.UtcNow - NocatFarm.Build.StartedUtc < TimeSpan.FromHours(6)));
