		Seam("Cancel", (Func<ulong, CancellationToken, Task<bool>>) ((id, _) => { cancelled.Add(id); return Task.FromResult(true); }));
		Seam("PriceCard", (Func<string, int, CancellationToken, Task>) ((_, _, _) => Task.CompletedTask));
