		Check("swap receive: a match this copy hasn't been handed yet → it waits (and asks nocat.lol), not left for you", await Judge(unknownOffer) == null && !heldSwaps.Contains(76));
		mark = Log.Recent(1).LastOrDefault()?.Seq ?? 0;
